create index payment_events_doc_idx on public.payment_events (doc_id, created_at);

do $$
declare t text;
begin
  foreach t in array array['subcontractors','subcontracts','subcontract_items','sc_certificates','labour_workers','labour_payrolls'] loop
    execute format('create trigger touch_updated_at before update on public.%I for each row execute function app.touch_updated_at()', t);
    execute format('create trigger audit after insert or update or delete on public.%I for each row execute function app.audit()', t);
  end loop;
  foreach t in array array['subcontractors','subcontracts','subcontract_items','sc_certificates','sc_certificate_lines',
                           'labour_workers','labour_payrolls','labour_attendance','labour_piecework','labour_payroll_lines','payment_events'] loop
    execute format('alter table public.%I enable row level security', t);
  end loop;
  foreach t in array array['subcontracts','subcontract_items','sc_certificates','sc_certificate_lines',
                           'labour_workers','labour_payrolls','labour_attendance','labour_piecework','labour_payroll_lines','payment_events'] loop
    execute format('create policy payment_read on public.%I for select to authenticated using (app.can_see_payments(project_id))', t);
  end loop;
end $$;
create policy payment_read on public.subcontractors for select to authenticated using (app.is_payment_role());
-- Site engineers verify piece-work quantities on site: they read the payroll header, workers and piece-work lines
-- (not the pay lines, certificates or bank details of subcontractors).
create policy site_verify_read on public.labour_payrolls for select to authenticated
  using (app.has_role_txt('site_engineer') and app.is_member(project_id));
create policy site_verify_read on public.labour_piecework for select to authenticated
  using (app.has_role_txt('site_engineer') and app.is_member(project_id));
create policy site_verify_read on public.labour_workers for select to authenticated
  using (app.has_role_txt('site_engineer') and app.is_member(project_id));
create trigger immutable before update or delete on public.payment_events for each row execute function app.block_mutation();

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------
-- <PRJ>-<TYPE>-0001 per project (server-side: payment documents are created online).
create or replace function app.pay_next_no(p_project uuid, p_type text, p_table text) returns text
language plpgsql security definer set search_path = public as $$
declare v_code text; v_n int;
begin
  select code into v_code from public.projects where id = p_project;
  perform pg_advisory_xact_lock(hashtext('pay:' || p_project::text || ':' || p_type));
  execute format('select coalesce(max(nullif(substring(number from ''-(\d+)$''), '''')::int), 0) from public.%I where project_id = $1 and number like $2', p_table)
    into v_n using p_project, v_code || '-' || p_type || '-%';
  return v_code || '-' || p_type || '-' || lpad((v_n + 1)::text, 4, '0');
end $$;

create or replace function app.pay_event(p_project uuid, p_type text, p_doc uuid, p_action text, p_from text, p_to text, p_comment text)
returns void language sql security definer set search_path = public as $$
  insert into public.payment_events (project_id, doc_type, doc_id, action, from_status, to_status, comment)
  values (p_project, p_type, p_doc, p_action, p_from, p_to, nullif(trim(p_comment), ''))
$$;

-- Actual cost line (rolls past a closed EVM cut-off like record_actual_cost).
create or replace function app.pay_cost(p_project uuid, p_number text, p_date date, p_category text, p_task uuid, p_boq uuid,
  p_description text, p_subcontractor text, p_qty numeric, p_uom text, p_rate numeric, p_amount numeric, p_source text, p_ref text)
returns void language plpgsql security definer set search_path = public as $$
declare v_cut date := app.closed_cutoff(p_project); v_date date := least(p_date, app.eat_date(now())); v_orig date; v_period uuid;
begin
  if coalesce(p_amount, 0) = 0 then return; end if;
  if v_cut is not null and v_date <= v_cut then
    v_orig := v_date; v_period := app.closed_period_for(p_project, v_date); v_date := v_cut + 1;
  end if;
  insert into public.cost_entries (id, project_id, number, entry_date, original_entry_date, relates_to_period_id, category, task_id,
    boq_item_id, description, subcontractor, qty, uom, rate, amount, source, source_ref)
  values (gen_random_uuid(), p_project, p_number, v_date, v_orig, v_period, p_category, p_task, p_boq, p_description,
    p_subcontractor, p_qty, p_uom, p_rate, round(p_amount, 2), p_source, p_ref);
end $$;

revoke execute on function app.pay_next_no(uuid, text, text) from public;
revoke execute on function app.pay_event(uuid, text, uuid, text, text, text, text) from public;
revoke execute on function app.pay_cost(uuid, text, date, text, uuid, uuid, text, text, numeric, text, numeric, numeric, text, text) from public;

-- ---------------------------------------------------------------------------
-- Subcontractors & subcontracts
-- ---------------------------------------------------------------------------
create or replace function public.save_subcontractor(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_seen jsonb := app.op_seen(p); v_id uuid := coalesce((p ->> 'id')::uuid, gen_random_uuid());
begin
  if v_seen is not null then return v_seen; end if;
  perform app.require_role_txt('office_engineer', 'coordinator', 'manager', 'finance', 'admin');
  if coalesce(trim(p ->> 'name'), '') = '' then raise exception 'Subcontractor name is required'; end if;
  if nullif(trim(p ->> 'tin'), '') is not null and trim(p ->> 'tin') !~ '^[0-9]{10}$' then
    raise exception 'TIN must be 10 digits';
  end if;
  insert into public.subcontractors (id, name, trade, tin, vat_registered, contact_person, phone, email, address, bank_name, bank_account, is_active)
  values (v_id, trim(p ->> 'name'), nullif(trim(p ->> 'trade'), ''), nullif(trim(p ->> 'tin'), ''), coalesce((p ->> 'vat_registered')::boolean, false),
    nullif(trim(p ->> 'contact_person'), ''), nullif(trim(p ->> 'phone'), ''), nullif(trim(p ->> 'email'), ''), nullif(trim(p ->> 'address'), ''),
    nullif(trim(p ->> 'bank_name'), ''), nullif(trim(p ->> 'bank_account'), ''), coalesce((p ->> 'is_active')::boolean, true))
  on conflict (id) do update set name = excluded.name, trade = excluded.trade, tin = excluded.tin, vat_registered = excluded.vat_registered,
    contact_person = excluded.contact_person, phone = excluded.phone, email = excluded.email, address = excluded.address,
    bank_name = excluded.bank_name, bank_account = excluded.bank_account, is_active = excluded.is_active;
  return app.op_done(p, 'save_subcontractor', jsonb_build_object('ok', true, 'id', v_id));
exception when unique_violation then
  raise exception 'A subcontractor named "%" already exists', trim(p ->> 'name');
end $$;

create or replace function public.save_subcontract(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p);
  v_id uuid := (p ->> 'id')::uuid;
  v_project uuid := (p ->> 'project_id')::uuid;
  s public.subcontracts;
  sub public.subcontractors;
  it jsonb; v_line int := 0; v_item uuid; v_keep uuid[] := '{}'; v_number text;
begin
  if v_seen is not null then return v_seen; end if;
  if v_id is null then raise exception 'Subcontract id is required'; end if;
  perform app.require_member(v_project);
  perform app.require_role_txt('office_engineer', 'coordinator', 'manager', 'admin');
  select * into sub from public.subcontractors where id = (p ->> 'subcontractor_id')::uuid and is_active;
  if not found then raise exception 'Choose an active subcontractor'; end if;
  if coalesce(trim(p ->> 'title'), '') = '' then raise exception 'Subcontract title is required'; end if;
  select * into s from public.subcontracts where id = v_id for update;
  if found and s.project_id <> v_project then raise exception 'Subcontract belongs to another project'; end if;
  if not found then
    v_number := app.pay_next_no(v_project, 'SUB', 'subcontracts');
    insert into public.subcontracts (id, project_id, number, subcontractor_id, title) values (v_id, v_project, v_number, sub.id, trim(p ->> 'title'));
  end if;
  update public.subcontracts set subcontractor_id = sub.id, title = trim(p ->> 'title'), scope = nullif(trim(p ->> 'scope'), ''),
    start_date = (p ->> 'start_date')::date, end_date = (p ->> 'end_date')::date,
    retention_pct = coalesce((p ->> 'retention_pct')::numeric, retention_pct),
    advance_amount = coalesce((p ->> 'advance_amount')::numeric, advance_amount),
    advance_recovery_pct = coalesce((p ->> 'advance_recovery_pct')::numeric, advance_recovery_pct),
    vat_pct = coalesce((p ->> 'vat_pct')::numeric, case when sub.vat_registered then 15 else 0 end),
    wht_pct = coalesce((p ->> 'wht_pct')::numeric, wht_pct),
    wht_threshold = coalesce((p ->> 'wht_threshold')::numeric, wht_threshold),
    status = coalesce(nullif(p ->> 'status', ''), status)
  where id = v_id;

  if p ? 'items' then
    for it in select x from jsonb_array_elements(p -> 'items') x loop
      v_line := v_line + 1;
      if coalesce(trim(it ->> 'description'), '') = '' or coalesce(trim(it ->> 'unit'), '') = '' then
        raise exception 'Line %: description and unit are required', v_line;
      end if;
      if (it ->> 'qty')::numeric is null or (it ->> 'qty')::numeric < 0 or (it ->> 'rate')::numeric is null or (it ->> 'rate')::numeric < 0 then
        raise exception 'Line %: quantity and rate must be zero or more', v_line;
      end if;
      if (it ->> 'boq_item_id') is not null and not exists (select 1 from public.boq_items where id = (it ->> 'boq_item_id')::uuid and project_id = v_project) then
        raise exception 'Line %: BoQ item not in this project', v_line;
      end if;
      if (it ->> 'task_id') is not null and not exists (select 1 from public.schedule_tasks where id = (it ->> 'task_id')::uuid and project_id = v_project) then
        raise exception 'Line %: task not in this project', v_line;
      end if;
      v_item := coalesce((it ->> 'id')::uuid, gen_random_uuid());
      -- a certified rate is contractual: it can't change once a certificate has been approved on it
      if exists (select 1 from public.subcontract_items si join public.sc_certificate_lines cl on cl.subcontract_item_id = si.id
                 join public.sc_certificates c on c.id = cl.certificate_id
                 where si.id = v_item and c.status in ('approved','paid') and si.rate <> (it ->> 'rate')::numeric) then
        raise exception 'Line %: the rate has been certified and cannot change (add a new line for a variation)', v_line;
      end if;
      insert into public.subcontract_items (id, subcontract_id, project_id, line_no, boq_item_id, task_id, description, unit, qty, rate)
      values (v_item, v_id, v_project, v_line, (it ->> 'boq_item_id')::uuid, (it ->> 'task_id')::uuid, trim(it ->> 'description'),
        trim(it ->> 'unit'), (it ->> 'qty')::numeric, (it ->> 'rate')::numeric)
      on conflict (id) do update set line_no = excluded.line_no, boq_item_id = excluded.boq_item_id, task_id = excluded.task_id,
        description = excluded.description, unit = excluded.unit, qty = excluded.qty, rate = excluded.rate, deleted_at = null
      where subcontract_items.subcontract_id = v_id;
      v_keep := v_keep || v_item;
    end loop;
    if exists (select 1 from public.subcontract_items si where si.subcontract_id = v_id and si.deleted_at is null and not (si.id = any (v_keep))
               and exists (select 1 from public.sc_certificate_lines cl join public.sc_certificates c on c.id = cl.certificate_id
                           where cl.subcontract_item_id = si.id and c.status <> 'rejected')) then
      raise exception 'A line that is on a payment certificate cannot be removed';
    end if;
    update public.subcontract_items set deleted_at = now() where subcontract_id = v_id and deleted_at is null and not (id = any (v_keep));
  end if;
  return app.op_done(p, 'save_subcontract', jsonb_build_object('ok', true, 'id', v_id,
    'number', (select number from public.subcontracts where id = v_id)));
end $$;

-- ---------------------------------------------------------------------------
-- Payment certificates
-- ---------------------------------------------------------------------------
create or replace function app.sc_recalc(p_cert uuid) returns void
language plpgsql security definer set search_path = public as $$
declare
  c public.sc_certificates; s public.subcontracts;
  v_to numeric; v_prev numeric; v_this numeric; v_ret numeric; v_adv_left numeric; v_adv numeric; v_vat numeric; v_wht numeric; v_rel numeric;
begin
  select * into c from public.sc_certificates where id = p_cert;
  select * into s from public.subcontracts where id = c.subcontract_id;
  update public.sc_certificate_lines l set
    rate = si.rate,
    amount_to_date = round(l.qty_verified_to_date * si.rate, 2),
    amount_previous = round(l.qty_previous * si.rate, 2),
    amount_this = round(l.qty_verified_to_date * si.rate, 2) - round(l.qty_previous * si.rate, 2)
  from public.subcontract_items si where si.id = l.subcontract_item_id and l.certificate_id = p_cert;
  select coalesce(sum(amount_to_date), 0), coalesce(sum(amount_previous), 0) into v_to, v_prev
    from public.sc_certificate_lines where certificate_id = p_cert;
  v_this := v_to - v_prev;
  v_ret := round(v_this * s.retention_pct / 100, 2);
  v_adv_left := s.advance_amount - coalesce((select sum(advance_recovery_this) from public.sc_certificates
                 where subcontract_id = s.id and id <> p_cert and status in ('approved','paid')), 0);
  v_adv := case when c.is_final then greatest(v_adv_left, 0)
                else least(greatest(v_adv_left, 0), greatest(round(v_this * s.advance_recovery_pct / 100, 2), 0)) end;
  -- final certificate releases all retention held so far (incl. this one); otherwise the entered (partial) release
  v_rel := case when c.is_final then coalesce((select sum(retention_this - retention_release) from public.sc_certificates
                 where subcontract_id = s.id and id <> p_cert and status in ('approved','paid')), 0) + v_ret
                else least(c.retention_release, greatest(coalesce((select sum(retention_this - retention_release) from public.sc_certificates
                 where subcontract_id = s.id and id <> p_cert and status in ('approved','paid')), 0), 0)) end;
  v_vat := round(greatest(v_this, 0) * s.vat_pct / 100, 2);
  v_wht := case when v_this >= s.wht_threshold then round(v_this * s.wht_pct / 100, 2) else 0 end;
  update public.sc_certificates set
    gross_to_date = v_to, gross_previous = v_prev, gross_this = v_this,
    retention_pct = s.retention_pct, retention_this = v_ret, retention_release = v_rel, advance_recovery_this = v_adv,
    vat_pct = s.vat_pct, vat_this = v_vat, wht_pct = case when v_this >= s.wht_threshold then s.wht_pct else 0 end, wht_this = v_wht,
    net_payable = v_this + v_vat - v_ret + v_rel - v_adv - material_deduction - penalty - other_deduction - v_wht
  where id = p_cert;
end $$;
revoke execute on function app.sc_recalc(uuid) from public;

create or replace function public.save_sc_certificate(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p);
  v_id uuid := (p ->> 'id')::uuid;
  s public.subcontracts; c public.sc_certificates;
  v_prev_cert uuid; ln jsonb; si public.subcontract_items; v_prev numeric; v_site numeric; v_number text; v_no int;
begin
  if v_seen is not null then return v_seen; end if;
  if v_id is null then raise exception 'Certificate id is required'; end if;
  select * into c from public.sc_certificates where id = v_id for update;
  select * into s from public.subcontracts where id = coalesce(c.subcontract_id, (p ->> 'subcontract_id')::uuid);
  if s.id is null then raise exception 'Subcontract not found'; end if;
  perform app.require_member(s.project_id);
  perform app.require_role_txt('office_engineer', 'coordinator', 'admin');
  if c.id is not null and c.status not in ('draft', 'returned') then
    raise exception 'Certificate % is % — only drafts and returned certificates can be edited', c.number, c.status;
  end if;
  if (p ->> 'period_from') is null or (p ->> 'period_to') is null then raise exception 'Enter the measurement period'; end if;
  if (p ->> 'period_to')::date > app.eat_date(now()) then raise exception 'The period cannot end in the future'; end if;
  if c.id is null then
    if s.status <> 'active' then raise exception 'Subcontract % is %', s.number, s.status; end if;
    if exists (select 1 from public.sc_certificates where subcontract_id = s.id and status in ('draft','submitted','checked','returned')) then
      raise exception 'Subcontract % already has a certificate in progress — finish it first', s.number;
    end if;
    select coalesce(max(cert_no), 0) + 1 into v_no from public.sc_certificates where subcontract_id = s.id;
    v_number := s.number || '-IPC' || lpad(v_no::text, 2, '0');
    insert into public.sc_certificates (id, project_id, subcontract_id, number, cert_no, period_from, period_to, prepared_by)
    values (v_id, s.project_id, s.id, v_number, v_no, (p ->> 'period_from')::date, (p ->> 'period_to')::date, auth.uid())
    returning * into c;
  end if;
  if (p ->> 'period_from')::date <= coalesce((select max(period_to) from public.sc_certificates where subcontract_id = s.id
       and id <> v_id and status in ('approved','paid')), '1900-01-01'::date) then
    raise exception 'The period must start after the last approved certificate''s period';
  end if;
  update public.sc_certificates set period_from = (p ->> 'period_from')::date, period_to = (p ->> 'period_to')::date,
    is_final = coalesce((p ->> 'is_final')::boolean, false), retention_release = coalesce((p ->> 'retention_release')::numeric, 0),
    material_deduction = coalesce((p ->> 'material_deduction')::numeric, 0), penalty = coalesce((p ->> 'penalty')::numeric, 0),
    other_deduction = coalesce((p ->> 'other_deduction')::numeric, 0), other_deduction_note = nullif(trim(p ->> 'other_deduction_note'), ''),
    remarks = nullif(trim(p ->> 'remarks'), ''), prepared_by = coalesce(prepared_by, auth.uid())
  where id = v_id;

  -- previous = verified to date on the last approved / paid certificate of this subcontract
  select id into v_prev_cert from public.sc_certificates where subcontract_id = s.id and id <> v_id and status in ('approved','paid')
   order by cert_no desc limit 1;
  delete from public.sc_certificate_lines where certificate_id = v_id;
  for si in select * from public.subcontract_items where subcontract_id = s.id and deleted_at is null order by line_no loop
    ln := (select x from jsonb_array_elements(coalesce(p -> 'lines', '[]'::jsonb)) x where (x ->> 'subcontract_item_id')::uuid = si.id limit 1);
    v_prev := coalesce((select qty_verified_to_date from public.sc_certificate_lines where certificate_id = v_prev_cert and subcontract_item_id = si.id), 0);
    -- site reference: verified progress on the linked BoQ item (task share) or the task's verified %
    v_site := coalesce(
      (select sum(l.verified_qty) from public.task_boq_links l where l.boq_item_id = si.boq_item_id and l.deleted_at is null
         and (si.task_id is null or l.task_id = si.task_id)),
      (select round(si.qty * t.pct_complete / 100, 3) from public.schedule_tasks t where t.id = si.task_id));
    if ln is null then
      insert into public.sc_certificate_lines (certificate_id, project_id, subcontract_item_id, qty_claimed_to_date, qty_verified_to_date, qty_previous, site_qty_to_date)
      values (v_id, s.project_id, si.id, v_prev, v_prev, v_prev, v_site);
      continue;
    end if;
    if coalesce((ln ->> 'qty_verified_to_date')::numeric, 0) > coalesce((ln ->> 'qty_claimed_to_date')::numeric, 0) then
      raise exception 'Line %: verified quantity is more than claimed', si.line_no;
    end if;
    if coalesce((ln ->> 'qty_verified_to_date')::numeric, 0) < v_prev and nullif(trim(ln ->> 'remark'), '') is null then
      raise exception 'Line %: verified quantity is below the previous certificate (%) — add a remark (re-measurement)', si.line_no, v_prev;
    end if;
    if coalesce((ln ->> 'qty_verified_to_date')::numeric, 0) > si.qty and nullif(trim(ln ->> 'remark'), '') is null then
      raise exception 'Line %: verified quantity is more than the contract quantity (%) — add a remark (variation / re-measurement)', si.line_no, si.qty;
    end if;
    insert into public.sc_certificate_lines (certificate_id, project_id, subcontract_item_id, qty_claimed_to_date, qty_verified_to_date, qty_previous, site_qty_to_date, remark)
    values (v_id, s.project_id, si.id, coalesce((ln ->> 'qty_claimed_to_date')::numeric, 0), coalesce((ln ->> 'qty_verified_to_date')::numeric, 0),
      v_prev, v_site, nullif(trim(ln ->> 'remark'), ''));
  end loop;
  perform app.sc_recalc(v_id);
  if c.status = 'draft' and not exists (select 1 from public.payment_events where doc_id = v_id) then
    perform app.pay_event(s.project_id, 'sc_certificate', v_id, 'prepare', null, 'draft', null);
  end if;
  select * into c from public.sc_certificates where id = v_id;
  return app.op_done(p, 'save_sc_certificate', jsonb_build_object('ok', true, 'id', v_id, 'number', c.number, 'status', c.status,
    'gross_this', c.gross_this, 'net_payable', c.net_payable));
end $$;

-- ---------------------------------------------------------------------------
-- Labour workers & payroll
-- ---------------------------------------------------------------------------
create or replace function public.save_labour_worker(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_seen jsonb := app.op_seen(p); v_id uuid := coalesce((p ->> 'id')::uuid, gen_random_uuid()); v_project uuid := (p ->> 'project_id')::uuid;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.require_member(v_project);
  perform app.require_role_txt('office_engineer', 'coordinator', 'manager', 'admin');
  if coalesce(trim(p ->> 'full_name'), '') = '' then raise exception 'Worker name is required'; end if;
  if (p ->> 'daily_rate')::numeric is null or (p ->> 'daily_rate')::numeric < 0 then
    raise exception 'Enter the daily rate (0 for piece-rate only workers)';
  end if;
  if exists (select 1 from public.labour_workers where id = v_id and project_id <> v_project) then raise exception 'Worker belongs to another project'; end if;
  insert into public.labour_workers (id, project_id, full_name, trade_id, trade_name, daily_rate, tin, tax_pct, id_no, phone, bank_account, is_active)
  values (v_id, v_project, trim(p ->> 'full_name'), (p ->> 'trade_id')::uuid, nullif(trim(p ->> 'trade_name'), ''), (p ->> 'daily_rate')::numeric,
    nullif(trim(p ->> 'tin'), ''), (p ->> 'tax_pct')::numeric, nullif(trim(p ->> 'id_no'), ''), nullif(trim(p ->> 'phone'), ''),
    nullif(trim(p ->> 'bank_account'), ''), coalesce((p ->> 'is_active')::boolean, true))
  on conflict (id) do update set full_name = excluded.full_name, trade_id = excluded.trade_id, trade_name = excluded.trade_name,
    daily_rate = excluded.daily_rate, tin = excluded.tin, tax_pct = excluded.tax_pct, id_no = excluded.id_no, phone = excluded.phone,
    bank_account = excluded.bank_account, is_active = excluded.is_active;
  return app.op_done(p, 'save_labour_worker', jsonb_build_object('ok', true, 'id', v_id));
end $$;

create or replace function app.payroll_recalc(p_payroll uuid) returns void
language plpgsql security definer set search_path = public as $$
declare pr public.labour_payrolls; v_ded jsonb;
begin
  select * into pr from public.labour_payrolls where id = p_payroll;
  update public.labour_piecework pw set amount = round(coalesce(pw.qty_verified, 0) * pw.rate, 2),
    kg_equivalent = case when lower(pw.unit) = 'berga' and pw.qty_verified is not null then
      round(pw.qty_verified * (select c.factor from public.spec_conversions c where c.material_spec_id = pw.material_spec_id
                                 and lower(c.alt_uom) = 'berga' and c.deleted_at is null), 3) end
  where pw.payroll_id = p_payroll;
  -- keep entered deductions, rebuild the rest from attendance + verified piece-work
  select coalesce(jsonb_object_agg(worker_id::text, jsonb_build_object('d', other_deduction, 'n', deduction_note)), '{}'::jsonb)
    into v_ded from public.labour_payroll_lines where payroll_id = p_payroll;
  delete from public.labour_payroll_lines where payroll_id = p_payroll;
  insert into public.labour_payroll_lines (payroll_id, project_id, worker_id, days, ot_hours, daily_rate, ot_amount, piece_amount, gross,
    tax_pct, tax, other_deduction, deduction_note, net)
  select p_payroll, pr.project_id, w.id, coalesce(a.days, 0), coalesce(a.ot, 0), w.daily_rate, g.ot_amt, coalesce(pw.amt, 0), g.gross, g.tax_pct, t.tax,
         coalesce((v_ded -> w.id::text ->> 'd')::numeric, 0), v_ded -> w.id::text ->> 'n',
         g.gross - t.tax - coalesce((v_ded -> w.id::text ->> 'd')::numeric, 0)
  from (select worker_id from public.labour_attendance where payroll_id = p_payroll
        union select worker_id from public.labour_piecework where payroll_id = p_payroll) ws
  join public.labour_workers w on w.id = ws.worker_id
  left join (select worker_id, sum(day_value) as days, sum(ot_hours) as ot from public.labour_attendance
              where payroll_id = p_payroll group by worker_id) a on a.worker_id = w.id
  left join (select worker_id, sum(amount) as amt from public.labour_piecework where payroll_id = p_payroll group by worker_id) pw on pw.worker_id = w.id
  cross join lateral (select round(coalesce(a.ot, 0) * w.daily_rate / 8 * pr.ot_multiplier, 2) as ot_amt) o
  cross join lateral (select o.ot_amt, round(coalesce(a.days, 0) * w.daily_rate, 2) + o.ot_amt + coalesce(pw.amt, 0) as gross,
                             coalesce(w.tax_pct, pr.tax_pct) as tax_pct) g
  cross join lateral (select round(g.gross * g.tax_pct / 100, 2) as tax) t;
  if exists (select 1 from public.labour_payroll_lines where payroll_id = p_payroll and net < 0) then
    raise exception 'Deductions are more than a worker''s pay after tax';
  end if;
  update public.labour_payrolls set
    workers = (select count(*) from public.labour_payroll_lines where payroll_id = p_payroll),
    days = coalesce((select sum(days) from public.labour_payroll_lines where payroll_id = p_payroll), 0),
    gross = coalesce((select sum(gross) from public.labour_payroll_lines where payroll_id = p_payroll), 0),
    tax = coalesce((select sum(tax) from public.labour_payroll_lines where payroll_id = p_payroll), 0),
    deductions = coalesce((select sum(other_deduction) from public.labour_payroll_lines where payroll_id = p_payroll), 0),
    net = coalesce((select sum(net) from public.labour_payroll_lines where payroll_id = p_payroll), 0)
  where id = p_payroll;
end $$;
revoke execute on function app.payroll_recalc(uuid) from public;

create or replace function public.save_payroll(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p);
  v_id uuid := (p ->> 'id')::uuid;
  v_project uuid := (p ->> 'project_id')::uuid;
  pr public.labour_payrolls;
  v_from date := (p ->> 'period_from')::date; v_to date := (p ->> 'period_to')::date;
  a jsonb; v_clash text; v_keep jsonb; v_pid uuid;
begin
  if v_seen is not null then return v_seen; end if;
  if v_id is null then raise exception 'Payroll id is required'; end if;
  perform app.require_member(v_project);
  perform app.require_role_txt('office_engineer', 'coordinator', 'admin');
  if v_from is null or v_to is null or v_to < v_from then raise exception 'Enter a valid payroll period'; end if;
  if v_to - v_from > 31 then raise exception 'A payroll period is at most one month'; end if;
  if v_to > app.eat_date(now()) then raise exception 'The payroll period cannot end in the future'; end if;
  if coalesce((p ->> 'tax_pct')::numeric, 15) not between 0 and 35 then raise exception 'Tax rate must be between 0 and 35 %%'; end if;
  select * into pr from public.labour_payrolls where id = v_id for update;
  if found and pr.project_id <> v_project then raise exception 'Payroll belongs to another project'; end if;
  if found and pr.status not in ('draft','returned') then raise exception 'Payroll % is % and cannot be edited', pr.number, pr.status; end if;
  if not found then
    insert into public.labour_payrolls (id, project_id, number, period_from, period_to, prepared_by)
    values (v_id, v_project, app.pay_next_no(v_project, 'PAY', 'labour_payrolls'), v_from, v_to, auth.uid());
    perform app.pay_event(v_project, 'payroll', v_id, 'prepare', null, 'draft', null);
  end if;
  update public.labour_payrolls set period_from = v_from, period_to = v_to,
    frequency = coalesce(nullif(p ->> 'frequency', ''), frequency), tax_pct = coalesce((p ->> 'tax_pct')::numeric, tax_pct),
    ot_multiplier = coalesce((p ->> 'ot_multiplier')::numeric, ot_multiplier), remarks = nullif(trim(p ->> 'remarks'), '')
  where id = v_id;

  if p ? 'attendance' then
    delete from public.labour_attendance where payroll_id = v_id;
    for a in select x from jsonb_array_elements(p -> 'attendance') x loop
      if coalesce((a ->> 'day_value')::numeric, 0) = 0 and coalesce((a ->> 'ot_hours')::numeric, 0) = 0 then continue; end if;
      if (a ->> 'work_date')::date not between v_from and v_to then
        raise exception 'Attendance on % is outside the payroll period', a ->> 'work_date';
      end if;
      if not exists (select 1 from public.labour_workers where id = (a ->> 'worker_id')::uuid and project_id = v_project) then
        raise exception 'Worker not registered on this project';
      end if;
      if (a ->> 'task_id') is not null and not exists (select 1 from public.schedule_tasks where id = (a ->> 'task_id')::uuid and project_id = v_project) then
        raise exception 'Task not in this project';
      end if;
      insert into public.labour_attendance (payroll_id, project_id, worker_id, work_date, day_value, ot_hours, task_id)
      values (v_id, v_project, (a ->> 'worker_id')::uuid, (a ->> 'work_date')::date, coalesce((a ->> 'day_value')::numeric, 0),
        coalesce((a ->> 'ot_hours')::numeric, 0), (a ->> 'task_id')::uuid);
    end loop;
    -- a worker is paid once per day: no overlap with another live payroll
    select w.full_name || ' on ' || to_char(x.work_date, 'DD Mon') || ' (' || o.number || ')' into v_clash
      from public.labour_attendance x join public.labour_attendance y on y.worker_id = x.worker_id and y.work_date = x.work_date and y.payroll_id <> x.payroll_id
      join public.labour_payrolls o on o.id = y.payroll_id and o.status <> 'rejected'
      join public.labour_workers w on w.id = x.worker_id
     where x.payroll_id = v_id limit 1;
    if v_clash is not null then raise exception 'Already on another payroll: %', v_clash; end if;
  end if;

  if p ? 'piecework' then
    -- verification survives a re-save when the line's quantity and rate are unchanged
    select coalesce(jsonb_object_agg(id::text, jsonb_build_object('c', qty_claimed, 'r', rate, 'v', qty_verified, 'by', verified_by, 'at', verified_at)), '{}'::jsonb)
      into v_keep from public.labour_piecework where payroll_id = v_id;
    delete from public.labour_piecework where payroll_id = v_id;
    for a in select x from jsonb_array_elements(p -> 'piecework') x loop
      v_pid := coalesce((a ->> 'id')::uuid, gen_random_uuid());
      if (a ->> 'work_date')::date is null or (a ->> 'work_date')::date not between v_from and v_to then
        raise exception 'Piece-work on % is outside the payroll period', coalesce(a ->> 'work_date', '(no date)');
      end if;
      if not exists (select 1 from public.labour_workers where id = (a ->> 'worker_id')::uuid and project_id = v_project) then
        raise exception 'Worker not registered on this project';
      end if;
      if coalesce(trim(a ->> 'description'), '') = '' or coalesce(trim(a ->> 'unit'), '') = '' then
        raise exception 'Piece-work needs a description and a unit (e.g. berga, m2)';
      end if;
      if coalesce((a ->> 'qty_claimed')::numeric, -1) < 0 or coalesce((a ->> 'rate')::numeric, -1) < 0 then
        raise exception 'Piece-work quantity and rate must be zero or more';
      end if;
      if lower(trim(a ->> 'unit')) = 'berga' and (a ->> 'material_spec_id') is null then
        raise exception 'Choose the bar diameter (rebar spec) for work measured in berga';
      end if;
      if (a ->> 'task_id') is not null and not exists (select 1 from public.schedule_tasks where id = (a ->> 'task_id')::uuid and project_id = v_project) then
        raise exception 'Task not in this project';
      end if;
      if (a ->> 'element_id') is not null and not exists (select 1 from public.elements where id = (a ->> 'element_id')::uuid and project_id = v_project) then
        raise exception 'Element not in this project';
      end if;
      if (a ->> 'boq_item_id') is not null and not exists (select 1 from public.boq_items where id = (a ->> 'boq_item_id')::uuid and project_id = v_project) then
        raise exception 'BoQ item not in this project';
      end if;
      insert into public.labour_piecework (id, payroll_id, project_id, worker_id, work_date, description, unit, qty_claimed, rate,
        task_id, element_id, boq_item_id, material_spec_id, remark, qty_verified, verified_by, verified_at)
      select v_pid, v_id, v_project, (a ->> 'worker_id')::uuid, (a ->> 'work_date')::date, trim(a ->> 'description'), trim(a ->> 'unit'),
        (a ->> 'qty_claimed')::numeric, (a ->> 'rate')::numeric, (a ->> 'task_id')::uuid, (a ->> 'element_id')::uuid, (a ->> 'boq_item_id')::uuid,
        (a ->> 'material_spec_id')::uuid, nullif(trim(a ->> 'remark'), ''),
        case when k.c = (a ->> 'qty_claimed')::numeric and k.r = (a ->> 'rate')::numeric then k.v end,
        case when k.c = (a ->> 'qty_claimed')::numeric and k.r = (a ->> 'rate')::numeric then k.vb end,
        case when k.c = (a ->> 'qty_claimed')::numeric and k.r = (a ->> 'rate')::numeric then k.va end
      from (select (v_keep -> v_pid::text ->> 'c')::numeric as c, (v_keep -> v_pid::text ->> 'r')::numeric as r,
                   (v_keep -> v_pid::text ->> 'v')::numeric as v, (v_keep -> v_pid::text ->> 'by')::uuid as vb,
                   (v_keep -> v_pid::text ->> 'at')::timestamptz as va) k;
    end loop;
  end if;

  perform app.payroll_recalc(v_id);
  if p ? 'deductions' then
    update public.labour_payroll_lines l set other_deduction = coalesce((d ->> 'other_deduction')::numeric, 0),
      deduction_note = nullif(trim(d ->> 'deduction_note'), '')
    from jsonb_array_elements(p -> 'deductions') d where l.payroll_id = v_id and l.worker_id = (d ->> 'worker_id')::uuid;
    perform app.payroll_recalc(v_id);
  end if;
  select * into pr from public.labour_payrolls where id = v_id;
  return app.op_done(p, 'save_payroll', jsonb_build_object('ok', true, 'id', v_id, 'number', pr.number, 'status', pr.status,
    'workers', pr.workers, 'gross', pr.gross, 'tax', pr.tax, 'net', pr.net));
end $$;

-- Site / office engineer verifies the piece-work quantities measured on site before the payroll goes for checking.
create or replace function public.verify_piecework(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_seen jsonb := app.op_seen(p); pr public.labour_payrolls; ln jsonb; w public.labour_piecework; n int := 0;
begin
  if v_seen is not null then return v_seen; end if;
  select * into pr from public.labour_payrolls where id = (p ->> 'payroll_id')::uuid for update;
  if not found then raise exception 'Payroll not found'; end if;
  perform app.require_member(pr.project_id);
  perform app.require_role_txt('site_engineer', 'office_engineer', 'coordinator', 'admin');
  if pr.status not in ('draft','returned') then raise exception 'Payroll % is % — quantities are verified before it is submitted', pr.number, pr.status; end if;
  for ln in select x from jsonb_array_elements(coalesce(p -> 'lines', '[]'::jsonb)) x loop
    select * into w from public.labour_piecework where id = (ln ->> 'id')::uuid and payroll_id = pr.id;
    if not found then raise exception 'Piece-work line not on payroll %', pr.number; end if;
    if (ln ->> 'qty_verified')::numeric is null or (ln ->> 'qty_verified')::numeric < 0 then raise exception 'Enter the verified quantity for "%"', w.description; end if;
    if (ln ->> 'qty_verified')::numeric > w.qty_claimed then
      raise exception '"%": verified % % is more than claimed %', w.description, (ln ->> 'qty_verified')::numeric, w.unit, w.qty_claimed;
    end if;
    update public.labour_piecework set qty_verified = (ln ->> 'qty_verified')::numeric, verified_by = auth.uid(), verified_at = now(),
      remark = coalesce(nullif(trim(ln ->> 'remark'), ''), remark) where id = w.id;
    n := n + 1;
  end loop;
  perform app.payroll_recalc(pr.id);
  perform app.pay_event(pr.project_id, 'payroll', pr.id, 'verify_quantities', pr.status, pr.status, n || ' piece-work line(s) verified');
  select * into pr from public.labour_payrolls where id = pr.id;
  return app.op_done(p, 'verify_piecework', jsonb_build_object('ok', true, 'verified', n, 'gross', pr.gross, 'net', pr.net));
end $$;

-- ---------------------------------------------------------------------------
-- Approval chain: submit (office engineer) → check (coordinator) → approve (manager, posts cost) → pay (finance)
-- ---------------------------------------------------------------------------
create or replace function app.post_certificate_cost(p_cert uuid) returns void
language plpgsql security definer set search_path = public as $$
declare c public.sc_certificates; s public.subcontracts; v_sub text; l record; n int := 0;
begin
  select * into c from public.sc_certificates where id = p_cert;
  select * into s from public.subcontracts where id = c.subcontract_id;
  select name into v_sub from public.subcontractors where id = s.subcontractor_id;
  for l in select cl.*, si.task_id, si.boq_item_id, si.description, si.unit from public.sc_certificate_lines cl
           join public.subcontract_items si on si.id = cl.subcontract_item_id where cl.certificate_id = p_cert and cl.amount_this <> 0
           order by si.line_no loop
    n := n + 1;
    perform app.pay_cost(c.project_id, c.number || '-CE' || n, c.period_to, 'subcontract', l.task_id, l.boq_item_id,
      v_sub || ': ' || l.description, v_sub, l.qty_verified_to_date - l.qty_previous, l.unit, l.rate, l.amount_this, 'invoice', c.number);
  end loop;
  -- charges against the subcontractor reduce the cost of the subcontract (materials are costed when issued)
  if c.material_deduction + c.penalty + c.other_deduction > 0 then
    perform app.pay_cost(c.project_id, c.number || '-CE' || (n + 1), c.period_to, 'subcontract', null, null,
      v_sub || ': deductions (materials supplied ' || c.material_deduction || ', penalty ' || c.penalty || ', other ' || c.other_deduction || ')',
      v_sub, null, null, null, -(c.material_deduction + c.penalty + c.other_deduction), 'invoice', c.number);
  end if;
end $$;

create or replace function app.post_payroll_cost(p_payroll uuid) returns void
language plpgsql security definer set search_path = public as $$
declare pr public.labour_payrolls; v_left numeric; v_tot_hc numeric; r record; n int := 0;
begin
  select * into pr from public.labour_payrolls where id = p_payroll;
  -- 0. piece-work goes to the task / BoQ item it was measured on
  for r in select pw.*, coalesce(pw.task_id, (select l.task_id from public.task_boq_links l where l.boq_item_id = pw.boq_item_id
                                                and l.deleted_at is null order by l.created_at limit 1)) as t
           from public.labour_piecework pw where pw.payroll_id = p_payroll and pw.amount <> 0 order by pw.work_date, pw.id loop
    n := n + 1;
    perform app.pay_cost(pr.project_id, pr.number || '-CE' || n, pr.period_to, 'labour', r.t, r.boq_item_id,
      'Piece-work ' || pr.number || ': ' || r.description, null, r.qty_verified, r.unit, r.rate, r.amount, 'payroll', pr.number);
  end loop;
  -- 1. attendance booked on a task
  for r in
    select a.task_id, sum(a.day_value * w.daily_rate + round(a.ot_hours * w.daily_rate / 8 * pr.ot_multiplier, 2)) as amt, sum(a.day_value) as days
    from public.labour_attendance a join public.labour_workers w on w.id = a.worker_id
    where a.payroll_id = p_payroll and a.task_id is not null group by a.task_id
  loop
    n := n + 1;
    perform app.pay_cost(pr.project_id, pr.number || '-CE' || n, pr.period_to, 'labour', r.task_id, null,
      'Daily labour ' || pr.number || ' (attendance)', null, r.days, 'man-day', null, r.amt, 'payroll', pr.number);
  end loop;
  v_left := pr.gross - coalesce((select sum(a.day_value * w.daily_rate + round(a.ot_hours * w.daily_rate / 8 * pr.ot_multiplier, 2))
    from public.labour_attendance a join public.labour_workers w on w.id = a.worker_id where a.payroll_id = p_payroll and a.task_id is not null), 0)
    - coalesce((select sum(amount) from public.labour_piecework where payroll_id = p_payroll), 0);
  if v_left <= 0 then return; end if;
  -- 2. the rest is spread over the activities the daily output reports manpower on in the period
  select sum(headcount) into v_tot_hc from public.diary_activities
   where project_id = pr.project_id and activity_date between pr.period_from and pr.period_to and deleted_at is null and coalesce(headcount, 0) > 0;
  if coalesce(v_tot_hc, 0) = 0 then
    perform app.pay_cost(pr.project_id, pr.number || '-CE' || (n + 1), pr.period_to, 'labour', null, null,
      'Daily labour ' || pr.number || ' (not allocated to activities)', null, null, null, null, v_left, 'payroll', pr.number);
    return;
  end if;
  for r in
    select task_id, sum(headcount) as hc from public.diary_activities
    where project_id = pr.project_id and activity_date between pr.period_from and pr.period_to and deleted_at is null and coalesce(headcount, 0) > 0
    group by task_id order by task_id
  loop
    n := n + 1;
    perform app.pay_cost(pr.project_id, pr.number || '-CE' || n, pr.period_to, 'labour', r.task_id, null,
      'Daily labour ' || pr.number || ' (by daily-output manpower)', null, r.hc, 'man-day', null, round(v_left * r.hc / v_tot_hc, 2), 'payroll', pr.number);
  end loop;
end $$;
revoke execute on function app.post_certificate_cost(uuid) from public;
revoke execute on function app.post_payroll_cost(uuid) from public;

create or replace function public.payment_action(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p);
  v_type text := p ->> 'doc_type';
  v_id uuid := (p ->> 'id')::uuid;
  v_action text := p ->> 'action';
  v_comment text := nullif(trim(p ->> 'comment'), '');
  v_project uuid; v_status text; v_number text; v_prep uuid; v_checked uuid; v_amount numeric; v_to text; v_label text;
begin
  if v_seen is not null then return v_seen; end if;
  if v_type = 'sc_certificate' then
    select project_id, status, number, prepared_by, checked_by, net_payable into v_project, v_status, v_number, v_prep, v_checked, v_amount
      from public.sc_certificates where id = v_id for update;
    v_label := 'Subcontractor certificate ' || v_number;
  elsif v_type = 'payroll' then
    select project_id, status, number, prepared_by, checked_by, net into v_project, v_status, v_number, v_prep, v_checked, v_amount
      from public.labour_payrolls where id = v_id for update;
    v_label := 'Labour payroll ' || v_number;
  else
    raise exception 'Unknown payment document type %', v_type;
  end if;
  if v_project is null then raise exception 'Payment document not found'; end if;
  perform app.require_member(v_project);

  if v_action = 'submit' then
    perform app.require_role_txt('office_engineer', 'coordinator', 'admin');
    if v_status not in ('draft','returned') then raise exception '% is % — only drafts can be submitted', v_label, v_status; end if;
    if v_type = 'sc_certificate' and not exists (select 1 from public.sc_certificate_lines where certificate_id = v_id and amount_this <> 0)
       and not exists (select 1 from public.sc_certificates where id = v_id and (is_final or retention_release > 0)) then
      raise exception 'Nothing to certify: no quantity was verified this period';
    end if;
    if v_type = 'payroll' and not exists (select 1 from public.labour_payroll_lines where payroll_id = v_id) then
      raise exception 'The payroll has no attendance or piece-work';
    end if;
    if v_type = 'payroll' and exists (select 1 from public.labour_piecework where payroll_id = v_id and qty_verified is null) then
      raise exception 'Piece-work quantities must be verified on site before the payroll is submitted';
    end if;
    v_to := 'submitted';
    perform app.notify_roles_txt(v_project, '{coordinator}', v_label || ' to check', 'Net ' || to_char(v_amount, 'FM999,999,999,990.00') || ' ETB', v_type, v_id);
  elsif v_action = 'check' then
    perform app.require_role_txt('coordinator', 'admin');
    if v_status <> 'submitted' then raise exception '% is % — only submitted documents can be checked', v_label, v_status; end if;
    if v_prep = auth.uid() and not app.has_role_txt('admin') then raise exception 'You prepared % — another person must check it', v_number using errcode = '42501'; end if;
    v_to := 'checked';
    perform app.notify_roles_txt(v_project, '{manager}', v_label || ' to approve', 'Checked · net ' || to_char(v_amount, 'FM999,999,999,990.00') || ' ETB', v_type, v_id);
  elsif v_action = 'approve' then
    perform app.require_role_txt('manager', 'admin');
    if v_status <> 'checked' then raise exception '% is % — it must be checked by the coordinator first', v_label, v_status; end if;
    if (v_prep = auth.uid() or v_checked = auth.uid()) and not app.has_role_txt('admin') then
      raise exception 'You prepared or checked % — the approver must be someone else', v_number using errcode = '42501';
    end if;
    v_to := 'approved';
    if v_type = 'sc_certificate' then perform app.post_certificate_cost(v_id); else perform app.post_payroll_cost(v_id); end if;
    perform app.notify_roles_txt(v_project, '{finance}', v_label || ' approved — to pay', 'Net payable ' || to_char(v_amount, 'FM999,999,999,990.00') || ' ETB', v_type, v_id);
    perform app.notify_user(v_prep, v_project, v_label || ' approved', null, v_type, v_id);
  elsif v_action = 'pay' then
    perform app.require_role_txt('finance', 'admin');
    if v_status <> 'approved' then raise exception '% is % — only approved documents can be paid', v_label, v_status; end if;
    if coalesce(p ->> 'payment_method', '') not in ('bank_transfer','cheque','cash') then raise exception 'Choose how it was paid'; end if;
    if (p ->> 'payment_date') is null or (p ->> 'payment_date')::date > app.eat_date(now()) then raise exception 'Enter the payment date (not in the future)'; end if;
    if p ->> 'payment_method' <> 'cash' and nullif(trim(p ->> 'payment_ref'), '') is null then raise exception 'Enter the transfer / cheque reference'; end if;
    v_to := 'paid';
    if v_type = 'sc_certificate' then
      update public.sc_certificates set paid_by = auth.uid(), paid_at = now(), payment_method = p ->> 'payment_method',
        payment_ref = nullif(trim(p ->> 'payment_ref'), ''), payment_date = (p ->> 'payment_date')::date where id = v_id;
    else
      update public.labour_payrolls set paid_by = auth.uid(), paid_at = now(), payment_method = p ->> 'payment_method',
        payment_ref = nullif(trim(p ->> 'payment_ref'), ''), payment_date = (p ->> 'payment_date')::date where id = v_id;
    end if;
    perform app.notify_user(v_prep, v_project, v_label || ' paid', coalesce(p ->> 'payment_ref', 'cash'), v_type, v_id);
    perform app.notify_roles_txt(v_project, '{coordinator}', v_label || ' paid', coalesce(p ->> 'payment_ref', 'cash'), v_type, v_id);
  elsif v_action in ('return', 'reject') then
    if v_comment is null then raise exception 'Say why it is %', case when v_action = 'return' then 'returned' else 'rejected' end; end if;
    if v_status = 'submitted' then perform app.require_role_txt('coordinator', 'manager', 'admin');
    elsif v_status = 'checked' then perform app.require_role_txt('manager', 'admin');
    else raise exception '% is % — it can no longer be %', v_label, v_status, case when v_action = 'return' then 'returned' else 'rejected' end;
    end if;
    v_to := case when v_action = 'return' then 'returned' else 'rejected' end;
    perform app.notify_user(v_prep, v_project, v_label || ' ' || v_to, v_comment, v_type, v_id);
  else
    raise exception 'Unknown action %', v_action;
  end if;

  if v_type = 'sc_certificate' then
    update public.sc_certificates set status = v_to,
      submitted_at = case when v_to = 'submitted' then now() else submitted_at end,
      checked_by = case when v_to = 'checked' then auth.uid() when v_to = 'submitted' then null else checked_by end,
      checked_at = case when v_to = 'checked' then now() when v_to = 'submitted' then null else checked_at end,
      approved_by = case when v_to = 'approved' then auth.uid() else approved_by end,
      approved_at = case when v_to = 'approved' then now() else approved_at end,
      return_comment = case when v_to in ('returned','rejected') then v_comment when v_to = 'submitted' then null else return_comment end
    where id = v_id;
  else
    update public.labour_payrolls set status = v_to,
      submitted_at = case when v_to = 'submitted' then now() else submitted_at end,
      checked_by = case when v_to = 'checked' then auth.uid() when v_to = 'submitted' then null else checked_by end,
      checked_at = case when v_to = 'checked' then now() when v_to = 'submitted' then null else checked_at end,
      approved_by = case when v_to = 'approved' then auth.uid() else approved_by end,
      approved_at = case when v_to = 'approved' then now() else approved_at end,
      return_comment = case when v_to in ('returned','rejected') then v_comment when v_to = 'submitted' then null else return_comment end
    where id = v_id;
  end if;
  perform app.pay_event(v_project, v_type, v_id, v_action, v_status, v_to,
    coalesce(v_comment, case when v_action = 'pay' then (p ->> 'payment_method') || coalesce(' ' || (p ->> 'payment_ref'), '') end));
  return app.op_done(p, 'payment_action', jsonb_build_object('ok', true, 'id', v_id, 'number', v_number, 'status', v_to));
end $$;

-- ---------------------------------------------------------------------------
-- Inbox (approvals registry) and reporting views
-- ---------------------------------------------------------------------------
create or replace function app.payments_approvals_for(p_user uuid)
returns table (kind text, entity_type text, entity_id uuid, project_id uuid, number text, title text, status text,
               requested_by uuid, requested_at timestamptz, is_urgent boolean, actions text[], age_hours numeric)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare v_role text;
begin
  select pr.role::text into v_role from public.profiles pr where pr.id = p_user and pr.is_active;
  if v_role is null or v_role not in ('office_engineer','coordinator','manager','finance','admin') then return; end if;
  return query
  with mem as (select pm.project_id as pid from public.project_members pm where pm.user_id = p_user
               union select pj.id from public.projects pj where v_role = 'admin'),
  docs as (
    select 'sc_certificate'::text as t, c.id, c.project_id, c.number, c.status, c.prepared_by, c.submitted_at, c.checked_at, c.approved_at, c.updated_at,
           (select sc.name from public.subcontracts k join public.subcontractors sc on sc.id = k.subcontractor_id where k.id = c.subcontract_id) as party,
           c.net_payable as net
    from public.sc_certificates c where c.project_id in (select pid from mem)
    union all
    select 'payroll', l.id, l.project_id, l.number, l.status, l.prepared_by, l.submitted_at, l.checked_at, l.approved_at, l.updated_at,
           'Daily labour · ' || l.workers || ' workers', l.net
    from public.labour_payrolls l where l.project_id in (select pid from mem))
  select 'payment'::text, d.t, d.id, d.project_id, d.number,
         d.party || ' · net ' || to_char(d.net, 'FM999,999,999,990.00') || ' ETB',
         d.status, d.prepared_by,
         coalesce(case d.status when 'submitted' then d.submitted_at when 'checked' then d.checked_at when 'approved' then d.approved_at end, d.updated_at),
         d.status = 'approved' and d.approved_at < now() - interval '7 days',
         array[case d.status when 'submitted' then 'check' when 'checked' then 'approve' when 'approved' then 'pay' else 'fix' end],
         round((extract(epoch from now() - coalesce(d.approved_at, d.checked_at, d.submitted_at, d.updated_at)) / 3600)::numeric, 1)
  from docs d
  where (d.status = 'submitted' and v_role in ('coordinator','admin'))
     or (d.status = 'checked' and v_role in ('manager','admin'))
     or (d.status = 'approved' and v_role in ('finance','admin'))
     or (d.status = 'returned' and d.prepared_by = p_user);
end $$;
insert into app.approval_sources (fn) values ('app.payments_approvals_for') on conflict do nothing;

create or replace view public.v_subcontracts with (security_invoker = true) as
select s.*, sc.name as subcontractor_name, sc.tin as subcontractor_tin, sc.vat_registered,
       coalesce((select sum(round(i.qty * i.rate, 2)) from public.subcontract_items i where i.subcontract_id = s.id and i.deleted_at is null), 0) as contract_value,
       coalesce((select c.gross_to_date from public.sc_certificates c where c.subcontract_id = s.id and c.status in ('approved','paid')
                 order by c.cert_no desc limit 1), 0) as certified_to_date,
       coalesce((select sum(c.net_payable) from public.sc_certificates c where c.subcontract_id = s.id and c.status = 'paid'), 0) as paid_to_date,
       coalesce((select sum(c.retention_this - c.retention_release) from public.sc_certificates c where c.subcontract_id = s.id and c.status in ('approved','paid')), 0) as retention_held,
       coalesce((select sum(c.advance_recovery_this) from public.sc_certificates c where c.subcontract_id = s.id and c.status in ('approved','paid')), 0) as advance_recovered,
       (select c.status from public.sc_certificates c where c.subcontract_id = s.id order by c.cert_no desc limit 1) as last_certificate_status
from public.subcontracts s join public.subcontractors sc on sc.id = s.subcontractor_id;

create or replace view public.v_payment_register with (security_invoker = true) as
select 'sc_certificate'::text as doc_type, c.id, c.project_id, c.number, sc.name as party, c.period_from, c.period_to, c.status,
       c.gross_this as gross, (c.retention_this - c.retention_release + c.advance_recovery_this + c.material_deduction + c.penalty + c.other_deduction) as deductions,
       c.vat_this as vat, c.wht_this as tax, c.net_payable as net, c.prepared_by, c.checked_by, c.approved_by, c.approved_at,
       c.paid_by, c.paid_at, c.payment_method, c.payment_ref, c.payment_date, c.created_at
from public.sc_certificates c join public.subcontracts s on s.id = c.subcontract_id join public.subcontractors sc on sc.id = s.subcontractor_id
union all
select 'payroll', l.id, l.project_id, l.number, 'Daily labour (' || l.workers || ' workers)', l.period_from, l.period_to, l.status,
       l.gross, l.deductions, 0, l.tax, l.net, l.prepared_by, l.checked_by, l.approved_by, l.approved_at,
       l.paid_by, l.paid_at, l.payment_method, l.payment_ref, l.payment_date, l.created_at
from public.labour_payrolls l;

grant select on public.v_subcontracts, public.v_payment_register to authenticated;

-- ---------------------------------------------------------------------------
-- Rebar in berga (one 12 m bar): alternative unit on every rebar spec, kept in step with the diameter
-- (spec_conversions: 1 berga = factor × the spec's base unit), so rebar can be requested / issued / counted in berga.
-- ---------------------------------------------------------------------------
create or replace function app.berga_factor(p_spec uuid) returns numeric
language sql stable security definer set search_path = public as $$
  select case lower(s.uom) when 'kg' then f.kg when 't' then round(f.kg / 1000, 6) when 'ton' then round(f.kg / 1000, 6)
                           when 'tonne' then round(f.kg / 1000, 6) end
  from public.material_specs s join public.materials m on m.id = s.material_id
  cross join lateral (select (regexp_match(s.grade || ' ' || coalesce(s.description, ''), '(?:Ø|ø|Φ|φ|dia\.?\s*)\s*(\d{1,2})', 'i'))[1]::numeric as d) dd
  cross join lateral (select round(12 * dd.d * dd.d / 162, 2) as kg) f
  where s.id = p_spec and dd.d between 6 and 40
    and (m.name ilike '%rebar%' or m.name ilike '%reinforc%' or m.category ilike '%reinforc%')
$$;

create or replace function app.trg_spec_berga() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_f numeric := app.berga_factor(new.id);
begin
  if v_f is not null and v_f > 0 then
    insert into public.spec_conversions (material_spec_id, alt_uom, factor) values (new.id, 'berga', v_f)
    on conflict (material_spec_id, alt_uom) do update set factor = excluded.factor, deleted_at = null;
  end if;
  return null;
end $$;
drop trigger if exists berga_unit on public.material_specs;
create trigger berga_unit after insert or update of grade, uom, description on public.material_specs
  for each row execute function app.trg_spec_berga();

insert into public.spec_conversions (material_spec_id, alt_uom, factor)
select s.id, 'berga', app.berga_factor(s.id) from public.material_specs s
 where app.berga_factor(s.id) > 0
on conflict (material_spec_id, alt_uom) do update set factor = excluded.factor, deleted_at = null;


-- >>>>>>>>>>>>>>>>>>>> 20261103000020_material_costing.sql

-- =============================================================================
-- Material costing: materials are a cost when USED, not when bought.
--
-- Practice (construction cost accounting / EVM):
--   * Material received into a site store is inventory (an asset), not cost. Purchase orders are commitments.
--   * Cost is recognised when material is issued to the work (MIV), at the store's carrying cost; returns (MRN)
--     credit it back; wastage, damage, loss, write-off and stock-count variances are cost (or gain) when
--     approved. EVM actual cost (AC) for materials = consumption at cost.
--   * Valuation method: perpetual MOVING WEIGHTED AVERAGE per project × material spec (all stores of a site
--     share one cost pool, so transfers between its stores are cost-neutral). Chosen over FIFO because site
--     stock of bulk materials (cement, rebar, aggregate) is physically mixed, average cost is what Ethiopian
--     contractors' stock ledgers and the IFRS/IAS 2 "weighted average" option use, and it is stable for EVM.
--   * Receipts are valued at the PO line unit price ex-VAT (input VAT is recoverable); no PO → standard
--     price (spec_prices); opening stock → standard price. Rejected / quarantined material is not valued.
--   * Reversals carry exactly the cost of the row they reverse. Cross-project transfers carry the cost of the
--     sending project.
--
-- Money lives in price-restricted tables (stock_ledger_costs, stock_cost_pool); the stock ledger itself stays
-- quantity-only so non-price roles never see values.
-- =============================================================================

create table if not exists public.stock_cost_pool (
  project_id        uuid not null references public.projects (id),
  material_spec_id  uuid not null references public.material_specs (id),
  qty               numeric(16,3) not null default 0,
  value             numeric(18,2) not null default 0,
  avg_cost          numeric(18,4),
  updated_at        timestamptz not null default now(),
  primary key (project_id, material_spec_id)
);

create table if not exists public.stock_ledger_costs (
  ledger_id         uuid primary key references public.stock_ledger (id),
  project_id        uuid not null references public.projects (id),
  material_spec_id  uuid not null references public.material_specs (id),
  cost_kind         text not null check (cost_kind in
                      ('receipt','opening','issue','return','wastage','loss','count','transfer','gate','quarantine','other')),
  is_consumption    boolean not null default false,   -- counts as actual material cost (AC)
  unit_cost         numeric(18,4),                     -- null = could not be valued (no PO price, no standard price, empty pool)
  value             numeric(18,2) not null default 0,  -- signed like qty: + into stock, − out of stock
  pool_qty_after    numeric(16,3),
  pool_avg_after    numeric(18,4),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create index if not exists stock_ledger_costs_project_idx on public.stock_ledger_costs (project_id, material_spec_id);
create index if not exists stock_ledger_costs_updated_at_idx on public.stock_ledger_costs (updated_at);

alter table public.stock_cost_pool enable row level security;
alter table public.stock_ledger_costs enable row level security;
drop policy if exists price_read on public.stock_cost_pool;
create policy price_read on public.stock_cost_pool for select to authenticated using (app.can_see_prices() and app.is_member(project_id));
drop policy if exists price_read on public.stock_ledger_costs;
create policy price_read on public.stock_ledger_costs for select to authenticated using (app.can_see_prices() and app.is_member(project_id));

-- -----------------------------------------------------------------------------
-- Value one ledger row (moving average). Called by the insert trigger and by the back-fill.
-- -----------------------------------------------------------------------------
create or replace function app.cost_ledger_row(l public.stock_ledger) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_kind text; v_cons boolean := false; v_unit numeric; v_val numeric; v_std numeric;
  o public.stock_ledger_costs; p public.stock_cost_pool; v_adj text;
begin
  if exists (select 1 from public.stock_ledger_costs where ledger_id = l.id) then return; end if;

  if l.txn_type = 'reversal' then
    select * into o from public.stock_ledger_costs where ledger_id = l.reversal_of;
    v_kind := coalesce(o.cost_kind, 'other'); v_cons := coalesce(o.is_consumption, false);
  elsif l.stock_status = 'quarantine' then v_kind := 'quarantine';
  elsif l.txn_type = 'grn' then v_kind := 'receipt';
  elsif l.txn_type = 'opening' then v_kind := 'opening';
  elsif l.txn_type = 'miv' then v_kind := 'issue'; v_cons := true;
  elsif l.txn_type = 'mrn' then v_kind := 'return'; v_cons := true;
  elsif l.txn_type in ('transfer_in','transfer_out') then v_kind := 'transfer';
  elsif l.txn_type in ('gate_in','gate_out') then v_kind := 'gate';
  elsif l.txn_type = 'adjustment' then
    select a.adj_type into v_adj from public.adjustments a where a.id = l.doc_id;
    v_kind := case v_adj when 'wastage' then 'wastage' when 'count_variance' then 'count' else 'loss' end;
    v_cons := true;
  else v_kind := 'other';
  end if;

  if v_kind = 'quarantine' or (l.txn_type = 'reversal' and o.cost_kind = 'quarantine') then
    insert into public.stock_ledger_costs (ledger_id, project_id, material_spec_id, cost_kind, is_consumption, unit_cost, value)
    values (l.id, l.project_id, l.material_spec_id, 'quarantine', false, null, 0);
    return;
  end if;

  insert into public.stock_cost_pool (project_id, material_spec_id) values (l.project_id, l.material_spec_id)
  on conflict do nothing;
  select * into p from public.stock_cost_pool
   where project_id = l.project_id and material_spec_id = l.material_spec_id for update;
  select sp.unit_price into v_std from public.spec_prices sp where sp.material_spec_id = l.material_spec_id;

  if l.txn_type = 'reversal' and o.ledger_id is not null then
    v_unit := o.unit_cost;
  elsif v_kind = 'receipt' then
    select pr.unit_price into v_unit from public.grn_lines gl join public.po_line_prices pr on pr.po_line_id = gl.po_line_id
     where gl.id = l.doc_line_id;
    v_unit := coalesce(v_unit, v_std, p.avg_cost);
  elsif v_kind = 'opening' then
    v_unit := coalesce(v_std, p.avg_cost);
  elsif l.txn_type = 'transfer_in' then
    select c.unit_cost into v_unit from public.stock_ledger x join public.stock_ledger_costs c on c.ledger_id = x.id
     where x.doc_id = l.doc_id and x.txn_type = 'transfer_out' and x.material_spec_id = l.material_spec_id
     order by x.created_at desc limit 1;
    v_unit := coalesce(v_unit, p.avg_cost, v_std);
  else
    v_unit := coalesce(p.avg_cost, v_std);
  end if;

  v_val := round(l.qty * coalesce(v_unit, 0), 2);
  update public.stock_cost_pool
     set qty = qty + l.qty,
         value = case when qty + l.qty <= 0 then 0 else value + v_val end,
         avg_cost = case when qty + l.qty > 0 then round((value + v_val) / (qty + l.qty), 4) else avg_cost end,
         updated_at = now()
   where project_id = l.project_id and material_spec_id = l.material_spec_id
  returning * into p;

  insert into public.stock_ledger_costs (ledger_id, project_id, material_spec_id, cost_kind, is_consumption, unit_cost, value,
    pool_qty_after, pool_avg_after)
  values (l.id, l.project_id, l.material_spec_id, v_kind, v_cons, round(v_unit, 4), v_val, p.qty, p.avg_cost);
end $$;
revoke execute on function app.cost_ledger_row(public.stock_ledger) from public;

create or replace function app.trg_stock_cost() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  perform app.cost_ledger_row(new);
  return null;
end $$;
drop trigger if exists stock_cost on public.stock_ledger;
create trigger stock_cost after insert on public.stock_ledger
  for each row execute function app.trg_stock_cost();

-- Back-fill existing ledgers in posting order.
do $$
declare l public.stock_ledger;
begin
  for l in select * from public.stock_ledger s
           where not exists (select 1 from public.stock_ledger_costs c where c.ledger_id = s.id)
           order by s.txn_at, s.created_at, s.id loop
    perform app.cost_ledger_row(l);
  end loop;
end $$;

-- -----------------------------------------------------------------------------
-- EVM actual cost: material consumption at cost (issues − returns + wastage/loss/count), allocated to tasks
-- exactly as before (element ∧ BoQ → element → BoQ item → unallocated).
-- -----------------------------------------------------------------------------
create or replace function app.material_alloc(p_project uuid)
returns table (project_id uuid, ledger_id uuid, txn_date date, element_id uuid, material_spec_id uuid,
               boq_item_id uuid, task_id uuid, share numeric, qty numeric, amount numeric)
language sql stable security definer set search_path = public as $$
  with led as (
    select l.id, l.project_id, app.eat_date(l.txn_at) as txn_date, l.element_id, l.material_spec_id,
           coalesce(ml.boq_item_id, et.boq_item_id) as boq_item_id, -l.qty as qty, -c.value as amount
    from public.stock_ledger l
    join public.stock_ledger_costs c on c.ledger_id = l.id and c.is_consumption
    left join public.mr_lines ml on ml.id = l.mr_line_id
    left join public.element_takeoffs et on et.element_id = l.element_id and et.material_spec_id = l.material_spec_id
      and et.deleted_at is null
    where l.project_id = p_project),
  tk as (
    select t.id from public.schedule_tasks t join public.schedules s on s.id = t.schedule_id and s.status = 'active'
    where t.project_id = p_project and t.deleted_at is null and not t.is_summary),
  el as (select x.task_id, x.element_id, coalesce(x.weight, 1) as w from public.task_element_links x
         join tk on tk.id = x.task_id where x.deleted_at is null),
  bl as (select x.task_id, x.boq_item_id, coalesce(nullif(x.qty_share, 0), 1) as w from public.task_boq_links x
         join tk on tk.id = x.task_id where x.deleted_at is null),
  cand as (
    select led.id as ledger_id, 1 as lvl, el.task_id, bl.w from led
      join el on el.element_id = led.element_id
      join bl on bl.task_id = el.task_id and bl.boq_item_id = led.boq_item_id
    union all
    select led.id, 2, el.task_id, el.w from led join el on el.element_id = led.element_id
    union all
    select led.id, 3, bl.task_id, bl.w from led join bl on bl.boq_item_id = led.boq_item_id),
  best as (select ledger_id, min(lvl) as lvl from cand group by ledger_id),
  pick as (
    select c.ledger_id, c.task_id, c.w / sum(c.w) over (partition by c.ledger_id) as share
    from cand c join best b on b.ledger_id = c.ledger_id and b.lvl = c.lvl)
  select led.project_id, led.id, led.txn_date, led.element_id, led.material_spec_id, led.boq_item_id,
         pick.task_id, coalesce(pick.share, 1), round(led.qty * coalesce(pick.share, 1), 3),
         round(led.amount * coalesce(pick.share, 1), 2)
  from led left join pick on pick.ledger_id = led.id
$$;

-- -----------------------------------------------------------------------------
-- Cost control: budget vs committed (open POs) vs received into stock vs USED (actual cost).
-- Same columns as before (issued = used); remaining = budget − used; pct_used = used / budget.
-- Appended: used, remaining_uncommitted = budget − max(received, used) − committed (what is still free to buy).
-- -----------------------------------------------------------------------------
create or replace view public.v_cost_control with (security_invoker = true) as
with facts as (
  select c.project_id, c.material_spec_id, c.boq_item_id, c.committed_value as committed, 0::numeric as received, 0::numeric as used
  from public.v_committed_cost c
  union all
  select l.project_id, l.material_spec_id, ml.boq_item_id, 0, c.value, 0
  from public.stock_ledger l join public.stock_ledger_costs c on c.ledger_id = l.id and c.cost_kind = 'receipt'
  left join public.mr_lines ml on ml.id = l.mr_line_id
  union all
  select l.project_id, l.material_spec_id, coalesce(ml.boq_item_id, et.boq_item_id), 0, 0, -c.value
  from public.stock_ledger l join public.stock_ledger_costs c on c.ledger_id = l.id and c.is_consumption
  left join public.mr_lines ml on ml.id = l.mr_line_id
  left join public.element_takeoffs et on et.element_id = l.element_id and et.material_spec_id = l.material_spec_id and et.deleted_at is null
),
f as (select facts.*, sp.category from facts join public.v_specs sp on sp.id = facts.material_spec_id),
g as (
  select b.id as budget_line_id, b.project_id,
         case when b.boq_item_id is not null then 'boq_item' when b.material_spec_id is not null then 'material' else 'category' end as scope,
         b.boq_item_id, bi.item_no as boq_item_no, b.material_spec_id, sp.label, coalesce(b.category, sp.category) as category,
         coalesce(b.description, bi.description, sp.label, b.category) as description,
         b.budget_qty, b.budget_rate, b.budget_amount,
         coalesce(sum(f.committed), 0) as committed, coalesce(sum(f.received), 0) as received, coalesce(sum(f.used), 0) as used
  from public.budget_lines b
  left join public.boq_items bi on bi.id = b.boq_item_id
  left join public.v_specs sp on sp.id = b.material_spec_id
  left join f on f.project_id = b.project_id and (
         (b.boq_item_id is not null and f.boq_item_id = b.boq_item_id
            and (b.material_spec_id is null or f.material_spec_id = b.material_spec_id))
      or (b.boq_item_id is null and b.material_spec_id is not null and f.material_spec_id = b.material_spec_id)
      or (b.boq_item_id is null and b.material_spec_id is null and f.category = b.category))
  where b.deleted_at is null
  group by b.id, bi.item_no, bi.description, sp.label, sp.category)
select budget_line_id, project_id, scope, boq_item_id, boq_item_no, material_spec_id, label, category, description,
       budget_qty, budget_rate, budget_amount,
       round(committed, 2) as committed, round(received, 2) as received, round(used, 2) as issued,
       round(budget_amount - used, 2) as remaining,
       round(100 * used / nullif(budget_amount, 0), 1) as pct_used,
       round(used, 2) as used,
       round(budget_amount - greatest(received, used) - committed, 2) as remaining_uncommitted
from g;

-- -----------------------------------------------------------------------------
-- Material actuals without budget lines: per project × spec × BoQ item (price roles).
-- -----------------------------------------------------------------------------
create or replace view public.v_material_cost with (security_invoker = true) as
with x as (
  select c.project_id, c.material_spec_id, c.boq_item_id, c.committed_value as committed,
         0::numeric as received_qty, 0::numeric as received_value, 0::numeric as issued_qty, 0::numeric as used_value,
         0::numeric as wastage_qty, 0::numeric as wastage_value
  from public.v_committed_cost c
  union all
  select l.project_id, l.material_spec_id,
         case when k.cost_kind = 'receipt' then ml.boq_item_id else coalesce(ml.boq_item_id, et.boq_item_id) end,
         0,
         case when k.cost_kind = 'receipt' then l.qty else 0 end,
         case when k.cost_kind = 'receipt' then k.value else 0 end,
         case when k.cost_kind in ('issue','return') then -l.qty else 0 end,
         case when k.is_consumption then -k.value else 0 end,
         case when k.cost_kind in ('wastage','loss') then -l.qty else 0 end,
         case when k.cost_kind in ('wastage','loss') then -k.value else 0 end
  from public.stock_ledger l
  join public.stock_ledger_costs k on k.ledger_id = l.id and (k.cost_kind = 'receipt' or k.is_consumption)
  left join public.mr_lines ml on ml.id = l.mr_line_id
  left join public.element_takeoffs et on et.element_id = l.element_id and et.material_spec_id = l.material_spec_id and et.deleted_at is null
)
select x.project_id, x.material_spec_id, sp.label, sp.category, sp.uom, x.boq_item_id, bi.item_no as boq_item_no,
       bi.description as boq_description, ms.wastage_pct as allowance_pct,
       round(sum(x.committed), 2) as committed, round(sum(x.received_qty), 3) as received_qty, round(sum(x.received_value), 2) as received_value,
       round(sum(x.issued_qty), 3) as issued_qty, round(sum(x.used_value), 2) as used_value,
       round(sum(x.wastage_qty), 3) as wastage_qty, round(sum(x.wastage_value), 2) as wastage_value
from x
join public.v_specs sp on sp.id = x.material_spec_id
join public.material_specs ms on ms.id = x.material_spec_id
left join public.boq_items bi on bi.id = x.boq_item_id
where app.can_see_prices() and app.is_member(x.project_id)
group by x.project_id, x.material_spec_id, sp.label, sp.category, sp.uom, x.boq_item_id, bi.item_no, bi.description, ms.wastage_pct;

-- Inventory on hand at average cost, per store (price roles). Quarantined stock is not valued.
create or replace view public.v_inventory_value with (security_invoker = true) as
select l.project_id, l.store_id, s.name as store_name, l.material_spec_id, sp.label, sp.category, sp.uom,
       round(sum(l.qty), 3) as qty, p.avg_cost, round(sum(l.qty) * coalesce(p.avg_cost, 0), 2) as value
from public.stock_ledger l
join public.stores s on s.id = l.store_id
join public.v_specs sp on sp.id = l.material_spec_id
left join public.stock_cost_pool p on p.project_id = l.project_id and p.material_spec_id = l.material_spec_id
where l.stock_status in ('available','on_loan') and app.can_see_prices() and app.is_member(l.project_id)
group by l.project_id, l.store_id, s.name, l.material_spec_id, sp.label, sp.category, sp.uom, p.avg_cost
having abs(sum(l.qty)) > 0.0005;

-- Ledger with cost per movement (bin card with values), price roles.
create or replace view public.v_stock_ledger_value with (security_invoker = true) as
select l.id, l.project_id, l.store_id, l.material_spec_id, l.qty, l.stock_status, l.txn_type, l.doc_type, l.doc_id, l.doc_number,
       l.element_id, l.txn_at, c.cost_kind, c.is_consumption, c.unit_cost, c.value, c.pool_qty_after, c.pool_avg_after
from public.stock_ledger l
join public.stock_ledger_costs c on c.ledger_id = l.id
where app.can_see_prices() and app.is_member(l.project_id);

grant select on public.v_cost_control, public.v_material_cost, public.v_inventory_value, public.v_stock_ledger_value to authenticated;
grant select on public.stock_cost_pool, public.stock_ledger_costs to authenticated;


-- >>>>>>>>>>>>>>>>>>>> 20261103000030_schedule_editing.sql

-- =============================================================================
-- Schedule editing in the app (MS Project-like) + resources.
--
--  * edit_schedule(p): add task / milestone / summary, rename, duration, start (→ SNET), constraints, deadline,
--    notes, indent / outdent / move, delete (refused when the task carries progress, cost, BoQ links or
--    assignments), links (FS/SS/FF/SF, lag in days or % of the predecessor), "Predecessors" column
--    (set_predecessors). After every edit: renumber (outline numbers, sort order), re-plan with CPM
--    (planned dates of not-started tasks), forecast again, summaries rolled up.
--  * Every edit is logged in schedule_edits (who / when / what) with a snapshot of the schedule before it,
--    so undo_schedule_edit restores the last edit (until the next MS Project import).
--  * Resources: schedule_resources (labour / crew / equipment / material, max units, link to labour trade or
--    material spec) + price-restricted rates; task_assignments; v_task_resource_cost; get_resource_usage
--    (weekly demand vs capacity, over-allocation, tasks with float that could move); set_baseline with
--    cost_source 'resources' (task BAC cost = assignment cost, value-based where a task has none).
--
-- Re-import rule (MS Project stays the master): the file wins. Imported tasks take the file's values; tasks
-- and links created in the app that are not in the file are removed like any task missing from the file
-- (kept as "removed from schedule" when they carry progress). The import wizard warns about tasks edited or
-- created in the app since the last import. To keep in-app changes, export to MS Project XML (UIDs are kept),
-- open it in MS Project and import that file.
-- =============================================================================

alter table public.schedule_tasks add column if not exists origin text not null default 'import';
alter table public.schedule_tasks add column if not exists edited_at timestamptz;
alter table public.schedule_tasks add column if not exists edited_by uuid references public.profiles (id);
alter table public.schedule_links add column if not exists origin text not null default 'import';
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'schedule_tasks_origin_check') then
    alter table public.schedule_tasks add constraint schedule_tasks_origin_check check (origin in ('import','app'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'schedule_links_origin_check') then
    alter table public.schedule_links add constraint schedule_links_origin_check check (origin in ('import','app'));
  end if;
end $$;

create table if not exists public.schedule_edits (
  id           uuid primary key default gen_random_uuid(),
  project_id   uuid not null references public.projects (id) on delete cascade,
  schedule_id  uuid not null references public.schedules (id) on delete cascade,
  action       text not null,
  task_id      uuid references public.schedule_tasks (id),
  summary      text not null,
  detail       jsonb not null default '{}'::jsonb,
  snapshot     jsonb,                  -- schedule before the edit (undo); trimmed to the last 30 edits
  version_id   uuid references public.schedule_versions (id),
  moved        int not null default 0, -- tasks whose planned dates changed
  undone_at    timestamptz,
  undone_by    uuid references public.profiles (id),
  created_by   uuid not null references public.profiles (id),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index if not exists schedule_edits_sched_idx on public.schedule_edits (schedule_id, created_at desc);

create table if not exists public.schedule_resources (
  id               uuid primary key default gen_random_uuid(),
  project_id       uuid not null references public.projects (id) on delete cascade,
  code             text not null,
  name             text not null,
  kind             text not null check (kind in ('labour','crew','equipment','material')),
  unit             text not null default 'day',     -- labour/equipment: people or machines per day; material: quantity unit
  max_units        numeric(10,2) not null default 1 check (max_units > 0),
  labour_trade_id  uuid references public.labour_trades (id),
  material_spec_id uuid references public.material_specs (id),
  notes            text,
  is_active        boolean not null default true,
  created_by       uuid references public.profiles (id),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  deleted_at       timestamptz,
  unique (project_id, code)
);

-- Price data: only price roles read it (RLS), like boq_rates.
create table if not exists public.schedule_resource_rates (
  resource_id   uuid primary key references public.schedule_resources (id) on delete cascade,
  project_id    uuid not null references public.projects (id) on delete cascade,
  std_rate      numeric(18,2) not null default 0 check (std_rate >= 0),   -- per day (labour/equipment) or per unit (material)
  cost_per_use  numeric(18,2) not null default 0 check (cost_per_use >= 0),
  updated_at    timestamptz not null default now()
);

create table if not exists public.task_assignments (
  id           uuid primary key default gen_random_uuid(),
  project_id   uuid not null references public.projects (id) on delete cascade,
  schedule_id  uuid not null references public.schedules (id) on delete cascade,
  task_id      uuid not null references public.schedule_tasks (id),
  resource_id  uuid not null references public.schedule_resources (id),
  units        numeric(12,3) not null check (units > 0),   -- per working day (labour/equipment) or total quantity (material)
  notes        text,
  created_by   uuid references public.profiles (id),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  deleted_at   timestamptz
);
create unique index if not exists task_assignments_uniq on public.task_assignments (task_id, resource_id) where deleted_at is null;
create index if not exists task_assignments_sched_idx on public.task_assignments (schedule_id) where deleted_at is null;

do $$
declare t text;
begin
  foreach t in array array['schedule_edits','schedule_resources','schedule_resource_rates','task_assignments'] loop
    execute format('drop trigger if exists touch_updated_at on public.%I', t);
    execute format('create trigger touch_updated_at before update on public.%I for each row execute function app.touch_updated_at()', t);
    execute format('alter table public.%I enable row level security', t);
  end loop;
  foreach t in array array['schedule_resources','task_assignments'] loop
    execute format('drop trigger if exists audit on public.%I', t);
    execute format('create trigger audit after insert or update or delete on public.%I for each row execute function app.audit()', t);
  end loop;
end $$;

drop policy if exists member_read on public.schedule_edits;
create policy member_read on public.schedule_edits for select to authenticated using (app.is_member(project_id));
drop policy if exists member_read on public.schedule_resources;
create policy member_read on public.schedule_resources for select to authenticated using (app.is_member(project_id));
drop policy if exists member_read on public.task_assignments;
create policy member_read on public.task_assignments for select to authenticated using (app.is_member(project_id));
drop policy if exists price_read on public.schedule_resource_rates;
create policy price_read on public.schedule_resource_rates for select to authenticated using (app.is_member(project_id) and app.can_see_prices());

-- Resource cost per assignment. Rates are RLS-restricted, so cost is null for roles without price access.
create or replace view public.v_task_resource_cost with (security_invoker = true) as
select a.id as assignment_id, a.project_id, a.schedule_id, a.task_id, a.resource_id, r.code, r.name, r.kind, r.unit, a.units,
       case when r.kind = 'material' then a.units else round(a.units * greatest(coalesce(t.duration_days, 0), 0), 3) end as work,
       rt.std_rate, rt.cost_per_use,
       case when rt.resource_id is null then null
            else round(case when r.kind = 'material' then a.units * rt.std_rate
                            else a.units * greatest(coalesce(t.duration_days, 0), 0) * rt.std_rate end + rt.cost_per_use, 2) end as cost
from public.task_assignments a
join public.schedule_resources r on r.id = a.resource_id
join public.schedule_tasks t on t.id = a.task_id and t.deleted_at is null
left join public.schedule_resource_rates rt on rt.resource_id = r.id
where a.deleted_at is null;
grant select on public.v_task_resource_cost to authenticated;

-- -----------------------------------------------------------------------------
-- Helpers
-- -----------------------------------------------------------------------------

-- Schedule state an edit can change (tasks + links), for undo.
create or replace function app.schedule_snapshot(p_schedule uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'tasks', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'parent_id', t.parent_id, 'sort_order', t.sort_order,
        'outline_level', t.outline_level, 'outline_number', t.outline_number, 'wbs', t.wbs, 'name', t.name, 'notes', t.notes,
        'is_summary', t.is_summary, 'is_milestone', t.is_milestone, 'planned_start', t.planned_start, 'planned_finish', t.planned_finish,
        'duration_days', t.duration_days, 'constraint_type', t.constraint_type, 'constraint_date', t.constraint_date,
        'deadline', t.deadline, 'ev_method', t.ev_method, 'deleted_at', t.deleted_at, 'edited_at', t.edited_at, 'edited_by', t.edited_by))
      from public.schedule_tasks t where t.schedule_id = p_schedule), '[]'::jsonb),
    'links', coalesce((select jsonb_agg(jsonb_build_object('id', l.id, 'link_type', l.link_type, 'lag_days', l.lag_days,
        'lag_elapsed', l.lag_elapsed, 'deleted_at', l.deleted_at))
      from public.schedule_links l where l.schedule_id = p_schedule), '[]'::jsonb));
$$;

-- Outline numbers, levels, sort order and summary flags from the parent tree (siblings keep their order).
create or replace function app.renumber_schedule(p_schedule uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_lvl int;
begin
  with recursive sib as (
    select id, parent_id, row_number() over (partition by parent_id order by sort_order, msp_uid)::int as pos
    from public.schedule_tasks where schedule_id = p_schedule and deleted_at is null),
  tr as (
    select s.id, 1 as lvl, array[s.pos] as path from sib s where s.parent_id is null
    union all
    select s.id, tr.lvl + 1, tr.path || s.pos from sib s join tr on s.parent_id = tr.id),
  ord as (select id, lvl, path, row_number() over (order by path)::int as rn from tr)
  update public.schedule_tasks t set outline_level = o.lvl, outline_number = array_to_string(o.path, '.'), sort_order = o.rn
  from ord o where t.id = o.id
    and (t.outline_level, t.outline_number, t.sort_order) is distinct from (o.lvl, array_to_string(o.path, '.'), o.rn);
  -- tasks created in the app: WBS = parent's WBS (or outline number) + position among its siblings (parents first)
  for v_lvl in select distinct outline_level from public.schedule_tasks
               where schedule_id = p_schedule and deleted_at is null and origin = 'app' order by 1 loop
    update public.schedule_tasks t set wbs = coalesce(coalesce(pt.wbs, pt.outline_number) || '.', '') || x.pos
    from (select id, parent_id, row_number() over (partition by parent_id order by sort_order) as pos
          from public.schedule_tasks where schedule_id = p_schedule and deleted_at is null) x
    left join public.schedule_tasks pt on pt.id = x.parent_id
    where t.id = x.id and t.origin = 'app' and t.outline_level = v_lvl
      and t.wbs is distinct from coalesce(coalesce(pt.wbs, pt.outline_number) || '.', '') || x.pos;
  end loop;
  update public.schedule_tasks t set is_summary = x.has_kids,
         duration_days = case when not x.has_kids and t.is_summary then greatest(1, coalesce(app.la_wd(t.project_id, t.planned_start, t.planned_finish), 1)) else t.duration_days end
  from (select p.id, exists (select 1 from public.schedule_tasks c where c.parent_id = p.id and c.deleted_at is null) as has_kids
        from public.schedule_tasks p where p.schedule_id = p_schedule and p.deleted_at is null) x
  where t.id = x.id and t.is_summary is distinct from x.has_kids;
end $$;

-- Planned dates from the logic: CPM from the project start (no progress date), copied to the not-started tasks
-- driven by the edit (the seeds and everything after them through the links; all tasks when p_seeds is null),
-- so one edit does not re-date unrelated work whose imported dates differ from the app calendar (holidays);
-- summaries rolled up; then the forecast at the schedule's status date. Returns how many tasks moved.
create or replace function app.replan_schedule(p_schedule uuid, p_seeds uuid[] default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  sc public.schedules; v_start date; v_before jsonb; v_moved int; v_lvl int; v_fc jsonb; v_status date; v_scope uuid[];
begin
  select * into sc from public.schedules where id = p_schedule;
  v_status := coalesce(sc.status_date, app.eat_date(now()));
  select coalesce(sc.planned_start, min(planned_start)) into v_start from public.schedule_tasks
   where schedule_id = p_schedule and deleted_at is null;
  v_start := coalesce(v_start, app.eat_date(now()));
  select coalesce(jsonb_object_agg(id, jsonb_build_array(planned_start, planned_finish)), '{}'::jsonb) into v_before
    from public.schedule_tasks where schedule_id = p_schedule and deleted_at is null and not is_summary;

  if p_seeds is not null then
    with recursive dn as (
      select x as id from unnest(p_seeds) x
      union
      select l.succ_task_id from public.schedule_links l join dn on l.pred_task_id = dn.id
       where l.schedule_id = p_schedule and l.deleted_at is null)
    select coalesce(array_agg(id), '{}') into v_scope from dn;
  end if;
  perform app.run_cpm(p_schedule, v_start - 1, true);
  update public.schedule_tasks set planned_start = forecast_start, planned_finish = forecast_finish
   where schedule_id = p_schedule and deleted_at is null and not is_summary and actual_start is null and pct_complete = 0
     and (v_scope is null or id = any (v_scope))
     and forecast_start is not null and (planned_start, planned_finish) is distinct from (forecast_start, forecast_finish);
  for v_lvl in select distinct outline_level from public.schedule_tasks
               where schedule_id = p_schedule and is_summary and deleted_at is null order by 1 desc loop
    update public.schedule_tasks s set planned_start = x.ps, planned_finish = x.pf,
           duration_days = app.la_wd(s.project_id, x.ps, x.pf)
    from (select c.parent_id, min(c.planned_start) ps, max(c.planned_finish) pf from public.schedule_tasks c
          where c.schedule_id = p_schedule and c.deleted_at is null and c.parent_id is not null group by c.parent_id) x
    where s.id = x.parent_id and s.outline_level = v_lvl and s.is_summary and s.deleted_at is null;
  end loop;
  update public.schedules s set planned_start = x.ps, planned_finish = x.pf
    from (select min(planned_start) ps, max(planned_finish) pf from public.schedule_tasks where schedule_id = p_schedule and deleted_at is null) x
   where s.id = p_schedule;
  v_fc := app.run_cpm(p_schedule, v_status, true);
  select count(*) into v_moved from public.schedule_tasks t
   where t.schedule_id = p_schedule and t.deleted_at is null and not t.is_summary
     and v_before ? t.id::text and (v_before -> t.id::text) <> jsonb_build_array(t.planned_start, t.planned_finish);
  return jsonb_build_object('moved', v_moved, 'planned_finish', (select planned_finish from public.schedules where id = p_schedule),
    'fc_finish', v_fc -> 'fc_finish', 'critical_count', v_fc -> 'critical_count');
end $$;

-- Why a task cannot become a summary (its links, progress, measurement and resources belong to detailed work).
create or replace function app.summary_blocker(p_task uuid) returns text
language sql stable security definer set search_path = public as $$
  select case
    when exists (select 1 from public.task_progress where task_id = p_task and status <> 'rejected') or
         exists (select 1 from public.schedule_tasks where id = p_task and (pct_complete > 0 or actual_start is not null)) then 'it has progress'
    when exists (select 1 from public.task_boq_links where task_id = p_task and deleted_at is null) then 'it is linked to BoQ items'
    when exists (select 1 from public.task_element_links where task_id = p_task and (to_jsonb(task_element_links) ->> 'deleted_at') is null) then 'it is linked to elements'
    when exists (select 1 from public.task_assignments where task_id = p_task and deleted_at is null) then 'it has resources assigned'
    when exists (select 1 from public.schedule_links where (pred_task_id = p_task or succ_task_id = p_task) and deleted_at is null) then 'it has predecessors or successors'
  end;
$$;

create or replace function app.check_no_cycle(p_schedule uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  perform app.run_cpm(p_schedule, app.eat_date(now()), false);
exception when others then
  if sqlerrm like '%loop%' then raise exception 'That link would make a loop in the logic (%).', substring(sqlerrm from 'UIDs: (.*)$'); end if;
  raise;
end $$;

-- -----------------------------------------------------------------------------
-- RPC: edit_schedule
-- -----------------------------------------------------------------------------
create or replace function public.edit_schedule(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p);
  v_act text := p ->> 'action';
  v_task uuid := nullif(p ->> 'task_id', '')::uuid;
  sc public.schedules; t public.schedule_tasks; a public.schedule_tasks; par public.schedule_tasks; nb public.schedule_tasks;
  v_new uuid; v_edit uuid := gen_random_uuid(); v_snap jsonb; v_summary text; v_plan jsonb; v_why text;
  v_kind text; v_uid int; v_dur numeric; v_start date; v_ids uuid[]; v_n int; v_pred public.schedule_tasks; v_succ public.schedule_tasks;
  v_type text; v_lag numeric; x jsonb; v_keep uuid[] := '{}'; v_link uuid; v_me uuid := auth.uid(); v_seeds uuid[] := '{}';
begin
  if v_seen is not null then return v_seen; end if;
  select * into sc from public.schedules
   where id = coalesce(nullif(p ->> 'schedule_id', '')::uuid, (select schedule_id from public.schedule_tasks where id = v_task),
                       (select schedule_id from public.schedule_tasks where id = nullif(p ->> 'succ_task_id', '')::uuid))
   for update;
  if not found then raise exception 'Schedule not found'; end if;
  perform app.require_member(sc.project_id);
  perform app.require_role('office_engineer','coordinator','manager','admin');
  if sc.status = 'archived' then raise exception 'Schedule % is archived', sc.code; end if;
  if v_task is not null then
    select * into t from public.schedule_tasks where id = v_task and schedule_id = sc.id and deleted_at is null;
    if not found then raise exception 'Task not found in this schedule'; end if;
  end if;
  v_snap := app.schedule_snapshot(sc.id);

  if v_act = 'add_task' then
    v_kind := coalesce(nullif(p ->> 'kind', ''), 'task');
    if v_kind not in ('task','milestone','summary') then raise exception 'Unknown task kind %', v_kind; end if;
    if coalesce(trim(p ->> 'name'), '') = '' then raise exception 'Give the task a name'; end if;
    if nullif(p ->> 'after_task_id', '') is not null then
      select * into a from public.schedule_tasks where id = (p ->> 'after_task_id')::uuid and schedule_id = sc.id and deleted_at is null;
      if not found then raise exception 'Task to insert after not found'; end if;
    end if;
    if nullif(p ->> 'parent_id', '') is not null then
      select * into par from public.schedule_tasks where id = (p ->> 'parent_id')::uuid and schedule_id = sc.id and deleted_at is null;
      if not found then raise exception 'Parent task not found'; end if;
      if not par.is_summary then
        v_why := app.summary_blocker(par.id);
        if v_why is not null then raise exception '"%" cannot get sub-tasks: %', par.name, v_why; end if;
      end if;
    end if;
    select coalesce(max(msp_uid), 0) + 1 into v_uid from public.schedule_tasks where schedule_id = sc.id;
    v_dur := case v_kind when 'milestone' then 0 when 'summary' then null else greatest(coalesce((p ->> 'duration_days')::numeric, 1), 0) end;
    v_start := coalesce((p ->> 'start')::date, a.planned_start, par.planned_start, sc.planned_start, app.eat_date(now()));
    insert into public.schedule_tasks (project_id, schedule_id, msp_uid, parent_id, sort_order, outline_level, name, notes,
      is_summary, is_milestone, planned_start, planned_finish, duration_days, constraint_type, constraint_date, ev_method,
      origin, edited_at, edited_by, block_id, level_id)
    values (sc.project_id, sc.id, v_uid,
      case when par.id is not null then par.id else a.parent_id end,
      case when par.id is not null and a.id is null then 2000000000 else coalesce(a.sort_order, 2000000000) end,
      1, trim(p ->> 'name'), nullif(p ->> 'notes', ''), v_kind = 'summary', v_kind = 'milestone', v_start, v_start, v_dur,
      case when (p ->> 'start') is not null then 4 end, (p ->> 'start')::date,
      case when v_kind = 'milestone' then 'milestone' else 'pct' end, 'app', now(), v_me,
      coalesce(par.block_id, a.block_id), coalesce(par.level_id, a.level_id))
    returning id into v_new;
    v_summary := 'Added ' || v_kind || ' "' || trim(p ->> 'name') || '"';

  elsif v_act = 'update_task' then
    if p ? 'name' and coalesce(trim(p ->> 'name'), '') = '' then raise exception 'The task name cannot be empty'; end if;
    if t.is_summary and (p ? 'duration_days' or p ? 'start' or p ? 'milestone' or p ? 'constraint_type') then
      raise exception '"%" is a summary: its dates come from its sub-tasks', t.name;
    end if;
    if (p ->> 'duration_days')::numeric < 0 then raise exception 'Duration cannot be negative'; end if;
    if (p ->> 'constraint_type')::int not between 0 and 7 then raise exception 'Unknown constraint type'; end if;
    if (p ->> 'constraint_type')::int in (2,3,4,5,6,7) and coalesce(p ->> 'constraint_date', t.constraint_date::text) is null then
      raise exception 'This constraint needs a date';
    end if;
    update public.schedule_tasks set
      name = case when p ? 'name' then trim(p ->> 'name') else name end,
      notes = case when p ? 'notes' then nullif(p ->> 'notes', '') else notes end,
      deadline = case when p ? 'deadline' then (p ->> 'deadline')::date else deadline end,
      is_milestone = case when p ? 'milestone' then (p ->> 'milestone')::boolean else is_milestone end,
      duration_days = case when p ? 'milestone' and (p ->> 'milestone')::boolean then 0
                           when p ? 'milestone' and not (p ->> 'milestone')::boolean and coalesce(duration_days, 0) = 0 then greatest(coalesce((p ->> 'duration_days')::numeric, 1), 1)
                           when p ? 'duration_days' then (p ->> 'duration_days')::numeric else duration_days end,
      ev_method = case when p ? 'milestone' and (p ->> 'milestone')::boolean and ev_method = 'pct' and pct_complete = 0 then 'milestone'
                       when p ? 'milestone' and not (p ->> 'milestone')::boolean and ev_method = 'milestone' then 'pct' else ev_method end,
      constraint_type = case when p ? 'start' then case when p ->> 'start' is null then 0 else 4 end
                             when p ? 'constraint_type' then (p ->> 'constraint_type')::smallint else constraint_type end,
      constraint_date = case when p ? 'start' then (p ->> 'start')::date
                             when p ? 'constraint_type' and (p ->> 'constraint_type')::int in (0, 1) then null
                             when p ? 'constraint_date' then (p ->> 'constraint_date')::date else constraint_date end,
      planned_start = case when p ->> 'start' is not null then (p ->> 'start')::date else planned_start end,
      edited_at = now(), edited_by = v_me
    where id = t.id;
    v_summary := 'Edited "' || t.name || '"' || coalesce(' (' || (select string_agg(k, ', ') from jsonb_object_keys(p - 'op_id' - 'action' - 'task_id' - 'schedule_id') k) || ')', '');

  elsif v_act = 'delete_task' then
    with recursive sub as (select id from public.schedule_tasks where id = t.id
                           union all select c.id from public.schedule_tasks c join sub on c.parent_id = sub.id where c.deleted_at is null)
    select array_agg(id) into v_ids from sub;
    select string_agg(distinct x.why, '; ') into v_why from (
      select format('"%s" has progress', s.name) why from public.schedule_tasks s where s.id = any (v_ids)
        and (s.pct_complete > 0 or s.actual_start is not null or exists (select 1 from public.task_progress tp where tp.task_id = s.id and tp.status <> 'rejected'))
      union all select format('"%s" has cost entries', s.name) from public.schedule_tasks s where s.id = any (v_ids) and exists (select 1 from public.cost_entries ce where ce.task_id = s.id)
      union all select format('"%s" is linked to BoQ items', s.name) from public.schedule_tasks s where s.id = any (v_ids) and exists (select 1 from public.task_boq_links b where b.task_id = s.id and b.deleted_at is null)
      union all select format('"%s" has resources assigned', s.name) from public.schedule_tasks s where s.id = any (v_ids) and exists (select 1 from public.task_assignments ta where ta.task_id = s.id and ta.deleted_at is null)
      union all select format('"%s" is in a monthly look-ahead', s.name) from public.schedule_tasks s where s.id = any (v_ids) and exists (select 1 from public.lookahead_items li where li.schedule_task_id = s.id)
    ) x;
    if v_why is not null then raise exception 'Cannot delete: % — keep it, or remove that first', v_why; end if;
    select coalesce(array_agg(distinct succ_task_id), '{}') into v_seeds from public.schedule_links
     where deleted_at is null and pred_task_id = any (v_ids) and not (succ_task_id = any (v_ids));
    update public.schedule_links set deleted_at = now() where deleted_at is null and (pred_task_id = any (v_ids) or succ_task_id = any (v_ids));
    update public.schedule_tasks set deleted_at = now(), edited_at = now(), edited_by = v_me where id = any (v_ids);
    v_summary := 'Deleted "' || t.name || '"' || case when array_length(v_ids, 1) > 1 then ' and ' || (array_length(v_ids, 1) - 1) || ' sub-task(s)' else '' end;

  elsif v_act = 'indent' then
    select * into nb from public.schedule_tasks where schedule_id = sc.id and deleted_at is null
      and parent_id is not distinct from t.parent_id and sort_order < t.sort_order order by sort_order desc limit 1;
    if not found then raise exception 'There is no task above "%" at the same level to indent under', t.name; end if;
    if not nb.is_summary then
      v_why := app.summary_blocker(nb.id);
      if v_why is not null then raise exception '"%" would become a summary, but %', nb.name, v_why; end if;
    end if;
    update public.schedule_tasks set parent_id = nb.id, edited_at = now(), edited_by = v_me where id = t.id;
    v_summary := 'Indented "' || t.name || '" under "' || nb.name || '"';

  elsif v_act = 'outdent' then
    if t.parent_id is null then raise exception '"%" is already at the top level', t.name; end if;
    select * into par from public.schedule_tasks where id = t.parent_id;
    select array_agg(id) into v_ids from public.schedule_tasks
     where parent_id = t.parent_id and deleted_at is null and sort_order > t.sort_order;
    if v_ids is not null and not t.is_summary then
      v_why := app.summary_blocker(t.id);
      if v_why is not null then raise exception '"%" would take the tasks below it as sub-tasks, but %', t.name, v_why; end if;
    end if;
    update public.schedule_tasks set parent_id = t.id where id = any (coalesce(v_ids, '{}'));
    update public.schedule_tasks set parent_id = par.parent_id, edited_at = now(), edited_by = v_me where id = t.id;
    v_summary := 'Outdented "' || t.name || '"';

  elsif v_act = 'move' then
    if coalesce(p ->> 'direction', '') = 'up' then
      select * into nb from public.schedule_tasks where schedule_id = sc.id and deleted_at is null
        and parent_id is not distinct from t.parent_id and sort_order < t.sort_order order by sort_order desc limit 1;
    else
      select * into nb from public.schedule_tasks where schedule_id = sc.id and deleted_at is null
        and parent_id is not distinct from t.parent_id and sort_order > t.sort_order order by sort_order limit 1;
    end if;
    if not found then raise exception '"%" cannot move further %', t.name, coalesce(p ->> 'direction', 'down'); end if;
    update public.schedule_tasks set sort_order = nb.sort_order, edited_at = now(), edited_by = v_me where id = t.id;
    update public.schedule_tasks set sort_order = t.sort_order where id = nb.id;
    v_summary := 'Moved "' || t.name || '" ' || coalesce(p ->> 'direction', 'down');

  elsif v_act in ('add_link', 'update_link', 'delete_link') then
    select * into v_pred from public.schedule_tasks where id = (p ->> 'pred_task_id')::uuid and schedule_id = sc.id and deleted_at is null;
    select * into v_succ from public.schedule_tasks where id = (p ->> 'succ_task_id')::uuid and schedule_id = sc.id and deleted_at is null;
    if v_pred.id is null or v_succ.id is null then raise exception 'Both tasks must be in this schedule'; end if;
    v_type := upper(coalesce(nullif(p ->> 'link_type', ''), 'FS'));
    if v_act = 'delete_link' then
      update public.schedule_links set deleted_at = now() where pred_task_id = v_pred.id and succ_task_id = v_succ.id
        and deleted_at is null and (p ->> 'link_type' is null or link_type = v_type);
      get diagnostics v_n = row_count;
      if v_n = 0 then raise exception 'There is no such link'; end if;
      v_summary := 'Removed link ' || v_pred.msp_uid || ' → ' || v_succ.msp_uid;
    else
      if v_type not in ('FS','SS','FF','SF') then raise exception 'Link type must be FS, SS, FF or SF'; end if;
      if v_pred.id = v_succ.id then raise exception 'A task cannot be linked to itself'; end if;
      if v_pred.is_summary or v_succ.is_summary then raise exception 'Link the detailed tasks, not a summary'; end if;
      v_lag := case when p ? 'lag_pct' then round(greatest(coalesce(v_pred.duration_days, 0), 0) * (p ->> 'lag_pct')::numeric / 100, 2)
                    else coalesce((p ->> 'lag_days')::numeric, 0) end;
      if v_act = 'update_link' then
        update public.schedule_links set deleted_at = now() where pred_task_id = v_pred.id and succ_task_id = v_succ.id and deleted_at is null;
      end if;
      insert into public.schedule_links (project_id, schedule_id, pred_task_id, succ_task_id, link_type, lag_days, origin)
      values (sc.project_id, sc.id, v_pred.id, v_succ.id, v_type, v_lag, 'app')
      on conflict (pred_task_id, succ_task_id, link_type) do update set lag_days = excluded.lag_days, deleted_at = null, origin = 'app';
      perform app.check_no_cycle(sc.id);
      v_summary := 'Linked ' || v_pred.msp_uid || ' → ' || v_succ.msp_uid || ' ' || v_type
        || case when v_lag <> 0 then (case when v_lag > 0 then '+' else '' end) || trim(trailing '.' from trim(trailing '0' from v_lag::text)) || 'd' else '' end;
    end if;
    update public.schedule_tasks set edited_at = now(), edited_by = v_me where id = v_succ.id;
    v_task := v_succ.id;

  elsif v_act = 'set_predecessors' then
    if t.is_summary then raise exception 'Link the detailed tasks, not a summary'; end if;
    for x in select y from jsonb_array_elements(coalesce(p -> 'predecessors', '[]'::jsonb)) y loop
      select * into v_pred from public.schedule_tasks where schedule_id = sc.id and deleted_at is null
        and (id = nullif(x ->> 'pred_task_id', '')::uuid or msp_uid = (x ->> 'pred_uid')::int) limit 1;
      if v_pred.id is null then raise exception 'Predecessor % is not in this schedule', coalesce(x ->> 'pred_uid', x ->> 'pred_task_id'); end if;
      if v_pred.id = t.id then raise exception 'A task cannot be its own predecessor'; end if;
      if v_pred.is_summary then raise exception 'Predecessor % is a summary — link its detailed tasks', v_pred.msp_uid; end if;
      v_type := upper(coalesce(nullif(x ->> 'link_type', ''), 'FS'));
      if v_type not in ('FS','SS','FF','SF') then raise exception 'Link type must be FS, SS, FF or SF'; end if;
      v_lag := case when x ? 'lag_pct' then round(greatest(coalesce(v_pred.duration_days, 0), 0) * (x ->> 'lag_pct')::numeric / 100, 2)
                    else coalesce((x ->> 'lag_days')::numeric, 0) end;
      insert into public.schedule_links (project_id, schedule_id, pred_task_id, succ_task_id, link_type, lag_days, origin)
      values (sc.project_id, sc.id, v_pred.id, t.id, v_type, v_lag, 'app')
      on conflict (pred_task_id, succ_task_id, link_type) do update
        set lag_days = excluded.lag_days, deleted_at = null,
            origin = case when schedule_links.lag_days = excluded.lag_days and schedule_links.deleted_at is null then schedule_links.origin else 'app' end
      returning id into v_link;
      v_keep := v_keep || v_link;
    end loop;
    update public.schedule_links set deleted_at = now() where succ_task_id = t.id and deleted_at is null and not (id = any (v_keep));
    perform app.check_no_cycle(sc.id);
    update public.schedule_tasks set edited_at = now(), edited_by = v_me where id = t.id;
    v_summary := 'Set predecessors of "' || t.name || '" (' || coalesce(array_length(v_keep, 1), 0) || ')';
  else
    raise exception 'Unknown schedule edit %', coalesce(v_act, '(none)');
  end if;

  perform app.renumber_schedule(sc.id);
  if v_act <> 'delete_task' then v_seeds := v_seeds || coalesce(v_new, v_task); end if;
  v_plan := app.replan_schedule(sc.id, array_remove(v_seeds, null));
  insert into public.schedule_edits (id, project_id, schedule_id, action, task_id, summary, detail, snapshot, version_id, moved, created_by)
  values (v_edit, sc.project_id, sc.id, v_act, coalesce(v_new, v_task), v_summary, p - 'op_id', v_snap, sc.current_version_id,
          coalesce((v_plan ->> 'moved')::int, 0), v_me);
  update public.schedule_edits set snapshot = null where schedule_id = sc.id and snapshot is not null
    and id not in (select id from public.schedule_edits where schedule_id = sc.id order by created_at desc limit 30);
  return app.op_done(p, 'edit_schedule', jsonb_build_object('ok', true, 'edit_id', v_edit, 'task_id', coalesce(v_new, v_task),
    'summary', v_summary) || v_plan);
end $$;

-- -----------------------------------------------------------------------------
-- RPC: undo_schedule_edit — restores the schedule as it was before its latest edit.
-- -----------------------------------------------------------------------------
create or replace function public.undo_schedule_edit(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p);
  sc public.schedules; e public.schedule_edits; v_plan jsonb; v_lvl int;
begin
  if v_seen is not null then return v_seen; end if;
  select * into sc from public.schedules where id = (p ->> 'schedule_id')::uuid for update;
  if not found then raise exception 'Schedule not found'; end if;
  perform app.require_member(sc.project_id);
  perform app.require_role('office_engineer','coordinator','manager','admin');
  select * into e from public.schedule_edits where schedule_id = sc.id and undone_at is null order by created_at desc limit 1;
  if not found then raise exception 'Nothing to undo'; end if;
  if e.snapshot is null then raise exception 'That edit is too old to undo'; end if;
  if e.version_id is distinct from sc.current_version_id then
    raise exception 'The schedule was imported from MS Project after "%" — it cannot be undone', e.summary;
  end if;

  update public.schedule_tasks t set parent_id = r.parent_id, sort_order = r.sort_order, outline_level = r.outline_level,
         outline_number = r.outline_number, wbs = r.wbs, name = r.name, notes = r.notes, is_summary = r.is_summary,
         is_milestone = r.is_milestone, planned_start = r.planned_start, planned_finish = r.planned_finish,
         duration_days = r.duration_days, constraint_type = r.constraint_type, constraint_date = r.constraint_date,
         deadline = r.deadline, ev_method = r.ev_method, deleted_at = r.deleted_at, edited_at = r.edited_at, edited_by = r.edited_by
  from jsonb_populate_recordset(null::public.schedule_tasks, e.snapshot -> 'tasks') r
  where t.id = r.id and t.schedule_id = sc.id;
  update public.schedule_tasks t set deleted_at = now()
   where t.schedule_id = sc.id and t.deleted_at is null
     and not exists (select 1 from jsonb_array_elements(e.snapshot -> 'tasks') s where (s ->> 'id')::uuid = t.id);
  update public.schedule_links l set link_type = r.link_type, lag_days = r.lag_days, lag_elapsed = r.lag_elapsed, deleted_at = r.deleted_at
  from jsonb_populate_recordset(null::public.schedule_links, e.snapshot -> 'links') r
  where l.id = r.id and l.schedule_id = sc.id;
  update public.schedule_links l set deleted_at = now()
   where l.schedule_id = sc.id and l.deleted_at is null
     and not exists (select 1 from jsonb_array_elements(e.snapshot -> 'links') s where (s ->> 'id')::uuid = l.id);
  update public.schedules s set planned_start = x.ps, planned_finish = x.pf
    from (select min(planned_start) ps, max(planned_finish) pf from public.schedule_tasks where schedule_id = sc.id and deleted_at is null) x
   where s.id = sc.id;
  v_plan := app.run_cpm(sc.id, coalesce(sc.status_date, app.eat_date(now())), true);
  update public.schedule_edits set undone_at = now(), undone_by = auth.uid() where id = e.id;
  return app.op_done(p, 'undo_schedule_edit', jsonb_build_object('ok', true, 'undone', e.summary, 'edit_id', e.id,
    'fc_finish', v_plan -> 'fc_finish'));
end $$;

-- -----------------------------------------------------------------------------
-- Resources
-- -----------------------------------------------------------------------------
create or replace function public.save_schedule_resource(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p);
  v_id uuid := coalesce(nullif(p ->> 'id', '')::uuid, gen_random_uuid());
  v_project uuid := (p ->> 'project_id')::uuid; v_old public.schedule_resources;
  v_kind text := coalesce(nullif(p ->> 'kind', ''), 'labour');
begin
  if v_seen is not null then return v_seen; end if;
  select * into v_old from public.schedule_resources where id = v_id;
  v_project := coalesce(v_old.project_id, v_project);
  perform app.require_member(v_project);
  perform app.require_role('office_engineer','coordinator','manager','admin');
  if coalesce(trim(p ->> 'code'), '') = '' or coalesce(trim(p ->> 'name'), '') = '' then raise exception 'Give the resource a code and a name'; end if;
  if v_kind not in ('labour','crew','equipment','material') then raise exception 'Unknown resource type %', v_kind; end if;
  if coalesce((p ->> 'max_units')::numeric, 1) <= 0 then raise exception 'Max units must be more than 0'; end if;
  if exists (select 1 from public.schedule_resources where project_id = v_project and lower(code) = lower(trim(p ->> 'code')) and id <> v_id and deleted_at is null) then
    raise exception 'Resource code % is already used', trim(p ->> 'code');
  end if;
  insert into public.schedule_resources (id, project_id, code, name, kind, unit, max_units, labour_trade_id, material_spec_id, notes, is_active, created_by)
  values (v_id, v_project, trim(p ->> 'code'), trim(p ->> 'name'), v_kind,
    coalesce(nullif(p ->> 'unit', ''), case v_kind when 'material' then 'unit' else 'day' end), coalesce((p ->> 'max_units')::numeric, 1),
    nullif(p ->> 'labour_trade_id', '')::uuid, nullif(p ->> 'material_spec_id', '')::uuid, nullif(p ->> 'notes', ''),
    coalesce((p ->> 'is_active')::boolean, true), auth.uid())
  on conflict (id) do update set code = excluded.code, name = excluded.name, kind = excluded.kind, unit = excluded.unit,
    max_units = excluded.max_units, labour_trade_id = excluded.labour_trade_id, material_spec_id = excluded.material_spec_id,
    notes = excluded.notes, is_active = excluded.is_active, deleted_at = null;
  if app.can_see_prices() and (p ? 'std_rate' or p ? 'cost_per_use') then
    insert into public.schedule_resource_rates (resource_id, project_id, std_rate, cost_per_use)
    values (v_id, v_project, coalesce((p ->> 'std_rate')::numeric, 0), coalesce((p ->> 'cost_per_use')::numeric, 0))
    on conflict (resource_id) do update set std_rate = excluded.std_rate, cost_per_use = excluded.cost_per_use;
  end if;
  return app.op_done(p, 'save_schedule_resource', jsonb_build_object('ok', true, 'id', v_id));
end $$;

-- Replace the resources assigned to a task: [{resource_id, units, notes}] (empty list = none).
create or replace function public.assign_resources(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p);
  t public.schedule_tasks; r public.schedule_resources; x jsonb; v_keep uuid[] := '{}'; v_n int := 0;
begin
  if v_seen is not null then return v_seen; end if;
  select * into t from public.schedule_tasks where id = (p ->> 'task_id')::uuid and deleted_at is null;
  if not found then raise exception 'Task not found'; end if;
  perform app.require_member(t.project_id);
  perform app.require_role('office_engineer','coordinator','manager','admin');
  if t.is_summary then raise exception 'Assign resources to the detailed tasks, not to the summary "%"', t.name; end if;
  for x in select y from jsonb_array_elements(coalesce(p -> 'assignments', '[]'::jsonb)) y loop
    select * into r from public.schedule_resources where id = (x ->> 'resource_id')::uuid and project_id = t.project_id and deleted_at is null;
    if not found then raise exception 'Resource not found in this project'; end if;
    if coalesce((x ->> 'units')::numeric, 0) <= 0 then raise exception 'Units for % must be more than 0', r.code; end if;
    insert into public.task_assignments (project_id, schedule_id, task_id, resource_id, units, notes, created_by)
    values (t.project_id, t.schedule_id, t.id, r.id, (x ->> 'units')::numeric, nullif(x ->> 'notes', ''), auth.uid())
    on conflict (task_id, resource_id) where deleted_at is null do update set units = excluded.units, notes = excluded.notes;
    v_keep := v_keep || r.id; v_n := v_n + 1;
  end loop;
  update public.task_assignments set deleted_at = now() where task_id = t.id and deleted_at is null and not (resource_id = any (v_keep));
  update public.schedule_tasks set edited_at = now(), edited_by = auth.uid() where id = t.id;
  return app.op_done(p, 'assign_resources', jsonb_build_object('ok', true, 'task_id', t.id, 'assignments', v_n));
end $$;

-- Weekly resource demand vs capacity. basis 'plan' (planned dates) or 'forecast'. Labour/equipment demand in
-- unit-days (units × working days), capacity = max units × working days; peak = highest daily units in the week.
-- Over-allocated weeks list the tasks with their total float (the ones with float can move — levelling hint).
create or replace function public.get_resource_usage(p jsonb) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  sc public.schedules; v_from date; v_to date; v_fc boolean := coalesce(p ->> 'basis', 'plan') = 'forecast'; v_days date[]; v_out jsonb;
begin
  select * into sc from public.schedules where id = (p ->> 'schedule_id')::uuid;
  if not found then raise exception 'Schedule not found'; end if;
  perform app.require_member(sc.project_id);
  v_from := coalesce((p ->> 'from')::date, sc.planned_start, app.eat_date(now()));
  v_to := coalesce((p ->> 'to')::date, greatest(sc.planned_finish, sc.fc_finish), v_from + 180);
  if v_to - v_from > 1500 then v_to := v_from + 1500; end if;
  v_days := app.working_dates(sc.project_id, v_from, v_to);
  with dd as (select unnest(v_days) as d),
  asg as (
    select a.resource_id, a.task_id, a.units, t.name, t.msp_uid, t.total_float_days, r.kind,
           case when v_fc then coalesce(t.forecast_start, t.planned_start) else t.planned_start end as s,
           case when v_fc then coalesce(t.forecast_finish, t.planned_finish) else t.planned_finish end as f
    from public.task_assignments a join public.schedule_tasks t on t.id = a.task_id and t.deleted_at is null and not t.is_summary
    join public.schedule_resources r on r.id = a.resource_id
    where a.schedule_id = sc.id and a.deleted_at is null and (not v_fc or t.actual_finish is null)),
  ndays as (select a.task_id, a.resource_id, greatest(count(dd.d), 1) as n from asg a left join dd on dd.d between a.s and a.f group by 1, 2),
  daily as (
    select a.resource_id, dd.d, date_trunc('week', dd.d)::date as wk, a.task_id, a.name, a.msp_uid, a.total_float_days,
           case when a.kind = 'material' then a.units / nd.n else a.units end as u
    from asg a join dd on dd.d between a.s and a.f join ndays nd on nd.task_id = a.task_id and nd.resource_id = a.resource_id),
  perday as (select resource_id, wk, d, sum(u) as u from daily group by 1, 2, 3),
  wk as (
    select pd.resource_id, pd.wk, round(sum(pd.u), 2) as demand, round(max(pd.u), 2) as peak,
           (select count(*) from dd where date_trunc('week', dd.d)::date = pd.wk) as wd
    from perday pd group by 1, 2),
  rows as (
    select w.resource_id, w.wk, w.demand, w.peak, w.wd, round(r.max_units * w.wd, 2) as capacity,
           r.kind <> 'material' and w.peak > r.max_units as over,
           case when r.kind <> 'material' and w.peak > r.max_units then
             (select jsonb_agg(distinct jsonb_build_object('task_id', x.task_id, 'uid', x.msp_uid, 'name', x.name, 'units', x.u,
                     'total_float_days', x.total_float_days)) from daily x where x.resource_id = w.resource_id and x.wk = w.wk) end as tasks
    from wk w join public.schedule_resources r on r.id = w.resource_id)
  select jsonb_build_object('from', v_from, 'to', v_to, 'basis', case when v_fc then 'forecast' else 'plan' end,
    'resources', coalesce((select jsonb_agg(jsonb_build_object('id', r.id, 'code', r.code, 'name', r.name, 'kind', r.kind, 'unit', r.unit,
        'max_units', r.max_units,
        'weeks', coalesce((select jsonb_agg(jsonb_build_object('week', x.wk, 'demand', x.demand, 'peak', x.peak, 'capacity', x.capacity,
                   'working_days', x.wd, 'over', x.over, 'tasks', x.tasks) order by x.wk) from rows x where x.resource_id = r.id), '[]'::jsonb))
      order by r.kind, r.code)
      from public.schedule_resources r where r.project_id = sc.project_id and r.deleted_at is null
        and exists (select 1 from rows x where x.resource_id = r.id)), '[]'::jsonb)) into v_out;
  return v_out;
end $$;

-- -----------------------------------------------------------------------------
-- Baseline with task cost from the resources (cost_source 'resources'): BAC cost = assignment cost of the
-- task; tasks without assignments (or without rates) keep the value-based cost.
-- -----------------------------------------------------------------------------
do $$
declare c text;
begin
  select conname into c from pg_constraint where conrelid = 'public.schedule_baselines'::regclass and contype = 'c'
    and pg_get_constraintdef(oid) like '%cost_source%';
  if c is not null then execute format('alter table public.schedule_baselines drop constraint %I', c); end if;
  alter table public.schedule_baselines add constraint schedule_baselines_cost_source_check
    check (cost_source in ('value','msp_baseline_cost','budget_lines','value_less_margin','resources'));
  if to_regprocedure('app.set_baseline_core(jsonb)') is null then
    alter function public.set_baseline(jsonb) set schema app;
    alter function app.set_baseline(jsonb) rename to set_baseline_core;
  end if;
end $$;
revoke execute on function app.set_baseline_core(jsonb) from public;

create or replace function public.set_baseline(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); v_res jsonb; v_id uuid; v_tot record;
begin
  if v_seen is not null then return v_seen; end if;
  if coalesce(p ->> 'cost_source', '') <> 'resources' then
    return app.op_done(p, 'set_baseline', app.set_baseline_core(p - 'op_id'));
  end if;
  if not app.can_see_prices() then raise exception 'Only price roles can cost a baseline from the resource rates'; end if;
  v_res := app.set_baseline_core((p - 'op_id') || jsonb_build_object('cost_source', 'value'));
  v_id := (v_res ->> 'id')::uuid;
  update public.schedule_baselines set cost_source = 'resources' where id = v_id;
  update public.schedule_baseline_task_costs c set bac_cost = x.cost
    from (select task_id, sum(cost) as cost from public.v_task_resource_cost where cost is not null group by task_id) x
   where c.baseline_id = v_id and c.task_id = x.task_id and x.cost > 0;
  select round(sum(bac_value), 2) bv, round(sum(bac_cost), 2) bc into v_tot from public.schedule_baseline_task_costs where baseline_id = v_id;
  return app.op_done(p, 'set_baseline', v_res || jsonb_build_object('bac_value', v_tot.bv, 'bac_cost', v_tot.bc, 'cost_source', 'resources'));
end $$;

revoke execute on function app.renumber_schedule(uuid) from public;
revoke execute on function app.replan_schedule(uuid, uuid[]) from public;
revoke execute on function app.schedule_snapshot(uuid) from public;


-- >>>>>>>>>>>>>>>>>>>> 20261103000040_elements_from_schedule.sql

-- =============================================================================
-- Elements from the schedule. MS Project building schedules are organised floor × trade × element
-- ("1st Floor › B] REBAR › c) To elevation Columns") or trade × element with the level in the name
-- ("4.1 FORMWORK › i) In 1st Basement floor slab"). The web detector (web/src/lib/msp/elements.ts) turns the
-- imported tasks into blocks, levels and elements (one per level × element type), the user reviews them, and
-- this RPC writes them:
--   * blocks / levels are matched by code (created when missing, never renamed);
--   * elements are matched by (block, level, code) — re-running never duplicates; new ones get their activity
--     sequence from activity_templates (trigger seed_activities);
--   * task_element_links (source 'file') say which tasks deliver which element, with the activity range the
--     task covers (formwork task → the element's "Formwork" activity …);
--   * element_takeoffs (planned material per element, tagged with the BoQ item) when the client sends them —
--     the look-ahead material needs and "request from store" use them.
--
-- p: { op_id, schedule_id, block: {id | code, name}, levels: [{code, name, sort_order}],
--      elements: [{ level_code | null, code, element_type, planned_start, planned_finish,
--                   tasks: [{task_id, activity_seq_from, activity_seq_to}],
--                   takeoffs: [{material_spec_id, boq_item_id, qty}] }],
--      replace_links: true }  -- drop this schedule's earlier 'file' links of these tasks that are no longer sent
-- =============================================================================

create or replace function public.create_elements_from_schedule(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p);
  sc public.schedules;
  v_block uuid;
  v_level uuid;
  v_el uuid;
  v_type text;
  v_code text;
  lv jsonb; el jsonb; tk jsonb; tf jsonb;
  v_task public.schedule_tasks;
  v_replace boolean := coalesce((p ->> 'replace_links')::boolean, true);
  v_sent uuid[] := '{}';
  v_el_ids uuid[] := '{}';
  v_pairs text[] := '{}';
  v_blocks int := 0; v_levels int := 0; v_new int := 0; v_matched int := 0; v_links int := 0; v_takeoffs int := 0; v_dropped int := 0;
  v_warn jsonb := '[]'::jsonb;
begin
  if v_seen is not null then return v_seen; end if;
  select * into sc from public.schedules where id = (p ->> 'schedule_id')::uuid;
  if not found then raise exception 'Schedule not found'; end if;
  perform app.require_member(sc.project_id);
  perform app.require_role('office_engineer','coordinator','manager','admin');
  if jsonb_typeof(p -> 'elements') <> 'array' or jsonb_array_length(p -> 'elements') = 0 then
    raise exception 'No elements to create';
  end if;

  -- block: by id, else by code (created when missing)
  if nullif(p #>> '{block,id}', '') is not null then
    select id into v_block from public.blocks where id = (p #>> '{block,id}')::uuid and project_id = sc.project_id and deleted_at is null;
    if v_block is null then raise exception 'Block does not belong to this project'; end if;
  else
    v_code := upper(btrim(coalesce(nullif(p #>> '{block,code}', ''), 'A')));
    select id into v_block from public.blocks where project_id = sc.project_id and upper(code) = v_code and deleted_at is null;
    if v_block is null then
      insert into public.blocks (project_id, code, name)
      values (sc.project_id, v_code, coalesce(nullif(btrim(p #>> '{block,name}'), ''), 'Block ' || v_code))
      returning id into v_block;
      v_blocks := 1;
    end if;
  end if;

  -- levels: matched by code within the block, created when missing
  for lv in select * from jsonb_array_elements(coalesce(p -> 'levels', '[]'::jsonb)) loop
    v_code := upper(btrim(lv ->> 'code'));
    if v_code is null or v_code = '' then continue; end if;
    if not exists (select 1 from public.levels where block_id = v_block and upper(code) = v_code and deleted_at is null) then
      insert into public.levels (project_id, block_id, code, name, sort_order)
      values (sc.project_id, v_block, v_code, coalesce(nullif(btrim(lv ->> 'name'), ''), v_code), coalesce((lv ->> 'sort_order')::int, 0));
      v_levels := v_levels + 1;
    end if;
  end loop;

  for el in select * from jsonb_array_elements(p -> 'elements') loop
    v_code := upper(btrim(el ->> 'code'));
    v_type := lower(btrim(el ->> 'element_type'));
    if v_code is null or v_code = '' or v_type is null or v_type = '' then raise exception 'Every element needs a code and a type'; end if;
    v_level := null;
    if nullif(el ->> 'level_code', '') is not null then
      select id into v_level from public.levels
       where block_id = v_block and upper(code) = upper(btrim(el ->> 'level_code')) and deleted_at is null;
      if v_level is null then raise exception 'Level % is not in the levels list', el ->> 'level_code'; end if;
    end if;

    select id into v_el from public.elements
     where project_id = sc.project_id and block_id is not distinct from v_block and level_id is not distinct from v_level
       and upper(code) = v_code and deleted_at is null;
    if v_el is null then
      insert into public.elements (project_id, block_id, level_id, code, element_type, planned_start, planned_finish)
      values (sc.project_id, v_block, v_level, v_code, v_type, nullif(el ->> 'planned_start', '')::date, nullif(el ->> 'planned_finish', '')::date)
      returning id into v_el;
      v_new := v_new + 1;
    else
      v_matched := v_matched + 1;
      update public.elements set
        planned_start = coalesce(nullif(el ->> 'planned_start', '')::date, planned_start),
        planned_finish = coalesce(nullif(el ->> 'planned_finish', '')::date, planned_finish)
       where id = v_el and status = 'not_started';
    end if;
    v_el_ids := v_el_ids || v_el;

    for tk in select * from jsonb_array_elements(coalesce(el -> 'tasks', '[]'::jsonb)) loop
      select * into v_task from public.schedule_tasks where id = (tk ->> 'task_id')::uuid;
      if not found or v_task.schedule_id <> sc.id then raise exception 'Task % is not in this schedule', tk ->> 'task_id'; end if;
      if v_task.is_summary then
        v_warn := v_warn || to_jsonb('Summary task "' || v_task.name || '" skipped');
        continue;
      end if;
      insert into public.task_element_links (project_id, task_id, element_id, activity_seq_from, activity_seq_to, source)
      values (sc.project_id, v_task.id, v_el, (tk ->> 'activity_seq_from')::int, (tk ->> 'activity_seq_to')::int, 'file')
      on conflict (task_id, element_id) do update set
        activity_seq_from = excluded.activity_seq_from, activity_seq_to = excluded.activity_seq_to,
        deleted_at = null, updated_at = now()
      where task_element_links.source <> 'ui';
      v_sent := v_sent || v_task.id;
      v_pairs := v_pairs || (v_el::text || ':' || v_task.id::text);
      v_links := v_links + 1;
    end loop;

    for tf in select * from jsonb_array_elements(coalesce(el -> 'takeoffs', '[]'::jsonb)) loop
      if (tf ->> 'qty')::numeric is null or (tf ->> 'qty')::numeric < 0 then raise exception 'Take-off quantity must be zero or more'; end if;
      if not exists (select 1 from public.material_specs where id = (tf ->> 'material_spec_id')::uuid) then
        raise exception 'Unknown material in take-off';
      end if;
      if nullif(tf ->> 'boq_item_id', '') is not null
         and not exists (select 1 from public.boq_items where id = (tf ->> 'boq_item_id')::uuid and project_id = sc.project_id) then
        raise exception 'BoQ item is not in this project';
      end if;
      insert into public.element_takeoffs (project_id, element_id, material_spec_id, boq_item_id, planned_qty)
      values (sc.project_id, v_el, (tf ->> 'material_spec_id')::uuid, nullif(tf ->> 'boq_item_id', '')::uuid, round((tf ->> 'qty')::numeric, 3))
      on conflict (element_id, material_spec_id) do update set
        planned_qty = excluded.planned_qty, boq_item_id = coalesce(excluded.boq_item_id, element_takeoffs.boq_item_id),
        deleted_at = null, updated_at = now();
      v_takeoffs := v_takeoffs + 1;
    end loop;
  end loop;

  -- earlier 'file' links of these elements / tasks (this schedule) that the reviewed list no longer contains
  if v_replace then
    with gone as (
      update public.task_element_links l set deleted_at = now(), updated_at = now()
       where l.project_id = sc.project_id and l.source = 'file' and l.deleted_at is null
         and (l.task_id = any (v_sent) or l.element_id = any (v_el_ids))
         and not ((l.element_id::text || ':' || l.task_id::text) = any (v_pairs))
         and exists (select 1 from public.schedule_tasks st where st.id = l.task_id and st.schedule_id = sc.id)
      returning 1)
    select count(*) into v_dropped from gone;
  end if;

  return app.op_done(p, 'create_elements_from_schedule', jsonb_build_object('ok', true, 'schedule_id', sc.id, 'block_id', v_block,
    'blocks_created', v_blocks, 'levels_created', v_levels, 'elements_created', v_new, 'elements_matched', v_matched,
    'links', v_links, 'links_removed', v_dropped, 'takeoffs', v_takeoffs, 'warnings', v_warn));
end $$;


-- >>>>>>>>>>>>>>>>>>>> 20261103000050_purchase_store_fixes.sql

-- =============================================================================
-- Award → purchase order → store: the awarded order must reach the store.
--
-- Before: award_rfq (management) with create_po made DRAFT purchase orders and stopped there. Procurement had to
-- find them, submit, get them approved and send them; until then nothing showed on the store side, and the
-- store keeper could only receive against a delivery notice. Users saw "awarded, confirmed … nothing in the store".
--
-- Now (common practice: the award decision by the approving manager IS the purchase approval):
--   * POs created by the award are approved with the award when their value is within the awarder's PO limit
--     (app.approval_limit_for 'po'); above it they are submitted for a higher approver (inbox 'po').
--   * procurement gets an inbox item to send each approved PO to the supplier ('po_send');
--   * the store keeper is told an order is coming and gets an inbox item when it is due ('po_receive'),
--     and can receive against the PO itself (post_grn with po_id — no delivery notice needed).
-- Safe to run again.
-- =============================================================================

do $$
begin
  if to_regprocedure('app.award_rfq_core(jsonb)') is null then
    alter function public.award_rfq(jsonb) set schema app;
    alter function app.award_rfq(jsonb) rename to award_rfq_core;
  end if;
end $$;
revoke execute on function app.award_rfq_core(jsonb) from public, anon, authenticated;

create or replace function public.award_rfq(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p);
  v_res jsonb;
  v_po uuid; po public.purchase_orders; v_total numeric; v_lim record; v_out jsonb := '[]'::jsonb; v_to text;
  v_sup text; v_rfq text;
begin
  if v_seen is not null then return v_seen; end if;
  v_res := app.award_rfq_core(p);
  select number into v_rfq from public.rfqs where id = (p ->> 'rfq_id')::uuid;
  for v_po in select (x #>> '{}')::uuid from jsonb_array_elements(coalesce(v_res -> 'po_ids', '[]'::jsonb)) x loop
    select * into po from public.purchase_orders where id = v_po for update;
    continue when not found or po.status <> 'draft';
    select total into v_total from public.po_totals where po_id = po.id;
    select * into v_lim from app.approval_limit_for(auth.uid(), po.project_id, 'po');
    select name into v_sup from public.suppliers where id = po.supplier_id;
    if v_lim.unlimited or coalesce(v_total, 0) <= v_lim.max_value then
      v_to := 'approved';
      update public.purchase_orders set status = 'approved', submitted_at = now(), approved_by = auth.uid(), approved_at = now()
       where id = po.id;
      perform app.po_event(po.id, 'approve_at_award', 'draft', 'approved', 'Approved with the award of ' || coalesce(v_rfq, 'the RFQ'));
      perform app.notify_user(po.created_by, po.project_id, 'PO ' || po.number || ' approved with the award — send it to ' || v_sup,
        'Awarded by ' || coalesce((select full_name from public.profiles where id = auth.uid()), 'management'), 'purchase_order', po.id);
    else
      v_to := 'submitted';
      update public.purchase_orders set status = 'submitted', submitted_at = now() where id = po.id;
      perform app.po_event(po.id, 'submit_at_award', 'draft', 'submitted',
        'Above the awarder''s PO limit (' || round(v_lim.max_value, 2) || '): needs a higher approver');
      perform app.notify_roles(po.project_id, '{coordinator,manager}', 'PO ' || po.number || ' awaiting approval', v_sup, 'purchase_order', po.id);
    end if;
    perform app.notify_roles(po.project_id, '{store_keeper}', 'Incoming order: PO ' || po.number || ' from ' || v_sup,
      'Expected ' || coalesce(to_char(coalesce(po.eta, po.expected_date), 'DD Mon YYYY'), 'date not set')
        || case when v_to = 'approved' then ' · being sent to the supplier' else ' · awaiting approval' end, 'purchase_order', po.id);
    perform app.refresh_mrs_for_po(po.id);
    v_out := v_out || jsonb_build_object('id', po.id, 'number', po.number, 'status', v_to);
  end loop;
  return app.op_done(p, 'award_rfq', v_res || jsonb_build_object('pos', v_out));
end $$;

-- -----------------------------------------------------------------------------
-- Inbox: procurement sends approved POs; the store keeper receives orders that are due.
-- -----------------------------------------------------------------------------
create or replace function app.purchase_store_approvals_for(p_user uuid)
returns table (kind text, entity_type text, entity_id uuid, project_id uuid, number text, title text, status text,
               requested_by uuid, requested_at timestamptz, is_urgent boolean, actions text[], age_hours numeric)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare v_role text;
begin
  select pr.role::text into v_role from public.profiles pr where pr.id = p_user and pr.is_active;
  if v_role is null then return; end if;
  if v_role in ('procurement', 'admin') then
    return query
    select 'po_send'::text, 'purchase_order'::text, po.id, po.project_id, po.number,
           'Send ' || po.number || ' to ' || s.name, po.status::text, po.created_by, coalesce(po.approved_at, po.created_at),
           coalesce(coalesce(po.expected_date, po.eta) <= app.local_date(now()) + 3, false), array['open'],
           round((extract(epoch from now() - coalesce(po.approved_at, po.created_at)) / 3600)::numeric, 1)
    from public.purchase_orders po join public.suppliers s on s.id = po.supplier_id
    where po.status = 'approved' and po.sent_at is null
      and po.project_id in (select pm.project_id from public.project_members pm where pm.user_id = p_user
                            union select pj.id from public.projects pj where v_role = 'admin');
  end if;
  if v_role in ('store_keeper', 'admin') then
    return query
    select 'po_receive'::text, 'purchase_order'::text, po.id, po.project_id, po.number,
           'Receive ' || po.number || ' from ' || s.name, po.status::text, po.created_by,
           coalesce(po.eta, po.expected_date)::timestamptz,
           coalesce(coalesce(po.eta, po.expected_date) < app.local_date(now()), false), array['open'],
           round((extract(epoch from now() - coalesce(po.eta, po.expected_date)::timestamptz) / 3600)::numeric, 1)
    from public.purchase_orders po join public.suppliers s on s.id = po.supplier_id
    where po.status in ('sent', 'partially_received')
      and coalesce(po.eta, po.expected_date, app.local_date(now())) <= app.local_date(now()) + 2
      and exists (select 1 from public.po_lines pl where pl.po_id = po.id and pl.deleted_at is null and not pl.closed
                    and pl.qty - pl.qty_accepted > 0.0005)
      and po.project_id in (select pm.project_id from public.project_members pm where pm.user_id = p_user
                            union select pj.id from public.projects pj where v_role = 'admin');
  end if;
end $$;
revoke execute on function app.purchase_store_approvals_for(uuid) from public;
insert into app.approval_sources (fn) values ('app.purchase_store_approvals_for') on conflict do nothing;


-- >>>>>>>>>>>>>>>>>>>> 20261103000060_client_billing.sql

-- =============================================================================
-- Client billing: interim payment certificates (IPC) to the client and variations (change orders).
--
-- * client_contracts  one per project: contract sum, VAT, advance + its recovery rate, retention (+ limit),
--                     materials-on-site allowance, withholding tax deducted by the client.
-- * client_ipcs       IPC No. n for a period; quantities to date default to the VERIFIED BoQ progress of the
--                     project's schedules (app.boq_progress_raw) and can be re-measured per line.
--                     Workflow: draft → prepared (office engineer / QS) → checked (coordinator) → submitted to the
--                     consultant (manager) → certified (consultant figures recorded, may differ) → paid (finance).
--                     Returned at any step before certification goes back to draft.
-- * variations        VO-n with lines (new BoQ items or quantity changes of existing ones), internal approval by
--                     the manager, then client approval recorded; an approved VO updates the BoQ, so the work is
--                     measured and billed in the next IPC like any other item.
-- Amounts are price data: tables are readable only by members who can see prices (app.can_see_prices()).
-- Ethiopian practice used as defaults: VAT 15 %, retention 5 % (limit 5 % of the contract sum), advance up to
-- 30 % recovered pro rata (same %), withholding 3 % on the ex-VAT amount (Proclamation 1395/2025).
-- Inbox items via app.approval_sources (20261103000000).
-- =============================================================================

create table if not exists public.client_contracts (
  project_id              uuid primary key references public.projects (id) on delete cascade,
  contract_no             text,
  client_name             text,
  consultant_name         text,
  contract_sum            numeric(18,2) not null default 0 check (contract_sum >= 0),   -- ex VAT
  vat_pct                 numeric(5,2) not null default 15 check (vat_pct between 0 and 100),
  advance_amount          numeric(18,2) not null default 0 check (advance_amount >= 0),
  advance_recovery_pct    numeric(5,2) not null default 0 check (advance_recovery_pct between 0 and 100),
  retention_pct           numeric(5,2) not null default 5 check (retention_pct between 0 and 100),
  retention_limit_pct     numeric(5,2) not null default 5 check (retention_limit_pct between 0 and 100),
  mos_pct                 numeric(5,2) not null default 0 check (mos_pct between 0 and 100),   -- share of materials on site paid
  wht_pct                 numeric(5,2) not null default 3 check (wht_pct between 0 and 100),
  updated_by              uuid references public.profiles (id),
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now()
);

create table if not exists public.variations (
  id               uuid primary key,
  project_id       uuid not null references public.projects (id),
  number           text not null,
  title            text not null,
  instruction_ref  text,
  instruction_date date,
  reason           text,
  status           text not null default 'draft' check (status in ('draft','pending','submitted','approved','rejected','cancelled')),
  amount           numeric(18,2) not null default 0,     -- ex VAT, from the lines (approved amount once approved)
  client_ref       text,
  decided_at       timestamptz,
  decision_comment text,
  created_by       uuid not null references public.profiles (id),
  approved_by      uuid references public.profiles (id),   -- internal (manager) approval
  approved_at      timestamptz,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (project_id, number)
);

create table if not exists public.variation_lines (
  id            uuid primary key,
  variation_id  uuid not null references public.variations (id) on delete cascade,
  project_id    uuid not null references public.projects (id),
  line_no       int not null,
  boq_item_id   uuid references public.boq_items (id),    -- existing item whose quantity changes; null = new item
  item_no       text not null,
  description   text not null,
  unit          text not null,
  qty           numeric(16,3) not null,                  -- change (may be negative for omissions)
  rate          numeric(18,2) not null check (rate >= 0),
  amount        numeric(18,2) generated always as (round(qty * rate, 2)) stored,
  created_boq_item_id uuid references public.boq_items (id),
  updated_at    timestamptz not null default now()
);

create table if not exists public.client_ipcs (
  id               uuid primary key,
  project_id       uuid not null references public.projects (id),
  ipc_no           int not null check (ipc_no > 0),
  period_from      date,
  period_to        date not null,
  status           text not null default 'draft' check (status in ('draft','prepared','checked','submitted','certified','paid','cancelled')),
  is_final         boolean not null default false,
  mos_value        numeric(18,2) not null default 0 check (mos_value >= 0),          -- materials on site at period end (claimed)
  price_adjustment numeric(18,2) not null default 0,                                 -- cumulative price adjustment claimed
  claimed          jsonb not null default '{}'::jsonb,                               -- totals (app.ipc_totals)
  certified        jsonb,                                                            -- consultant's totals
  certified_mos_value        numeric(18,2),
  certified_price_adjustment numeric(18,2),
  consultant_ref   text,
  certified_on     date,
  paid_amount      numeric(18,2) not null default 0,
  paid_on          date,
  payment_ref      text,
  remarks          text,
  return_comment   text,
  prepared_by      uuid references public.profiles (id),
  prepared_at      timestamptz,
  checked_by       uuid references public.profiles (id),
  checked_at       timestamptz,
  submitted_by     uuid references public.profiles (id),
  submitted_at     timestamptz,
  certified_by     uuid references public.profiles (id),
  paid_by          uuid references public.profiles (id),
  created_by       uuid not null references public.profiles (id),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (project_id, ipc_no)
);

create table if not exists public.client_ipc_lines (
  id               uuid primary key default gen_random_uuid(),
  ipc_id           uuid not null references public.client_ipcs (id) on delete cascade,
  project_id       uuid not null references public.projects (id),
  boq_item_id      uuid not null references public.boq_items (id),
  item_no          text not null,
  description      text not null,
  unit             text not null,
  contract_qty     numeric(16,3) not null default 0,
  rate             numeric(18,2) not null default 0,
  verified_qty     numeric(16,3) not null default 0,     -- verified site progress to date (reference)
  prev_qty         numeric(16,3) not null default 0,     -- cumulative of the previous IPC (certified when certified)
  cum_qty          numeric(16,3) not null default 0,     -- claimed cumulative
  certified_cum_qty numeric(16,3),                       -- consultant's cumulative
  remeasured       boolean not null default false,
  updated_at       timestamptz not null default now(),
  unique (ipc_id, boq_item_id)
);

create index if not exists client_ipc_lines_ipc_idx on public.client_ipc_lines (ipc_id);
create index if not exists variation_lines_var_idx on public.variation_lines (variation_id);
create index if not exists client_ipcs_project_idx on public.client_ipcs (project_id, ipc_no);

do $$
declare t text;
begin
  foreach t in array array['client_contracts','variations','variation_lines','client_ipcs','client_ipc_lines'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop trigger if exists touch_updated_at on public.%I', t);
    execute format('create trigger touch_updated_at before update on public.%I for each row execute function app.touch_updated_at()', t);
    execute format('drop policy if exists price_read on public.%I', t);
    execute format('create policy price_read on public.%I for select to authenticated using (app.is_member(project_id) and app.can_see_prices())', t);
  end loop;
  foreach t in array array['client_contracts','variations','client_ipcs'] loop
    execute format('drop trigger if exists audit on public.%I', t);
    execute format('create trigger audit after insert or update or delete on public.%I for each row execute function app.audit()', t);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- helpers
-- ---------------------------------------------------------------------------
create or replace function app.billing_guard(p_project uuid, variadic p_roles text[]) returns void
language plpgsql stable security definer set search_path = public as $$
begin
  perform app.require_member(p_project);
  perform app.require_role_txt(variadic p_roles);
  if not app.can_see_prices() then
    raise exception 'Client billing needs access to prices — ask the admin to add your role to the price roles' using errcode = '42501';
  end if;
end $$;

-- Verified quantity to date per BoQ item over the project's active schedules.
create or replace function app.billing_verified_qty(p_project uuid, p_date date)
returns table (boq_item_id uuid, qty numeric)
language sql stable security definer set search_path = public as $$
  select r.boq_item_id, sum(r.qty_to_date)
  from public.schedules s cross join lateral app.boq_progress_raw(s.id, p_date) r
  where s.project_id = p_project and s.status = 'active'
  group by r.boq_item_id
$$;

-- Totals of an IPC on the claimed or certified figures:
-- work, materials on site, price adjustment, gross, retention, advance recovery, net (all cumulative),
-- previous net, this period net (ex VAT), VAT, withholding, payable.
create or replace function app.ipc_totals(p_ipc uuid, p_basis text) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  i public.client_ipcs; c public.client_contracts; v_prev public.client_ipcs;
  v_work numeric; v_mos numeric; v_pa numeric; v_gross numeric; v_ret numeric; v_adv numeric; v_net numeric;
  v_prev_net numeric := 0; v_this numeric; v_vat numeric; v_wht numeric; v_prev_work numeric := 0;
begin
  select * into i from public.client_ipcs where id = p_ipc;
  select * into c from public.client_contracts where project_id = i.project_id;
  select coalesce(sum(round(case when p_basis = 'certified' then coalesce(l.certified_cum_qty, l.cum_qty) else l.cum_qty end * l.rate, 2)), 0),
         coalesce(sum(round(l.prev_qty * l.rate, 2)), 0)
    into v_work, v_prev_work from public.client_ipc_lines l where l.ipc_id = p_ipc;
  v_mos := round(case when p_basis = 'certified' then coalesce(i.certified_mos_value, i.mos_value) else i.mos_value end
                 * coalesce(c.mos_pct, 0) / 100, 2);
  v_pa := case when p_basis = 'certified' then coalesce(i.certified_price_adjustment, i.price_adjustment) else i.price_adjustment end;
  v_gross := v_work + v_mos + v_pa;
  v_ret := round(least(v_work * coalesce(c.retention_pct, 0) / 100,
                       case when coalesce(c.retention_limit_pct, 0) > 0 and coalesce(c.contract_sum, 0) > 0
                            then c.contract_sum * c.retention_limit_pct / 100 else v_work end), 2);
  if i.is_final then v_ret := 0; end if;                     -- final account releases retention (on final IPC)
  v_adv := round(least(coalesce(c.advance_amount, 0), v_work * coalesce(c.advance_recovery_pct, 0) / 100), 2);
  v_net := v_gross - v_ret - v_adv;
  select * into v_prev from public.client_ipcs
   where project_id = i.project_id and ipc_no < i.ipc_no and status <> 'cancelled' order by ipc_no desc limit 1;
  if found then v_prev_net := coalesce((coalesce(v_prev.certified, v_prev.claimed) ->> 'net_cum')::numeric, 0); end if;
  v_this := v_net - v_prev_net;
  v_vat := round(v_this * coalesce(c.vat_pct, 15) / 100, 2);
  v_wht := round(greatest(v_this, 0) * coalesce(c.wht_pct, 0) / 100, 2);
  return jsonb_build_object(
    'work_cum', v_work, 'work_prev', v_prev_work, 'work_this', v_work - v_prev_work,
    'mos', v_mos, 'price_adjustment', v_pa, 'gross_cum', v_gross,
    'retention_cum', v_ret, 'advance_recovery_cum', v_adv, 'net_cum', v_net,
    'previous_net', v_prev_net, 'this_net', v_this, 'vat', v_vat, 'total_incl_vat', v_this + v_vat,
    'wht', v_wht, 'payable', v_this + v_vat - v_wht,
    'retention_pct', c.retention_pct, 'advance_recovery_pct', c.advance_recovery_pct, 'vat_pct', coalesce(c.vat_pct, 15),
    'wht_pct', c.wht_pct, 'mos_pct', c.mos_pct, 'contract_sum', c.contract_sum,
    'progress_pct', case when coalesce(c.contract_sum, 0) > 0 then round(v_work / c.contract_sum * 100, 2) end);
end $$;
revoke execute on function app.ipc_totals(uuid, text) from public;

-- ---------------------------------------------------------------------------
-- contract terms
-- ---------------------------------------------------------------------------
create or replace function public.save_client_contract(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_seen jsonb := app.op_seen(p); v_project uuid := (p ->> 'project_id')::uuid; v_adv_pct numeric;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.billing_guard(v_project, 'coordinator', 'manager', 'admin');
  v_adv_pct := nullif(p ->> 'advance_recovery_pct', '')::numeric;
  insert into public.client_contracts (project_id, contract_no, client_name, consultant_name, contract_sum, vat_pct, advance_amount,
    advance_recovery_pct, retention_pct, retention_limit_pct, mos_pct, wht_pct, updated_by)
  values (v_project, nullif(p ->> 'contract_no', ''), nullif(p ->> 'client_name', ''), nullif(p ->> 'consultant_name', ''),
    coalesce((p ->> 'contract_sum')::numeric, 0), coalesce((p ->> 'vat_pct')::numeric, 15), coalesce((p ->> 'advance_amount')::numeric, 0),
    coalesce(v_adv_pct, case when coalesce((p ->> 'contract_sum')::numeric, 0) > 0
                             then round(coalesce((p ->> 'advance_amount')::numeric, 0) / (p ->> 'contract_sum')::numeric * 100, 2) else 0 end),
    coalesce((p ->> 'retention_pct')::numeric, 5), coalesce((p ->> 'retention_limit_pct')::numeric, 5),
    coalesce((p ->> 'mos_pct')::numeric, 0), coalesce((p ->> 'wht_pct')::numeric, 3), auth.uid())
  on conflict (project_id) do update set contract_no = excluded.contract_no, client_name = excluded.client_name,
    consultant_name = excluded.consultant_name, contract_sum = excluded.contract_sum, vat_pct = excluded.vat_pct,
    advance_amount = excluded.advance_amount, advance_recovery_pct = excluded.advance_recovery_pct,
    retention_pct = excluded.retention_pct, retention_limit_pct = excluded.retention_limit_pct, mos_pct = excluded.mos_pct,
    wht_pct = excluded.wht_pct, updated_by = auth.uid();
  if (select advance_amount > contract_sum and contract_sum > 0 from public.client_contracts where project_id = v_project) then
    raise exception 'The advance cannot be more than the contract sum';
  end if;
  return app.op_done(p, 'save_client_contract', jsonb_build_object('ok', true, 'project_id', v_project));
end $$;

-- ---------------------------------------------------------------------------
-- variations
-- ---------------------------------------------------------------------------
create or replace function public.save_variation(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); v_id uuid := coalesce((p ->> 'id')::uuid, gen_random_uuid());
  v_project uuid := (p ->> 'project_id')::uuid; v public.variations; x record; n int := 0; v_no text;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.billing_guard(v_project, 'office_engineer', 'coordinator', 'manager', 'admin');
  if nullif(trim(p ->> 'title'), '') is null then raise exception 'Give the variation a title'; end if;
  if jsonb_array_length(coalesce(p -> 'lines', '[]'::jsonb)) = 0 then raise exception 'Add at least one line'; end if;
  select * into v from public.variations where id = v_id for update;
  if found then
    if v.project_id <> v_project then raise exception 'Variation belongs to another project'; end if;
    if v.status not in ('draft') then raise exception 'Variation % is % and cannot be edited', v.number, v.status; end if;
    update public.variations set title = trim(p ->> 'title'), instruction_ref = nullif(p ->> 'instruction_ref', ''),
      instruction_date = nullif(p ->> 'instruction_date', '')::date, reason = nullif(p ->> 'reason', '') where id = v_id;
    delete from public.variation_lines where variation_id = v_id;
  else
    v_no := coalesce(nullif(p ->> 'number', ''), 'VO-' || lpad((coalesce((select count(*) from public.variations where project_id = v_project), 0) + 1)::text, 3, '0'));
    insert into public.variations (id, project_id, number, title, instruction_ref, instruction_date, reason, created_by)
    values (v_id, v_project, v_no, trim(p ->> 'title'), nullif(p ->> 'instruction_ref', ''), nullif(p ->> 'instruction_date', '')::date,
      nullif(p ->> 'reason', ''), auth.uid());
  end if;
  for x in select * from jsonb_to_recordset(p -> 'lines') as y(boq_item_id uuid, item_no text, description text, unit text, qty numeric, rate numeric) loop
    n := n + 1;
    if x.boq_item_id is not null then
      select coalesce(nullif(x.item_no, ''), b.item_no), coalesce(nullif(x.description, ''), b.description), coalesce(nullif(x.unit, ''), b.unit),
             coalesce(x.rate, (select r.rate from public.boq_rates r where r.boq_item_id = b.id))
        into x.item_no, x.description, x.unit, x.rate
        from public.boq_items b where b.id = x.boq_item_id and b.project_id = v_project;
      if not found then raise exception 'Line %: BoQ item is not in this project', n; end if;
    end if;
    if nullif(trim(x.item_no), '') is null or nullif(trim(x.description), '') is null or nullif(trim(x.unit), '') is null then
      raise exception 'Line %: item no., description and unit are required', n;
    end if;
    if x.qty is null or x.qty = 0 then raise exception 'Line %: enter the quantity (negative for an omission)', n; end if;
    if x.rate is null or x.rate < 0 then raise exception 'Line %: enter the rate', n; end if;
    if x.boq_item_id is null and x.qty < 0 then raise exception 'Line %: a new item cannot have a negative quantity', n; end if;
    if x.boq_item_id is null and exists (select 1 from public.boq_items where project_id = v_project and item_no = trim(x.item_no) and deleted_at is null) then
      raise exception 'Line %: item no. % already exists in the BoQ — pick the item to change its quantity', n, trim(x.item_no);
    end if;
    insert into public.variation_lines (id, variation_id, project_id, line_no, boq_item_id, item_no, description, unit, qty, rate)
    values (gen_random_uuid(), v_id, v_project, n, x.boq_item_id, trim(x.item_no), trim(x.description), trim(x.unit), x.qty, x.rate);
  end loop;
  update public.variations set amount = (select coalesce(sum(amount), 0) from public.variation_lines where variation_id = v_id) where id = v_id;
  if coalesce((p ->> 'submit')::boolean, false) then
    update public.variations set status = 'pending' where id = v_id;
    perform app.notify_roles(v_project, '{manager}', 'Variation to approve', (select number || ' ' || title from public.variations where id = v_id), 'variation', v_id);
  end if;
  return app.op_done(p, 'save_variation', jsonb_build_object('ok', true, 'id', v_id,
    'number', (select number from public.variations where id = v_id), 'status', (select status from public.variations where id = v_id),
    'amount', (select amount from public.variations where id = v_id)));
end $$;

-- action: approve (manager, pending → submitted to client), return (→ draft), client_approve / client_reject
-- (coordinator / manager, submitted → approved | rejected), cancel (draft/pending)
create or replace function public.decide_variation(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); v public.variations; a text := p ->> 'action'; c text := nullif(trim(p ->> 'comment'), '');
  l record; v_item uuid;
begin
  if v_seen is not null then return v_seen; end if;
  select * into v from public.variations where id = (p ->> 'variation_id')::uuid for update;
  if not found then raise exception 'Variation not found'; end if;
  if a in ('approve','return') then
    perform app.billing_guard(v.project_id, 'manager', 'admin');
    if v.status <> 'pending' then raise exception 'Only a variation waiting for approval can be %', case a when 'approve' then 'approved' else 'returned' end; end if;
    if a = 'return' and c is null then raise exception 'Say what needs changing'; end if;
    if a = 'approve' then
      update public.variations set status = 'submitted', approved_by = auth.uid(), approved_at = now(), decision_comment = c where id = v.id;
    else
      update public.variations set status = 'draft', decision_comment = c where id = v.id;
      perform app.notify_user(v.created_by, v.project_id, 'Variation ' || v.number || ' returned', c, 'variation', v.id);
    end if;
  elsif a in ('client_approve','client_reject') then
    perform app.billing_guard(v.project_id, 'coordinator', 'manager', 'admin');
    if v.status <> 'submitted' then raise exception 'Only a variation submitted to the client can be decided'; end if;
    if a = 'client_reject' then
      update public.variations set status = 'rejected', decided_at = now(), decision_comment = c, client_ref = nullif(p ->> 'client_ref', '') where id = v.id;
    else
      -- approved: new items enter the BoQ, changed items get the quantity change
      for l in select * from public.variation_lines where variation_id = v.id order by line_no loop
        if l.boq_item_id is null then
          insert into public.boq_items (project_id, item_no, description, unit, quantity)
          values (v.project_id, l.item_no, l.description || ' [' || v.number || ']', l.unit, l.qty)
          on conflict (project_id, item_no) do update set quantity = public.boq_items.quantity + excluded.quantity, deleted_at = null
          returning id into v_item;
          insert into public.boq_rates (boq_item_id, rate) values (v_item, l.rate) on conflict (boq_item_id) do nothing;
          update public.variation_lines set created_boq_item_id = v_item where id = l.id;
        else
          update public.boq_items set quantity = greatest(quantity + l.qty, 0) where id = l.boq_item_id;
          insert into public.boq_rates (boq_item_id, rate) values (l.boq_item_id, l.rate) on conflict (boq_item_id) do nothing;
        end if;
      end loop;
      update public.variations set status = 'approved', decided_at = now(), decision_comment = c,
        client_ref = nullif(p ->> 'client_ref', '') where id = v.id;
      update public.client_contracts set contract_sum = contract_sum + v.amount where project_id = v.project_id;
    end if;
  elsif a = 'cancel' then
    perform app.billing_guard(v.project_id, 'office_engineer', 'coordinator', 'manager', 'admin');
    if v.status not in ('draft','pending') then raise exception 'Only a draft or pending variation can be cancelled'; end if;
    update public.variations set status = 'cancelled', decision_comment = c where id = v.id;
  else
    raise exception 'Unknown action %', a;
  end if;
  return app.op_done(p, 'decide_variation', jsonb_build_object('ok', true, 'id', v.id, 'status', (select status from public.variations where id = v.id)));
end $$;

-- ---------------------------------------------------------------------------
-- IPC
-- ---------------------------------------------------------------------------
-- (Re)build the lines of a draft IPC: every BoQ item with work to date or billed before; quantities to date
-- default to verified progress at period_to (re-measured lines keep their claimed quantity).
create or replace function app.ipc_build_lines(p_ipc uuid) returns void
language plpgsql security definer set search_path = public as $$
declare i public.client_ipcs; v_prev uuid;
begin
  select * into i from public.client_ipcs where id = p_ipc;
  select id into v_prev from public.client_ipcs
   where project_id = i.project_id and ipc_no < i.ipc_no and status <> 'cancelled' order by ipc_no desc limit 1;
  with v as (select * from app.billing_verified_qty(i.project_id, i.period_to)),
  pr as (select boq_item_id, coalesce(certified_cum_qty, cum_qty) as q from public.client_ipc_lines where ipc_id = v_prev),
  items as (
    select b.id, b.item_no, b.description, b.unit, b.quantity, coalesce(r.rate, 0) as rate,
           coalesce(v.qty, 0) as vq, coalesce(pr.q, 0) as pq
    from public.boq_items b
    left join public.boq_rates r on r.boq_item_id = b.id
    left join v on v.boq_item_id = b.id
    left join pr on pr.boq_item_id = b.id
    where b.project_id = i.project_id and b.deleted_at is null and (coalesce(v.qty, 0) > 0 or coalesce(pr.q, 0) > 0))
  insert into public.client_ipc_lines (ipc_id, project_id, boq_item_id, item_no, description, unit, contract_qty, rate, verified_qty, prev_qty, cum_qty)
  select p_ipc, i.project_id, id, item_no, description, unit, quantity, rate, round(vq, 3), round(pq, 3), round(greatest(vq, pq), 3) from items
  on conflict (ipc_id, boq_item_id) do update set item_no = excluded.item_no, description = excluded.description, unit = excluded.unit,
    contract_qty = excluded.contract_qty, rate = excluded.rate, verified_qty = excluded.verified_qty, prev_qty = excluded.prev_qty,
    cum_qty = case when public.client_ipc_lines.remeasured then public.client_ipc_lines.cum_qty else excluded.cum_qty end;
end $$;
revoke execute on function app.ipc_build_lines(uuid) from public;

-- Create or update a draft: {id, project_id, period_to, period_from?, mos_value?, price_adjustment?, remarks?, is_final?,
--   lines?: [{boq_item_id, cum_qty}] (re-measured cumulative), refresh?: bool, prepare?: bool (send to the coordinator)}
create or replace function public.save_client_ipc(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); v_id uuid := coalesce((p ->> 'id')::uuid, gen_random_uuid());
  v_project uuid := (p ->> 'project_id')::uuid; i public.client_ipcs; v_prev public.client_ipcs; x record; v_no int;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.billing_guard(v_project, 'office_engineer', 'coordinator', 'manager', 'admin');
  if not exists (select 1 from public.client_contracts where project_id = v_project) then
    raise exception 'Enter the contract terms first (contract sum, retention, advance)';
  end if;
  select * into i from public.client_ipcs where id = v_id for update;
  if not found then
    if exists (select 1 from public.client_ipcs where project_id = v_project and status in ('draft','prepared','checked')) then
      raise exception 'IPC % is still being prepared — finish or cancel it first',
        (select ipc_no from public.client_ipcs where project_id = v_project and status in ('draft','prepared','checked') order by ipc_no limit 1);
    end if;
    select * into v_prev from public.client_ipcs where project_id = v_project and status <> 'cancelled' order by ipc_no desc limit 1;
    v_no := coalesce(v_prev.ipc_no, 0) + 1;
    if (p ->> 'period_to') is null then raise exception 'Enter the period end (measurement date)'; end if;
    if v_prev.id is not null and (p ->> 'period_to')::date <= v_prev.period_to then
      raise exception 'The period must end after IPC % (%)', v_prev.ipc_no, v_prev.period_to;
    end if;
    insert into public.client_ipcs (id, project_id, ipc_no, period_from, period_to, mos_value, price_adjustment, remarks, is_final, created_by)
    values (v_id, v_project, v_no, coalesce((p ->> 'period_from')::date, v_prev.period_to + 1), (p ->> 'period_to')::date,
      coalesce((p ->> 'mos_value')::numeric, 0), coalesce((p ->> 'price_adjustment')::numeric, 0), nullif(p ->> 'remarks', ''),
      coalesce((p ->> 'is_final')::boolean, false), auth.uid());
    perform app.ipc_build_lines(v_id);
  else
    if i.project_id <> v_project then raise exception 'IPC belongs to another project'; end if;
    if i.status <> 'draft' then raise exception 'IPC % is % — return it to draft to change it', i.ipc_no, i.status; end if;
    update public.client_ipcs set
      period_from = coalesce((p ->> 'period_from')::date, period_from), period_to = coalesce((p ->> 'period_to')::date, period_to),
      mos_value = coalesce((p ->> 'mos_value')::numeric, mos_value), price_adjustment = coalesce((p ->> 'price_adjustment')::numeric, price_adjustment),
      remarks = coalesce(nullif(p ->> 'remarks', ''), remarks), is_final = coalesce((p ->> 'is_final')::boolean, is_final)
    where id = v_id;
    if coalesce((p ->> 'refresh')::boolean, false) or (p ->> 'period_to') is not null then perform app.ipc_build_lines(v_id); end if;
  end if;
  if (select mos_value < 0 from public.client_ipcs where id = v_id) then raise exception 'Materials on site cannot be negative'; end if;
  for x in select * from jsonb_to_recordset(coalesce(p -> 'lines', '[]'::jsonb)) as y(boq_item_id uuid, cum_qty numeric) loop
    if x.cum_qty is null or x.cum_qty < 0 then raise exception 'Quantity to date must be zero or more'; end if;
    if not exists (select 1 from public.client_ipc_lines where ipc_id = v_id and boq_item_id = x.boq_item_id) then
      insert into public.client_ipc_lines (ipc_id, project_id, boq_item_id, item_no, description, unit, contract_qty, rate, cum_qty, remeasured)
      select v_id, v_project, b.id, b.item_no, b.description, b.unit, b.quantity, coalesce(r.rate, 0), x.cum_qty, true
        from public.boq_items b left join public.boq_rates r on r.boq_item_id = b.id where b.id = x.boq_item_id and b.project_id = v_project;
      if not found then raise exception 'BoQ item is not in this project'; end if;
    else
      update public.client_ipc_lines set cum_qty = x.cum_qty, remeasured = (x.cum_qty <> verified_qty)
       where ipc_id = v_id and boq_item_id = x.boq_item_id;
    end if;
    if (select cum_qty < prev_qty from public.client_ipc_lines where ipc_id = v_id and boq_item_id = x.boq_item_id)
       and nullif(p ->> 'remarks', '') is null and (select remarks from public.client_ipcs where id = v_id) is null then
      raise exception 'Quantity to date is less than the previous certificate — add a remark explaining the correction';
    end if;
  end loop;
  update public.client_ipcs set claimed = app.ipc_totals(v_id, 'claimed') where id = v_id;
  if coalesce((p ->> 'prepare')::boolean, false) then
    if not exists (select 1 from public.client_ipc_lines where ipc_id = v_id and cum_qty > 0) and (select mos_value = 0 from public.client_ipcs where id = v_id) then
      raise exception 'Nothing to bill: no verified progress and no materials on site';
    end if;
    update public.client_ipcs set status = 'prepared', prepared_by = auth.uid(), prepared_at = now(), return_comment = null where id = v_id;
    perform app.notify_roles(v_project, '{coordinator}', 'IPC ' || (select ipc_no from public.client_ipcs where id = v_id) || ' to check',
      'Payment certificate to the client', 'client_ipc', v_id);
  end if;
  select * into i from public.client_ipcs where id = v_id;
  return app.op_done(p, 'save_client_ipc', jsonb_build_object('ok', true, 'id', v_id, 'ipc_no', i.ipc_no, 'status', i.status, 'claimed', i.claimed));
end $$;

-- action: check (coordinator: prepared → checked), submit (manager: checked → submitted), return (→ draft, comment),
-- certify (coordinator/manager: submitted → certified; certified_lines [{boq_item_id, cum_qty}], certified_mos_value,
-- certified_price_adjustment, consultant_ref, certified_on), pay (finance/manager/admin: certified → paid),
-- cancel (draft/prepared)
create or replace function public.decide_client_ipc(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); i public.client_ipcs; a text := p ->> 'action'; c text := nullif(trim(p ->> 'comment'), '');
  x record; v_cert jsonb; v_amt numeric;
begin
  if v_seen is not null then return v_seen; end if;
  select * into i from public.client_ipcs where id = (p ->> 'ipc_id')::uuid for update;
  if not found then raise exception 'IPC not found'; end if;
  if a = 'check' then
    perform app.billing_guard(i.project_id, 'coordinator', 'admin');
    if i.status <> 'prepared' then raise exception 'IPC % is % — only a prepared IPC can be checked', i.ipc_no, i.status; end if;
    if i.prepared_by = auth.uid() and not app.has_role_txt('admin') then raise exception 'The preparer cannot check their own IPC' using errcode = '42501'; end if;
    update public.client_ipcs set status = 'checked', checked_by = auth.uid(), checked_at = now() where id = i.id;
    perform app.notify_roles(i.project_id, '{manager}', 'IPC ' || i.ipc_no || ' to approve', 'Checked by the coordinator', 'client_ipc', i.id);
  elsif a = 'submit' then
    perform app.billing_guard(i.project_id, 'manager', 'admin');
    if i.status <> 'checked' then raise exception 'IPC % must be checked by the coordinator before it is submitted', i.ipc_no; end if;
    update public.client_ipcs set status = 'submitted', submitted_by = auth.uid(), submitted_at = now(),
      claimed = app.ipc_totals(i.id, 'claimed') where id = i.id;
  elsif a = 'return' then
    perform app.billing_guard(i.project_id, 'coordinator', 'manager', 'admin');
    if i.status not in ('prepared','checked','submitted') then raise exception 'IPC % is % and cannot be returned', i.ipc_no, i.status; end if;
    if c is null then raise exception 'Say what needs correcting'; end if;
    update public.client_ipcs set status = 'draft', return_comment = c where id = i.id;
    if i.prepared_by is not null then
      perform app.notify_user(i.prepared_by, i.project_id, 'IPC ' || i.ipc_no || ' returned', c, 'client_ipc', i.id);
    end if;
  elsif a = 'certify' then
    perform app.billing_guard(i.project_id, 'coordinator', 'manager', 'admin');
    if i.status <> 'submitted' then raise exception 'Only a submitted IPC can be certified'; end if;
    update public.client_ipc_lines set certified_cum_qty = null where ipc_id = i.id;
    for x in select * from jsonb_to_recordset(coalesce(p -> 'certified_lines', '[]'::jsonb)) as y(boq_item_id uuid, cum_qty numeric) loop
      if x.cum_qty is null or x.cum_qty < 0 then raise exception 'Certified quantity must be zero or more'; end if;
      update public.client_ipc_lines set certified_cum_qty = x.cum_qty where ipc_id = i.id and boq_item_id = x.boq_item_id;
    end loop;
    update public.client_ipcs set certified_mos_value = coalesce((p ->> 'certified_mos_value')::numeric, mos_value),
      certified_price_adjustment = coalesce((p ->> 'certified_price_adjustment')::numeric, price_adjustment),
      consultant_ref = nullif(p ->> 'consultant_ref', ''), certified_on = coalesce((p ->> 'certified_on')::date, app.local_date(now())),
      certified_by = auth.uid()
    where id = i.id;
    v_cert := app.ipc_totals(i.id, 'certified');
    update public.client_ipcs set certified = v_cert, status = 'certified' where id = i.id;
    perform app.notify_roles(i.project_id, '{manager,coordinator}', 'IPC ' || i.ipc_no || ' certified',
      'Payable ' || to_char((v_cert ->> 'payable')::numeric, 'FM999,999,999,990.00'), 'client_ipc', i.id);
  elsif a = 'pay' then
    perform app.billing_guard(i.project_id, 'finance', 'manager', 'admin');
    if i.status not in ('certified','paid') then raise exception 'Only a certified IPC can be marked paid'; end if;
    v_amt := (p ->> 'amount')::numeric;
    if v_amt is null or v_amt <= 0 then raise exception 'Enter the amount received'; end if;
    update public.client_ipcs set paid_amount = paid_amount + v_amt, paid_on = coalesce((p ->> 'paid_on')::date, app.local_date(now())),
      payment_ref = coalesce(nullif(p ->> 'payment_ref', ''), payment_ref), paid_by = auth.uid(),
      status = case when paid_amount + v_amt >= coalesce((certified ->> 'payable')::numeric, 0) - 0.005 then 'paid' else 'certified' end
    where id = i.id;
  elsif a = 'cancel' then
    perform app.billing_guard(i.project_id, 'coordinator', 'manager', 'admin');
    if i.status not in ('draft','prepared') then raise exception 'Only a draft IPC can be cancelled'; end if;
    if exists (select 1 from public.client_ipcs where project_id = i.project_id and ipc_no > i.ipc_no and status <> 'cancelled') then
      raise exception 'A later IPC exists';
    end if;
    update public.client_ipcs set status = 'cancelled', return_comment = c where id = i.id;
  else
    raise exception 'Unknown action %', a;
  end if;
  select * into i from public.client_ipcs where id = i.id;
  return app.op_done(p, 'decide_client_ipc', jsonb_build_object('ok', true, 'id', i.id, 'status', i.status,
    'claimed', i.claimed, 'certified', i.certified, 'paid_amount', i.paid_amount));
end $$;

-- ---------------------------------------------------------------------------
-- approvals inbox
-- ---------------------------------------------------------------------------
create or replace function app.billing_approvals_for(p_user uuid)
returns table (kind text, entity_type text, entity_id uuid, project_id uuid, number text, title text, status text,
               requested_by uuid, requested_at timestamptz, is_urgent boolean, actions text[], age_hours numeric)
language plpgsql stable security definer set search_path = public as $$
declare v_role text; v_prices boolean;
begin
  select pr.role::text into v_role from public.profiles pr where pr.id = p_user and pr.is_active;
  if v_role is null then return; end if;
  v_prices := v_role = 'admin' or v_role = any (coalesce((select s.price_roles::text[] from public.app_settings s where s.id = 1), '{}'));
  if not v_prices then return; end if;
  return query
  with mem as (
    select pm.project_id as pid from public.project_members pm where pm.user_id = p_user
    union select pj.id from public.projects pj where v_role = 'admin')
  select 'client_ipc'::text, 'client_ipc'::text, i.id, i.project_id, 'IPC ' || i.ipc_no,
         case i.status when 'prepared' then 'Check payment certificate ' when 'checked' then 'Approve & submit payment certificate '
                       when 'submitted' then 'Record consultant certification — IPC ' else 'Record client payment — IPC ' end
           || case when i.status in ('prepared','checked') then i.ipc_no::text else i.ipc_no::text end
           || ' (' || to_char(coalesce((coalesce(i.certified, i.claimed) ->> 'payable')::numeric, 0), 'FM999,999,999,990') || ' ETB)',
         i.status, coalesce(i.prepared_by, i.created_by), coalesce(i.checked_at, i.prepared_at, i.submitted_at, i.created_at), false,
         array['open'], round((extract(epoch from now() - coalesce(i.checked_at, i.prepared_at, i.created_at)) / 3600)::numeric, 1)
  from public.client_ipcs i
  where i.project_id in (select pid from mem)
    and ((i.status = 'prepared' and v_role in ('coordinator','admin') and i.prepared_by is distinct from p_user)
      or (i.status = 'checked' and v_role in ('manager','admin'))
      or (i.status = 'certified' and v_role in ('finance','admin') and i.paid_amount < coalesce((i.certified ->> 'payable')::numeric, 0)))
  union all
  select 'variation'::text, 'variation'::text, v.id, v.project_id, v.number,
         case v.status when 'pending' then 'Approve variation ' else 'Record client decision — ' end || v.title
           || ' (' || to_char(v.amount, 'FM999,999,999,990') || ' ETB)',
         v.status, v.created_by, v.updated_at, false, array['open'],
         round((extract(epoch from now() - v.updated_at) / 3600)::numeric, 1)
  from public.variations v
  where v.project_id in (select pid from mem)
    and ((v.status = 'pending' and v_role in ('manager','admin')));
end $$;
revoke execute on function app.billing_approvals_for(uuid) from public;
insert into app.approval_sources (fn) values ('app.billing_approvals_for') on conflict do nothing;


-- >>>>>>>>>>>>>>>>>>>> 20261104000000_ipc_certificate.sql

-- =============================================================================
-- Payment certificate in the company's layout (template "CCECC 2nd payment"):
--
--   1  value of work executed (and materials) to date
--   2  total previous payment            = value to date of the previous certificate
--   3  rebate         rebate % × (1 − 2)
--   4  retention      retention % × (1 − 2)   (cumulative capped at the limit; released on the final IPC)
--   5  penalty        6 material delivered (client-supplied materials)
--   7  total deduction = 2 + 3 + 4 + 5 + 6
--   8  net before advance repayment & VAT = 1 − 7
--   9  advance repayment (this certificate)      10 net after advance = 8 − 9
--  11  withholding    wht % × (1 − 2)          12 VAT  vat % × (1 − 2)
--      total to the contractor = 10 − 11 + 12
--
-- Contract summary adds a supplementary contract, the rebate % and the signing date; the company logo for printed
-- forms lives in app_settings. Re-runnable.
-- =============================================================================

alter table public.app_settings add column if not exists company_logo text;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'app_settings_company_logo_size') then
    alter table public.app_settings add constraint app_settings_company_logo_size
      check (company_logo is null or (company_logo like 'data:image/%' and length(company_logo) <= 700000));
  end if;
end $$;

alter table public.client_contracts add column if not exists supplementary_sum numeric(18,2) not null default 0;
alter table public.client_contracts add column if not exists rebate_pct numeric(5,2) not null default 0;
alter table public.client_contracts add column if not exists signed_on date;
alter table public.client_ipcs add column if not exists penalty numeric(18,2) not null default 0;
alter table public.client_ipcs add column if not exists material_delivered numeric(18,2) not null default 0;

create or replace function app.ipc_totals(p_ipc uuid, p_basis text) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  i public.client_ipcs; c public.client_contracts; v_prev public.client_ipcs; pt jsonb;
  v_work numeric; v_prev_work numeric := 0; v_mos numeric; v_pa numeric; v_value numeric; v_prev_value numeric := 0; v_this numeric;
  v_prev_ret numeric := 0; v_prev_adv numeric := 0; v_limit numeric; v_ret numeric; v_rebate numeric; v_pen numeric; v_mat numeric;
  v_ded numeric; v_before numeric; v_adv_cum numeric; v_adv numeric; v_after numeric; v_vat numeric; v_wht numeric; v_sum numeric;
begin
  select * into i from public.client_ipcs where id = p_ipc;
  select * into c from public.client_contracts where project_id = i.project_id;
  select coalesce(sum(round(case when p_basis = 'certified' then coalesce(l.certified_cum_qty, l.cum_qty) else l.cum_qty end * l.rate, 2)), 0),
         coalesce(sum(round(l.prev_qty * l.rate, 2)), 0)
    into v_work, v_prev_work from public.client_ipc_lines l where l.ipc_id = p_ipc;
  v_mos := round(case when p_basis = 'certified' then coalesce(i.certified_mos_value, i.mos_value) else i.mos_value end
                 * coalesce(c.mos_pct, 0) / 100, 2);
  v_pa := case when p_basis = 'certified' then coalesce(i.certified_price_adjustment, i.price_adjustment) else i.price_adjustment end;
  v_value := v_work + v_mos + v_pa;

  select * into v_prev from public.client_ipcs
   where project_id = i.project_id and ipc_no < i.ipc_no and status <> 'cancelled' order by ipc_no desc limit 1;
  if found then
    pt := coalesce(v_prev.certified, v_prev.claimed);
    v_prev_value := coalesce((pt ->> 'value_cum')::numeric, (pt ->> 'gross_cum')::numeric, 0);
    v_prev_ret := coalesce((pt ->> 'retention_cum')::numeric, 0);
    v_prev_adv := coalesce((pt ->> 'advance_recovery_cum')::numeric, 0);
  end if;
  v_this := v_value - v_prev_value;
  v_sum := coalesce(c.contract_sum, 0) + coalesce(c.supplementary_sum, 0);

  v_rebate := round(v_this * coalesce(c.rebate_pct, 0) / 100, 2);
  v_ret := round(v_this * coalesce(c.retention_pct, 0) / 100, 2);
  if coalesce(c.retention_limit_pct, 0) > 0 and v_sum > 0 then
    v_limit := round(v_sum * c.retention_limit_pct / 100, 2);
    v_ret := least(v_ret, greatest(v_limit - v_prev_ret, 0));
  end if;
  if i.is_final then v_ret := -v_prev_ret; end if;             -- final certificate releases the retention
  v_pen := coalesce(i.penalty, 0);
  v_mat := coalesce(i.material_delivered, 0);
  v_ded := v_prev_value + v_rebate + v_ret + v_pen + v_mat;
  v_before := v_value - v_ded;
  v_adv_cum := round(least(coalesce(c.advance_amount, 0), v_work * coalesce(c.advance_recovery_pct, 0) / 100), 2);
  v_adv := v_adv_cum - v_prev_adv;
  v_after := v_before - v_adv;
  v_wht := round(greatest(v_this, 0) * coalesce(c.wht_pct, 0) / 100, 2);
  v_vat := round(v_this * coalesce(c.vat_pct, 15) / 100, 2);

  return jsonb_build_object(
    -- template lines
    'value_cum', v_value, 'previous_value', v_prev_value, 'this_value', v_this,
    'rebate', v_rebate, 'retention_this', v_ret, 'penalty', v_pen, 'material_delivered', v_mat,
    'total_deduction', v_ded, 'net_before_advance', v_before, 'advance_this', v_adv, 'net_after_advance', v_after,
    'wht', v_wht, 'vat', v_vat, 'payable', v_after - v_wht + v_vat,
    -- breakdown / cumulative
    'work_cum', v_work, 'work_prev', v_prev_work, 'work_this', v_work - v_prev_work,
    'mos', v_mos, 'price_adjustment', v_pa, 'gross_cum', v_value,
    'retention_cum', v_prev_ret + v_ret, 'advance_recovery_cum', v_adv_cum,
    'net_cum', v_value - (v_prev_ret + v_ret) - v_adv_cum, 'previous_net', v_prev_value,
    'this_net', v_after, 'total_incl_vat', v_after + v_vat,
    'rebate_pct', coalesce(c.rebate_pct, 0), 'retention_pct', c.retention_pct, 'advance_recovery_pct', c.advance_recovery_pct,
    'vat_pct', coalesce(c.vat_pct, 15), 'wht_pct', c.wht_pct, 'mos_pct', c.mos_pct, 'contract_sum', c.contract_sum,
    'progress_pct', case when v_sum > 0 then round(v_work / v_sum * 100, 2) end);
end $$;
revoke execute on function app.ipc_totals(uuid, text) from public;

create or replace function public.save_client_contract(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_seen jsonb := app.op_seen(p); v_project uuid := (p ->> 'project_id')::uuid; v_adv_pct numeric;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.billing_guard(v_project, 'coordinator', 'manager', 'admin');
  v_adv_pct := nullif(p ->> 'advance_recovery_pct', '')::numeric;
  insert into public.client_contracts (project_id, contract_no, client_name, consultant_name, contract_sum, vat_pct, advance_amount,
    advance_recovery_pct, retention_pct, retention_limit_pct, mos_pct, wht_pct, supplementary_sum, rebate_pct, signed_on, updated_by)
  values (v_project, nullif(p ->> 'contract_no', ''), nullif(p ->> 'client_name', ''), nullif(p ->> 'consultant_name', ''),
    coalesce((p ->> 'contract_sum')::numeric, 0), coalesce((p ->> 'vat_pct')::numeric, 15), coalesce((p ->> 'advance_amount')::numeric, 0),
    coalesce(v_adv_pct, case when coalesce((p ->> 'contract_sum')::numeric, 0) > 0
                             then round(coalesce((p ->> 'advance_amount')::numeric, 0) / (p ->> 'contract_sum')::numeric * 100, 2) else 0 end),
    coalesce((p ->> 'retention_pct')::numeric, 5), coalesce((p ->> 'retention_limit_pct')::numeric, 5),
    coalesce((p ->> 'mos_pct')::numeric, 0), coalesce((p ->> 'wht_pct')::numeric, 3),
    coalesce(nullif(p ->> 'supplementary_sum', '')::numeric, 0), coalesce(nullif(p ->> 'rebate_pct', '')::numeric, 0),
    nullif(p ->> 'signed_on', '')::date, auth.uid())
  on conflict (project_id) do update set contract_no = excluded.contract_no, client_name = excluded.client_name,
    consultant_name = excluded.consultant_name, contract_sum = excluded.contract_sum, vat_pct = excluded.vat_pct,
    advance_amount = excluded.advance_amount, advance_recovery_pct = excluded.advance_recovery_pct,
    retention_pct = excluded.retention_pct, retention_limit_pct = excluded.retention_limit_pct, mos_pct = excluded.mos_pct,
    wht_pct = excluded.wht_pct, supplementary_sum = excluded.supplementary_sum, rebate_pct = excluded.rebate_pct,
    signed_on = excluded.signed_on, updated_by = auth.uid();
  if (select advance_amount > contract_sum and contract_sum > 0 from public.client_contracts where project_id = v_project) then
    raise exception 'The advance cannot be more than the contract sum';
  end if;
  if (select supplementary_sum < 0 or rebate_pct not between 0 and 100 from public.client_contracts where project_id = v_project) then
    raise exception 'Supplementary contract cannot be negative and the rebate must be 0–100 %%';
  end if;
  return app.op_done(p, 'save_client_contract', jsonb_build_object('ok', true, 'project_id', v_project));
end $$;

-- As 20261103000060 plus penalty and material_delivered (client-supplied materials) per certificate.
create or replace function public.save_client_ipc(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); v_id uuid := coalesce((p ->> 'id')::uuid, gen_random_uuid());
  v_project uuid := (p ->> 'project_id')::uuid; i public.client_ipcs; v_prev public.client_ipcs; x record; v_no int;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.billing_guard(v_project, 'office_engineer', 'coordinator', 'manager', 'admin');
  if not exists (select 1 from public.client_contracts where project_id = v_project) then
    raise exception 'Enter the contract terms first (contract sum, retention, advance)';
  end if;
  select * into i from public.client_ipcs where id = v_id for update;
  if not found then
    if exists (select 1 from public.client_ipcs where project_id = v_project and status in ('draft','prepared','checked')) then
      raise exception 'IPC % is still being prepared — finish or cancel it first',
        (select ipc_no from public.client_ipcs where project_id = v_project and status in ('draft','prepared','checked') order by ipc_no limit 1);
    end if;
    select * into v_prev from public.client_ipcs where project_id = v_project and status <> 'cancelled' order by ipc_no desc limit 1;
    v_no := coalesce(v_prev.ipc_no, 0) + 1;
    if (p ->> 'period_to') is null then raise exception 'Enter the period end (measurement date)'; end if;
    if v_prev.id is not null and (p ->> 'period_to')::date <= v_prev.period_to then
      raise exception 'The period must end after IPC % (%)', v_prev.ipc_no, v_prev.period_to;
    end if;
    insert into public.client_ipcs (id, project_id, ipc_no, period_from, period_to, mos_value, price_adjustment, penalty, material_delivered,
      remarks, is_final, created_by)
    values (v_id, v_project, v_no, coalesce((p ->> 'period_from')::date, v_prev.period_to + 1), (p ->> 'period_to')::date,
      coalesce((p ->> 'mos_value')::numeric, 0), coalesce((p ->> 'price_adjustment')::numeric, 0),
      coalesce((p ->> 'penalty')::numeric, 0), coalesce((p ->> 'material_delivered')::numeric, 0), nullif(p ->> 'remarks', ''),
      coalesce((p ->> 'is_final')::boolean, false), auth.uid());
    perform app.ipc_build_lines(v_id);
  else
    if i.project_id <> v_project then raise exception 'IPC belongs to another project'; end if;
    if i.status <> 'draft' then raise exception 'IPC % is % — return it to draft to change it', i.ipc_no, i.status; end if;
    update public.client_ipcs set
      period_from = coalesce((p ->> 'period_from')::date, period_from), period_to = coalesce((p ->> 'period_to')::date, period_to),
      mos_value = coalesce((p ->> 'mos_value')::numeric, mos_value), price_adjustment = coalesce((p ->> 'price_adjustment')::numeric, price_adjustment),
      penalty = coalesce((p ->> 'penalty')::numeric, penalty), material_delivered = coalesce((p ->> 'material_delivered')::numeric, material_delivered),
      remarks = coalesce(nullif(p ->> 'remarks', ''), remarks), is_final = coalesce((p ->> 'is_final')::boolean, is_final)
    where id = v_id;
    if coalesce((p ->> 'refresh')::boolean, false) or (p ->> 'period_to') is not null then perform app.ipc_build_lines(v_id); end if;
  end if;
  if (select mos_value < 0 or penalty < 0 or material_delivered < 0 from public.client_ipcs where id = v_id) then
    raise exception 'Materials on site, penalty and materials delivered cannot be negative';
  end if;
  for x in select * from jsonb_to_recordset(coalesce(p -> 'lines', '[]'::jsonb)) as y(boq_item_id uuid, cum_qty numeric) loop
    if x.cum_qty is null or x.cum_qty < 0 then raise exception 'Quantity to date must be zero or more'; end if;
    if not exists (select 1 from public.client_ipc_lines where ipc_id = v_id and boq_item_id = x.boq_item_id) then
      insert into public.client_ipc_lines (ipc_id, project_id, boq_item_id, item_no, description, unit, contract_qty, rate, cum_qty, remeasured)
      select v_id, v_project, b.id, b.item_no, b.description, b.unit, b.quantity, coalesce(r.rate, 0), x.cum_qty, true
        from public.boq_items b left join public.boq_rates r on r.boq_item_id = b.id where b.id = x.boq_item_id and b.project_id = v_project;
      if not found then raise exception 'BoQ item is not in this project'; end if;
    else
      update public.client_ipc_lines set cum_qty = x.cum_qty, remeasured = (x.cum_qty <> verified_qty)
       where ipc_id = v_id and boq_item_id = x.boq_item_id;
    end if;
    if (select cum_qty < prev_qty from public.client_ipc_lines where ipc_id = v_id and boq_item_id = x.boq_item_id)
       and nullif(p ->> 'remarks', '') is null and (select remarks from public.client_ipcs where id = v_id) is null then
      raise exception 'Quantity to date is less than the previous certificate — add a remark explaining the correction';
    end if;
  end loop;
  update public.client_ipcs set claimed = app.ipc_totals(v_id, 'claimed') where id = v_id;
  if coalesce((p ->> 'prepare')::boolean, false) then
    if not exists (select 1 from public.client_ipc_lines where ipc_id = v_id and cum_qty > 0) and (select mos_value = 0 from public.client_ipcs where id = v_id) then
      raise exception 'Nothing to bill: no verified progress and no materials on site';
    end if;
    update public.client_ipcs set status = 'prepared', prepared_by = auth.uid(), prepared_at = now(), return_comment = null where id = v_id;
    perform app.notify_roles(v_project, '{coordinator}', 'IPC ' || (select ipc_no from public.client_ipcs where id = v_id) || ' to check',
      'Payment certificate to the client', 'client_ipc', v_id);
  end if;
  select * into i from public.client_ipcs where id = v_id;
  return app.op_done(p, 'save_client_ipc', jsonb_build_object('ok', true, 'id', v_id, 'ipc_no', i.ipc_no, 'status', i.status, 'claimed', i.claimed));
end $$;

-- Recalculate open certificates with the new layout's figures.
update public.client_ipcs set claimed = app.ipc_totals(id, 'claimed') where status in ('draft','prepared','checked');


-- >>>>>>>>>>>>>>>>>>>> 20261105000010_project_calendar.sql

-- =============================================================================
-- Project calendar: Ethiopian public holidays for any year, a work / no-work decision per project for every
-- upcoming holiday, and day-by-day calendar editing (rain days, shutdowns, overtime days, half days).
--
-- Holidays (public_holidays, country 'ET', Proclamation 1334/2024 arts. 4 and 6; memorial days in art. 5 stay open):
--   fixed in the Ethiopian calendar  Enkutatash (Meskerem 1), Meskel (Meskerem 17), Timket (Tir 11),
--                                    Adwa (Yekatit 23), Patriots' Victory (Miyazya 27)
--   fixed in the Gregorian calendar  Genna (7 Jan = Julian 25 Dec; Tahsas 28 in the year after a Pagume-6 year),
--                                    International Labour Day (1 May)
--   Orthodox Easter computus         Siklet (Good Friday) and Fasika (Julian Easter converted to Gregorian)
--   Hijri (tabular, tentative)       Eid al-Fitr (1 Shawwal), Eid al-Adha / Arafa (10 Dhu al-Hijja), Mawlid (12 Rabi I).
--                                    Ethiopia fixes these by moon sighting, often ±1 day: they stay is_tentative until
--                                    an admin confirms or moves them (save_public_holiday).
--   app.generate_et_holidays(from, to) fills any range of years; 2026–2035 are generated here.
--
-- Who decides (Labour Proclamation 1156/2019 art. 68: work on a public holiday is paid at 2.5× the hourly wage.
-- FIDIC 2017 clause 6.5 separately requires the Engineer's consent where that contract applies. The project MANAGER
-- records the project's operational decision; the planner side PROPOSES. External consent is not implied by this RPC):
--   view calendar                        every project member
--   propose work / no work on a holiday  site engineer, office engineer, coordinator (manager may decide directly)
--   decide a holiday                     manager, admin
--   edit ordinary days (rain day, client shutdown, overtime Sunday, half day, rename)
--                                        office engineer (planner), coordinator, manager, admin
--   working week / Saturday factor       coordinator, manager, admin
--   national holiday list (add / move / confirm lunar dates / generate years)   admin
-- Undecided holidays stay NON-working (the calendar default). Holidays on a non-working weekday need no decision.
--
-- Decisions and edits are calendar_exceptions (source 'project'); afterwards the not-started tasks whose
-- planned window covers a changed day are re-planned with the schedule CPM (app.replan_schedule) and the
-- forecast re-runs, so successors move too. Deciders are notified 30 days ahead (app.calendar_holiday_reminders,
-- run daily by pg_cron when available, and whenever the calendar page loads via calendar_sync); pending decisions
-- appear in the Approvals inbox (kind 'holiday') through app.approval_sources. Re-runnable.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- Holiday generator
-- ---------------------------------------------------------------------------
alter table public.public_holidays add column if not exists source text not null default 'seed';
alter table public.public_holidays add column if not exists confirmed_by uuid references public.profiles (id);
alter table public.public_holidays add column if not exists confirmed_at timestamptz;

-- Orthodox (Julian) Easter in the Gregorian calendar (Meeus). The Julian–Gregorian offset changes in century years.
create or replace function app.orthodox_easter(p_year int) returns date
language plpgsql immutable as $$
declare a int := p_year % 4; b int := p_year % 7; c int := p_year % 19; d int; e int; s int;
begin
  d := (19 * c + 15) % 30;
  e := (2 * a + 4 * b - d + 34) % 7;
  s := d + e + 114;
  return make_date(p_year, s / 31, s % 31 + 1) + (p_year / 100 - p_year / 400 - 2);
end $$;

-- Tabular (civil) Hijri date → Gregorian. Within a day of the sighted date; used as the tentative date.
create or replace function app.hijri_to_date(p_y int, p_m int, p_d int) returns date
language sql immutable as $$
  select to_date((p_d + (59 * (p_m - 1) + 1) / 2 + (p_y - 1) * 354 + (3 + 11 * p_y) / 30 + 1948439)::text, 'J')
$$;

-- Insert the Ethiopian public holidays of Gregorian years p_from..p_to. Existing rows (also the same holiday
-- moved by up to 5 days, e.g. a confirmed Eid) are kept. Returns the number of holidays added.
create or replace function app.generate_et_holidays(p_from int, p_to int) returns int
language plpgsql security definer set search_path = public as $$
declare g int; hy int; n int := 0; k int;
begin
  if p_to < p_from or p_to - p_from > 50 then raise exception 'Choose at most 50 years'; end if;
  for g in p_from .. p_to loop
    with c(on_date, name, name_am, kind, tentative) as (
      values
        (make_date(g, 1, 7), 'Genna (Ethiopian Christmas)', 'ገና', 'religious_orthodox', false),
        (app.from_ethiopian(g - 8, 5, 11), 'Timket (Epiphany)', 'ጥምቀት', 'religious_orthodox', false),
        (app.from_ethiopian(g - 8, 6, 23), 'Adwa Victory Day', 'የዓድዋ ድል በዓል', 'national', false),
        (app.orthodox_easter(g) - 2, 'Siklet (Good Friday)', 'ስቅለት', 'religious_orthodox', false),
        (app.orthodox_easter(g), 'Fasika (Easter)', 'ፋሲካ', 'religious_orthodox', false),
        (make_date(g, 5, 1), 'International Labour Day', 'የሠራተኞች ቀን', 'national', false),
        (app.from_ethiopian(g - 8, 8, 27), 'Patriots'' Victory Day', 'የአርበኞች ቀን', 'national', false),
        (app.from_ethiopian(g - 7, 1, 1), 'Enkutatash (New Year ' || (g - 7) || ' E.C.)', 'እንቁጣጣሽ', 'national', false),
        (app.from_ethiopian(g - 7, 1, 17), 'Meskel', 'መስቀል', 'religious_orthodox', false)
    )
    insert into public.public_holidays (country, on_date, name, name_am, kind, is_tentative, source)
    select 'ET', c.on_date, c.name, c.name_am, c.kind, c.tentative, 'generated' from c
    where not exists (select 1 from public.public_holidays h where h.country = 'ET' and h.name = c.name and abs(h.on_date - c.on_date) <= 5);
    get diagnostics k = row_count; n := n + k;

    for hy in (g - 622) * 33 / 32 - 1 .. (g - 622) * 33 / 32 + 2 loop
      with c(on_date, name, name_am) as (
        values
          (app.hijri_to_date(hy, 10, 1), 'Eid al-Fitr', 'ኢድ አልፈጥር'),
          (app.hijri_to_date(hy, 12, 10), 'Eid al-Adha (Arafa)', 'ኢድ አልአድሐ (አረፋ)'),
          (app.hijri_to_date(hy, 3, 12), 'Mawlid', 'መውሊድ')
      )
      insert into public.public_holidays (country, on_date, name, name_am, kind, is_tentative, source)
      select 'ET', c.on_date, c.name, c.name_am, 'religious_muslim', true, 'generated' from c
      where extract(year from c.on_date)::int = g
        and not exists (select 1 from public.public_holidays h where h.country = 'ET' and h.name = c.name and abs(h.on_date - c.on_date) <= 5);
      get diagnostics k = row_count; n := n + k;
    end loop;
  end loop;
  return n;
end $$;
revoke execute on function app.generate_et_holidays(int, int) from public;

-- ---------------------------------------------------------------------------
-- Decisions per project and calendar edits
-- ---------------------------------------------------------------------------
create table if not exists public.holiday_decisions (
  id               uuid primary key default gen_random_uuid(),
  project_id       uuid not null references public.projects (id) on delete cascade,
  holiday_id       uuid not null references public.public_holidays (id) on delete cascade,
  on_date          date not null,
  status           text not null default 'pending' check (status in ('pending','proposed','decided')),
  proposed_choice  text check (proposed_choice in ('work','half_day','no_work')),
  proposed_note    text,
  proposed_by      uuid references public.profiles (id),
  proposed_at      timestamptz,
  decision         text check (decision in ('work','half_day','no_work')),
  decision_note    text,
  decided_by       uuid references public.profiles (id),
  decided_at       timestamptz,
  notified_at      timestamptz,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (project_id, holiday_id)
);
create index if not exists holiday_decisions_project_date on public.holiday_decisions (project_id, on_date);
alter table public.holiday_decisions enable row level security;
drop policy if exists member_read on public.holiday_decisions;
create policy member_read on public.holiday_decisions for select to authenticated using (app.is_member(project_id));
drop trigger if exists touch_updated_at on public.holiday_decisions;
create trigger touch_updated_at before update on public.holiday_decisions for each row execute function app.touch_updated_at();
drop trigger if exists audit on public.holiday_decisions;
create trigger audit after insert or update or delete on public.holiday_decisions for each row execute function app.audit();

alter table public.calendar_exceptions add column if not exists category text;
alter table public.calendar_exceptions add column if not exists note text;
alter table public.calendar_exceptions add column if not exists holiday_decision_id uuid references public.holiday_decisions (id) on delete set null;
alter table public.calendar_exceptions add column if not exists updated_by uuid references public.profiles (id);
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'calendar_exceptions_category_check') then
    alter table public.calendar_exceptions add constraint calendar_exceptions_category_check
      check (category is null or category in ('rain','shutdown','overtime','half_day','holiday_work','holiday_off','other'));
  end if;
end $$;

-- Calendars change only through the RPCs below (they enforce who may do what); admin keeps direct access.
-- The national list is shared by every project, so only admins may write it (including direct table writes).
drop policy if exists master_write on public.project_calendars;
drop policy if exists master_write on public.calendar_exceptions;
drop policy if exists mgmt_write on public.public_holidays;
drop policy if exists admin_write on public.project_calendars;
drop policy if exists admin_write on public.calendar_exceptions;
drop policy if exists admin_write on public.public_holidays;
create policy admin_write on public.project_calendars for all to authenticated
  using (app.has_role_txt('admin')) with check (app.has_role_txt('admin'));
create policy admin_write on public.calendar_exceptions for all to authenticated
  using (app.has_role_txt('admin')) with check (app.has_role_txt('admin'));
create policy admin_write on public.public_holidays for all to authenticated
  using (app.has_role_txt('admin')) with check (app.has_role_txt('admin'));

-- Decision rows for every active project whose calendar uses public holidays: holidays from a month ago to
-- 400 days ahead that fall on a working weekday. Moved holidays carry their decision along; undecided rows for
-- days that no longer need one are dropped.
create or replace function app.ensure_holiday_decisions(p_project uuid default null) returns void
language plpgsql security definer set search_path = public as $$
declare v_today date := app.eat_date(now());
begin
  insert into public.holiday_decisions (project_id, holiday_id, on_date)
  select pc.project_id, h.id, h.on_date
  from public.project_calendars pc
  join public.projects pj on pj.id = pc.project_id and pj.is_active
  join public.public_holidays h on h.country = pc.holiday_country and h.deleted_at is null
   and h.on_date between v_today - 31 and v_today + 400
   and extract(isodow from h.on_date)::int = any (pc.working_weekdays)
  where pc.is_default and pc.deleted_at is null and pc.use_public_holidays
    and (p_project is null or pc.project_id = p_project)
  on conflict (project_id, holiday_id) do update set on_date = excluded.on_date
    where public.holiday_decisions.on_date is distinct from excluded.on_date;

  delete from public.holiday_decisions d
  where d.status <> 'decided' and (p_project is null or d.project_id = p_project)
    and not exists (
      select 1 from public.project_calendars pc join public.public_holidays h on h.id = d.holiday_id
      where pc.project_id = d.project_id and pc.is_default and pc.deleted_at is null and pc.use_public_holidays
        and h.deleted_at is null and h.country = pc.holiday_country and extract(isodow from h.on_date)::int = any (pc.working_weekdays));
end $$;
revoke execute on function app.ensure_holiday_decisions(uuid) from public;

-- Write the calendar exception of a decision (or remove it when the decision is reopened / the holiday moved).
create or replace function app.apply_holiday_decision(p_decision uuid) returns void
language plpgsql security definer set search_path = public as $$
declare d public.holiday_decisions; v_cal uuid; v_name text;
begin
  select * into d from public.holiday_decisions where id = p_decision;
  if not found then return; end if;
  v_cal := app.project_calendar(d.project_id);
  if v_cal is null then return; end if;
  update public.calendar_exceptions set deleted_at = now(), updated_by = auth.uid()
   where holiday_decision_id = d.id and deleted_at is null and (d.status <> 'decided' or on_date <> d.on_date);
  if d.status = 'decided' then
    select name into v_name from public.public_holidays where id = d.holiday_id;
    insert into public.calendar_exceptions (calendar_id, project_id, on_date, is_working, factor, name, source, category, note, holiday_decision_id, updated_by)
    values (v_cal, d.project_id, d.on_date, d.decision <> 'no_work', case when d.decision = 'half_day' then 0.5 end,
      v_name || case d.decision when 'work' then ' — working' when 'half_day' then ' — half day' else '' end, 'project',
      case when d.decision = 'no_work' then 'holiday_off' else 'holiday_work' end, d.decision_note, d.id, auth.uid())
    on conflict (calendar_id, on_date) do update set is_working = excluded.is_working, factor = excluded.factor, name = excluded.name,
      source = 'project', category = excluded.category, note = excluded.note, holiday_decision_id = excluded.holiday_decision_id,
      updated_by = excluded.updated_by, deleted_at = null;
  end if;
end $$;
revoke execute on function app.apply_holiday_decision(uuid) from public;

-- Re-date the project's active schedules after calendar days changed: not-started tasks whose planned window
-- covers a changed day are re-planned (successors follow through the links); all of them when p_dates is null.
-- The forecast is re-run either way. Returns {moved, schedules}.
create or replace function app.calendar_redate(p_project uuid, p_dates date[]) returns jsonb
language plpgsql security definer set search_path = public as $$
declare s record; v_seeds uuid[]; v_moved int := 0; v_n int := 0; r jsonb;
begin
  for s in select id, status_date from public.schedules where project_id = p_project and status = 'active' loop
    v_n := v_n + 1;
    if p_dates is null then
      v_seeds := null;
    else
      select coalesce(array_agg(t.id), '{}') into v_seeds from public.schedule_tasks t
       where t.schedule_id = s.id and t.deleted_at is null and not t.is_summary and t.actual_start is null and coalesce(t.pct_complete, 0) = 0
         and exists (select 1 from unnest(p_dates) x where x between t.planned_start and t.planned_finish);
    end if;
    if v_seeds is null or cardinality(v_seeds) > 0 then
      r := app.replan_schedule(s.id, v_seeds);
      v_moved := v_moved + coalesce((r ->> 'moved')::int, 0);
    else
      perform app.run_cpm(s.id, coalesce(s.status_date, app.eat_date(now())), true);
    end if;
  end loop;
  return jsonb_build_object('moved', v_moved, 'schedules', v_n);
end $$;
revoke execute on function app.calendar_redate(uuid, date[]) from public;

-- Holidays within 30 days that are not decided yet: notify once (manager decides; coordinator / office engineer
-- propose). Returns how many decisions were notified.
create or replace function app.calendar_holiday_reminders() returns int
language plpgsql security definer set search_path = public as $$
declare d record; n int := 0; v_today date := app.eat_date(now());
begin
  perform app.ensure_holiday_decisions(null);
  for d in select hd.id, hd.project_id, hd.on_date, hd.status, h.name, h.is_tentative from public.holiday_decisions hd
           join public.public_holidays h on h.id = hd.holiday_id
           where hd.status <> 'decided' and hd.notified_at is null and hd.on_date between v_today and v_today + 30 loop
    perform app.notify_roles_txt(d.project_id, '{manager,coordinator,office_engineer}',
      'Public holiday: work or not? — ' || d.name,
      to_char(d.on_date, 'Dy DD Mon YYYY') || ' (' || app.to_ethiopian(d.on_date) || ')' ||
      case when d.is_tentative then ' · date not yet confirmed' else '' end ||
      ' · confirm in the project calendar. Undecided = no work.', 'holiday_decision', d.id);
    update public.holiday_decisions set notified_at = now() where id = d.id;
    n := n + 1;
  end loop;
  return n;
end $$;
revoke execute on function app.calendar_holiday_reminders() from public;

-- New / re-dated holidays and calendar changes keep the decision rows complete.
create or replace function app.trg_holiday_decisions() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  perform app.ensure_holiday_decisions(null);
  return null;
end $$;
drop trigger if exists ensure_decisions on public.public_holidays;
create trigger ensure_decisions after insert on public.public_holidays
  for each statement execute function app.trg_holiday_decisions();
drop trigger if exists ensure_decisions on public.project_calendars;
create trigger ensure_decisions after insert or update of use_public_holidays, holiday_country, working_weekdays on public.project_calendars
  for each statement execute function app.trg_holiday_decisions();

-- ---------------------------------------------------------------------------
-- RPCs
-- ---------------------------------------------------------------------------
-- {project_id}: make sure upcoming holidays have decision rows and reminders went out (called by the calendar page).
create or replace function public.calendar_sync(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_project uuid := (p ->> 'project_id')::uuid;
begin
  perform app.require_member(v_project);
  return jsonb_build_object('ok', true, 'notified', app.calendar_holiday_reminders());
end $$;

-- {project_id, from, to}: the days of a range (≤ 100) with Ethiopian date, working / capacity, holiday, exception and
-- decision, plus the calendar settings and the holiday decisions from today to 120 days ahead.
create or replace function public.get_project_calendar(p jsonb) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_project uuid := (p ->> 'project_id')::uuid; v_from date := (p ->> 'from')::date; v_to date := (p ->> 'to')::date;
  v_cal public.project_calendars; v_today date := app.eat_date(now());
begin
  perform app.require_member(v_project);
  if v_from is null or v_to is null or v_to < v_from or v_to - v_from > 100 then raise exception 'Choose a range of at most 100 days'; end if;
  select * into v_cal from public.project_calendars where project_id = v_project and is_default and deleted_at is null limit 1;
  return jsonb_build_object(
    'calendar', case when v_cal.id is null then null else jsonb_build_object('id', v_cal.id, 'name', v_cal.name, 'working_weekdays', v_cal.working_weekdays,
      'saturday_factor', v_cal.saturday_factor, 'hours_per_day', v_cal.hours_per_day, 'use_public_holidays', v_cal.use_public_holidays,
      'holiday_country', v_cal.holiday_country, 'source', v_cal.source) end,
    'today', v_today,
    'days', (select coalesce(jsonb_agg(jsonb_build_object(
        'date', g.d, 'isodow', extract(isodow from g.d)::int,
        'eth_y', e.y, 'eth_m', e.m, 'eth_d', e.d,
        'working', app.is_working_day(v_project, g.d), 'capacity', app.day_capacity(v_project, g.d),
        'holiday', (select jsonb_build_object('id', h.id, 'name', h.name, 'name_am', h.name_am, 'kind', h.kind, 'is_tentative', h.is_tentative)
                    from public.public_holidays h
                    where h.country = coalesce(v_cal.holiday_country, 'ET') and h.on_date = g.d and h.deleted_at is null
                    order by h.kind = 'national' desc limit 1),
        'exception', (select jsonb_build_object('id', x.id, 'is_working', x.is_working, 'factor', x.factor, 'name', x.name, 'category', x.category,
                        'note', x.note, 'source', x.source, 'holiday_decision_id', x.holiday_decision_id)
                      from public.calendar_exceptions x where x.calendar_id = v_cal.id and x.on_date = g.d and x.deleted_at is null),
        'decision_id', (select hd.id from public.holiday_decisions hd where hd.project_id = v_project and hd.on_date = g.d limit 1)
      ) order by g.d), '[]'::jsonb)
      from generate_series(v_from, v_to, interval '1 day') as g0(t)
      cross join lateral (select g0.t::date as d) g
      cross join lateral app.ethiopian_parts(g.d) e),
    'decisions', (select coalesce(jsonb_agg(jsonb_build_object(
        'id', hd.id, 'holiday_id', hd.holiday_id, 'on_date', hd.on_date, 'status', hd.status,
        'name', h.name, 'name_am', h.name_am, 'kind', h.kind, 'is_tentative', h.is_tentative,
        'proposed_choice', hd.proposed_choice, 'proposed_note', hd.proposed_note, 'proposed_by', hd.proposed_by, 'proposed_at', hd.proposed_at,
        'decision', hd.decision, 'decision_note', hd.decision_note, 'decided_by', hd.decided_by, 'decided_at', hd.decided_at,
        'days_to_go', hd.on_date - v_today) order by hd.on_date), '[]'::jsonb)
      from public.holiday_decisions hd join public.public_holidays h on h.id = hd.holiday_id
      where hd.project_id = v_project and (hd.on_date between v_today and v_today + 120 or hd.on_date between v_from and v_to)));
end $$;

-- {decision_id, choice: work|half_day|no_work, note?}: suggest what the site does on a holiday; the manager decides.
create or replace function public.propose_holiday_decision(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_seen jsonb := app.op_seen(p); d public.holiday_decisions; v_choice text := p ->> 'choice'; v_name text;
begin
  if v_seen is not null then return v_seen; end if;
  select * into d from public.holiday_decisions where id = (p ->> 'decision_id')::uuid for update;
  if not found then raise exception 'Holiday not found for this project'; end if;
  perform app.require_member(d.project_id);
  perform app.require_role_txt('site_engineer', 'office_engineer', 'coordinator', 'manager', 'admin');
  if v_choice is null or v_choice not in ('work','half_day','no_work') then raise exception 'Choose work, half day or no work'; end if;
  if d.status = 'decided' then raise exception 'The manager already decided this holiday — ask them to reopen it'; end if;
  update public.holiday_decisions set status = 'proposed', proposed_choice = v_choice, proposed_note = nullif(trim(p ->> 'note'), ''),
    proposed_by = auth.uid(), proposed_at = now() where id = d.id;
  select name into v_name from public.public_holidays where id = d.holiday_id;
  perform app.notify_roles_txt(d.project_id, '{manager}', 'Holiday to decide — ' || v_name,
    'Proposed: ' || replace(v_choice, '_', ' ') || ' on ' || to_char(d.on_date, 'DD Mon YYYY') || coalesce(' · ' || nullif(trim(p ->> 'note'), ''), ''),
    'holiday_decision', d.id);
  return app.op_done(p, 'propose_holiday_decision', jsonb_build_object('ok', true, 'id', d.id, 'status', 'proposed'));
end $$;

-- {decision_id, choice: work|half_day|no_work | action: reopen, note?}: the project manager's decision; the
-- calendar and the schedule follow.
create or replace function public.decide_holiday(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_seen jsonb := app.op_seen(p); d public.holiday_decisions; v_choice text := p ->> 'choice'; v_r jsonb; v_name text;
begin
  if v_seen is not null then return v_seen; end if;
  select * into d from public.holiday_decisions where id = (p ->> 'decision_id')::uuid for update;
  if not found then raise exception 'Holiday not found for this project'; end if;
  perform app.require_member(d.project_id);
  if not app.has_role_txt('manager', 'admin') then
    raise exception 'Only the project manager records the project decision (2.5× pay; obtain Engineer consent when the contract requires it) — propose it instead'
      using errcode = '42501';
  end if;
  if p ->> 'action' = 'reopen' then
    update public.holiday_decisions set status = case when proposed_choice is null then 'pending' else 'proposed' end,
      decision = null, decision_note = null, decided_by = null, decided_at = null where id = d.id;
  else
    if v_choice is null or v_choice not in ('work','half_day','no_work') then raise exception 'Choose work, half day or no work'; end if;
    update public.holiday_decisions set status = 'decided', decision = v_choice, decision_note = nullif(trim(p ->> 'note'), ''),
      decided_by = auth.uid(), decided_at = now() where id = d.id;
  end if;
  perform app.apply_holiday_decision(d.id);
  v_r := app.calendar_redate(d.project_id, array[d.on_date]);
  if d.proposed_by is not null and p ->> 'action' is distinct from 'reopen' then
    select name into v_name from public.public_holidays where id = d.holiday_id;
    perform app.notify_user(d.proposed_by, d.project_id, 'Holiday decided — ' || v_name,
      replace(v_choice, '_', ' ') || ' on ' || to_char(d.on_date, 'DD Mon YYYY'), 'holiday_decision', d.id);
  end if;
  return app.op_done(p, 'decide_holiday', jsonb_build_object('ok', true, 'id', d.id,
    'status', (select status from public.holiday_decisions where id = d.id), 'moved', v_r -> 'moved'));
end $$;

-- {project_id, dates: [date…] (≤ 366), kind: normal|non_working|working|half_day, category?, name?, note?}
-- normal = back to the working-week pattern. On a public holiday the change is the holiday decision (manager only).
create or replace function public.edit_calendar_days(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); v_project uuid := (p ->> 'project_id')::uuid; v_kind text := p ->> 'kind';
  v_cal public.project_calendars; v_dates date[]; x date; v_dec uuid; v_cat text; v_name text := nullif(trim(p ->> 'name'), '');
  v_note text := nullif(trim(p ->> 'note'), ''); v_r jsonb; v_hol boolean;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.require_member(v_project);
  perform app.require_role_txt('office_engineer', 'coordinator', 'manager', 'admin');
  if v_kind is null or v_kind not in ('normal','non_working','working','half_day') then raise exception 'Unknown day type %', v_kind; end if;
  select array_agg(distinct (v)::date order by (v)::date) into v_dates from jsonb_array_elements_text(coalesce(p -> 'dates', '[]'::jsonb)) v;
  if v_dates is null then raise exception 'Pick at least one day'; end if;
  if cardinality(v_dates) > 366 then raise exception 'Pick at most 366 days at a time'; end if;
  v_cat := coalesce(nullif(p ->> 'category', ''), case v_kind when 'non_working' then 'other' when 'working' then 'overtime' when 'half_day' then 'half_day' end);
  if v_cat is not null and v_cat not in ('rain','shutdown','overtime','half_day','other') then raise exception 'Unknown reason %', v_cat; end if;
  select * into v_cal from public.project_calendars where project_id = v_project and is_default and deleted_at is null limit 1;
  if v_cal.id is null then raise exception 'This project has no calendar'; end if;

  foreach x in array v_dates loop
    v_hol := v_cal.use_public_holidays and exists (select 1 from public.public_holidays h
              where h.country = v_cal.holiday_country and h.on_date = x and h.deleted_at is null);
    select id into v_dec from public.holiday_decisions where project_id = v_project and on_date = x limit 1;
    if v_hol then
      if not app.has_role_txt('manager', 'admin') then
        raise exception '% is a public holiday — propose work / no work from the holiday list; the project manager decides', to_char(x, 'DD Mon YYYY')
          using errcode = '42501';
      end if;
      if v_dec is null then
        perform app.ensure_holiday_decisions(v_project);
        select id into v_dec from public.holiday_decisions where project_id = v_project and on_date = x limit 1;
      end if;
      if v_dec is not null then
        if v_kind = 'normal' then
          update public.holiday_decisions set status = case when proposed_choice is null then 'pending' else 'proposed' end,
            decision = null, decision_note = null, decided_by = null, decided_at = null where id = v_dec;
        else
          update public.holiday_decisions set status = 'decided', decided_by = auth.uid(), decided_at = now(), decision_note = coalesce(v_note, decision_note),
            decision = case v_kind when 'non_working' then 'no_work' when 'working' then 'work' else 'half_day' end where id = v_dec;
        end if;
        perform app.apply_holiday_decision(v_dec);
        continue;
      end if;
      -- holiday on a non-working weekday: a plain exception below
    end if;
    if v_kind = 'normal' then
      update public.calendar_exceptions set deleted_at = now(), updated_by = auth.uid()
       where calendar_id = v_cal.id and on_date = x and deleted_at is null;
    else
      insert into public.calendar_exceptions (calendar_id, project_id, on_date, is_working, factor, name, source, category, note, holiday_decision_id, updated_by)
      values (v_cal.id, v_project, x, v_kind <> 'non_working', case when v_kind = 'half_day' then 0.5 end,
        coalesce(v_name, case v_cat when 'rain' then 'Rain day' when 'shutdown' then 'Site shutdown' when 'overtime' then 'Overtime working day'
                                     when 'half_day' then 'Half day' else case when v_kind = 'non_working' then 'Non-working day' else 'Working day' end end),
        'project', v_cat, v_note, null, auth.uid())
      on conflict (calendar_id, on_date) do update set is_working = excluded.is_working, factor = excluded.factor, name = excluded.name,
        source = 'project', category = excluded.category, note = excluded.note, holiday_decision_id = null, updated_by = excluded.updated_by, deleted_at = null;
    end if;
  end loop;
  v_r := app.calendar_redate(v_project, v_dates);
  return app.op_done(p, 'edit_calendar_days', jsonb_build_object('ok', true, 'days', cardinality(v_dates), 'moved', v_r -> 'moved'));
end $$;

-- {project_id, working_weekdays[], saturday_factor?, hours_per_day?, use_public_holidays?, name?}
create or replace function public.save_project_calendar(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_seen jsonb := app.op_seen(p); v_project uuid := (p ->> 'project_id')::uuid; v_wd int[]; v_r jsonb;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.require_member(v_project);
  perform app.require_role_txt('coordinator', 'manager', 'admin');
  if p ? 'working_weekdays' then
    select array_agg(distinct v::int order by v::int) into v_wd from jsonb_array_elements_text(p -> 'working_weekdays') v;
    if v_wd is null or not (v_wd <@ '{1,2,3,4,5,6,7}'::int[]) then raise exception 'Pick the working days of the week'; end if;
  end if;
  if not exists (select 1 from public.project_calendars where project_id = v_project and is_default and deleted_at is null) then
    insert into public.project_calendars (project_id) values (v_project);
  end if;
  update public.project_calendars set
    working_weekdays = coalesce(v_wd, working_weekdays),
    saturday_factor = coalesce((p ->> 'saturday_factor')::numeric, saturday_factor),
    hours_per_day = coalesce((p ->> 'hours_per_day')::numeric, hours_per_day),
    use_public_holidays = coalesce((p ->> 'use_public_holidays')::boolean, use_public_holidays),
    name = coalesce(nullif(trim(p ->> 'name'), ''), name)
  where project_id = v_project and is_default and deleted_at is null;
  if (p ->> 'use_public_holidays')::boolean is false then
    update public.calendar_exceptions set deleted_at = now(), updated_by = auth.uid()
     where project_id = v_project and deleted_at is null and holiday_decision_id in
       (select id from public.holiday_decisions where project_id = v_project);
    delete from public.holiday_decisions where project_id = v_project;
  end if;
  v_r := app.calendar_redate(v_project, null);
  return app.op_done(p, 'save_project_calendar', jsonb_build_object('ok', true, 'moved', v_r -> 'moved'));
end $$;

-- {id?, on_date, name, name_am?, kind?, is_tentative?, delete?: bool} (admin): add a holiday, confirm or
-- move a lunar date, or remove one. Decisions follow the holiday; affected projects re-date.
create or replace function public.save_public_holiday(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); v_id uuid := (p ->> 'id')::uuid; h public.public_holidays; v_old date; d record; v_new date := (p ->> 'on_date')::date;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.require_role_txt('admin');
  if v_id is not null then
    select * into h from public.public_holidays where id = v_id for update;
    if not found then raise exception 'Holiday not found'; end if;
    v_old := h.on_date;
    if coalesce((p ->> 'delete')::boolean, false) then
      update public.public_holidays set deleted_at = now() where id = v_id;
      for d in select id, project_id from public.holiday_decisions where holiday_id = v_id loop
        update public.calendar_exceptions set deleted_at = now(), updated_by = auth.uid() where holiday_decision_id = d.id and deleted_at is null;
        delete from public.holiday_decisions where id = d.id;
        perform app.calendar_redate(d.project_id, array[v_old]);
      end loop;
      return app.op_done(p, 'save_public_holiday', jsonb_build_object('ok', true, 'id', v_id, 'deleted', true));
    end if;
    update public.public_holidays set on_date = coalesce(v_new, on_date), name = coalesce(nullif(trim(p ->> 'name'), ''), name),
      name_am = coalesce(nullif(trim(p ->> 'name_am'), ''), name_am), kind = coalesce(nullif(p ->> 'kind', ''), kind),
      is_tentative = coalesce((p ->> 'is_tentative')::boolean, false),
      confirmed_by = case when coalesce((p ->> 'is_tentative')::boolean, false) then confirmed_by else auth.uid() end,
      confirmed_at = case when coalesce((p ->> 'is_tentative')::boolean, false) then confirmed_at else now() end
    where id = v_id;
  else
    if v_new is null or nullif(trim(p ->> 'name'), '') is null then raise exception 'Enter the date and the name'; end if;
    insert into public.public_holidays (country, on_date, name, name_am, kind, is_tentative, source, confirmed_by, confirmed_at)
    values (coalesce(nullif(p ->> 'country', ''), 'ET'), v_new, trim(p ->> 'name'), nullif(trim(p ->> 'name_am'), ''),
      coalesce(nullif(p ->> 'kind', ''), 'other'), coalesce((p ->> 'is_tentative')::boolean, false), 'manual',
      case when coalesce((p ->> 'is_tentative')::boolean, false) then null else auth.uid() end,
      case when coalesce((p ->> 'is_tentative')::boolean, false) then null else now() end)
    returning id into v_id;
  end if;
  perform app.ensure_holiday_decisions(null);
  select * into h from public.public_holidays where id = v_id;
  for d in select id, project_id from public.holiday_decisions where holiday_id = v_id loop
    perform app.apply_holiday_decision(d.id);
    perform app.calendar_redate(d.project_id, array_remove(array[v_old, h.on_date], null));
  end loop;
  return app.op_done(p, 'save_public_holiday', jsonb_build_object('ok', true, 'id', v_id, 'on_date', h.on_date));
end $$;

-- {from_year, to_year} (admin): add the holidays of more years.
create or replace function public.generate_public_holidays(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
begin
  perform app.require_role_txt('admin');
  return jsonb_build_object('ok', true, 'added', app.generate_et_holidays((p ->> 'from_year')::int, (p ->> 'to_year')::int));
end $$;

-- ---------------------------------------------------------------------------
-- Approvals inbox: holidays within 30 days that still need a decision.
-- ---------------------------------------------------------------------------
create or replace function app.calendar_approvals_for(p_user uuid)
returns table (kind text, entity_type text, entity_id uuid, project_id uuid, number text, title text, status text,
               requested_by uuid, requested_at timestamptz, is_urgent boolean, actions text[], age_hours numeric)
language plpgsql stable security definer set search_path = public as $$
declare v_role text; v_today date := app.eat_date(now());
begin
  select pr.role::text into v_role from public.profiles pr where pr.id = p_user and pr.is_active;
  if v_role is null or v_role not in ('manager','admin','coordinator','office_engineer') then return; end if;
  return query
  select 'holiday'::text, 'holiday_decision'::text, hd.id, hd.project_id, to_char(hd.on_date, 'DD Mon YYYY'),
         case when v_role in ('manager','admin') then 'Decide: work on ' else 'Propose: work on ' end || h.name || '?'
           || case when hd.proposed_choice is not null then ' (proposed: ' || replace(hd.proposed_choice, '_', ' ') || ')' else '' end,
         hd.status, hd.proposed_by, coalesce(hd.proposed_at, (hd.on_date - 30)::timestamptz), hd.on_date - v_today <= 7,
         case when v_role in ('manager','admin') then array['work','half_day','no_work'] else array['propose'] end,
         round((extract(epoch from now() - coalesce(hd.proposed_at, (hd.on_date - 30)::timestamptz)) / 3600)::numeric, 1)
  from public.holiday_decisions hd
  join public.public_holidays h on h.id = hd.holiday_id
  where hd.on_date between v_today and v_today + 30
    and (v_role = 'admin' or exists (select 1 from public.project_members m where m.project_id = hd.project_id and m.user_id = p_user))
    and ((v_role in ('manager','admin') and hd.status in ('pending','proposed'))
      or (v_role in ('coordinator','office_engineer') and hd.status = 'pending'));
end $$;
revoke execute on function app.calendar_approvals_for(uuid) from public;
insert into app.approval_sources (fn) values ('app.calendar_approvals_for') on conflict do nothing;

-- ---------------------------------------------------------------------------
-- Data: holidays 2026–2035, decision rows, daily reminders (pg_cron when the project has it)
-- ---------------------------------------------------------------------------
update public.public_holidays set source = 'seed' where source is null;

-- Proclamation 1334/2024 (effective 14 Aug 2024) replaced the former list and does not make 28 May a day off.
-- Retire seeded/generated Derg rows, remove their decisions and re-date schedules that used the old calendar.
do $$
declare d record;
begin
  for d in select pc.project_id, h.id as holiday_id, h.on_date
           from public.public_holidays h join public.project_calendars pc on pc.holiday_country = h.country
           where h.country = 'ET' and h.name = 'Downfall of the Derg' and h.on_date >= '2024-08-14' and h.deleted_at is null
             and pc.is_default and pc.deleted_at is null and pc.use_public_holidays loop
    update public.public_holidays set deleted_at = now() where id = d.holiday_id;
    update public.calendar_exceptions set deleted_at = now()
     where project_id = d.project_id and deleted_at is null and holiday_decision_id in
       (select id from public.holiday_decisions where project_id = d.project_id and holiday_id = d.holiday_id);
    delete from public.holiday_decisions where project_id = d.project_id and holiday_id = d.holiday_id;
    perform app.calendar_redate(d.project_id, array[d.on_date]);
  end loop;
  -- Also retire rows on a fresh installation, before any project has been created.
  update public.public_holidays set deleted_at = now()
   where country = 'ET' and name = 'Downfall of the Derg' and on_date >= '2024-08-14' and deleted_at is null;
end $$;

select app.generate_et_holidays(2026, 2035);
select app.ensure_holiday_decisions(null);

do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    execute $c$select cron.schedule('sm-holiday-reminders', '0 4 * * *', 'select app.calendar_holiday_reminders()')$c$;
  end if;
exception when others then
  raise notice 'Holiday reminders not scheduled (%): they still run when the calendar page opens', sqlerrm;
end $$;


-- >>>>>>>>>>>>>>>>>>>> 20261105000020_photos.sql

-- =============================================================================
-- Photos & documents everywhere (web upload, bulk import, site photo gallery, before/after).
--
-- * attachments gets caption, tag (before / after / progress / issue / handover / other), block / level,
--   file name + size and a soft delete (evidence is never physically removed; the audit trigger keeps the trail).
-- * Who sees an attachment follows the record it belongs to (app.attachment_visible): payment documents only
--   for payment roles, price documents (client IPC, variations, quotations, POs) only for price roles, stock
--   books not for the gate guard. Enforced on the table AND on the storage files (path = project/entity_type/file).
-- * entity_type 'site' (entity_id = project id) holds general site photos uploaded in the gallery.
-- * Location (block / level) is filled from the linked element / snag / inspection / progress update when not given.
-- * public.update_attachment: caption / tag / location, or delete (uploader within 24 h, or coordinator / manager / admin).
-- Re-runnable.
-- =============================================================================

alter table public.attachments add column if not exists caption    text;
alter table public.attachments add column if not exists tag        text;
alter table public.attachments add column if not exists block_id   uuid references public.blocks (id);
alter table public.attachments add column if not exists level_id   uuid references public.levels (id);
alter table public.attachments add column if not exists file_name  text;
alter table public.attachments add column if not exists size_bytes bigint;
alter table public.attachments add column if not exists deleted_at timestamptz;
alter table public.attachments add column if not exists deleted_by uuid references public.profiles (id);

do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'attachments_tag_check') then
    alter table public.attachments add constraint attachments_tag_check
      check (tag is null or tag in ('before','after','progress','issue','handover','other'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'attachments_caption_len') then
    alter table public.attachments add constraint attachments_caption_len check (caption is null or length(caption) <= 500);
  end if;
end $$;

select app.extend_check_values('public.attachments', 'kind',
  array['photo','delivery_note','signature','document','proforma','batch_ticket','bbs','drawing','diary',
        'measurement','attendance_sheet','signed_certificate','site_instruction','invoice','report']);
select app.extend_check_values('public.attachments', 'source', array['camera','gallery','upload']);

create index if not exists attachments_project_created_idx on public.attachments (project_id, created_at desc) where deleted_at is null;

-- ---------------------------------------------------------------------------
-- Visibility by the type of record the file belongs to
-- ---------------------------------------------------------------------------
create or replace function app.attachment_visible(p_entity_type text, p_project uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select app.is_member(p_project) and case
    when p_entity_type in ('sc_certificate','subcontract','subcontractor','payment') then app.can_see_payments(p_project)
    when p_entity_type in ('payroll','labour_payroll') then app.can_see_payments(p_project) or app.has_role_txt('site_engineer')
    when p_entity_type in ('client_ipc','variation','quotation','purchase_order','rfq','supplier_invoice') then app.can_see_prices()
    when p_entity_type in ('stock_count','adjustment') then coalesce(app.my_role()::text, '') <> 'security'
    else true
  end
$$;
revoke execute on function app.attachment_visible(text, uuid) from public;
grant execute on function app.attachment_visible(text, uuid) to authenticated;

-- storage object name = <project_id>/<entity_type>/<file>
create or replace function app.storage_path_visible(p_name text) returns boolean
language plpgsql stable security definer set search_path = public as $$
declare f text[] := storage.foldername(p_name); v_project uuid;
begin
  begin v_project := f[1]::uuid; exception when others then return false; end;
  return app.attachment_visible(coalesce(f[2], ''), v_project);
end $$;
revoke execute on function app.storage_path_visible(text) from public;
grant execute on function app.storage_path_visible(text) to authenticated;

drop policy if exists entity_read on public.attachments;
create policy entity_read on public.attachments as restrictive for select to authenticated
  using (app.attachment_visible(entity_type, project_id));
drop policy if exists entity_insert on public.attachments;
create policy entity_insert on public.attachments as restrictive for insert to authenticated
  with check (app.attachment_visible(entity_type, project_id) and deleted_at is null);

-- Replace the original member-only policies too: their direct uuid cast rejected malformed paths with an error.
drop policy if exists attachments_read on storage.objects;
create policy attachments_read on storage.objects for select to authenticated
  using (bucket_id = 'attachments' and app.storage_path_visible(name));
drop policy if exists attachments_insert on storage.objects;
create policy attachments_insert on storage.objects for insert to authenticated
  with check (bucket_id = 'attachments' and app.storage_path_visible(name));
drop policy if exists attachments_entity_read on storage.objects;
create policy attachments_entity_read on storage.objects as restrictive for select to authenticated
  using (bucket_id <> 'attachments' or app.storage_path_visible(name));
drop policy if exists attachments_entity_insert on storage.objects;
create policy attachments_entity_insert on storage.objects as restrictive for insert to authenticated
  with check (bucket_id <> 'attachments' or app.storage_path_visible(name));

-- ---------------------------------------------------------------------------
-- Validate supplied locations, then inherit block / level from the linked record.
-- ---------------------------------------------------------------------------
create or replace function app.attachment_location() returns trigger
language plpgsql security definer set search_path = public as $$
declare v_el uuid; b uuid; l uuid; v_block uuid; v_project uuid;
begin
  if new.level_id is not null then
    select lv.block_id, lv.project_id into v_block, v_project from public.levels lv where lv.id = new.level_id;
    if not found or v_project <> new.project_id then raise exception 'Level is not in this project'; end if;
    if new.block_id is not null and new.block_id <> v_block then raise exception 'Block does not match level'; end if;
    new.block_id := v_block;
  elsif new.block_id is not null and not exists (
    select 1 from public.blocks b where b.id = new.block_id and b.project_id = new.project_id
  ) then
    raise exception 'Block is not in this project';
  end if;
  if new.block_id is not null or new.level_id is not null then return new; end if;
  if new.entity_type = 'element' then v_el := new.entity_id;
  elsif new.entity_type = 'snag' then
    select s.block_id, s.level_id, s.element_id into b, l, v_el from public.snags s where s.id = new.entity_id and s.project_id = new.project_id;
    if b is not null or l is not null then new.block_id := b; new.level_id := l; return new; end if;
  elsif new.entity_type = 'inspection' then
    select i.element_id into v_el from public.inspections i where i.id = new.entity_id and i.project_id = new.project_id;
  elsif new.entity_type = 'progress_update' then
    select p.element_id into v_el from public.progress_updates p where p.id = new.entity_id and p.project_id = new.project_id;
  end if;
  if v_el is not null then
    select e.block_id, e.level_id into new.block_id, new.level_id from public.elements e where e.id = v_el and e.project_id = new.project_id;
  end if;
  return new;
end $$;
drop trigger if exists location on public.attachments;
create trigger location before insert on public.attachments for each row execute function app.attachment_location();

-- ---------------------------------------------------------------------------
-- Edit caption / tag / location, or delete (soft)
-- p: {id, caption?, tag?, block_id?, level_id?, delete?: bool}
-- ---------------------------------------------------------------------------
create or replace function public.update_attachment(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare a public.attachments; v_mgmt boolean; v_block uuid;
begin
  select * into a from public.attachments where id = (p ->> 'id')::uuid for update;
  if not found or a.deleted_at is not null or not app.attachment_visible(a.entity_type, a.project_id) then
    raise exception 'Attachment not found';
  end if;
  v_mgmt := app.has_role_txt('coordinator', 'manager', 'admin');
  if coalesce((p ->> 'delete')::boolean, false) then
    if not (v_mgmt or (a.created_by = auth.uid() and a.created_at > now() - interval '24 hours')) then
      raise exception 'Only the person who added it (within 24 hours) or a coordinator / manager can delete a photo' using errcode = '42501';
    end if;
    update public.attachments set deleted_at = now(), deleted_by = auth.uid(), updated_at = now() where id = a.id;
    return jsonb_build_object('ok', true, 'id', a.id, 'deleted', true);
  end if;
  if not (v_mgmt or a.created_by = auth.uid()) then
    raise exception 'Only the person who added it or a coordinator / manager can change it' using errcode = '42501';
  end if;
  if p ? 'level_id' and nullif(p ->> 'level_id', '') is not null then
    select l.block_id into v_block from public.levels l
      where l.id = (p ->> 'level_id')::uuid and l.project_id = a.project_id;
    if not found then raise exception 'Level is not in this project'; end if;
    if p ? 'block_id' and nullif(p ->> 'block_id', '') is not null
       and (p ->> 'block_id')::uuid <> v_block then
      raise exception 'Block does not match level';
    end if;
  end if;
  if p ? 'block_id' and nullif(p ->> 'block_id', '') is not null then
    if not exists (select 1 from public.blocks b where b.id = (p ->> 'block_id')::uuid and b.project_id = a.project_id) then
      raise exception 'Block is not in this project';
    end if;
    if not (p ? 'level_id') and a.level_id is not null and not exists (
      select 1 from public.levels l where l.id = a.level_id and l.block_id = (p ->> 'block_id')::uuid
    ) then
      raise exception 'Block does not match level';
    end if;
  elsif p ? 'block_id' and not (p ? 'level_id') and a.level_id is not null then
    raise exception 'Clear the level before clearing its block';
  end if;
  update public.attachments set
    caption  = case when p ? 'caption' then nullif(trim(p ->> 'caption'), '') else caption end,
    tag      = case when p ? 'tag' then nullif(p ->> 'tag', '') else tag end,
    block_id = case
      when p ? 'level_id' and nullif(p ->> 'level_id', '') is not null then v_block
      when p ? 'block_id' then nullif(p ->> 'block_id', '')::uuid else block_id end,
    level_id = case when p ? 'level_id' then nullif(p ->> 'level_id', '')::uuid else level_id end,
    updated_at = now()
  where id = a.id;
  return jsonb_build_object('ok', true, 'id', a.id);
end $$;
revoke execute on function public.update_attachment(jsonb) from public;
grant execute on function public.update_attachment(jsonb) to authenticated;


-- >>>>>>>>>>>>>>>>>>>> 20261105000030_site_ops.sql

-- =============================================================================
-- Site operations for site engineers / foremen (and the people who answer them):
--
-- * hse_incidents      Injuries, near misses, property damage, environmental, dangerous occurrences: reported by anyone
--                      on the project → investigated (root cause, corrective action, owner, due) → closed. Lost-time,
--                      serious and fatal cases must record the labour-inspection notification before closing
--                      (Labour Proclamation 1156/2019: employment accidents are registered and notified).
-- * toolbox_talks      Daily briefing: topic, hazards, attendance, PPE check.
-- * work_permits       Permits to work (hot work, height, excavation, confined space, lifting, electrical): requested
--                      on site with a precaution checklist → approved by coordinator / manager (not the requester, all
--                      precautions in place) → closed when the work ends. Approved past valid_to = expired.
-- * plant_items /      Plant & equipment register (owned / hired) and a daily log per machine: meter readings, hours
--   plant_logs         worked / idle / breakdown, fuel, operator. Meter readings may not go backwards; a breakdown
--                      puts the machine under repair and alerts the coordinator.
--
-- RFIs / site instructions live in the contract-administration register (20261105000040, save_rfi).
-- Writes only through the RPCs below (idempotent op_id). Read: project members. Inbox: app.approval_sources.
-- Photos attach through public.attachments (entity_type 'hse_incident' | 'toolbox_talk' | 'work_permit' |
-- 'plant_log'). Re-runnable.
-- =============================================================================

create table if not exists public.hse_incidents (
  id                     uuid primary key,
  project_id             uuid not null references public.projects (id),
  number                 text not null,
  kind                   text not null check (kind in ('injury','near_miss','property_damage','environmental','dangerous_occurrence')),
  severity               text not null default 'minor' check (severity in ('minor','moderate','serious','fatal')),
  occurred_at            timestamptz not null,
  location_text          text,
  element_id             uuid references public.elements (id),
  description            text not null,
  immediate_action       text,
  injured_name           text,
  injured_trade          text,
  injured_party          text check (injured_party in ('own','subcontractor','visitor','public')),
  body_part              text,
  first_aid              boolean not null default false,
  hospital               boolean not null default false,
  lost_time              boolean not null default false,
  days_lost              int not null default 0 check (days_lost >= 0),
  root_cause             text,
  corrective_action      text,
  action_owner           uuid references public.profiles (id),
  action_due             date,
  reported_to_authority  boolean not null default false,
  authority_ref          text,
  status                 text not null default 'reported' check (status in ('reported','action','closed')),
  close_note             text,
  reported_by            uuid not null references public.profiles (id),
  investigated_by        uuid references public.profiles (id),
  investigated_at        timestamptz,
  closed_by              uuid references public.profiles (id),
  closed_at              timestamptz,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  unique (project_id, number)
);

create table if not exists public.toolbox_talks (
  id               uuid primary key,
  project_id       uuid not null references public.projects (id),
  number           text not null,
  held_on          date not null,
  topic            text not null,
  hazards          text,
  presenter_name   text,
  attendees_count  int not null check (attendees_count > 0),
  attendee_names   text,
  trades           text[] not null default '{}',
  duration_min     int check (duration_min > 0),
  ppe_checked      boolean not null default false,
  ppe_issues       text,
  notes            text,
  created_by       uuid not null references public.profiles (id),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (project_id, number)
);

create table if not exists public.work_permits (
  id               uuid primary key,
  project_id       uuid not null references public.projects (id),
  number           text not null,
  permit_type      text not null check (permit_type in ('hot_work','work_at_height','excavation','confined_space','lifting','electrical','other')),
  description      text not null,
  location_text    text,
  element_id       uuid references public.elements (id),
  valid_from       timestamptz not null,
  valid_to         timestamptz not null,
  crew_size        int check (crew_size > 0),
  supervisor_name  text,
  precautions      jsonb not null default '[]'::jsonb,       -- [{text, done}]
  status           text not null default 'requested' check (status in ('requested','approved','rejected','closed','cancelled')),
  decision_comment text,
  requested_by     uuid not null references public.profiles (id),
  approved_by      uuid references public.profiles (id),
  approved_at      timestamptz,
  closed_by        uuid references public.profiles (id),
  closed_at        timestamptz,
  close_note       text,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (project_id, number),
  check (valid_to > valid_from)
);

create table if not exists public.plant_items (
  id           uuid primary key,
  project_id   uuid not null references public.projects (id),
  code         text not null,
  name         text not null,
  category     text not null default 'other' check (category in ('excavator','loader','crane','mixer','vibrator','generator',
                 'truck','pump','compactor','other')),
  ownership    text not null default 'owned' check (ownership in ('owned','hired')),
  supplier     text,
  plate_no     text,
  meter_unit   text not null default 'hours' check (meter_unit in ('hours','km','none')),
  last_meter   numeric(12,1),
  status       text not null default 'active' check (status in ('active','under_repair','off_hire')),
  on_site_from date,
  notes        text,
  created_by   uuid references public.profiles (id),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  unique (project_id, code)
);

create table if not exists public.plant_logs (
  id               uuid primary key,
  project_id       uuid not null references public.projects (id),
  plant_id         uuid not null references public.plant_items (id),
  log_date         date not null,
  operator_name    text,
  meter_start      numeric(12,1),
  meter_end        numeric(12,1),
  hours_worked     numeric(5,1) not null default 0 check (hours_worked >= 0),
  hours_idle       numeric(5,1) not null default 0 check (hours_idle >= 0),
  hours_breakdown  numeric(5,1) not null default 0 check (hours_breakdown >= 0),
  fuel_litres      numeric(8,1) not null default 0 check (fuel_litres >= 0),
  status           text not null default 'working' check (status in ('working','idle','breakdown')),
  idle_reason      text,
  breakdown_note   text,
  work_done        text,
  element_id       uuid references public.elements (id),
  created_by       uuid not null references public.profiles (id),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (plant_id, log_date),
  check (hours_worked + hours_idle + hours_breakdown <= 24)
);

create index if not exists hse_incidents_project_idx on public.hse_incidents (project_id, status);
create index if not exists toolbox_talks_project_idx on public.toolbox_talks (project_id, held_on);
create index if not exists work_permits_project_idx on public.work_permits (project_id, status);
create index if not exists plant_logs_plant_idx on public.plant_logs (plant_id, log_date);

do $$
declare t text;
begin
  foreach t in array array['hse_incidents','toolbox_talks','work_permits','plant_items','plant_logs'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop trigger if exists touch_updated_at on public.%I', t);
    execute format('create trigger touch_updated_at before update on public.%I for each row execute function app.touch_updated_at()', t);
    execute format('drop trigger if exists audit on public.%I', t);
    execute format('create trigger audit after insert or update or delete on public.%I for each row execute function app.audit()', t);
    execute format('drop policy if exists member_read on public.%I', t);
    execute format('create policy member_read on public.%I for select to authenticated using (app.is_member(project_id))', t);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- helpers
-- ---------------------------------------------------------------------------
-- Document number: the client's (device numbering, offline) or <project code>-<prefix>-0001.
create or replace function app.site_doc_no(p_project uuid, p_prefix text, p_table text, p_given text) returns text
language plpgsql security definer set search_path = public as $$
declare n int;
begin
  if nullif(trim(p_given), '') is not null then return trim(p_given); end if;
  execute format('select count(*) from public.%I where project_id = $1', p_table) into n using p_project;
  return (select code from public.projects where id = p_project) || '-' || p_prefix || '-' || lpad((n + 1)::text, 4, '0');
end $$;
revoke execute on function app.site_doc_no(uuid, text, text, text) from public;

create or replace function app.site_guard(p_project uuid, variadic p_roles text[]) returns void
language plpgsql stable security definer set search_path = public as $$
begin
  perform app.require_member(p_project);
  perform app.require_role_txt(variadic p_roles);
end $$;
revoke execute on function app.site_guard(uuid, text[]) from public;

-- ---------------------------------------------------------------------------
-- HSE: incidents
-- ---------------------------------------------------------------------------
-- {id, project_id, number?, kind, severity?, occurred_at, location_text?, element_id?, description, immediate_action?,
--  injured_name?, injured_trade?, injured_party?, body_part?, first_aid?, hospital?, lost_time?, days_lost?}
create or replace function public.report_incident(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); v_id uuid := (p ->> 'id')::uuid; v_project uuid := (p ->> 'project_id')::uuid;
  i public.hse_incidents; v_no text; v_crit boolean; v_new boolean;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.require_member(v_project);
  if nullif(trim(p ->> 'description'), '') is null then raise exception 'Describe what happened'; end if;
  if (p ->> 'occurred_at') is null then raise exception 'Enter when it happened'; end if;
  if (p ->> 'occurred_at')::timestamptz > now() + interval '10 minutes' then raise exception 'The time it happened is in the future'; end if;
  if (p ->> 'kind') = 'injury' and nullif(trim(p ->> 'injured_name'), '') is null then raise exception 'Enter the name of the injured person'; end if;
  select * into i from public.hse_incidents where id = v_id for update;
  if found then
    if i.project_id <> v_project then raise exception 'Incident belongs to another project'; end if;
    if i.status <> 'reported' then raise exception 'Incident % is under investigation — add details there', i.number; end if;
    if i.reported_by <> auth.uid() and not app.has_role_txt('coordinator', 'manager', 'admin') then
      raise exception 'Only the reporter can edit this report' using errcode = '42501';
    end if;
  end if;
  v_no := coalesce(i.number, app.site_doc_no(v_project, 'INC', 'hse_incidents', p ->> 'number'));
  insert into public.hse_incidents (id, project_id, number, kind, severity, occurred_at, location_text, element_id, description, immediate_action,
    injured_name, injured_trade, injured_party, body_part, first_aid, hospital, lost_time, days_lost, reported_by)
  values (v_id, v_project, v_no, p ->> 'kind', coalesce(nullif(p ->> 'severity', ''), 'minor'), (p ->> 'occurred_at')::timestamptz,
    nullif(p ->> 'location_text', ''), (p ->> 'element_id')::uuid, trim(p ->> 'description'), nullif(p ->> 'immediate_action', ''),
    nullif(p ->> 'injured_name', ''), nullif(p ->> 'injured_trade', ''), nullif(p ->> 'injured_party', ''), nullif(p ->> 'body_part', ''),
    coalesce((p ->> 'first_aid')::boolean, false), coalesce((p ->> 'hospital')::boolean, false), coalesce((p ->> 'lost_time')::boolean, false),
    coalesce((p ->> 'days_lost')::int, 0), auth.uid())
  on conflict (id) do update set kind = excluded.kind, severity = excluded.severity, occurred_at = excluded.occurred_at,
    location_text = excluded.location_text, element_id = excluded.element_id, description = excluded.description,
    immediate_action = excluded.immediate_action, injured_name = excluded.injured_name, injured_trade = excluded.injured_trade,
    injured_party = excluded.injured_party, body_part = excluded.body_part, first_aid = excluded.first_aid, hospital = excluded.hospital,
    lost_time = excluded.lost_time, days_lost = excluded.days_lost;
  v_new := i.id is null;
  select * into i from public.hse_incidents where id = v_id;
  v_crit := i.severity in ('serious','fatal') or i.lost_time or i.hospital;
  if v_new then
    perform app.notify_roles_txt(v_project, '{coordinator,manager}',
      (case i.kind when 'near_miss' then 'Near miss ' else 'Incident ' end) || i.number || ' reported',
      left(i.description, 200), 'hse_incident', v_id, v_crit);
  end if;
  return app.op_done(p, 'report_incident', jsonb_build_object('ok', true, 'id', v_id, 'number', i.number, 'status', i.status));
end $$;

-- {incident_id, action: investigate | close, root_cause?, corrective_action?, action_owner?, action_due?,
--  reported_to_authority?, authority_ref?, close_note?, days_lost?, lost_time?}
create or replace function public.incident_action(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); i public.hse_incidents; a text := p ->> 'action';
begin
  if v_seen is not null then return v_seen; end if;
  select * into i from public.hse_incidents where id = (p ->> 'incident_id')::uuid for update;
  if not found then raise exception 'Incident not found'; end if;
  perform app.site_guard(i.project_id, 'coordinator', 'manager', 'admin');
  update public.hse_incidents set
    reported_to_authority = coalesce((p ->> 'reported_to_authority')::boolean, reported_to_authority),
    authority_ref = coalesce(nullif(p ->> 'authority_ref', ''), authority_ref),
    days_lost = coalesce((p ->> 'days_lost')::int, days_lost), lost_time = coalesce((p ->> 'lost_time')::boolean, lost_time)
  where id = i.id;
  if a = 'investigate' then
    if i.status = 'closed' then raise exception 'Incident % is closed', i.number; end if;
    if nullif(trim(p ->> 'root_cause'), '') is null or nullif(trim(p ->> 'corrective_action'), '') is null then
      raise exception 'Enter the root cause and the corrective action';
    end if;
    if (p ->> 'action_owner') is not null and not exists (select 1 from public.project_members where project_id = i.project_id and user_id = (p ->> 'action_owner')::uuid) then
      raise exception 'The action owner is not on this project';
    end if;
    update public.hse_incidents set status = 'action', root_cause = trim(p ->> 'root_cause'), corrective_action = trim(p ->> 'corrective_action'),
      action_owner = (p ->> 'action_owner')::uuid, action_due = nullif(p ->> 'action_due', '')::date,
      investigated_by = auth.uid(), investigated_at = now()
    where id = i.id;
    if (p ->> 'action_owner') is not null then
      perform app.notify_user((p ->> 'action_owner')::uuid, i.project_id, 'Corrective action — ' || i.number, trim(p ->> 'corrective_action'), 'hse_incident', i.id);
    end if;
  elsif a = 'close' then
    if i.status <> 'action' then raise exception 'Investigate incident % (root cause, corrective action) before closing it', i.number; end if;
    select * into i from public.hse_incidents where id = i.id;
    if i.kind = 'injury' and (i.lost_time or i.severity in ('serious','fatal')) and not i.reported_to_authority then
      raise exception 'Lost-time, serious and fatal injuries must be notified to the labour inspection office — record the notification first';
    end if;
    update public.hse_incidents set status = 'closed', close_note = nullif(p ->> 'close_note', ''), closed_by = auth.uid(), closed_at = now()
    where id = i.id;
  elsif a is not null and a <> 'update' then
    raise exception 'Unknown action %', a;
  end if;
  select * into i from public.hse_incidents where id = i.id;
  return app.op_done(p, 'incident_action', jsonb_build_object('ok', true, 'id', i.id, 'number', i.number, 'status', i.status));
end $$;

-- ---------------------------------------------------------------------------
-- HSE: toolbox talks
-- ---------------------------------------------------------------------------
-- {id, project_id, number?, held_on, topic, hazards?, presenter_name?, attendees_count, attendee_names?, trades?,
--  duration_min?, ppe_checked?, ppe_issues?, notes?}
create or replace function public.save_toolbox_talk(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); v_id uuid := (p ->> 'id')::uuid; v_project uuid := (p ->> 'project_id')::uuid;
  t public.toolbox_talks; v_no text;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.site_guard(v_project, 'site_engineer', 'office_engineer', 'coordinator', 'manager', 'admin');
  if nullif(trim(p ->> 'topic'), '') is null then raise exception 'Enter the topic'; end if;
  if coalesce((p ->> 'attendees_count')::int, 0) <= 0 then raise exception 'Enter how many people attended'; end if;
  if (p ->> 'held_on')::date > app.local_date(now()) then raise exception 'A toolbox talk cannot be recorded for a future date'; end if;
  select * into t from public.toolbox_talks where id = v_id for update;
  if found then
    if t.project_id <> v_project then raise exception 'Toolbox talk belongs to another project'; end if;
    if t.created_by <> auth.uid() and not app.has_role_txt('coordinator', 'manager', 'admin') then
      raise exception 'Only the person who recorded it can edit this toolbox talk' using errcode = '42501';
    end if;
  end if;
  v_no := coalesce(t.number, app.site_doc_no(v_project, 'TBT', 'toolbox_talks', p ->> 'number'));
  insert into public.toolbox_talks (id, project_id, number, held_on, topic, hazards, presenter_name, attendees_count, attendee_names, trades,
    duration_min, ppe_checked, ppe_issues, notes, created_by)
  values (v_id, v_project, v_no, (p ->> 'held_on')::date, trim(p ->> 'topic'), nullif(p ->> 'hazards', ''), nullif(p ->> 'presenter_name', ''),
    (p ->> 'attendees_count')::int, nullif(p ->> 'attendee_names', ''),
    coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(p -> 'trades', '[]'::jsonb)) x), '{}'),
    (p ->> 'duration_min')::int, coalesce((p ->> 'ppe_checked')::boolean, false), nullif(p ->> 'ppe_issues', ''), nullif(p ->> 'notes', ''), auth.uid())
  on conflict (id) do update set held_on = excluded.held_on, topic = excluded.topic, hazards = excluded.hazards,
    presenter_name = excluded.presenter_name, attendees_count = excluded.attendees_count, attendee_names = excluded.attendee_names,
    trades = excluded.trades, duration_min = excluded.duration_min, ppe_checked = excluded.ppe_checked, ppe_issues = excluded.ppe_issues,
    notes = excluded.notes;
  return app.op_done(p, 'save_toolbox_talk', jsonb_build_object('ok', true, 'id', v_id, 'number', v_no));
end $$;

-- ---------------------------------------------------------------------------
-- HSE: permits to work
-- ---------------------------------------------------------------------------
-- {id, project_id, number?, permit_type, description, location_text?, element_id?, valid_from, valid_to, crew_size?,
--  supervisor_name?, precautions: [{text, done}]}
create or replace function public.request_permit(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); v_id uuid := (p ->> 'id')::uuid; v_project uuid := (p ->> 'project_id')::uuid;
  w public.work_permits; v_no text;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.site_guard(v_project, 'site_engineer', 'office_engineer', 'coordinator', 'manager', 'admin');
  if nullif(trim(p ->> 'description'), '') is null then raise exception 'Describe the work'; end if;
  if (p ->> 'valid_from') is null or (p ->> 'valid_to') is null then raise exception 'Enter when the permit starts and ends'; end if;
  if (p ->> 'valid_to')::timestamptz <= (p ->> 'valid_from')::timestamptz then raise exception 'The permit must end after it starts'; end if;
  if (p ->> 'valid_to')::timestamptz - (p ->> 'valid_from')::timestamptz > interval '7 days' then
    raise exception 'A permit is valid for at most 7 days — request a new one for longer work';
  end if;
  if jsonb_typeof(coalesce(p -> 'precautions', '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p -> 'precautions', '[]'::jsonb)) = 0 then
    raise exception 'List the precautions';
  end if;
  select * into w from public.work_permits where id = v_id for update;
  if found then
    if w.project_id <> v_project then raise exception 'Permit belongs to another project'; end if;
    if w.status <> 'requested' then raise exception 'Permit % is % and cannot be edited', w.number, w.status; end if;
    if w.requested_by <> auth.uid() and not app.has_role_txt('coordinator', 'manager', 'admin') then
      raise exception 'Only the requester can edit this permit' using errcode = '42501';
    end if;
  end if;
  v_no := coalesce(w.number, app.site_doc_no(v_project, 'PTW', 'work_permits', p ->> 'number'));
  insert into public.work_permits (id, project_id, number, permit_type, description, location_text, element_id, valid_from, valid_to,
    crew_size, supervisor_name, precautions, requested_by)
  values (v_id, v_project, v_no, p ->> 'permit_type', trim(p ->> 'description'), nullif(p ->> 'location_text', ''), (p ->> 'element_id')::uuid,
    (p ->> 'valid_from')::timestamptz, (p ->> 'valid_to')::timestamptz, (p ->> 'crew_size')::int, nullif(p ->> 'supervisor_name', ''),
    p -> 'precautions', auth.uid())
  on conflict (id) do update set permit_type = excluded.permit_type, description = excluded.description, location_text = excluded.location_text,
    element_id = excluded.element_id, valid_from = excluded.valid_from, valid_to = excluded.valid_to, crew_size = excluded.crew_size,
    supervisor_name = excluded.supervisor_name, precautions = excluded.precautions;
  if w.id is null then
    perform app.notify_roles_txt(v_project, '{coordinator,manager}', 'Permit to work ' || v_no || ' to approve',
      replace(p ->> 'permit_type', '_', ' ') || ': ' || left(trim(p ->> 'description'), 150), 'work_permit', v_id);
  end if;
  return app.op_done(p, 'request_permit', jsonb_build_object('ok', true, 'id', v_id, 'number', v_no, 'status', 'requested'));
end $$;

-- {permit_id, action: approve | reject | close | cancel, precautions?, comment?}
create or replace function public.permit_action(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); w public.work_permits; a text := p ->> 'action'; c text := nullif(trim(p ->> 'comment'), '');
begin
  if v_seen is not null then return v_seen; end if;
  select * into w from public.work_permits where id = (p ->> 'permit_id')::uuid for update;
  if not found then raise exception 'Permit not found'; end if;
  if a in ('approve','reject') then
    perform app.site_guard(w.project_id, 'coordinator', 'manager', 'admin');
    if w.status <> 'requested' then raise exception 'Permit % is % — only a requested permit can be %', w.number, w.status, a || 'd'; end if;
    if w.requested_by = auth.uid() and not app.has_role_txt('admin') then
      raise exception 'You cannot approve your own permit' using errcode = '42501';
    end if;
    if a = 'reject' then
      if c is null then raise exception 'Say why the permit is rejected'; end if;
      update public.work_permits set status = 'rejected', decision_comment = c, approved_by = auth.uid(), approved_at = now() where id = w.id;
      perform app.notify_user(w.requested_by, w.project_id, 'Permit ' || w.number || ' rejected', c, 'work_permit', w.id);
    else
      if p ? 'precautions' then update public.work_permits set precautions = p -> 'precautions' where id = w.id; end if;
      if exists (select 1 from public.work_permits x, jsonb_array_elements(x.precautions) e
                 where x.id = w.id and coalesce((e ->> 'done')::boolean, false) = false) then
        raise exception 'Not all precautions are in place — tick each one after checking it on site';
      end if;
      if w.valid_to <= now() then raise exception 'The permit period has already ended — ask for new dates'; end if;
      update public.work_permits set status = 'approved', decision_comment = c, approved_by = auth.uid(), approved_at = now() where id = w.id;
      perform app.notify_user(w.requested_by, w.project_id, 'Permit ' || w.number || ' approved', 'Work may start', 'work_permit', w.id);
    end if;
  elsif a = 'close' then
    perform app.require_member(w.project_id);
    if w.requested_by <> auth.uid() and not app.has_role_txt('site_engineer', 'coordinator', 'manager', 'admin') then
      raise exception 'Only the site team can close a permit' using errcode = '42501';
    end if;
    if w.status <> 'approved' then raise exception 'Only an approved permit can be closed'; end if;
    update public.work_permits set status = 'closed', close_note = c, closed_by = auth.uid(), closed_at = now() where id = w.id;
  elsif a = 'cancel' then
    perform app.require_member(w.project_id);
    if w.requested_by <> auth.uid() and not app.has_role_txt('coordinator', 'manager', 'admin') then
      raise exception 'Only the requester can cancel this permit' using errcode = '42501';
    end if;
    if w.status <> 'requested' then raise exception 'Only a requested permit can be cancelled'; end if;
    update public.work_permits set status = 'cancelled', decision_comment = c where id = w.id;
  else
    raise exception 'Unknown action %', a;
  end if;
  select * into w from public.work_permits where id = w.id;
  return app.op_done(p, 'permit_action', jsonb_build_object('ok', true, 'id', w.id, 'number', w.number, 'status', w.status));
end $$;

-- ---------------------------------------------------------------------------
-- Plant & equipment
-- ---------------------------------------------------------------------------
-- {id, project_id, code, name, category?, ownership?, supplier?, plate_no?, meter_unit?, last_meter?, status?, on_site_from?, notes?}
create or replace function public.save_plant(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_seen jsonb := app.op_seen(p); v_id uuid := (p ->> 'id')::uuid; v_project uuid := (p ->> 'project_id')::uuid; x public.plant_items;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.site_guard(v_project, 'site_engineer', 'office_engineer', 'coordinator', 'manager', 'admin');
  if nullif(trim(p ->> 'code'), '') is null or nullif(trim(p ->> 'name'), '') is null then raise exception 'Enter the plant code and name'; end if;
  select * into x from public.plant_items where id = v_id;
  if found and x.project_id <> v_project then raise exception 'Plant belongs to another project'; end if;
  if exists (select 1 from public.plant_items where project_id = v_project and code = trim(p ->> 'code') and id <> v_id) then
    raise exception 'Plant code % is already used', trim(p ->> 'code');
  end if;
  insert into public.plant_items (id, project_id, code, name, category, ownership, supplier, plate_no, meter_unit, last_meter, status, on_site_from, notes, created_by)
  values (v_id, v_project, trim(p ->> 'code'), trim(p ->> 'name'), coalesce(nullif(p ->> 'category', ''), 'other'),
    coalesce(nullif(p ->> 'ownership', ''), 'owned'), nullif(p ->> 'supplier', ''), nullif(p ->> 'plate_no', ''),
    coalesce(nullif(p ->> 'meter_unit', ''), 'hours'), (p ->> 'last_meter')::numeric, coalesce(nullif(p ->> 'status', ''), 'active'),
    nullif(p ->> 'on_site_from', '')::date, nullif(p ->> 'notes', ''), auth.uid())
  on conflict (id) do update set code = excluded.code, name = excluded.name, category = excluded.category, ownership = excluded.ownership,
    supplier = excluded.supplier, plate_no = excluded.plate_no, meter_unit = excluded.meter_unit,
    last_meter = coalesce(excluded.last_meter, public.plant_items.last_meter), status = excluded.status,
    on_site_from = excluded.on_site_from, notes = excluded.notes;
  return app.op_done(p, 'save_plant', jsonb_build_object('ok', true, 'id', v_id));
end $$;

-- {id, plant_id, log_date, operator_name?, meter_start?, meter_end?, hours_worked?, hours_idle?, hours_breakdown?, fuel_litres?,
--  status?, idle_reason?, breakdown_note?, work_done?, element_id?}
create or replace function public.log_plant(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); v_id uuid := (p ->> 'id')::uuid; x public.plant_items; l public.plant_logs;
  v_prev numeric; v_next numeric; v_start numeric := (p ->> 'meter_start')::numeric; v_end numeric := (p ->> 'meter_end')::numeric;
  v_worked numeric; v_status text := coalesce(nullif(p ->> 'status', ''), 'working'); v_date date := (p ->> 'log_date')::date;
begin
  if v_seen is not null then return v_seen; end if;
  select * into x from public.plant_items where id = (p ->> 'plant_id')::uuid;
  if not found then raise exception 'Plant not found'; end if;
  perform app.site_guard(x.project_id, 'site_engineer', 'store_keeper', 'office_engineer', 'coordinator', 'manager', 'admin');
  if v_date is null then raise exception 'Enter the date'; end if;
  if v_date > app.local_date(now()) then raise exception 'Cannot log a future day'; end if;
  select * into l from public.plant_logs where plant_id = x.id and log_date = v_date;
  if found and l.id <> v_id then raise exception '% is already logged for % — edit that entry', x.code, v_date; end if;
  if v_start is not null and v_end is not null and v_end < v_start then raise exception 'The closing meter reading is lower than the opening one'; end if;
  select meter_end into v_prev from public.plant_logs where plant_id = x.id and log_date < v_date and meter_end is not null order by log_date desc limit 1;
  if v_start is not null and v_prev is not null and v_start < v_prev then
    raise exception 'Opening meter % is lower than the last reading % — check the meter', v_start, v_prev;
  end if;
  select meter_start into v_next from public.plant_logs where plant_id = x.id and log_date > v_date and meter_start is not null order by log_date limit 1;
  if v_end is not null and v_next is not null and v_end > v_next then
    raise exception 'Closing meter % is higher than the next day''s opening reading %', v_end, v_next;
  end if;
  v_worked := coalesce((p ->> 'hours_worked')::numeric, case when x.meter_unit = 'hours' and v_start is not null and v_end is not null then v_end - v_start end, 0);
  if v_status = 'breakdown' and nullif(trim(p ->> 'breakdown_note'), '') is null then raise exception 'Describe the breakdown'; end if;
  insert into public.plant_logs (id, project_id, plant_id, log_date, operator_name, meter_start, meter_end, hours_worked, hours_idle, hours_breakdown,
    fuel_litres, status, idle_reason, breakdown_note, work_done, element_id, created_by)
  values (v_id, x.project_id, x.id, v_date, nullif(p ->> 'operator_name', ''), v_start, v_end, v_worked,
    coalesce((p ->> 'hours_idle')::numeric, 0), coalesce((p ->> 'hours_breakdown')::numeric, 0), coalesce((p ->> 'fuel_litres')::numeric, 0),
    v_status, nullif(p ->> 'idle_reason', ''), nullif(p ->> 'breakdown_note', ''), nullif(p ->> 'work_done', ''), (p ->> 'element_id')::uuid, auth.uid())
  on conflict (id) do update set log_date = excluded.log_date, operator_name = excluded.operator_name, meter_start = excluded.meter_start,
    meter_end = excluded.meter_end, hours_worked = excluded.hours_worked, hours_idle = excluded.hours_idle, hours_breakdown = excluded.hours_breakdown,
    fuel_litres = excluded.fuel_litres, status = excluded.status, idle_reason = excluded.idle_reason, breakdown_note = excluded.breakdown_note,
    work_done = excluded.work_done, element_id = excluded.element_id;
  update public.plant_items set
    last_meter = greatest(coalesce(last_meter, 0), coalesce(v_end, v_start, last_meter, 0)),
    status = case when v_status = 'breakdown' then 'under_repair' when status = 'under_repair' and v_status = 'working' then 'active' else status end
  where id = x.id;
  if v_status = 'breakdown' and (l.id is null or l.status <> 'breakdown') then
    perform app.notify_roles_txt(x.project_id, '{coordinator,manager}', x.code || ' ' || x.name || ' broke down',
      left(trim(p ->> 'breakdown_note'), 200), 'plant_log', v_id);
  end if;
  return app.op_done(p, 'log_plant', jsonb_build_object('ok', true, 'id', v_id, 'hours_worked', v_worked));
end $$;

-- Utilisation over a period: worked / (worked + idle + breakdown); fuel per working hour.
create or replace function public.plant_utilisation(p_project uuid, p_from date, p_to date)
returns table (plant_id uuid, code text, name text, category text, ownership text, status text, days_logged int, hours_worked numeric,
               hours_idle numeric, hours_breakdown numeric, fuel_litres numeric, utilisation_pct numeric, litres_per_hour numeric)
language sql stable security definer set search_path = public as $$
  select x.id, x.code, x.name, x.category, x.ownership, x.status, count(l.id)::int,
         coalesce(sum(l.hours_worked), 0), coalesce(sum(l.hours_idle), 0), coalesce(sum(l.hours_breakdown), 0), coalesce(sum(l.fuel_litres), 0),
         case when coalesce(sum(l.hours_worked + l.hours_idle + l.hours_breakdown), 0) > 0
              then round(100 * sum(l.hours_worked) / sum(l.hours_worked + l.hours_idle + l.hours_breakdown), 1) end,
         case when coalesce(sum(l.hours_worked), 0) > 0 then round(sum(l.fuel_litres) / sum(l.hours_worked), 2) end
  from public.plant_items x
  left join public.plant_logs l on l.plant_id = x.id and l.log_date between p_from and p_to
  where x.project_id = p_project and app.is_member(p_project)
  group by x.id
  order by x.code
$$;
revoke execute on function public.plant_utilisation(uuid, date, date) from public;
grant execute on function public.plant_utilisation(uuid, date, date) to authenticated;

-- ---------------------------------------------------------------------------
-- Approvals inbox (kind 'site_ops')
-- ---------------------------------------------------------------------------
create or replace function app.site_ops_approvals_for(p_user uuid)
returns table (kind text, entity_type text, entity_id uuid, project_id uuid, number text, title text, status text,
               requested_by uuid, requested_at timestamptz, is_urgent boolean, actions text[], age_hours numeric)
language plpgsql stable security definer set search_path = public as $$
declare v_role text; v_today date := app.local_date(now());
begin
  select pr.role::text into v_role from public.profiles pr where pr.id = p_user and pr.is_active;
  if v_role is null then return; end if;
  return query
  with mem as (
    select pm.project_id as pid from public.project_members pm where pm.user_id = p_user
    union select pj.id from public.projects pj where v_role = 'admin')
  -- incidents: investigate (management), corrective action (owner)
  select 'site_ops'::text, 'hse_incident'::text, i.id, i.project_id, i.number,
         case when i.status = 'reported' then 'Investigate ' || replace(i.kind, '_', ' ') || ' — ' else 'Corrective action — ' end || left(i.description, 80),
         i.status, i.reported_by, coalesce(i.investigated_at, i.created_at),
         i.severity in ('serious','fatal') or i.lost_time or (i.status = 'action' and i.action_due < v_today),
         array[case i.status when 'reported' then 'investigate' else 'action' end],
         round((extract(epoch from now() - coalesce(i.investigated_at, i.created_at)) / 3600)::numeric, 1)
  from public.hse_incidents i
  where i.project_id in (select pid from mem)
    and ((i.status = 'reported' and v_role in ('coordinator','manager','admin'))
      or (i.status = 'action' and (i.action_owner = p_user or (i.action_owner is null and v_role in ('coordinator','manager','admin')))))
  union all
  -- permits: approve (management, not own), close when expired (requester)
  select 'site_ops', 'work_permit', w.id, w.project_id, w.number,
         case when w.status = 'requested' then 'Approve permit to work — ' else 'Permit expired — close it: ' end
           || replace(w.permit_type, '_', ' ') || ', ' || left(w.description, 60),
         w.status, w.requested_by, case when w.status = 'requested' then w.created_at else w.valid_to end,
         w.status = 'requested' and w.valid_from <= now() + interval '2 hours',
         array[case w.status when 'requested' then 'approve' else 'close' end],
         round((extract(epoch from now() - case when w.status = 'requested' then w.created_at else w.valid_to end) / 3600)::numeric, 1)
  from public.work_permits w
  where w.project_id in (select pid from mem)
    and ((w.status = 'requested' and v_role in ('coordinator','manager','admin') and (w.requested_by <> p_user or v_role = 'admin'))
      or (w.status = 'approved' and w.valid_to < now() and w.requested_by = p_user));
end $$;
revoke execute on function app.site_ops_approvals_for(uuid) from public;
insert into app.approval_sources (fn) values ('app.site_ops_approvals_for') on conflict do nothing;


-- >>>>>>>>>>>>>>>>>>>> 20261105000040_contract_admin.sql

-- =============================================================================
-- Contract administration registers for the office (coordinator / planner, office engineer / QS, manager):
--
--  * contract_admin_settings  per project: RFI / SI / submittal response days, claim notice + particulars days,
--                             reminder lead time. Defaults: RFI 7 d, submittal 14 d, claim notice 28 d, particulars 42 d
--                             (FIDIC 20.1 style; check the project's GCC/SCC — Ethiopian PPA contracts vary).
--  * rfis                     RFIs (question to the consultant, ball in court, due date, answer, cost/time impact)
--                             and site instructions (SI received from the engineer/client, comply-by date), linked to
--                             a variation or an EOT claim; SIs can be registered from a site-diary instruction.
--  * project_documents /      drawing & document register with revisions; a new revision supersedes the previous one
--    document_revisions       and site roles are told which revision is current.
--  * submittals /             material approvals, shop drawings, method statements; each submission is a revision
--    submittal_revisions      answered with a review code A approved · B approved as noted · C revise & resubmit ·
--                             D rejected.
--  * meetings /               minutes with action items (owner, due date); actions can also stand alone.
--    meeting_actions
--  * risks                    risk & issue register (likelihood × impact 1–5, owner, response, review date).
--  * eot_claims               extension-of-time / delay claims: event, notice (late-notice warning), particulars,
--                             consultant decision; diary delays in the event window are the evidence
--                             (public.eot_delay_evidence); v_completion_dates = completion date + days granted.
--
-- Read: every project member (RLS app.is_member). Write: only through the RPCs below (security definer, role checks).
-- Inbox items: app.office_approvals_for (20261105000042). Re-runnable.
-- =============================================================================

create table if not exists public.contract_admin_settings (
  project_id               uuid primary key references public.projects (id) on delete cascade,
  rfi_response_days        int not null default 7 check (rfi_response_days between 1 and 90),
  si_response_days         int not null default 7 check (si_response_days between 1 and 90),
  submittal_response_days  int not null default 14 check (submittal_response_days between 1 and 90),
  claim_notice_days        int not null default 28 check (claim_notice_days between 1 and 180),
  claim_particulars_days   int not null default 42 check (claim_particulars_days between 1 and 365),
  reminder_days            int not null default 2 check (reminder_days between 0 and 30),
  updated_by               uuid references public.profiles (id),
  updated_at               timestamptz not null default now()
);

create or replace function app.ca_settings(p_project uuid) returns public.contract_admin_settings
language sql stable security definer set search_path = public as $$
  select coalesce((select s from public.contract_admin_settings s where s.project_id = p_project),
                  row(p_project, 7, 7, 14, 28, 42, 2, null, now())::public.contract_admin_settings)
$$;

-- Next register number per project: <prefix>-001 (serialised per project + prefix).
create or replace function app.ca_next_no(p_project uuid, p_table regclass, p_prefix text) returns text
language plpgsql security definer set search_path = public as $$
declare n int;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_project::text || p_prefix, 0));
  execute format('select coalesce(max(nullif(regexp_replace(number, ''^.*-'', ''''), '''')::int), 0) from %s where project_id = $1 and number ~ $2', p_table)
    into n using p_project, '^' || p_prefix || '-[0-9]+$';
  return p_prefix || '-' || lpad((n + 1)::text, 3, '0');
end $$;
revoke execute on function app.ca_next_no(uuid, regclass, text) from public;

-- ---------------------------------------------------------------------------
-- tables
-- ---------------------------------------------------------------------------
create table if not exists public.eot_claims (
  id                uuid primary key,
  project_id        uuid not null references public.projects (id),
  number            text not null,
  title             text not null,
  cause             text not null check (cause in ('variation','late_information','late_possession','client_payment','suspension',
                      'weather','force_majeure','utility','permit','other')),
  description       text,
  event_from        date not null,
  event_to          date,                                   -- null = continuing
  notice_date       date,
  notice_ref        text,
  particulars_date  date,
  days_claimed      numeric(6,1) not null default 0 check (days_claimed >= 0),
  cost_claimed      numeric(18,2) not null default 0 check (cost_claimed >= 0),
  status            text not null default 'draft' check (status in ('draft','notice_sent','submitted','granted','partly_granted','rejected','withdrawn')),
  days_granted      numeric(6,1) check (days_granted >= 0),
  cost_granted      numeric(18,2) check (cost_granted >= 0),
  decided_on        date,
  consultant_ref    text,
  decision_comment  text,
  variation_id      uuid references public.variations (id),
  created_by        uuid not null references public.profiles (id),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  unique (project_id, number)
);

create table if not exists public.rfis (
