);
create index if not exists meeting_actions_meeting_idx on public.meeting_actions (meeting_id);
create index if not exists meeting_actions_owner_idx on public.meeting_actions (owner_id) where status = 'open';

create table if not exists public.risks (
  id                  uuid primary key,
  project_id          uuid not null references public.projects (id),
  number              text not null,
  kind                text not null default 'risk' check (kind in ('risk','issue')),
  title               text not null,
  description         text,
  category            text not null default 'other' check (category in ('design','ground','client','finance','procurement','labour','equipment',
                        'weather','safety','regulatory','subcontractor','other')),
  likelihood          int not null default 3 check (likelihood between 1 and 5),
  impact              int not null default 3 check (impact between 1 and 5),
  score               int generated always as (likelihood * impact) stored,
  owner_id            uuid references public.profiles (id),
  response_type       text check (response_type in ('avoid','reduce','transfer','accept')),
  response            text,
  cost_exposure       numeric(18,2),
  time_exposure_days  numeric(6,1),
  review_by           date,
  status              text not null default 'open' check (status in ('open','occurred','closed')),
  closed_at           timestamptz,
  created_by          uuid not null references public.profiles (id),
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (project_id, number)
);

do $$
declare t text;
begin
  foreach t in array array['contract_admin_settings','eot_claims','rfis','project_documents','document_revisions','submittals',
                           'submittal_revisions','meetings','meeting_actions','risks'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop trigger if exists touch_updated_at on public.%I', t);
    execute format('create trigger touch_updated_at before update on public.%I for each row execute function app.touch_updated_at()', t);
    execute format('drop policy if exists member_read on public.%I', t);
    execute format('create policy member_read on public.%I for select to authenticated using (app.is_member(project_id))', t);
  end loop;
  foreach t in array array['eot_claims','rfis','project_documents','submittals','meetings','risks'] loop
    execute format('drop trigger if exists audit on public.%I', t);
    execute format('create trigger audit after insert or update or delete on public.%I for each row execute function app.audit()', t);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- helpers
-- ---------------------------------------------------------------------------
create or replace function app.ca_guard(p_project uuid, variadic p_roles text[]) returns void
language plpgsql stable security definer set search_path = public as $$
begin
  perform app.require_member(p_project);
  perform app.require_role_txt(variadic p_roles);
end $$;

create or replace function public.save_contract_admin_settings(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_seen jsonb := app.op_seen(p); v_project uuid := (p ->> 'project_id')::uuid; d public.contract_admin_settings;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.ca_guard(v_project, 'coordinator', 'manager', 'admin');
  d := app.ca_settings(v_project);
  insert into public.contract_admin_settings (project_id, rfi_response_days, si_response_days, submittal_response_days, claim_notice_days,
    claim_particulars_days, reminder_days, updated_by)
  values (v_project, coalesce((p ->> 'rfi_response_days')::int, d.rfi_response_days), coalesce((p ->> 'si_response_days')::int, d.si_response_days),
    coalesce((p ->> 'submittal_response_days')::int, d.submittal_response_days), coalesce((p ->> 'claim_notice_days')::int, d.claim_notice_days),
    coalesce((p ->> 'claim_particulars_days')::int, d.claim_particulars_days), coalesce((p ->> 'reminder_days')::int, d.reminder_days), auth.uid())
  on conflict (project_id) do update set rfi_response_days = excluded.rfi_response_days, si_response_days = excluded.si_response_days,
    submittal_response_days = excluded.submittal_response_days, claim_notice_days = excluded.claim_notice_days,
    claim_particulars_days = excluded.claim_particulars_days, reminder_days = excluded.reminder_days, updated_by = auth.uid();
  return app.op_done(p, 'save_contract_admin_settings', jsonb_build_object('ok', true));
end $$;

-- ---------------------------------------------------------------------------
-- RFIs & site instructions
-- ---------------------------------------------------------------------------
-- {id, project_id, kind 'rfi'|'si', subject, description, discipline?, location?, drawing_refs?, priority?, addressed_to?,
--  issued_by?, raised_on?, due_date?, cost_impact?, cost_amount?, time_impact?, time_days?, diary_instruction_id?}
create or replace function public.save_rfi(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); v_id uuid := coalesce((p ->> 'id')::uuid, gen_random_uuid()); v_project uuid := (p ->> 'project_id')::uuid;
  r public.rfis; v_kind text := coalesce(nullif(p ->> 'kind', ''), 'rfi'); v_raised date; s public.contract_admin_settings; di public.diary_instructions;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.ca_guard(v_project, 'site_engineer', 'office_engineer', 'coordinator', 'manager', 'admin');
  if nullif(trim(p ->> 'subject'), '') is null then raise exception 'Give it a subject'; end if;
  if nullif(trim(p ->> 'description'), '') is null then
    raise exception '%', case v_kind when 'si' then 'Write the instruction as given' else 'Write the question' end;
  end if;
  s := app.ca_settings(v_project);
  v_raised := coalesce(nullif(p ->> 'raised_on', '')::date, app.eat_date(now()));
  select * into r from public.rfis where id = v_id for update;
  if found then
    if r.project_id <> v_project then raise exception 'Belongs to another project'; end if;
    if r.status in ('closed','void') then raise exception '% is % and cannot be edited', r.number, r.status; end if;
    if r.created_by <> auth.uid() and not app.has_role_txt('office_engineer', 'coordinator', 'manager', 'admin') then
      raise exception 'Only the author or the office can edit %', r.number using errcode = '42501';
    end if;
    update public.rfis set subject = trim(p ->> 'subject'), description = trim(p ->> 'description'),
      discipline = nullif(p ->> 'discipline', ''), location = nullif(p ->> 'location', ''), drawing_refs = nullif(p ->> 'drawing_refs', ''),
      priority = coalesce(nullif(p ->> 'priority', ''), priority), addressed_to = nullif(p ->> 'addressed_to', ''), issued_by = nullif(p ->> 'issued_by', ''),
      raised_on = v_raised, due_date = coalesce(nullif(p ->> 'due_date', '')::date, due_date),
      cost_impact = coalesce(nullif(p ->> 'cost_impact', ''), cost_impact), cost_amount = nullif(p ->> 'cost_amount', '')::numeric,
      time_impact = coalesce(nullif(p ->> 'time_impact', ''), time_impact), time_days = nullif(p ->> 'time_days', '')::numeric
    where id = v_id;
  else
    if v_kind not in ('rfi','si') then raise exception 'Unknown kind %', v_kind; end if;
    if (p ->> 'diary_instruction_id') is not null then
      select * into di from public.diary_instructions where id = (p ->> 'diary_instruction_id')::uuid and project_id = v_project and deleted_at is null;
      if not found then raise exception 'Diary instruction not found in this project'; end if;
    end if;
    insert into public.rfis (id, project_id, kind, number, subject, description, discipline, location, drawing_refs, priority, addressed_to, issued_by,
      raised_on, due_date, ball_in_court, cost_impact, cost_amount, time_impact, time_days, diary_instruction_id, created_by)
    values (v_id, v_project, v_kind, app.ca_next_no(v_project, 'public.rfis', upper(v_kind)), trim(p ->> 'subject'), trim(p ->> 'description'),
      nullif(p ->> 'discipline', ''), nullif(p ->> 'location', ''), nullif(p ->> 'drawing_refs', ''), coalesce(nullif(p ->> 'priority', ''), 'normal'),
      nullif(p ->> 'addressed_to', ''), coalesce(nullif(p ->> 'issued_by', ''), di.given_by), v_raised,
      coalesce(nullif(p ->> 'due_date', '')::date, v_raised + case v_kind when 'si' then s.si_response_days else s.rfi_response_days end),
      case v_kind when 'si' then 'contractor' else 'consultant' end,
      coalesce(nullif(p ->> 'cost_impact', ''), 'none'), nullif(p ->> 'cost_amount', '')::numeric,
      coalesce(nullif(p ->> 'time_impact', ''), 'none'), nullif(p ->> 'time_days', '')::numeric, di.id, auth.uid());
    select * into r from public.rfis where id = v_id;
    if v_kind = 'si' then
      perform app.notify_roles_txt(v_project, '{coordinator,office_engineer,site_engineer}', 'Site instruction ' || r.number || ' received',
        r.subject || coalesce(' — comply by ' || to_char(r.due_date, 'DD Mon'), ''), 'rfi', v_id, r.priority = 'urgent');
    else
      perform app.notify_roles_txt(v_project, '{office_engineer,coordinator}', r.number || ' raised: ' || r.subject,
        'Answer due ' || to_char(r.due_date, 'DD Mon YYYY'), 'rfi', v_id, r.priority = 'urgent');
    end if;
  end if;
  if (select (cost_impact = 'yes' and cost_amount is null) or (time_impact = 'yes' and time_days is null) from public.rfis where id = v_id) then
    raise exception 'Enter the cost amount / days when the impact is "yes" (use "to be determined" if not known yet)';
  end if;
  select * into r from public.rfis where id = v_id;
  return app.op_done(p, 'save_rfi', jsonb_build_object('ok', true, 'id', v_id, 'number', r.number, 'status', r.status, 'due_date', r.due_date));
end $$;

-- {rfi_id, action: 'answer' (answer, answered_on?, answered_by?, cost_impact?, cost_amount?, time_impact?, time_days?) |
--  'close' | 'reopen' | 'void' (comment) | 'link' (variation_id? , eot_claim_id?) | 'ball' (ball_in_court)}
create or replace function public.decide_rfi(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_seen jsonb := app.op_seen(p); r public.rfis; a text := p ->> 'action'; c text := nullif(trim(p ->> 'comment'), '');
begin
  if v_seen is not null then return v_seen; end if;
  select * into r from public.rfis where id = (p ->> 'rfi_id')::uuid for update;
  if not found then raise exception 'RFI / instruction not found'; end if;
  perform app.ca_guard(r.project_id, 'office_engineer', 'coordinator', 'manager', 'admin');
  if a = 'answer' then
    if r.status not in ('open','answered') then raise exception '% is %', r.number, r.status; end if;
    if nullif(trim(p ->> 'answer'), '') is null then
      raise exception '%', case r.kind when 'si' then 'Say what was done to comply' else 'Enter the consultant''s answer' end;
    end if;
    update public.rfis set status = 'answered', answer = trim(p ->> 'answer'),
      answered_on = coalesce(nullif(p ->> 'answered_on', '')::date, app.eat_date(now())), answered_by = nullif(p ->> 'answered_by', ''),
      ball_in_court = 'contractor',
      cost_impact = coalesce(nullif(p ->> 'cost_impact', ''), cost_impact), cost_amount = coalesce(nullif(p ->> 'cost_amount', '')::numeric, cost_amount),
      time_impact = coalesce(nullif(p ->> 'time_impact', ''), time_impact), time_days = coalesce(nullif(p ->> 'time_days', '')::numeric, time_days)
    where id = r.id;
    perform app.notify_user(r.created_by, r.project_id, r.number || ' answered', left(trim(p ->> 'answer'), 200), 'rfi', r.id);
  elsif a = 'close' then
    if r.status = 'void' or r.status = 'closed' then raise exception '% is already %', r.number, r.status; end if;
    if r.kind = 'rfi' and r.status <> 'answered' then raise exception 'Record the answer before closing %', r.number; end if;
    update public.rfis set status = 'closed', closed_by = auth.uid(), closed_at = now() where id = r.id;
  elsif a = 'reopen' then
    if r.status not in ('answered','closed') then raise exception 'Only an answered or closed item can be reopened'; end if;
    update public.rfis set status = 'open', closed_by = null, closed_at = null,
      ball_in_court = case r.kind when 'rfi' then 'consultant' else 'contractor' end where id = r.id;
  elsif a = 'void' then
    if c is null then raise exception 'Say why it is void'; end if;
    if r.status = 'void' then raise exception '% is already void', r.number; end if;
    update public.rfis set status = 'void', void_reason = c where id = r.id;
  elsif a = 'link' then
    if (p ->> 'variation_id') is not null and not exists (select 1 from public.variations where id = (p ->> 'variation_id')::uuid and project_id = r.project_id) then
      raise exception 'Variation not in this project';
    end if;
    if (p ->> 'eot_claim_id') is not null and not exists (select 1 from public.eot_claims where id = (p ->> 'eot_claim_id')::uuid and project_id = r.project_id) then
      raise exception 'EOT claim not in this project';
    end if;
    update public.rfis set variation_id = case when p ? 'variation_id' then nullif(p ->> 'variation_id', '')::uuid else variation_id end,
      eot_claim_id = case when p ? 'eot_claim_id' then nullif(p ->> 'eot_claim_id', '')::uuid else eot_claim_id end where id = r.id;
  elsif a = 'ball' then
    if coalesce(p ->> 'ball_in_court', '') not in ('contractor','consultant','client') then raise exception 'Ball in court: contractor, consultant or client'; end if;
    update public.rfis set ball_in_court = p ->> 'ball_in_court' where id = r.id;
  else
    raise exception 'Unknown action %', a;
  end if;
  select * into r from public.rfis where id = r.id;
  return app.op_done(p, 'decide_rfi', jsonb_build_object('ok', true, 'id', r.id, 'number', r.number, 'status', r.status));
end $$;

-- ---------------------------------------------------------------------------
-- Drawing / document register
-- ---------------------------------------------------------------------------
-- {id, project_id, doc_no, title, discipline?, doc_type?, revision?: {rev, rev_date?, status?, received_on?, transmittal_ref?, notes?}}
create or replace function public.save_document(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); v_id uuid := coalesce((p ->> 'id')::uuid, gen_random_uuid()); v_project uuid := (p ->> 'project_id')::uuid;
  d public.project_documents; rv jsonb := p -> 'revision'; v_rev text; v_status text;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.ca_guard(v_project, 'office_engineer', 'coordinator', 'manager', 'admin');
  if nullif(trim(p ->> 'doc_no'), '') is null or nullif(trim(p ->> 'title'), '') is null then raise exception 'Document no. and title are required'; end if;
  select * into d from public.project_documents where id = v_id for update;
  if found then
    if d.project_id <> v_project then raise exception 'Belongs to another project'; end if;
    update public.project_documents set doc_no = trim(p ->> 'doc_no'), title = trim(p ->> 'title'), discipline = nullif(p ->> 'discipline', ''),
      doc_type = coalesce(nullif(p ->> 'doc_type', ''), doc_type), deleted_at = null where id = v_id;
  else
    if exists (select 1 from public.project_documents where project_id = v_project and doc_no = trim(p ->> 'doc_no')) then
      raise exception 'Document % is already in the register — add a revision to it', trim(p ->> 'doc_no');
    end if;
    insert into public.project_documents (id, project_id, doc_no, title, discipline, doc_type, created_by)
    values (v_id, v_project, trim(p ->> 'doc_no'), trim(p ->> 'title'), nullif(p ->> 'discipline', ''), coalesce(nullif(p ->> 'doc_type', ''), 'drawing'), auth.uid());
  end if;
  if rv is not null and nullif(trim(rv ->> 'rev'), '') is not null then
    v_rev := upper(trim(rv ->> 'rev'));
    v_status := coalesce(nullif(rv ->> 'status', ''), 'for_construction');
    if exists (select 1 from public.document_revisions where document_id = v_id and rev = v_rev) then
      raise exception 'Revision % of % is already registered', v_rev, trim(p ->> 'doc_no');
    end if;
    update public.document_revisions set superseded_at = now() where document_id = v_id and superseded_at is null;
    insert into public.document_revisions (document_id, project_id, rev, rev_date, status, received_on, transmittal_ref, notes, created_by)
    values (v_id, v_project, v_rev, nullif(rv ->> 'rev_date', '')::date, v_status,
      coalesce(nullif(rv ->> 'received_on', '')::date, app.eat_date(now())), nullif(rv ->> 'transmittal_ref', ''), nullif(rv ->> 'notes', ''), auth.uid());
    update public.project_documents set current_rev = v_rev, current_status = v_status where id = v_id;
    if v_status in ('for_construction','as_built') then
      perform app.notify_roles_txt(v_project, '{site_engineer,office_engineer,coordinator}',
        trim(p ->> 'doc_no') || ' rev ' || v_rev || ' issued for construction',
        trim(p ->> 'title') || ' — withdraw earlier revisions from site', 'document', v_id);
    end if;
  end if;
  select * into d from public.project_documents where id = v_id;
  return app.op_done(p, 'save_document', jsonb_build_object('ok', true, 'id', v_id, 'current_rev', d.current_rev));
end $$;

-- ---------------------------------------------------------------------------
-- Submittals
-- ---------------------------------------------------------------------------
-- {id, project_id, title, kind?, spec_section?, material_spec_id?, supplier?, required_by?, notes?}
create or replace function public.save_submittal(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_seen jsonb := app.op_seen(p); v_id uuid := coalesce((p ->> 'id')::uuid, gen_random_uuid()); v_project uuid := (p ->> 'project_id')::uuid; s public.submittals;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.ca_guard(v_project, 'office_engineer', 'coordinator', 'manager', 'procurement', 'admin');
  if nullif(trim(p ->> 'title'), '') is null then raise exception 'Give the submittal a title'; end if;
  if (p ->> 'material_spec_id') is not null and not exists (select 1 from public.material_specs where id = (p ->> 'material_spec_id')::uuid) then
    raise exception 'Material not found';
  end if;
  select * into s from public.submittals where id = v_id for update;
  if found then
    if s.project_id <> v_project then raise exception 'Belongs to another project'; end if;
    if s.status = 'void' then raise exception '% is void', s.number; end if;
    update public.submittals set title = trim(p ->> 'title'), kind = coalesce(nullif(p ->> 'kind', ''), kind), spec_section = nullif(p ->> 'spec_section', ''),
      material_spec_id = nullif(p ->> 'material_spec_id', '')::uuid, supplier = nullif(p ->> 'supplier', ''),
      required_by = nullif(p ->> 'required_by', '')::date, notes = nullif(p ->> 'notes', '') where id = v_id;
  else
    insert into public.submittals (id, project_id, number, title, kind, spec_section, material_spec_id, supplier, required_by, notes, created_by)
    values (v_id, v_project, app.ca_next_no(v_project, 'public.submittals', 'SUB'), trim(p ->> 'title'), coalesce(nullif(p ->> 'kind', ''), 'material'),
      nullif(p ->> 'spec_section', ''), nullif(p ->> 'material_spec_id', '')::uuid, nullif(p ->> 'supplier', ''),
      nullif(p ->> 'required_by', '')::date, nullif(p ->> 'notes', ''), auth.uid());
  end if;
  select * into s from public.submittals where id = v_id;
  return app.op_done(p, 'save_submittal', jsonb_build_object('ok', true, 'id', v_id, 'number', s.number, 'status', s.status));
end $$;

-- {submittal_id, action: 'submit' (submitted_on?, response_due?, transmittal_ref?) | 'respond' (code A|B|C|D, responded_on?, reviewer?, comments?)
--  | 'void' (comment)}
create or replace function public.decide_submittal(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); s public.submittals; a text := p ->> 'action'; v_rev int; v_on date; v_code text; v_status text;
  st public.contract_admin_settings;
begin
  if v_seen is not null then return v_seen; end if;
  select * into s from public.submittals where id = (p ->> 'submittal_id')::uuid for update;
  if not found then raise exception 'Submittal not found'; end if;
  perform app.ca_guard(s.project_id, 'office_engineer', 'coordinator', 'manager', 'admin');
  if a = 'submit' then
    if s.status not in ('draft','revise_resubmit','rejected') then
      raise exception '% is % — only a draft or a returned submittal can be (re)submitted', s.number, replace(s.status, '_', ' ');
    end if;
    st := app.ca_settings(s.project_id);
    v_rev := coalesce(s.current_rev + 1, 0);
    v_on := coalesce(nullif(p ->> 'submitted_on', '')::date, app.eat_date(now()));
    insert into public.submittal_revisions (submittal_id, project_id, rev, submitted_on, response_due, transmittal_ref, created_by)
    values (s.id, s.project_id, v_rev, v_on, coalesce(nullif(p ->> 'response_due', '')::date, v_on + st.submittal_response_days),
      nullif(p ->> 'transmittal_ref', ''), auth.uid());
    update public.submittals set status = 'submitted', current_rev = v_rev where id = s.id;
  elsif a = 'respond' then
    if s.status <> 'submitted' then raise exception '% is not waiting for a response', s.number; end if;
    v_code := upper(coalesce(p ->> 'code', ''));
    if v_code not in ('A','B','C','D') then raise exception 'Review code: A approved, B approved as noted, C revise & resubmit, D rejected'; end if;
    if v_code in ('B','C','D') and nullif(trim(p ->> 'comments'), '') is null then raise exception 'Enter the reviewer''s comments'; end if;
    update public.submittal_revisions set code = v_code, responded_on = coalesce(nullif(p ->> 'responded_on', '')::date, app.eat_date(now())),
      reviewer = nullif(p ->> 'reviewer', ''), comments = nullif(trim(p ->> 'comments'), '')
    where submittal_id = s.id and rev = s.current_rev;
    v_status := case v_code when 'A' then 'approved' when 'B' then 'approved_as_noted' when 'C' then 'revise_resubmit' else 'rejected' end;
    update public.submittals set status = v_status where id = s.id;
    perform app.notify_user(s.created_by, s.project_id, s.number || ' returned code ' || v_code, s.title, 'submittal', s.id);
    if v_code in ('A','B') and s.material_spec_id is not null then
      perform app.notify_roles_txt(s.project_id, '{procurement}', 'Material approved: ' || s.title,
        s.number || ' code ' || v_code || ' — it can be ordered', 'submittal', s.id);
    end if;
  elsif a = 'void' then
    if nullif(trim(p ->> 'comment'), '') is null then raise exception 'Say why it is void'; end if;
    update public.submittals set status = 'void', notes = coalesce(notes || E'\n', '') || 'Void: ' || trim(p ->> 'comment') where id = s.id;
  else
    raise exception 'Unknown action %', a;
  end if;
  select * into s from public.submittals where id = s.id;
  return app.op_done(p, 'decide_submittal', jsonb_build_object('ok', true, 'id', s.id, 'number', s.number, 'status', s.status, 'rev', s.current_rev));
end $$;

-- ---------------------------------------------------------------------------
-- Meetings & actions
-- ---------------------------------------------------------------------------
-- {id, project_id, kind?, title, held_on, location?, chaired_by?, attendees?, agenda?, minutes?, next_meeting_on?,
--  actions?: [{id?, description, owner_id?, owner_name?, due_date?}], issue?: bool}
create or replace function public.save_meeting(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); v_id uuid := coalesce((p ->> 'id')::uuid, gen_random_uuid()); v_project uuid := (p ->> 'project_id')::uuid;
  m public.meetings; x record; n int := 0; v_keep uuid[] := '{}'; v_aid uuid;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.ca_guard(v_project, 'site_engineer', 'office_engineer', 'coordinator', 'manager', 'admin');
  if nullif(trim(p ->> 'title'), '') is null then raise exception 'Give the meeting a title'; end if;
  if (p ->> 'held_on') is null then raise exception 'Enter the meeting date'; end if;
  select * into m from public.meetings where id = v_id for update;
  if found then
    if m.project_id <> v_project then raise exception 'Belongs to another project'; end if;
    update public.meetings set kind = coalesce(nullif(p ->> 'kind', ''), kind), title = trim(p ->> 'title'), held_on = (p ->> 'held_on')::date,
      location = nullif(p ->> 'location', ''), chaired_by = nullif(p ->> 'chaired_by', ''), attendees = nullif(p ->> 'attendees', ''),
      agenda = nullif(p ->> 'agenda', ''), minutes = nullif(p ->> 'minutes', ''), next_meeting_on = nullif(p ->> 'next_meeting_on', '')::date
    where id = v_id;
  else
    insert into public.meetings (id, project_id, number, kind, title, held_on, location, chaired_by, attendees, agenda, minutes, next_meeting_on, created_by)
    values (v_id, v_project, app.ca_next_no(v_project, 'public.meetings', 'MOM'), coalesce(nullif(p ->> 'kind', ''), 'progress'), trim(p ->> 'title'),
      (p ->> 'held_on')::date, nullif(p ->> 'location', ''), nullif(p ->> 'chaired_by', ''), nullif(p ->> 'attendees', ''), nullif(p ->> 'agenda', ''),
      nullif(p ->> 'minutes', ''), nullif(p ->> 'next_meeting_on', '')::date, auth.uid());
  end if;
  if p ? 'actions' then
    for x in select * from jsonb_to_recordset(coalesce(p -> 'actions', '[]'::jsonb)) as y(id uuid, description text, owner_id uuid, owner_name text, due_date date) loop
      n := n + 1;
      if nullif(trim(x.description), '') is null then raise exception 'Action %: describe it', n; end if;
      if x.owner_id is null and nullif(trim(x.owner_name), '') is null then raise exception 'Action %: who owns it?', n; end if;
      if x.owner_id is not null and not exists (select 1 from public.project_members where project_id = v_project and user_id = x.owner_id) then
        raise exception 'Action %: the owner is not on this project', n;
      end if;
      v_aid := coalesce(x.id, gen_random_uuid());
      insert into public.meeting_actions (id, project_id, meeting_id, seq, description, owner_id, owner_name, due_date, created_by)
      values (v_aid, v_project, v_id, n, trim(x.description), x.owner_id, nullif(trim(x.owner_name), ''), x.due_date, auth.uid())
      on conflict (id) do update set seq = excluded.seq, description = excluded.description, owner_id = excluded.owner_id,
        owner_name = excluded.owner_name, due_date = excluded.due_date
      where meeting_actions.meeting_id = v_id;
      v_keep := v_keep || v_aid;
    end loop;
    delete from public.meeting_actions where meeting_id = v_id and status = 'open' and not (id = any (v_keep));
  end if;
  if coalesce((p ->> 'issue')::boolean, false) then
    select * into m from public.meetings where id = v_id;
    if m.status <> 'issued' then
      update public.meetings set status = 'issued', issued_at = now() where id = v_id;
      for x in select a.* from public.meeting_actions a where a.meeting_id = v_id and a.status = 'open' and a.owner_id is not null loop
        perform app.notify_user(x.owner_id, v_project, 'Action from ' || m.number || coalesce(' — due ' || to_char(x.due_date, 'DD Mon'), ''),
          x.description, 'meeting_action', x.id);
      end loop;
    end if;
  end if;
  select * into m from public.meetings where id = v_id;
  return app.op_done(p, 'save_meeting', jsonb_build_object('ok', true, 'id', v_id, 'number', m.number, 'status', m.status,
    'actions', (select count(*) from public.meeting_actions where meeting_id = v_id)));
end $$;

-- Standalone action or an edit of one: {id, project_id, description, owner_id?, owner_name?, due_date?, meeting_id?}
-- Status change: {id, project_id, action: 'done' | 'reopen' | 'cancel', note?} — owner or the office.
create or replace function public.save_action_item(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); v_id uuid := coalesce((p ->> 'id')::uuid, gen_random_uuid()); v_project uuid := (p ->> 'project_id')::uuid;
  a public.meeting_actions; v_act text := p ->> 'action'; v_office boolean; v_exists boolean;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.require_member(v_project);
  v_office := app.has_role_txt('office_engineer', 'coordinator', 'manager', 'admin');
  select * into a from public.meeting_actions where id = v_id for update;
  v_exists := found;
  if v_act is not null then
    if not v_exists or a.project_id <> v_project then raise exception 'Action not found'; end if;
    if a.owner_id is distinct from auth.uid() and not v_office then
      raise exception 'Only the owner or the office can update this action' using errcode = '42501';
    end if;
    if v_act = 'done' then
      if a.status <> 'open' then raise exception 'The action is already %', a.status; end if;
      update public.meeting_actions set status = 'done', done_at = now(), done_by = auth.uid(), done_note = nullif(trim(p ->> 'note'), '') where id = v_id;
      if a.created_by is distinct from auth.uid() then
        perform app.notify_user(a.created_by, v_project, 'Action done', left(a.description, 120), 'meeting_action', v_id);
      end if;
    elsif v_act = 'reopen' then
      update public.meeting_actions set status = 'open', done_at = null, done_by = null where id = v_id;
    elsif v_act = 'cancel' then
      if not v_office then raise exception 'Only the office can cancel an action' using errcode = '42501'; end if;
      update public.meeting_actions set status = 'cancelled', done_note = nullif(trim(p ->> 'note'), '') where id = v_id;
    else
      raise exception 'Unknown action %', v_act;
    end if;
  else
    perform app.require_role_txt('site_engineer', 'office_engineer', 'coordinator', 'manager', 'admin');
    if nullif(trim(p ->> 'description'), '') is null then raise exception 'Describe the action'; end if;
    if (p ->> 'owner_id') is null and nullif(trim(p ->> 'owner_name'), '') is null then raise exception 'Who owns the action?'; end if;
    if (p ->> 'owner_id') is not null and not exists (select 1 from public.project_members where project_id = v_project and user_id = (p ->> 'owner_id')::uuid) then
      raise exception 'The owner is not on this project';
    end if;
    if v_exists then
      if a.project_id <> v_project then raise exception 'Action not found'; end if;
      update public.meeting_actions set description = trim(p ->> 'description'), owner_id = nullif(p ->> 'owner_id', '')::uuid,
        owner_name = nullif(trim(p ->> 'owner_name'), ''), due_date = nullif(p ->> 'due_date', '')::date where id = v_id;
    else
      insert into public.meeting_actions (id, project_id, meeting_id, description, owner_id, owner_name, due_date, created_by)
      values (v_id, v_project, nullif(p ->> 'meeting_id', '')::uuid, trim(p ->> 'description'), nullif(p ->> 'owner_id', '')::uuid,
        nullif(trim(p ->> 'owner_name'), ''), nullif(p ->> 'due_date', '')::date, auth.uid());
      perform app.notify_user(nullif(p ->> 'owner_id', '')::uuid, v_project, 'New action for you' || coalesce(' — due ' || to_char(nullif(p ->> 'due_date', '')::date, 'DD Mon'), ''),
        trim(p ->> 'description'), 'meeting_action', v_id);
    end if;
  end if;
  select * into a from public.meeting_actions where id = v_id;
  return app.op_done(p, 'save_action_item', jsonb_build_object('ok', true, 'id', v_id, 'status', a.status));
end $$;

-- ---------------------------------------------------------------------------
-- Risks & issues
-- ---------------------------------------------------------------------------
-- {id, project_id, kind?, title, description?, category?, likelihood?, impact?, owner_id?, response_type?, response?, cost_exposure?,
--  time_exposure_days?, review_by?, status?}
create or replace function public.save_risk(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_seen jsonb := app.op_seen(p); v_id uuid := coalesce((p ->> 'id')::uuid, gen_random_uuid()); v_project uuid := (p ->> 'project_id')::uuid; r public.risks;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.require_member(v_project);
  if nullif(trim(p ->> 'title'), '') is null then raise exception 'Give the risk a title'; end if;
  if (p ->> 'owner_id') is not null and not exists (select 1 from public.project_members where project_id = v_project and user_id = (p ->> 'owner_id')::uuid) then
    raise exception 'The owner is not on this project';
  end if;
  select * into r from public.risks where id = v_id for update;
  if found then
    if r.project_id <> v_project then raise exception 'Belongs to another project'; end if;
    if r.owner_id is distinct from auth.uid() and not app.has_role_txt('office_engineer', 'coordinator', 'manager', 'admin') then
      raise exception 'Only the owner or the office can update %', r.number using errcode = '42501';
    end if;
    update public.risks set kind = coalesce(nullif(p ->> 'kind', ''), kind), title = trim(p ->> 'title'), description = nullif(p ->> 'description', ''),
      category = coalesce(nullif(p ->> 'category', ''), category), likelihood = coalesce((p ->> 'likelihood')::int, likelihood),
      impact = coalesce((p ->> 'impact')::int, impact), owner_id = nullif(p ->> 'owner_id', '')::uuid,
      response_type = nullif(p ->> 'response_type', ''), response = nullif(p ->> 'response', ''),
      cost_exposure = nullif(p ->> 'cost_exposure', '')::numeric, time_exposure_days = nullif(p ->> 'time_exposure_days', '')::numeric,
      review_by = nullif(p ->> 'review_by', '')::date, status = coalesce(nullif(p ->> 'status', ''), status),
      closed_at = case when coalesce(nullif(p ->> 'status', ''), status) = 'closed' then coalesce(closed_at, now()) else null end
    where id = v_id;
  else
    perform app.require_role_txt('site_engineer', 'office_engineer', 'coordinator', 'manager', 'procurement', 'admin');
    insert into public.risks (id, project_id, number, kind, title, description, category, likelihood, impact, owner_id, response_type, response,
      cost_exposure, time_exposure_days, review_by, created_by)
    values (v_id, v_project, app.ca_next_no(v_project, 'public.risks', 'R'), coalesce(nullif(p ->> 'kind', ''), 'risk'), trim(p ->> 'title'),
      nullif(p ->> 'description', ''), coalesce(nullif(p ->> 'category', ''), 'other'), coalesce((p ->> 'likelihood')::int, 3), coalesce((p ->> 'impact')::int, 3),
      nullif(p ->> 'owner_id', '')::uuid, nullif(p ->> 'response_type', ''), nullif(p ->> 'response', ''), nullif(p ->> 'cost_exposure', '')::numeric,
      nullif(p ->> 'time_exposure_days', '')::numeric, nullif(p ->> 'review_by', '')::date, auth.uid());
    select * into r from public.risks where id = v_id;
    perform app.notify_user(r.owner_id, v_project, 'You own ' || r.number || ': ' || r.title, 'Score ' || r.score || ' — set a response', 'risk', v_id, r.score >= 15);
    if r.score >= 15 then
      perform app.notify_roles_txt(v_project, '{manager}', 'High ' || r.kind || ' ' || r.number || ': ' || r.title, 'Score ' || r.score, 'risk', v_id, true);
    end if;
  end if;
  select * into r from public.risks where id = v_id;
  return app.op_done(p, 'save_risk', jsonb_build_object('ok', true, 'id', v_id, 'number', r.number, 'score', r.score, 'status', r.status));
end $$;

-- ---------------------------------------------------------------------------
-- Extension of time (EOT) claims
-- ---------------------------------------------------------------------------
-- {id, project_id, title, cause, description?, event_from, event_to?, days_claimed?, cost_claimed?, variation_id?}
create or replace function public.save_eot_claim(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_seen jsonb := app.op_seen(p); v_id uuid := coalesce((p ->> 'id')::uuid, gen_random_uuid()); v_project uuid := (p ->> 'project_id')::uuid; e public.eot_claims;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.ca_guard(v_project, 'office_engineer', 'coordinator', 'manager', 'admin');
  if nullif(trim(p ->> 'title'), '') is null then raise exception 'Give the claim a title'; end if;
  if (p ->> 'event_from') is null then raise exception 'When did the delay event start?'; end if;
  if nullif(p ->> 'event_to', '')::date < (p ->> 'event_from')::date then raise exception 'The event cannot end before it starts'; end if;
  if (p ->> 'variation_id') is not null and not exists (select 1 from public.variations where id = (p ->> 'variation_id')::uuid and project_id = v_project) then
    raise exception 'Variation not in this project';
  end if;
  select * into e from public.eot_claims where id = v_id for update;
  if found then
    if e.project_id <> v_project then raise exception 'Belongs to another project'; end if;
    if e.status not in ('draft','notice_sent') then raise exception '% is % — it can no longer be edited', e.number, replace(e.status, '_', ' '); end if;
    update public.eot_claims set title = trim(p ->> 'title'), cause = coalesce(nullif(p ->> 'cause', ''), cause), description = nullif(p ->> 'description', ''),
      event_from = (p ->> 'event_from')::date, event_to = nullif(p ->> 'event_to', '')::date,
      days_claimed = coalesce((p ->> 'days_claimed')::numeric, days_claimed), cost_claimed = coalesce((p ->> 'cost_claimed')::numeric, cost_claimed),
      variation_id = nullif(p ->> 'variation_id', '')::uuid where id = v_id;
  else
    insert into public.eot_claims (id, project_id, number, title, cause, description, event_from, event_to, days_claimed, cost_claimed, variation_id, created_by)
    values (v_id, v_project, app.ca_next_no(v_project, 'public.eot_claims', 'EOT'), trim(p ->> 'title'), coalesce(nullif(p ->> 'cause', ''), 'other'),
      nullif(p ->> 'description', ''), (p ->> 'event_from')::date, nullif(p ->> 'event_to', '')::date, coalesce((p ->> 'days_claimed')::numeric, 0),
      coalesce((p ->> 'cost_claimed')::numeric, 0), nullif(p ->> 'variation_id', '')::uuid, auth.uid());
    perform app.notify_roles_txt(v_project, '{coordinator,manager}', 'Delay event ' || (select number from public.eot_claims where id = v_id) || ': ' || trim(p ->> 'title'),
      'Send the notice by ' || to_char((p ->> 'event_from')::date + (app.ca_settings(v_project)).claim_notice_days, 'DD Mon YYYY'), 'eot_claim', v_id, true);
  end if;
  select * into e from public.eot_claims where id = v_id;
  return app.op_done(p, 'save_eot_claim', jsonb_build_object('ok', true, 'id', v_id, 'number', e.number, 'status', e.status,
    'notice_due', e.event_from + (app.ca_settings(v_project)).claim_notice_days));
end $$;

-- {claim_id, action: 'send_notice' (notice_date?, notice_ref?) | 'submit' (particulars_date?, days_claimed?, cost_claimed?) |
--  'decide' (days_granted, cost_granted?, decided_on?, consultant_ref?, comment?) | 'withdraw' (comment)}
create or replace function public.decide_eot_claim(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_seen jsonb := app.op_seen(p); e public.eot_claims; a text := p ->> 'action'; v_days numeric; v_status text; v_late boolean := false;
begin
  if v_seen is not null then return v_seen; end if;
  select * into e from public.eot_claims where id = (p ->> 'claim_id')::uuid for update;
  if not found then raise exception 'Claim not found'; end if;
  perform app.ca_guard(e.project_id, 'coordinator', 'manager', 'admin');
  if a = 'send_notice' then
    if e.status <> 'draft' then raise exception 'The notice for % was already sent', e.number; end if;
    update public.eot_claims set status = 'notice_sent', notice_date = coalesce(nullif(p ->> 'notice_date', '')::date, app.eat_date(now())),
      notice_ref = nullif(p ->> 'notice_ref', '') where id = e.id;
    v_late := (select notice_date from public.eot_claims where id = e.id) > e.event_from + (app.ca_settings(e.project_id)).claim_notice_days;
  elsif a = 'submit' then
    if e.status <> 'notice_sent' then raise exception 'Send the notice before the detailed claim'; end if;
    update public.eot_claims set status = 'submitted', particulars_date = coalesce(nullif(p ->> 'particulars_date', '')::date, app.eat_date(now())),
      days_claimed = coalesce((p ->> 'days_claimed')::numeric, days_claimed), cost_claimed = coalesce((p ->> 'cost_claimed')::numeric, cost_claimed)
    where id = e.id;
    if (select days_claimed <= 0 and cost_claimed <= 0 from public.eot_claims where id = e.id) then
      raise exception 'Enter the days and/or cost claimed';
    end if;
  elsif a = 'decide' then
    if e.status <> 'submitted' then raise exception 'Only a submitted claim can be decided'; end if;
    v_days := (p ->> 'days_granted')::numeric;
    if v_days is null or v_days < 0 then raise exception 'Enter the days granted (0 if rejected)'; end if;
    v_status := case when v_days = 0 and coalesce((p ->> 'cost_granted')::numeric, 0) = 0 then 'rejected'
                     when v_days >= e.days_claimed and coalesce((p ->> 'cost_granted')::numeric, 0) >= e.cost_claimed then 'granted'
                     else 'partly_granted' end;
    update public.eot_claims set status = v_status, days_granted = v_days, cost_granted = coalesce((p ->> 'cost_granted')::numeric, 0),
      decided_on = coalesce(nullif(p ->> 'decided_on', '')::date, app.eat_date(now())), consultant_ref = nullif(p ->> 'consultant_ref', ''),
      decision_comment = nullif(trim(p ->> 'comment'), '') where id = e.id;
    perform app.notify_roles_txt(e.project_id, '{coordinator,manager,office_engineer}', e.number || ' ' || replace(v_status, '_', ' '),
      v_days || ' day(s) granted of ' || e.days_claimed, 'eot_claim', e.id);
  elsif a = 'withdraw' then
    if e.status in ('granted','partly_granted','rejected','withdrawn') then raise exception '% is already %', e.number, replace(e.status, '_', ' '); end if;
    update public.eot_claims set status = 'withdrawn', decision_comment = nullif(trim(p ->> 'comment'), '') where id = e.id;
  else
    raise exception 'Unknown action %', a;
  end if;
  select * into e from public.eot_claims where id = e.id;
  return app.op_done(p, 'decide_eot_claim', jsonb_build_object('ok', true, 'id', e.id, 'number', e.number, 'status', e.status, 'notice_late', v_late));
end $$;

-- Delay evidence from signed / submitted site diaries in a window: hours lost by cause (8 h = 1 day) and rain hours.
create or replace function public.eot_delay_evidence(p_project uuid, p_from date, p_to date)
returns table (cause text, diaries bigint, hours_lost numeric, days_lost numeric, first_date date, last_date date)
language sql stable security invoker set search_path = public as $$
  select x.cause, count(distinct d.id), coalesce(sum(x.hours_lost), 0), round(coalesce(sum(x.hours_lost), 0) / 8, 1), min(d.diary_date), max(d.diary_date)
  from public.diary_delays x join public.site_diaries d on d.id = x.diary_id
  where d.project_id = p_project and d.diary_date between p_from and coalesce(p_to, app.eat_date(now()))
    and x.deleted_at is null and d.status <> 'draft'
  group by x.cause order by 3 desc
$$;
grant execute on function public.eot_delay_evidence(uuid, date, date) to authenticated;

create or replace view public.v_completion_dates with (security_invoker = true) as
select pj.id as project_id, pj.start_date, pj.end_date as original_completion,
       coalesce(sum(e.days_granted) filter (where e.status in ('granted','partly_granted')), 0) as days_granted,
       coalesce(sum(e.days_claimed) filter (where e.status in ('notice_sent','submitted')), 0) as days_pending,
       pj.end_date + coalesce(sum(e.days_granted) filter (where e.status in ('granted','partly_granted')), 0)::int as revised_completion
from public.projects pj left join public.eot_claims e on e.project_id = pj.id
where app.is_member(pj.id)
group by pj.id;
grant select on public.v_completion_dates to authenticated;

-- RFI / submittal registers with the overdue figures the inbox and the pages use.
create or replace view public.v_rfi_register with (security_invoker = true) as
select r.*, case when r.status = 'open' and r.due_date < app.eat_date(now()) then app.eat_date(now()) - r.due_date else 0 end as days_overdue,
       coalesce(r.answered_on, app.eat_date(now())) - r.raised_on as days_open,
       v.number as variation_number, e.number as eot_number
from public.rfis r left join public.variations v on v.id = r.variation_id left join public.eot_claims e on e.id = r.eot_claim_id;
grant select on public.v_rfi_register to authenticated;

create or replace view public.v_submittal_register with (security_invoker = true) as
select s.*, r.submitted_on, r.response_due, r.code, r.responded_on, r.reviewer, r.comments, r.transmittal_ref,
       case when s.status = 'submitted' and r.response_due < app.eat_date(now()) then app.eat_date(now()) - r.response_due else 0 end as days_overdue,
       (s.required_by is not null and s.status not in ('approved','approved_as_noted','void') and s.required_by <= app.eat_date(now()) + 14) as at_risk
from public.submittals s left join public.submittal_revisions r on r.submittal_id = s.id and r.rev = s.current_rev;
grant select on public.v_submittal_register to authenticated;

notify pgrst, 'reload schema';


-- >>>>>>>>>>>>>>>>>>>> 20261105000041_receivables_retention.sql

-- =============================================================================
-- Client receivables ageing and retention release (gap list #3, #4).
--
--  * client_contracts gets payment_days (client pays a certificate within N days of certification — check the
--    GCC/SCC; 28 by default), certify_days (consultant certifies within N days of submission), practical completion
--    date, defects liability period (months) and the share of retention released at practical completion (50 %).
--  * v_client_receivables  per IPC: submitted / certified / due date, payable, received, outstanding, days overdue
--                          and ageing bucket (not certified · not due · 1–30 · 31–60 · 61–90 · 90+).
--  * retention_releases    stage 'practical_completion' (part, usually half) and 'final' (rest after the DLP):
--                          requested → certified → received.
--  * v_retention_status    held (certified retention to date), released, due now per stage.
-- Price data: readable by members with price access (as the IPC tables). Re-runnable.
-- =============================================================================

alter table public.client_contracts add column if not exists payment_days int not null default 28;
alter table public.client_contracts add column if not exists certify_days int not null default 28;
alter table public.client_contracts add column if not exists practical_completion_on date;
alter table public.client_contracts add column if not exists dlp_months int not null default 12;
alter table public.client_contracts add column if not exists retention_pc_release_pct numeric(5,2) not null default 50;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'client_contracts_completion_terms') then
    alter table public.client_contracts add constraint client_contracts_completion_terms
      check (payment_days between 0 and 365 and certify_days between 0 and 365 and dlp_months between 0 and 60
             and retention_pc_release_pct between 0 and 100);
  end if;
end $$;

create table if not exists public.retention_releases (
  id               uuid primary key,
  project_id       uuid not null references public.projects (id),
  stage            text not null check (stage in ('practical_completion','final')),
  amount           numeric(18,2) not null check (amount >= 0),
  requested_on     date not null,
  certified_on     date,
  received_on      date,
  received_amount  numeric(18,2) not null default 0 check (received_amount >= 0),
  ref              text,
  status           text not null default 'requested' check (status in ('requested','certified','received')),
  created_by       uuid not null references public.profiles (id),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (project_id, stage)
);
alter table public.retention_releases enable row level security;
drop trigger if exists touch_updated_at on public.retention_releases;
create trigger touch_updated_at before update on public.retention_releases for each row execute function app.touch_updated_at();
drop trigger if exists audit on public.retention_releases;
create trigger audit after insert or update or delete on public.retention_releases for each row execute function app.audit();
drop policy if exists price_read on public.retention_releases;
create policy price_read on public.retention_releases for select to authenticated using (app.is_member(project_id) and app.can_see_prices());

create or replace view public.v_client_receivables with (security_invoker = true) as
with b as (
  select i.id, i.project_id, i.ipc_no, i.status, i.period_to, i.submitted_at::date as submitted_on, i.certified_on,
         coalesce((coalesce(i.certified, i.claimed) ->> 'payable')::numeric, 0) as payable, i.paid_amount, i.paid_on,
         c.payment_days, c.certify_days
  from public.client_ipcs i join public.client_contracts c on c.project_id = i.project_id
  where i.status in ('submitted','certified','paid'))
select b.*,
       case when b.status = 'submitted' then b.submitted_on + b.certify_days else b.certified_on + b.payment_days end as due_on,
       greatest(b.payable - b.paid_amount, 0) as outstanding,
       case when b.status = 'paid' or b.payable - b.paid_amount <= 0.005 then 0
            when b.status = 'submitted' then greatest(app.eat_date(now()) - (b.submitted_on + b.certify_days), 0)
            else greatest(app.eat_date(now()) - (b.certified_on + b.payment_days), 0) end as days_overdue,
       case when b.status = 'paid' or b.payable - b.paid_amount <= 0.005 then 'paid'
            when b.status = 'submitted' then 'not_certified'
            when app.eat_date(now()) <= b.certified_on + b.payment_days then 'not_due'
            when app.eat_date(now()) - (b.certified_on + b.payment_days) <= 30 then '1_30'
            when app.eat_date(now()) - (b.certified_on + b.payment_days) <= 60 then '31_60'
            when app.eat_date(now()) - (b.certified_on + b.payment_days) <= 90 then '61_90'
            else '90_plus' end as bucket
from b;
grant select on public.v_client_receivables to authenticated;

create or replace view public.v_retention_status with (security_invoker = true) as
with held as (
  select distinct on (i.project_id) i.project_id, coalesce((i.certified ->> 'retention_cum')::numeric, 0) as held, i.ipc_no
  from public.client_ipcs i where i.status in ('certified','paid') order by i.project_id, i.ipc_no desc),
rel as (
  select project_id,
         coalesce(sum(amount) filter (where stage = 'practical_completion'), 0) as pc_amount,
         max(status) filter (where stage = 'practical_completion') as pc_status,
         coalesce(sum(amount) filter (where stage = 'final'), 0) as final_amount,
         max(status) filter (where stage = 'final') as final_status,
         coalesce(sum(received_amount), 0) as received
  from public.retention_releases group by project_id)
select c.project_id, coalesce(h.held, 0) as held, c.practical_completion_on, c.dlp_months, c.retention_pc_release_pct,
       (c.practical_completion_on + make_interval(months => c.dlp_months))::date as dlp_end,
       round(coalesce(h.held, 0) * c.retention_pc_release_pct / 100, 2) as pc_release_amount,
       coalesce(r.pc_amount, 0) as pc_requested, r.pc_status,
       coalesce(h.held, 0) - coalesce(r.pc_amount, 0) as final_release_amount,
       coalesce(r.final_amount, 0) as final_requested, r.final_status,
       coalesce(r.received, 0) as received,
       coalesce(h.held, 0) - coalesce(r.received, 0) as still_held,
       (c.practical_completion_on is not null and c.practical_completion_on <= app.eat_date(now()) and r.pc_status is null and coalesce(h.held, 0) > 0) as pc_release_due,
       (c.practical_completion_on is not null and (c.practical_completion_on + make_interval(months => c.dlp_months))::date <= app.eat_date(now())
         and r.final_status is null and coalesce(h.held, 0) - coalesce(r.pc_amount, 0) > 0) as final_release_due
from public.client_contracts c left join held h on h.project_id = c.project_id left join rel r on r.project_id = c.project_id;
grant select on public.v_retention_status to authenticated;

-- {project_id, payment_days?, certify_days?, practical_completion_on?, dlp_months?, retention_pc_release_pct?}
create or replace function public.save_contract_completion(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_seen jsonb := app.op_seen(p); v_project uuid := (p ->> 'project_id')::uuid;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.billing_guard(v_project, 'coordinator', 'manager', 'admin');
  if not exists (select 1 from public.client_contracts where project_id = v_project) then raise exception 'Enter the contract terms first'; end if;
  update public.client_contracts set payment_days = coalesce((p ->> 'payment_days')::int, payment_days),
    certify_days = coalesce((p ->> 'certify_days')::int, certify_days),
    practical_completion_on = case when p ? 'practical_completion_on' then nullif(p ->> 'practical_completion_on', '')::date else practical_completion_on end,
    dlp_months = coalesce((p ->> 'dlp_months')::int, dlp_months),
    retention_pc_release_pct = coalesce((p ->> 'retention_pc_release_pct')::numeric, retention_pc_release_pct), updated_by = auth.uid()
  where project_id = v_project;
  return app.op_done(p, 'save_contract_completion', jsonb_build_object('ok', true));
end $$;

-- {id, project_id, stage, amount?, requested_on?, certified_on?, received_on?, received_amount?, ref?}
-- amount defaults to what v_retention_status says is due for the stage; receipts by finance / management.
create or replace function public.save_retention_release(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); v_project uuid := (p ->> 'project_id')::uuid; v_stage text := p ->> 'stage'; r public.retention_releases;
  st record; v_amt numeric; v_id uuid := coalesce((p ->> 'id')::uuid, gen_random_uuid());
begin
  if v_seen is not null then return v_seen; end if;
  perform app.billing_guard(v_project, 'coordinator', 'manager', 'finance', 'admin');
  if v_stage not in ('practical_completion','final') then raise exception 'Stage: practical_completion or final'; end if;
  select * into st from public.v_retention_status where project_id = v_project;
  if not found or st.practical_completion_on is null then raise exception 'Record the practical completion date first'; end if;
  select * into r from public.retention_releases where project_id = v_project and stage = v_stage for update;
  if not found then
    if not app.has_role_txt('coordinator', 'manager', 'admin') then raise exception 'Coordinators and managers request retention' using errcode = '42501'; end if;
    if v_stage = 'final' and st.dlp_end > app.eat_date(now()) and not coalesce((p ->> 'early')::boolean, false) then
      raise exception 'The defects liability period ends on % — the final retention is due then', st.dlp_end;
    end if;
    v_amt := coalesce((p ->> 'amount')::numeric, case v_stage when 'practical_completion' then st.pc_release_amount else st.final_release_amount end);
    if v_amt <= 0 then raise exception 'No retention is held for this stage'; end if;
    if v_amt > st.held - (case v_stage when 'final' then st.pc_requested else st.final_requested end) + 0.005 then
      raise exception 'Cannot release more than the retention held (%)', st.held;
    end if;
    insert into public.retention_releases (id, project_id, stage, amount, requested_on, ref, created_by)
    values (v_id, v_project, v_stage, v_amt, coalesce(nullif(p ->> 'requested_on', '')::date, app.eat_date(now())), nullif(p ->> 'ref', ''), auth.uid());
    perform app.notify_roles_txt(v_project, '{finance,manager}', 'Retention release requested (' || replace(v_stage, '_', ' ') || ')',
      to_char(v_amt, 'FM999,999,999,990.00') || ' ETB', 'retention_release', v_id);
  else
    v_id := r.id;
    if (p ->> 'received_amount') is not null and not app.has_role_txt('finance', 'manager', 'admin') then
      raise exception 'Finance or the manager records money received' using errcode = '42501';
    end if;
    update public.retention_releases set certified_on = coalesce(nullif(p ->> 'certified_on', '')::date, certified_on),
      received_on = coalesce(nullif(p ->> 'received_on', '')::date, received_on),
      received_amount = received_amount + coalesce((p ->> 'received_amount')::numeric, 0), ref = coalesce(nullif(p ->> 'ref', ''), ref)
    where id = r.id;
    update public.retention_releases set status = case when received_amount >= amount - 0.005 then 'received'
                                                       when certified_on is not null then 'certified' else 'requested' end where id = r.id;
  end if;
  select * into r from public.retention_releases where id = v_id;
  return app.op_done(p, 'save_retention_release', jsonb_build_object('ok', true, 'id', r.id, 'status', r.status, 'amount', r.amount));
end $$;

notify pgrst, 'reload schema';


-- >>>>>>>>>>>>>>>>>>>> 20261105000042_office_inbox.sql

-- =============================================================================
-- Office inbox items (kind 'office' in v_my_approvals, entity_type tells them apart) for the registers of
-- 20261105000040 and the receivables of 20261105000041, plus a portfolio view across the caller's projects.
--
--   rfi              RFI overdue with the consultant → office engineer, coordinator ("chase")
--                    site instruction open → coordinator, site engineer ("act / comply")
--                    answered with a cost / time impact but no variation / EOT linked → coordinator, manager
--   submittal        response overdue → office engineer, coordinator; code C / D → the author (resubmit);
--                    approval needed within 14 days and not approved → coordinator
--   meeting_action   my open actions due within the reminder days (or overdue) → the owner (any role)
--   risk             my open risks whose review date has come → the owner
--   eot_claim        draft claim whose notice deadline is within 7 days (or passed) → coordinator, manager;
--                    detailed claim not sent N days after the notice → coordinator, manager
--   client_ipc_due   certified IPC unpaid after the payment days → coordinator, manager, finance (price roles)
--   retention_release  practical completion / end of DLP reached and nothing requested → coordinator, manager
-- Re-runnable.
-- =============================================================================

create or replace function app.office_approvals_for(p_user uuid)
returns table (kind text, entity_type text, entity_id uuid, project_id uuid, number text, title text, status text,
               requested_by uuid, requested_at timestamptz, is_urgent boolean, actions text[], age_hours numeric)
language plpgsql stable security definer set search_path = public as $$
declare v_role text; v_prices boolean; v_today date := app.eat_date(now());
begin
  select pr.role::text into v_role from public.profiles pr where pr.id = p_user and pr.is_active;
  if v_role is null then return; end if;
  v_prices := v_role = 'admin' or v_role = any (coalesce((select s.price_roles::text[] from public.app_settings s where s.id = 1), '{}'));
  return query
  with mem as (
    select pm.project_id as pid from public.project_members pm where pm.user_id = p_user
    union select pj.id from public.projects pj where v_role = 'admin'),
  st as (select m.pid, (app.ca_settings(m.pid)).* from mem m)
  -- RFIs overdue with the consultant
  select 'office'::text, 'rfi'::text, r.id, r.project_id, r.number,
         'Chase the answer to ' || r.number || ': ' || r.subject || ' (' || (v_today - r.due_date) || ' d overdue)',
         r.status, r.created_by, r.created_at, r.priority = 'urgent' or v_today - r.due_date > 7, array['open'],
         round((extract(epoch from now() - r.created_at) / 3600)::numeric, 1)
  from public.rfis r join mem on mem.pid = r.project_id
  where r.kind = 'rfi' and r.status = 'open' and r.ball_in_court <> 'contractor' and r.due_date < v_today
    and v_role in ('office_engineer','coordinator','admin')
  union all
  -- site instructions to act on
  select 'office', 'rfi', r.id, r.project_id, r.number,
         'Act on site instruction ' || r.number || ': ' || r.subject || coalesce(' (comply by ' || to_char(r.due_date, 'DD Mon') || ')', ''),
         r.status, r.created_by, r.created_at, r.priority = 'urgent' or r.due_date < v_today, array['open'],
         round((extract(epoch from now() - r.created_at) / 3600)::numeric, 1)
  from public.rfis r join mem on mem.pid = r.project_id
  where r.kind = 'si' and r.status = 'open' and v_role in ('coordinator','site_engineer','admin')
  union all
  -- answered with an impact, nothing raised yet
  select 'office', 'rfi', r.id, r.project_id, r.number,
         'Raise a variation / EOT for ' || r.number || ' (' ||
           concat_ws(', ', case when r.cost_impact <> 'none' then 'cost impact' end, case when r.time_impact <> 'none' then 'time impact' end) || ')',
         r.status, r.created_by, coalesce(r.answered_on::timestamptz, r.updated_at), false, array['open'],
         round((extract(epoch from now() - r.updated_at) / 3600)::numeric, 1)
  from public.rfis r join mem on mem.pid = r.project_id
  where r.status in ('answered','closed') and (r.cost_impact <> 'none' or r.time_impact <> 'none')
    and ((r.cost_impact = 'none' or r.variation_id is not null) and (r.time_impact = 'none' or r.eot_claim_id is not null)) is false
    and v_role in ('coordinator','manager','admin')
  union all
  -- submittals: response overdue
  select 'office', 'submittal', s.id, s.project_id, s.number,
         'Chase the review of ' || s.number || ' rev ' || s.current_rev || ': ' || s.title || ' (' || (v_today - sr.response_due) || ' d overdue)',
         s.status, s.created_by, sr.created_at, s.required_by is not null and s.required_by <= v_today + 7, array['open'],
         round((extract(epoch from now() - sr.created_at) / 3600)::numeric, 1)
  from public.submittals s join mem on mem.pid = s.project_id
  join public.submittal_revisions sr on sr.submittal_id = s.id and sr.rev = s.current_rev
  where s.status = 'submitted' and sr.response_due < v_today and v_role in ('office_engineer','coordinator','admin')
  union all
  -- submittals returned C / D
  select 'office', 'submittal', s.id, s.project_id, s.number,
         'Revise and resubmit ' || s.number || ': ' || s.title || ' (code ' || case s.status when 'rejected' then 'D' else 'C' end || ')',
         s.status, s.created_by, s.updated_at, s.required_by is not null and s.required_by <= v_today + 7, array['open'],
         round((extract(epoch from now() - s.updated_at) / 3600)::numeric, 1)
  from public.submittals s join mem on mem.pid = s.project_id
  where s.status in ('revise_resubmit','rejected') and (s.created_by = p_user or v_role in ('coordinator','admin'))
    and v_role in ('office_engineer','coordinator','manager','procurement','admin')
  union all
  -- approval needed soon (draft not yet sent)
  select 'office', 'submittal', s.id, s.project_id, s.number,
         'Approval needed by ' || to_char(s.required_by, 'DD Mon') || ' — ' || s.number || ' ' || s.title || ' is still a draft',
         s.status, s.created_by, s.created_at, s.required_by <= v_today, array['open'],
         round((extract(epoch from now() - s.created_at) / 3600)::numeric, 1)
  from public.submittals s join mem on mem.pid = s.project_id
  where s.status = 'draft' and s.required_by is not null and s.required_by <= v_today + 14 and v_role in ('office_engineer','coordinator','admin')
  union all
  -- my action items
  select 'office', 'meeting_action', a.id, a.project_id, coalesce(m.number, 'Action'),
         'Action: ' || left(a.description, 120) || coalesce(' (due ' || to_char(a.due_date, 'DD Mon') || ')', ''),
         a.status, a.created_by, a.created_at, a.due_date < v_today, array['done'],
         round((extract(epoch from now() - a.created_at) / 3600)::numeric, 1)
  from public.meeting_actions a join mem on mem.pid = a.project_id join st on st.pid = a.project_id
  left join public.meetings m on m.id = a.meeting_id
  where a.status = 'open' and a.owner_id = p_user and (m.id is null or m.status = 'issued')
    and (a.due_date is null or a.due_date <= v_today + st.reminder_days)
  union all
  -- my risks to review
  select 'office', 'risk', k.id, k.project_id, k.number,
         'Review ' || k.kind || ' ' || k.number || ': ' || k.title || ' (score ' || k.score || ')',
         k.status, k.created_by, k.updated_at, k.score >= 15, array['open'],
         round((extract(epoch from now() - k.updated_at) / 3600)::numeric, 1)
  from public.risks k join mem on mem.pid = k.project_id
  where k.status <> 'closed' and k.owner_id = p_user and k.review_by is not null and k.review_by <= v_today
  union all
  -- EOT notice deadline
  select 'office', 'eot_claim', e.id, e.project_id, e.number,
         'Send the delay notice for ' || e.number || ': ' || e.title || ' — deadline ' || to_char(e.event_from + st.claim_notice_days, 'DD Mon YYYY'),
         e.status, e.created_by, e.created_at, e.event_from + st.claim_notice_days <= v_today, array['open'],
         round((extract(epoch from now() - e.created_at) / 3600)::numeric, 1)
  from public.eot_claims e join mem on mem.pid = e.project_id join st on st.pid = e.project_id
  where e.status = 'draft' and e.event_from + st.claim_notice_days <= v_today + 7 and v_role in ('coordinator','manager','admin')
  union all
  -- EOT detailed claim due after the notice
  select 'office', 'eot_claim', e.id, e.project_id, e.number,
         'Submit the detailed claim ' || e.number || ' — due ' || to_char(e.notice_date + st.claim_particulars_days, 'DD Mon YYYY'),
         e.status, e.created_by, e.updated_at, e.notice_date + st.claim_particulars_days <= v_today, array['open'],
         round((extract(epoch from now() - e.updated_at) / 3600)::numeric, 1)
  from public.eot_claims e join mem on mem.pid = e.project_id join st on st.pid = e.project_id
  where e.status = 'notice_sent' and e.notice_date + st.claim_particulars_days <= v_today + 7 and v_role in ('coordinator','manager','admin')
  union all
  -- client payment overdue
  select 'office', 'client_ipc_due', i.id, i.project_id, 'IPC ' || i.ipc_no,
         'Client payment overdue: IPC ' || i.ipc_no || ' — ' || to_char(coalesce((i.certified ->> 'payable')::numeric, 0) - i.paid_amount, 'FM999,999,999,990') || ' ETB, '
           || (v_today - (i.certified_on + c.payment_days)) || ' d late',
         i.status, i.prepared_by, i.certified_on::timestamptz, v_today - (i.certified_on + c.payment_days) > 30, array['open'],
         round((extract(epoch from now() - i.certified_on::timestamptz) / 3600)::numeric, 1)
  from public.client_ipcs i join mem on mem.pid = i.project_id join public.client_contracts c on c.project_id = i.project_id
  where v_prices and v_role in ('coordinator','manager','finance','admin') and i.status = 'certified'
    and i.certified_on + c.payment_days < v_today and coalesce((i.certified ->> 'payable')::numeric, 0) - i.paid_amount > 0.005
  union all
  -- retention release due
  select 'office', 'retention_release', c.project_id, c.project_id, 'Retention',
         case when rs.pc_release_due then 'Request the retention release at practical completion (' || to_char(rs.pc_release_amount, 'FM999,999,999,990') || ' ETB)'
              else 'Request the final retention release — DLP ended ' || to_char(rs.dlp_end, 'DD Mon YYYY') || ' (' || to_char(rs.final_release_amount, 'FM999,999,999,990') || ' ETB)' end,
         'due', null::uuid, coalesce(rs.dlp_end, rs.practical_completion_on)::timestamptz, rs.final_release_due, array['open'], 0::numeric
  from public.client_contracts c join mem on mem.pid = c.project_id
  join lateral (select * from public.v_retention_status v where v.project_id = c.project_id) rs on true
  where v_prices and v_role in ('coordinator','manager','admin') and (rs.pc_release_due or rs.final_release_due);
end $$;
revoke execute on function app.office_approvals_for(uuid) from public;
insert into app.approval_sources (fn) values ('app.office_approvals_for') on conflict do nothing;

-- One row per project the caller belongs to: registers at a glance (progress / money come from v_progress_overview,
-- v_client_receivables on the page, so price rules stay with those views).
create or replace view public.v_office_portfolio with (security_invoker = true) as
select pj.id as project_id, pj.code, pj.name, pj.client, pj.start_date, pj.end_date, pj.is_active,
       cd.revised_completion, cd.days_granted, cd.days_pending,
       (select count(*) from public.rfis r where r.project_id = pj.id and r.kind = 'rfi' and r.status = 'open') as rfis_open,
       (select count(*) from public.rfis r where r.project_id = pj.id and r.kind = 'rfi' and r.status = 'open' and r.due_date < app.eat_date(now())) as rfis_overdue,
       (select count(*) from public.rfis r where r.project_id = pj.id and r.kind = 'si' and r.status = 'open') as sis_open,
       (select count(*) from public.submittals s where s.project_id = pj.id and s.status in ('draft','submitted','revise_resubmit','rejected')) as submittals_pending,
       (select count(*) from public.meeting_actions a where a.project_id = pj.id and a.status = 'open' and a.due_date < app.eat_date(now())) as actions_overdue,
       (select count(*) from public.risks k where k.project_id = pj.id and k.status <> 'closed' and k.score >= 15) as risks_high,
       (select count(*) from public.eot_claims e where e.project_id = pj.id and e.status in ('draft','notice_sent','submitted')) as claims_open
from public.projects pj left join public.v_completion_dates cd on cd.project_id = pj.id
where app.is_member(pj.id);
grant select on public.v_office_portfolio to authenticated;

notify pgrst, 'reload schema';


-- >>>>>>>>>>>>>>>>>>>> 20261105000050_store_inbox_dedupe.sql

-- =============================================================================
-- Store keeper inbox: one item per incoming order, not two.
-- When procurement announces a delivery (delivery notice, status 'notified') the store keeper already gets
-- "Confirm delivery of PO …" (app.approvals_for, kind delivery_ack). The PO-level "Receive PO …" item
-- (app.purchase_store_approvals_for, kind po_receive) showed up for the same order as well. It is now held
-- back while a notice is waiting for the store keeper's confirmation; once confirmed (or for orders
-- without a notice) "Receive …" is the single item. Re-runnable.
-- =============================================================================

create or replace function app.purchase_store_approvals_for(p_user uuid)
returns table (kind text, entity_type text, entity_id uuid, project_id uuid, number text, title text, status text,
               requested_by uuid, requested_at timestamptz, is_urgent boolean, actions text[], age_hours numeric)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare v_role text;
begin
  select pr.role::text into v_role from public.profiles pr where pr.id = p_user and pr.is_active;
  if v_role is null then return; end if;
  if v_role in ('procurement', 'admin') then
    return query
    select 'po_send'::text, 'purchase_order'::text, po.id, po.project_id, po.number,
           'Send ' || po.number || ' to ' || s.name, po.status::text, po.created_by, coalesce(po.approved_at, po.created_at),
           coalesce(coalesce(po.expected_date, po.eta) <= app.local_date(now()) + 3, false), array['open'],
           round((extract(epoch from now() - coalesce(po.approved_at, po.created_at)) / 3600)::numeric, 1)
    from public.purchase_orders po join public.suppliers s on s.id = po.supplier_id
    where po.status = 'approved' and po.sent_at is null
      and po.project_id in (select pm.project_id from public.project_members pm where pm.user_id = p_user
                            union select pj.id from public.projects pj where v_role = 'admin');
  end if;
  if v_role in ('store_keeper', 'admin') then
    return query
    select 'po_receive'::text, 'purchase_order'::text, po.id, po.project_id, po.number,
           'Receive ' || po.number || ' from ' || s.name, po.status::text, po.created_by,
           coalesce(po.eta, po.expected_date)::timestamptz,
           coalesce(coalesce(po.eta, po.expected_date) < app.local_date(now()), false), array['open'],
           round((extract(epoch from now() - coalesce(po.eta, po.expected_date)::timestamptz) / 3600)::numeric, 1)
    from public.purchase_orders po join public.suppliers s on s.id = po.supplier_id
    where po.status in ('sent', 'partially_received')
      and coalesce(po.eta, po.expected_date, app.local_date(now())) <= app.local_date(now()) + 2
      and exists (select 1 from public.po_lines pl where pl.po_id = po.id and pl.deleted_at is null and not pl.closed
                    and pl.qty - pl.qty_accepted > 0.0005)
      and not exists (select 1 from public.delivery_notices dn where dn.po_id = po.id and dn.status = 'notified')
      and po.project_id in (select pm.project_id from public.project_members pm where pm.user_id = p_user
                            union select pj.id from public.projects pj where v_role = 'admin');
  end if;
end $$;
revoke execute on function app.purchase_store_approvals_for(uuid) from public;
insert into app.approval_sources (fn) values ('app.purchase_store_approvals_for') on conflict do nothing;


-- >>>>>>>>>>>>>>>>>>>> 20261105000051_tools_register.sql

-- =============================================================================
-- Tools & small equipment register (store keeper): returnable items tracked separately from consumables.
--   tool_items      one row per tagged tool (drill, vibrator, level, safety harness …) with its current state
--   tool_movements  history: issue → return (condition checked) / repair / lost / found / dispose
-- Store practice: a sign-out / sign-in register for hand tools, power tools and minor equipment, the store keeper
-- inspects returned tools before restocking; losses are reported to the site / project manager.
-- Writes go through public.save_tool / public.tool_action; overdue returns appear in the store keeper's inbox.
-- Re-runnable.
-- =============================================================================

create table if not exists public.tool_items (
  id           uuid primary key,
  project_id   uuid not null references public.projects (id),
  store_id     uuid references public.stores (id),
  tag          text not null,
  name         text not null,
  category     text not null default 'hand_tool'
                 check (category in ('hand_tool','power_tool','measuring','equipment','safety','formwork','other')),
  serial_no    text,
  status       text not null default 'in_store' check (status in ('in_store','issued','repair','lost','disposed')),
  condition    text not null default 'good' check (condition in ('good','fair','damaged')),
  holder_id    uuid references public.profiles (id),
  holder_name  text,
  issued_at    timestamptz,
  due_on       date,
  notes        text,
  created_by   uuid not null references public.profiles (id),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  deleted_at   timestamptz,
  unique (project_id, tag)
);

create table if not exists public.tool_movements (
  id           uuid primary key default gen_random_uuid(),
  tool_id      uuid not null references public.tool_items (id) on delete cascade,
  project_id   uuid not null references public.projects (id),
  action       text not null check (action in ('issue','return','repair','repaired','lost','found','dispose')),
  holder_id    uuid references public.profiles (id),
  holder_name  text,
  due_on       date,
  condition    text check (condition in ('good','fair','damaged')),
  note         text,
  created_by   uuid not null references public.profiles (id),
  created_at   timestamptz not null default now()
);
create index if not exists tool_movements_tool_idx on public.tool_movements (tool_id, created_at);
create index if not exists tool_items_project_idx on public.tool_items (project_id, status);

do $$
declare t text;
begin
  foreach t in array array['tool_items','tool_movements'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists member_read on public.%I', t);
    execute format('create policy member_read on public.%I for select to authenticated using (app.is_member(project_id))', t);
  end loop;
  drop trigger if exists touch_updated_at on public.tool_items;
  create trigger touch_updated_at before update on public.tool_items for each row execute function app.touch_updated_at();
  drop trigger if exists audit on public.tool_items;
  create trigger audit after insert or update or delete on public.tool_items for each row execute function app.audit();
end $$;

create or replace view public.v_tools with (security_invoker = true) as
select t.*, st.name as store_name,
       coalesce(pr.full_name, t.holder_name) as holder,
       (t.status = 'issued' and t.due_on is not null and t.due_on < app.local_date(now())) as is_overdue,
       case when t.status = 'issued' and t.due_on is not null then app.local_date(now()) - t.due_on end as days_overdue
from public.tool_items t
left join public.stores st on st.id = t.store_id
left join public.profiles pr on pr.id = t.holder_id
where t.deleted_at is null;
grant select on public.v_tools to authenticated;

-- {id, project_id, tag?, name, category?, store_id?, serial_no?, condition?, notes?}
create or replace function public.save_tool(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); v_id uuid := coalesce((p ->> 'id')::uuid, gen_random_uuid());
  v_project uuid := (p ->> 'project_id')::uuid; t public.tool_items; v_tag text := nullif(upper(trim(p ->> 'tag')), '');
begin
  if v_seen is not null then return v_seen; end if;
  perform app.require_member(v_project);
  perform app.require_role_txt('store_keeper', 'coordinator', 'manager', 'admin');
  if nullif(trim(p ->> 'name'), '') is null then raise exception 'Enter the tool name'; end if;
  if (p ->> 'store_id') is not null and not exists (select 1 from public.stores where id = (p ->> 'store_id')::uuid and project_id = v_project) then
    raise exception 'Store is not in this project';
  end if;
  select * into t from public.tool_items where id = v_id for update;
  if found then
    if t.project_id <> v_project then raise exception 'Tool belongs to another project'; end if;
    update public.tool_items set tag = coalesce(v_tag, tag), name = trim(p ->> 'name'), category = coalesce(nullif(p ->> 'category', ''), category),
      store_id = coalesce((p ->> 'store_id')::uuid, store_id), serial_no = nullif(trim(p ->> 'serial_no'), ''),
      condition = coalesce(nullif(p ->> 'condition', ''), condition), notes = nullif(trim(p ->> 'notes'), '')
    where id = v_id;
  else
    v_tag := coalesce(v_tag, 'T-' || lpad(((select count(*) from public.tool_items where project_id = v_project) + 1)::text, 4, '0'));
    if exists (select 1 from public.tool_items where project_id = v_project and tag = v_tag) then
      raise exception 'Tag % is already used in this project', v_tag;
    end if;
    insert into public.tool_items (id, project_id, store_id, tag, name, category, serial_no, condition, notes, created_by)
    values (v_id, v_project, (p ->> 'store_id')::uuid, v_tag, trim(p ->> 'name'), coalesce(nullif(p ->> 'category', ''), 'hand_tool'),
      nullif(trim(p ->> 'serial_no'), ''), coalesce(nullif(p ->> 'condition', ''), 'good'), nullif(trim(p ->> 'notes'), ''), auth.uid());
  end if;
  return app.op_done(p, 'save_tool', jsonb_build_object('ok', true, 'id', v_id, 'tag', (select tag from public.tool_items where id = v_id)));
end $$;

-- {tool_id, action: issue|return|repair|repaired|lost|found|dispose, holder_id?, holder_name?, due_on?, condition?, note?}
create or replace function public.tool_action(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); t public.tool_items; a text := p ->> 'action'; v_note text := nullif(trim(p ->> 'note'), '');
  v_cond text := nullif(p ->> 'condition', ''); v_holder uuid := (p ->> 'holder_id')::uuid; v_hname text := nullif(trim(p ->> 'holder_name'), '');
  v_to text; v_due date := nullif(p ->> 'due_on', '')::date;
begin
  if v_seen is not null then return v_seen; end if;
  select * into t from public.tool_items where id = (p ->> 'tool_id')::uuid and deleted_at is null for update;
  if not found then raise exception 'Tool not found'; end if;
  perform app.require_member(t.project_id);
  if a = 'dispose' then perform app.require_role_txt('coordinator', 'manager', 'admin');
  else perform app.require_role_txt('store_keeper', 'coordinator', 'manager', 'admin'); end if;
  if v_cond is not null and v_cond not in ('good','fair','damaged') then raise exception 'Unknown condition %', v_cond; end if;

  if a = 'issue' then
    if t.status <> 'in_store' then
      raise exception '% is % — only a tool in the store can be issued', t.tag,
        case t.status when 'repair' then 'under repair' else t.status end;
    end if;
    if t.condition = 'damaged' then raise exception '% is damaged — send it for repair first', t.tag; end if;
    if v_holder is null and v_hname is null then raise exception 'Who receives the tool?'; end if;
    if v_holder is not null and not exists (select 1 from public.project_members where project_id = t.project_id and user_id = v_holder) then
      raise exception 'The receiver is not a member of this project';
    end if;
    if v_due is not null and v_due < app.local_date(now()) then raise exception 'The return date cannot be in the past'; end if;
    update public.tool_items set status = 'issued', holder_id = v_holder, holder_name = v_hname, issued_at = now(), due_on = v_due where id = t.id;
  elsif a = 'return' then
    if t.status <> 'issued' then raise exception '% is not issued', t.tag; end if;
    if v_cond is null then raise exception 'Record the condition of the returned tool'; end if;
    if v_cond = 'damaged' and v_note is null then raise exception 'Describe the damage'; end if;
    v_to := case when v_cond = 'damaged' then 'repair' else 'in_store' end;
    update public.tool_items set status = v_to, condition = v_cond, holder_id = null, holder_name = null, issued_at = null, due_on = null where id = t.id;
    if v_cond = 'damaged' then
      perform app.notify_roles_txt(t.project_id, '{coordinator}', 'Tool returned damaged: ' || t.tag || ' ' || t.name,
        concat_ws(' · ', 'Returned by ' || coalesce((select full_name from public.profiles where id = t.holder_id), t.holder_name), v_note), 'tool', t.id);
    end if;
  elsif a = 'repair' then
    if t.status <> 'in_store' then raise exception 'Only a tool in the store can be sent for repair'; end if;
    update public.tool_items set status = 'repair', condition = 'damaged' where id = t.id;
  elsif a = 'repaired' then
    if t.status <> 'repair' then raise exception '% is not under repair', t.tag; end if;
    update public.tool_items set status = 'in_store', condition = coalesce(v_cond, 'good') where id = t.id;
  elsif a = 'lost' then
    if t.status not in ('issued','in_store') then raise exception 'Only an issued or stored tool can be reported lost'; end if;
    if v_note is null then raise exception 'Say how the tool was lost'; end if;
    update public.tool_items set status = 'lost' where id = t.id;
    perform app.notify_roles_txt(t.project_id, '{coordinator,manager}', 'Tool lost: ' || t.tag || ' ' || t.name,
      concat_ws(' · ', 'Last with ' || coalesce((select full_name from public.profiles where id = t.holder_id), t.holder_name), v_note), 'tool', t.id, true);
  elsif a = 'found' then
    if t.status <> 'lost' then raise exception '% is not lost', t.tag; end if;
    update public.tool_items set status = 'in_store', condition = coalesce(v_cond, condition), holder_id = null, holder_name = null, issued_at = null, due_on = null where id = t.id;
  elsif a = 'dispose' then
    if t.status not in ('in_store','repair','lost') then raise exception 'Return the tool before disposing of it'; end if;
    if v_note is null then raise exception 'Give the reason for disposal'; end if;
    update public.tool_items set status = 'disposed' where id = t.id;
  else
    raise exception 'Unknown action %', a;
  end if;

  insert into public.tool_movements (tool_id, project_id, action, holder_id, holder_name, due_on, condition, note, created_by)
  values (t.id, t.project_id, a,
    case when a in ('return','lost') then t.holder_id else v_holder end,
    case when a in ('return','lost') then t.holder_name else v_hname end,
    case when a = 'issue' then v_due end, v_cond, v_note, auth.uid());
  return app.op_done(p, 'tool_action', jsonb_build_object('ok', true, 'id', t.id, 'tag', t.tag,
    'status', (select status from public.tool_items where id = t.id)));
end $$;

-- Inbox: tools not returned by their due date (store keeper chases them).
create or replace function app.tools_approvals_for(p_user uuid)
returns table (kind text, entity_type text, entity_id uuid, project_id uuid, number text, title text, status text,
               requested_by uuid, requested_at timestamptz, is_urgent boolean, actions text[], age_hours numeric)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare v_role text;
begin
  select pr.role::text into v_role from public.profiles pr where pr.id = p_user and pr.is_active;
  if v_role is null or v_role not in ('store_keeper', 'admin') then return; end if;
  return query
  select 'tool_overdue'::text, 'tool'::text, t.id, t.project_id, t.tag,
         'Get back ' || t.tag || ' ' || t.name || ' from ' || coalesce(pr.full_name, t.holder_name, '?')
           || ' (due ' || to_char(t.due_on, 'DD Mon') || ')',
         t.status, t.created_by, t.due_on::timestamptz, app.local_date(now()) - t.due_on > 3, array['open'],
         round((extract(epoch from now() - t.due_on::timestamptz) / 3600)::numeric, 1)
  from public.tool_items t left join public.profiles pr on pr.id = t.holder_id
  where t.deleted_at is null and t.status = 'issued' and t.due_on < app.local_date(now())
    and t.project_id in (select pm.project_id from public.project_members pm where pm.user_id = p_user
                         union select pj.id from public.projects pj where v_role = 'admin');
end $$;
revoke execute on function app.tools_approvals_for(uuid) from public;
insert into app.approval_sources (fn) values ('app.tools_approvals_for') on conflict do nothing;


-- >>>>>>>>>>>>>>>>>>>> 20261105000052_supplier_performance.sql

-- =============================================================================
-- Supplier performance scorecard (procurement): quality, delivery dependability and price, the three criteria
-- construction buyers weigh most, combined as a weighted score (quality 50 %, on-time delivery 35 %, price 15 %;
-- without price access the score uses quality and delivery only, re-weighted).
--   quality   = accepted ÷ delivered quantity on goods receipts against purchase orders
--   on time   = receipts on or before the promised date of the order (expected date, else ETA)
--   price     = supplier's ordered / quoted unit prices vs the company 90-day average for the same spec
--   service   = 1–5 rating the store keeper / buyer gives per order (paperwork, responsiveness, packaging …)
-- Grade A ≥ 90, B ≥ 80, C ≥ 70, D below. Views are security-invoker: users only count what they can see.
-- Re-runnable.
-- =============================================================================

create table if not exists public.supplier_ratings (
  id           uuid primary key default gen_random_uuid(),
  project_id   uuid not null references public.projects (id),
  supplier_id  uuid not null references public.suppliers (id),
  po_id        uuid not null references public.purchase_orders (id),
  score        int not null check (score between 1 and 5),
  comment      text,
  created_by   uuid not null references public.profiles (id),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  unique (po_id, created_by)
);
alter table public.supplier_ratings enable row level security;
drop policy if exists member_read on public.supplier_ratings;
create policy member_read on public.supplier_ratings for select to authenticated using (app.is_member(project_id));
drop trigger if exists touch_updated_at on public.supplier_ratings;
create trigger touch_updated_at before update on public.supplier_ratings for each row execute function app.touch_updated_at();

-- {po_id, score 1–5, comment?} — one rating per order and person (re-rating replaces it).
create or replace function public.rate_supplier(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_seen jsonb := app.op_seen(p); po public.purchase_orders; v_score int := (p ->> 'score')::int;
begin
  if v_seen is not null then return v_seen; end if;
  select * into po from public.purchase_orders where id = (p ->> 'po_id')::uuid;
  if not found then raise exception 'Purchase order not found'; end if;
  perform app.require_member(po.project_id);
  perform app.require_role_txt('store_keeper', 'procurement', 'coordinator', 'manager', 'admin');
  if v_score is null or v_score not between 1 and 5 then raise exception 'Give a score from 1 to 5'; end if;
  if po.status not in ('sent','partially_received','received','closed') then
    raise exception 'Rate the supplier once % has been sent', po.number;
  end if;
  if v_score <= 2 and nullif(trim(p ->> 'comment'), '') is null then raise exception 'Say what went wrong'; end if;
  insert into public.supplier_ratings (project_id, supplier_id, po_id, score, comment, created_by)
  values (po.project_id, po.supplier_id, po.id, v_score, nullif(trim(p ->> 'comment'), ''), auth.uid())
  on conflict (po_id, created_by) do update set score = excluded.score, comment = excluded.comment;
  return app.op_done(p, 'rate_supplier', jsonb_build_object('ok', true, 'po_id', po.id, 'score', v_score));
end $$;

-- One row per receipt against an order: promised date, received date, quantities.
create or replace view public.v_supplier_deliveries with (security_invoker = true) as
select g.id as grn_id, g.number as grn_number, g.project_id, po.id as po_id, po.number as po_number, po.supplier_id,
       coalesce(po.expected_date, po.eta) as promised_on, app.local_date(g.received_at) as received_on,
       case when coalesce(po.expected_date, po.eta) is null then null
            else app.local_date(g.received_at) - coalesce(po.expected_date, po.eta) end as days_late,
       coalesce(sum(l.qty_delivered), 0) as qty_delivered, coalesce(sum(l.qty_accepted), 0) as qty_accepted,
       coalesce(sum(l.qty_rejected), 0) as qty_rejected,
       count(*) filter (where l.inspection_result = 'reject' or l.qty_rejected > 0) as rejected_lines
from public.grns g
join public.purchase_orders po on po.id = g.po_id
left join public.grn_lines l on l.grn_id = g.id
where g.status = 'posted'
group by g.id, g.number, g.project_id, po.id, po.number, po.supplier_id, po.expected_date, po.eta, g.received_at;
grant select on public.v_supplier_deliveries to authenticated;

create or replace view public.v_supplier_performance with (security_invoker = true) as
with d as (
  select supplier_id, count(*) as deliveries,
         count(*) filter (where days_late is not null and days_late <= 0) as on_time,
         count(*) filter (where days_late is not null) as dated,
         round(avg(greatest(days_late, 0)) filter (where days_late is not null), 1) as avg_days_late,
         sum(qty_delivered) as qty_delivered, sum(qty_accepted) as qty_accepted, sum(rejected_lines) as rejected_lines,
         max(received_on) as last_delivery
  from public.v_supplier_deliveries group by supplier_id),
o as (
  select supplier_id, count(*) as orders,
         count(*) filter (where status in ('sent','partially_received') and coalesce(expected_date, eta) < app.local_date(now())) as overdue_orders
  from public.purchase_orders where status not in ('draft','submitted','rejected','cancelled') group by supplier_id),
p as (
  select supplier_id, round(avg(unit_price / avg_90d), 3) as price_index
  from public.price_observations
  where supplier_id is not null and avg_90d > 0 and source in ('po','quotation') and app.can_see_prices()
  group by supplier_id),
r as (select supplier_id, round(avg(score), 1) as service_rating, count(*) as ratings from public.supplier_ratings group by supplier_id),
s as (
  select su.id as supplier_id, su.name, su.phone, su.categories,
         coalesce(o.orders, 0) as orders, coalesce(o.overdue_orders, 0) as overdue_orders,
         coalesce(d.deliveries, 0) as deliveries, d.on_time, d.dated, d.avg_days_late, d.rejected_lines, d.last_delivery,
         case when d.dated > 0 then round(d.on_time * 100.0 / d.dated, 1) end as on_time_pct,
         case when d.qty_delivered > 0 then round(d.qty_accepted * 100.0 / d.qty_delivered, 1) end as quality_pct,
         p.price_index,
         case when p.price_index is not null then greatest(0, least(100, round(100 - (p.price_index - 1) * 200, 1))) end as price_score,
         r.service_rating, coalesce(r.ratings, 0) as ratings
  from public.suppliers su
  left join d on d.supplier_id = su.id left join o on o.supplier_id = su.id
  left join p on p.supplier_id = su.id left join r on r.supplier_id = su.id
  where su.deleted_at is null and (o.orders is not null or d.deliveries is not null))
select s.*, x.score,
       case when x.score is null then null when x.score >= 90 then 'A' when x.score >= 80 then 'B' when x.score >= 70 then 'C' else 'D' end as grade
from s cross join lateral (
  select case
    when s.quality_pct is null and s.on_time_pct is null then null
    when s.price_score is not null then round((coalesce(s.quality_pct, s.on_time_pct) * 50 + coalesce(s.on_time_pct, s.quality_pct) * 35 + s.price_score * 15) / 100, 1)
    else round((coalesce(s.quality_pct, s.on_time_pct) * 50 + coalesce(s.on_time_pct, s.quality_pct) * 35) / 85, 1) end as score) x;
grant select on public.v_supplier_performance to authenticated;


-- >>>>>>>>>>>>>>>>>>>> 20261105000053_stock_ageing.sql

-- =============================================================================
-- Shelf life & stock ageing (store keeper): cement and site chemicals lose strength / expire in storage.
-- Site practice: first-in-first-out, label stacks with arrival dates, unsealed cement within ~3 months,
-- older or damp-stored cement re-tested before structural use.
--   material_specs.shelf_life_days   null = does not expire. Cement specs default to 90 days (only where unset).
--   lot_expiry                       optional date printed on the pack (admixtures, sealants, paints …) per receipt
--                                    line (receipt lines themselves are immutable, BR-07)
--   v_stock_lots                     what is on the shelf now, lot by lot, by consuming the oldest receipts first
--                                    (FIFO), with age, expiry date and status expired / expiring (≤ 14 days) / ok
--   set_lot_expiry                   store keeper records / corrects the expiry date of a received lot
-- Expired and expiring lots appear in the store keeper's inbox (use first or have them re-tested). Re-runnable.
-- =============================================================================

alter table public.material_specs add column if not exists shelf_life_days int check (shelf_life_days is null or shelf_life_days > 0);
create table if not exists public.lot_expiry (
  grn_line_id  uuid primary key references public.grn_lines (id),
  project_id   uuid not null references public.projects (id),
  expiry_date  date not null,
  set_by       uuid not null references public.profiles (id),
  updated_at   timestamptz not null default now()
);
alter table public.lot_expiry enable row level security;
drop policy if exists member_read on public.lot_expiry;
create policy member_read on public.lot_expiry for select to authenticated using (app.is_member(project_id));

update public.material_specs s set shelf_life_days = 90
  from public.materials m
 where m.id = s.material_id and s.shelf_life_days is null and m.category ilike '%cement%' and m.name !~* 'pipe|board|sheet';

create index if not exists stock_ledger_reversal_idx on public.stock_ledger (reversal_of) where reversal_of is not null;

create or replace view public.v_stock_lots with (security_invoker = true) as
with active as (
  select l.* from public.stock_ledger l
  where l.reversal_of is null
    and not exists (select 1 from public.stock_ledger r where r.reversal_of = l.id)),
inbound as (
  select l.id as ledger_id, l.project_id, l.store_id, l.material_spec_id, l.qty, l.txn_at, l.txn_type, l.doc_number, l.batch_no, l.doc_line_id,
         sum(l.qty) over (partition by l.project_id, l.store_id, l.material_spec_id order by l.txn_at, l.created_at, l.id) as cum_in
  from active l
  where l.stock_status = 'available' and l.qty > 0),
outbound as (
  select l.project_id, l.store_id, l.material_spec_id, -sum(l.qty) as qty_out
  from active l where l.stock_status = 'available' and l.qty < 0
  group by l.project_id, l.store_id, l.material_spec_id),
lots as (
  select i.*, least(i.qty, greatest(i.cum_in - coalesce(o.qty_out, 0), 0)) as remaining_qty
  from inbound i left join outbound o on o.project_id = i.project_id and o.store_id = i.store_id and o.material_spec_id = i.material_spec_id)
select x.ledger_id, x.project_id, x.store_id, st.name as store_name, x.material_spec_id, sp.label, sp.category, sp.uom,
       x.txn_type, x.doc_number, x.batch_no, case when x.txn_type = 'grn' then x.doc_line_id end as grn_line_id,
       app.local_date(x.txn_at) as received_on, x.remaining_qty,
       app.local_date(now()) - app.local_date(x.txn_at) as age_days,
       ms.shelf_life_days, e.expiry_date,
       e.expiry_date - app.local_date(now()) as days_to_expiry,
       case when e.expiry_date is null then 'no_expiry'
            when e.expiry_date < app.local_date(now()) then 'expired'
            when e.expiry_date <= app.local_date(now()) + 14 then 'expiring'
            else 'ok' end as expiry_status
from lots x
join public.stores st on st.id = x.store_id
join public.v_specs sp on sp.id = x.material_spec_id
join public.material_specs ms on ms.id = x.material_spec_id
left join public.lot_expiry le on x.txn_type = 'grn' and le.grn_line_id = x.doc_line_id
cross join lateral (select coalesce(le.expiry_date,
  case when ms.shelf_life_days is not null then app.local_date(x.txn_at) + ms.shelf_life_days end) as expiry_date) e
where x.remaining_qty > 0.0005;
grant select on public.v_stock_lots to authenticated;

-- {grn_line_id, expiry_date|null}
create or replace function public.set_lot_expiry(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_seen jsonb := app.op_seen(p); gl public.grn_lines; v_date date := nullif(p ->> 'expiry_date', '')::date;
begin
  if v_seen is not null then return v_seen; end if;
  select * into gl from public.grn_lines where id = (p ->> 'grn_line_id')::uuid;
  if not found then raise exception 'Receipt line not found'; end if;
  perform app.require_member(gl.project_id);
  perform app.require_role_txt('store_keeper', 'coordinator', 'manager', 'admin');
  if v_date is not null and v_date < (select app.local_date(received_at) from public.grns where id = gl.grn_id) - 3650 then
    raise exception 'Check the expiry date';
  end if;
  if v_date is null then
    delete from public.lot_expiry where grn_line_id = gl.id;
  else
    insert into public.lot_expiry (grn_line_id, project_id, expiry_date, set_by) values (gl.id, gl.project_id, v_date, auth.uid())
    on conflict (grn_line_id) do update set expiry_date = excluded.expiry_date, set_by = excluded.set_by, updated_at = now();
  end if;
  return app.op_done(p, 'set_lot_expiry', jsonb_build_object('ok', true, 'grn_line_id', gl.id, 'expiry_date', v_date));
end $$;

-- Inbox: one item per store + material with expired or soon-expiring stock.
create or replace function app.stock_expiry_approvals_for(p_user uuid)
returns table (kind text, entity_type text, entity_id uuid, project_id uuid, number text, title text, status text,
               requested_by uuid, requested_at timestamptz, is_urgent boolean, actions text[], age_hours numeric)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare v_role text; v_pid uuid;
begin
  select pr.role::text into v_role from public.profiles pr where pr.id = p_user and pr.is_active;
  if v_role is null or v_role not in ('store_keeper', 'admin') then return; end if;
  -- per project so the project filter reaches the FIFO window (an IN-subquery would not)
  for v_pid in select pm.project_id from public.project_members pm where pm.user_id = p_user
               union select pj.id from public.projects pj where v_role = 'admin' loop
  return query
  with bad as (
    select l.project_id, l.store_id, l.store_name, l.material_spec_id, l.label, l.uom,
           sum(l.remaining_qty) as qty, min(l.expiry_date) as first_expiry, bool_or(l.expiry_status = 'expired') as any_expired
    from public.v_stock_lots l
    where l.project_id = v_pid and l.expiry_status in ('expired','expiring')
    group by l.project_id, l.store_id, l.store_name, l.material_spec_id, l.label, l.uom)
  select 'stock_expiry'::text, 'material_spec'::text, b.material_spec_id, b.project_id, b.store_name,
         case when b.any_expired then 'Expired: ' else 'Use first: ' end || b.label || ' — '
           || trim(to_char(b.qty, 'FM999G999G990D###')) || ' ' || b.uom || ' in ' || b.store_name
           || case when b.any_expired then ' (re-test or write off)' else ' expires ' || to_char(b.first_expiry, 'DD Mon') end,
         case when b.any_expired then 'expired' else 'expiring' end, null::uuid, b.first_expiry::timestamptz, b.any_expired,
         array['open'], round((extract(epoch from now() - b.first_expiry::timestamptz) / 3600)::numeric, 1)
  from bad b;
  end loop;
end $$;
revoke execute on function app.stock_expiry_approvals_for(uuid) from public;
insert into app.approval_sources (fn) values ('app.stock_expiry_approvals_for') on conflict do nothing;


-- >>>>>>>>>>>>>>>>>>>> 20261105000060_finance.sql

-- =============================================================================
-- FINANCE & ADMIN
--   A. Supplier invoices with a 3-way match (PO price · goods accepted on GRN · invoiced quantity). Duplicate
--      supplier invoice numbers are refused. Chain: procurement / finance / office engineer records → coordinator
--      checks → manager approves (a variance needs a written override) → finance pays. Invoices are PAYABLES only:
--      material cost is recognised when the material is used (20261103000020), so no cost entry is posted here.
--   B. Petty cash (imprest): a float per custodian; expenses are recorded against the balance and replenished by a
--      claim that goes custodian → coordinator → manager → finance. Approval posts the actual cost.
--   C. Cash-flow forecast (13 weeks): client receipts vs supplier, subcontractor, labour, petty-cash and committed
--      purchase-order payments, plus a finance overview (receivable ageing, retention receivable / payable).
--   D. Monthly tax report: withholding to remit, payroll tax, VAT output / input, withholding suffered.
--   E. Admin: pending inbox of another user (handover before deactivation).
-- Tax rates and thresholds come only from effective-dated tax_settings. Current reference sources:
-- Income Tax (Amendment) Proclamation 1395/2025 (EY tax alert 2025-2542, withholding effective 7 Aug 2025),
-- VAT Proclamation 1341/2024 (EY tax alert, 16 Sep 2024), and PwC Ethiopia Tax Summaries (VAT / WHT).
-- No-TIN withholding here is a configured calculation, not proof of the supplier's TIN and business-licence status.
-- Exports are internal working papers: confirm tax periods, deadlines and input-VAT eligibility with the MoR.
-- Re-runnable.
-- =============================================================================

alter table public.suppliers add column if not exists tin text;
alter table public.client_contracts add column if not exists payment_days int not null default 30;
alter table public.tax_settings add column if not exists bank_payment_threshold numeric(18,2) not null default 50000
  check (bank_payment_threshold >= 0);

alter table public.payment_events drop constraint if exists payment_events_doc_type_check;
alter table public.payment_events add constraint payment_events_doc_type_check
  check (doc_type in ('sc_certificate','payroll','supplier_invoice','petty_cash'));

-- ---------------------------------------------------------------------------
-- A. Supplier invoices
-- ---------------------------------------------------------------------------
create table if not exists public.supplier_invoices (
  id                uuid primary key,
  project_id        uuid not null references public.projects (id),
  number            text not null unique,
  supplier_id       uuid not null references public.suppliers (id),
  po_id             uuid not null references public.purchase_orders (id),
  invoice_no        text not null,
  invoice_date      date not null,
  due_date          date not null,
  status            text not null default 'draft'
                      check (status in ('draft','submitted','checked','approved','paid','returned','rejected')),
  subtotal          numeric(18,2) not null default 0,
  vat               numeric(18,2) not null default 0,
  total             numeric(18,2) not null default 0,
  withholding_rate  numeric(5,2) not null default 0,
  withholding       numeric(18,2) not null default 0,
  net_payable       numeric(18,2) not null default 0,
  match_status      text not null default 'matched' check (match_status in ('matched','variance')),
  match_notes       text[] not null default '{}',
  override_comment  text,
  remarks           text,
  return_comment    text,
  prepared_by       uuid references public.profiles (id),
  submitted_at      timestamptz,
  checked_by        uuid references public.profiles (id),
  checked_at        timestamptz,
  approved_by       uuid references public.profiles (id),
  approved_at       timestamptz,
  paid_by           uuid references public.profiles (id),
  paid_at           timestamptz,
  payment_method    text check (payment_method in ('bank_transfer','cheque','cash')),
  payment_ref       text,
  payment_date      date,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create unique index if not exists supplier_invoices_dup on public.supplier_invoices (supplier_id, lower(invoice_no)) where status <> 'rejected';
create index if not exists supplier_invoices_project_idx on public.supplier_invoices (project_id, status);
create index if not exists supplier_invoices_po_idx on public.supplier_invoices (po_id);

create table if not exists public.supplier_invoice_lines (
  id                 uuid primary key default gen_random_uuid(),
  invoice_id         uuid not null references public.supplier_invoices (id) on delete cascade,
  project_id         uuid not null references public.projects (id),
  po_line_id         uuid not null references public.po_lines (id),
  line_no            int not null,
  description        text,
  qty                numeric(16,3) not null check (qty > 0),
  unit_price         numeric(18,2) not null check (unit_price >= 0),
  amount             numeric(18,2) generated always as (round(qty * unit_price, 2)) stored,
  vat_applicable     boolean not null default true,
  po_unit_price      numeric(18,2),
  qty_ordered        numeric(16,3),
  qty_accepted       numeric(16,3),
  qty_invoiced_before numeric(16,3),
  flag               text check (flag in ('price','qty','price_qty')),
  unique (invoice_id, po_line_id)
);
create index if not exists supplier_invoice_lines_inv_idx on public.supplier_invoice_lines (invoice_id);
create index if not exists supplier_invoice_lines_po_line_idx on public.supplier_invoice_lines (po_line_id);

-- ---------------------------------------------------------------------------
-- B. Petty cash
-- ---------------------------------------------------------------------------
create table if not exists public.petty_cash_floats (
  id            uuid primary key,
  project_id    uuid not null references public.projects (id),
  name          text not null,
  custodian_id  uuid not null references public.profiles (id),
  float_amount  numeric(18,2) not null check (float_amount > 0),
  is_active     boolean not null default true,
  created_by    uuid references public.profiles (id) default auth.uid(),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create unique index if not exists petty_cash_floats_one on public.petty_cash_floats (project_id, custodian_id) where is_active;

create table if not exists public.petty_cash_claims (
  id              uuid primary key,
  project_id      uuid not null references public.projects (id),
  float_id        uuid not null references public.petty_cash_floats (id),
  number          text not null unique,
  status          text not null default 'submitted'
                    check (status in ('submitted','checked','approved','paid','returned','rejected')),
  total           numeric(18,2) not null default 0,
  entries         int not null default 0,
  remarks         text,
  return_comment  text,
  prepared_by     uuid references public.profiles (id),
  submitted_at    timestamptz,
  checked_by      uuid references public.profiles (id),
  checked_at      timestamptz,
  approved_by     uuid references public.profiles (id),
  approved_at     timestamptz,
  paid_by         uuid references public.profiles (id),
  paid_at         timestamptz,
  payment_method  text check (payment_method in ('bank_transfer','cheque','cash')),
  payment_ref     text,
  payment_date    date,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

create table if not exists public.petty_cash_entries (
  id           uuid primary key,
  project_id   uuid not null references public.projects (id),
  float_id     uuid not null references public.petty_cash_floats (id),
  number       text not null unique,
  entry_date   date not null,
  category     text not null check (category in ('transport','fuel','food','materials','repairs','office','labour','other')),
  description  text not null,
  payee        text,
  receipt_no   text,
  amount       numeric(18,2) not null check (amount > 0),
  claim_id     uuid references public.petty_cash_claims (id),
  voided       boolean not null default false,
  recorded_by  uuid references public.profiles (id) default auth.uid(),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index if not exists petty_cash_entries_float_idx on public.petty_cash_entries (float_id, claim_id);

do $$
declare t text;
begin
  foreach t in array array['supplier_invoices','supplier_invoice_lines','petty_cash_floats','petty_cash_claims','petty_cash_entries'] loop
    execute format('alter table public.%I enable row level security', t);
  end loop;
  foreach t in array array['supplier_invoices','petty_cash_floats','petty_cash_claims','petty_cash_entries'] loop
    execute format('drop trigger if exists touch_updated_at on public.%I', t);
    execute format('create trigger touch_updated_at before update on public.%I for each row execute function app.touch_updated_at()', t);
    execute format('drop trigger if exists audit on public.%I', t);
    execute format('create trigger audit after insert or update or delete on public.%I for each row execute function app.audit()', t);
  end loop;
  foreach t in array array['supplier_invoices','supplier_invoice_lines'] loop
    execute format('drop policy if exists price_read on public.%I', t);
    execute format('create policy price_read on public.%I for select to authenticated using (app.is_member(project_id) and app.can_see_prices())', t);
  end loop;
end $$;

-- Custodians see their own float; payment roles see all floats of their projects.
create or replace function app.can_see_petty(p_project uuid, p_float uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select app.is_member(p_project) and (app.is_payment_role()
    or exists (select 1 from public.petty_cash_floats f where f.id = p_float and f.custodian_id = auth.uid()))
$$;
drop policy if exists petty_read on public.petty_cash_floats;
create policy petty_read on public.petty_cash_floats for select to authenticated using (app.can_see_petty(project_id, id));
drop policy if exists petty_read on public.petty_cash_claims;
create policy petty_read on public.petty_cash_claims for select to authenticated using (app.can_see_petty(project_id, float_id));
drop policy if exists petty_read on public.petty_cash_entries;
create policy petty_read on public.petty_cash_entries for select to authenticated using (app.can_see_petty(project_id, float_id));

-- ---------------------------------------------------------------------------
-- A. Supplier invoice: match + totals
-- ---------------------------------------------------------------------------
drop function if exists app.sinv_recalc(uuid);
create or replace function app.sinv_recalc(p_inv uuid, p_include_later boolean default false) returns void
language plpgsql security definer set search_path = public as $$
declare
  i public.supplier_invoices; ts public.tax_settings; v_vat_rate numeric; v_wht_rate numeric; v_sub numeric; v_vat numeric;
  v_wht numeric; v_notes text[];
begin
  select * into i from public.supplier_invoices where id = p_inv;
  if not found then raise exception 'Supplier invoice not found'; end if;
  ts := app.tax_for(i.invoice_date);
  if ts.id is null then raise exception 'No tax settings are effective on %', i.invoice_date; end if;
  select pt.vat_rate into v_vat_rate from public.po_totals pt where pt.po_id = i.po_id;
  v_vat_rate := coalesce(v_vat_rate, ts.vat_rate);

  update public.supplier_invoice_lines l set
    po_unit_price = pp.unit_price,
    vat_applicable = coalesce(pp.vat_applicable, true),
    qty_ordered = pl.qty,
    qty_accepted = pl.qty_accepted,
    qty_invoiced_before = coalesce((select sum(o.qty) from public.supplier_invoice_lines o join public.supplier_invoices oi on oi.id = o.invoice_id
                                    where o.po_line_id = l.po_line_id and o.invoice_id <> l.invoice_id and oi.status <> 'rejected'
                                      and (p_include_later or (oi.created_at, oi.id) < (i.created_at, i.id))), 0)
  from public.po_lines pl left join public.po_line_prices pp on pp.po_line_id = pl.id
  where pl.id = l.po_line_id and l.invoice_id = p_inv;
  update public.supplier_invoice_lines l set flag = case
      when l.unit_price > coalesce(l.po_unit_price, 0) + 0.005 and l.qty + l.qty_invoiced_before > l.qty_accepted + 0.0005 then 'price_qty'
      when l.unit_price > coalesce(l.po_unit_price, 0) + 0.005 then 'price'
      when l.qty + l.qty_invoiced_before > l.qty_accepted + 0.0005 then 'qty' end
  where l.invoice_id = p_inv;

  select coalesce(sum(amount), 0), coalesce(round(sum(case when vat_applicable then amount else 0 end) * v_vat_rate / 100, 2), 0)
    into v_sub, v_vat from public.supplier_invoice_lines where invoice_id = p_inv;
  v_wht_rate := case when v_sub >= ts.wht_goods_threshold then
      case when nullif(trim((select tin from public.suppliers where id = i.supplier_id)), '') is null
           then ts.wht_no_tin_rate else ts.wht_goods_rate end else 0 end;
  v_wht := round(v_sub * v_wht_rate / 100, 2);
  select coalesce(array_agg(format('Line %s: %s', l.line_no, case l.flag
           when 'price' then format('price %s above the PO price %s', to_char(l.unit_price, 'FM999,999,990.00'), to_char(l.po_unit_price, 'FM999,999,990.00'))
           when 'qty' then format('invoiced %s but only %s accepted on GRNs (%s on other invoices)', l.qty::text, l.qty_accepted::text, l.qty_invoiced_before::text)
           else format('price above the PO and quantity above what was accepted (%s of %s)', (l.qty + l.qty_invoiced_before)::text, l.qty_accepted::text) end)
           order by l.line_no), '{}')
    into v_notes from public.supplier_invoice_lines l where l.invoice_id = p_inv and l.flag is not null;
  update public.supplier_invoices set subtotal = v_sub, vat = v_vat, total = v_sub + v_vat, withholding_rate = v_wht_rate,
    withholding = v_wht, net_payable = v_sub + v_vat - v_wht, match_notes = v_notes,
    match_status = case when cardinality(v_notes) > 0 then 'variance' else 'matched' end
  where id = p_inv;
end $$;
revoke execute on function app.sinv_recalc(uuid, boolean) from public;

-- {id, po_id, invoice_no, invoice_date, due_date?, remarks?, lines: [{po_line_id, qty, unit_price?, description?}], submit?}
create or replace function public.save_supplier_invoice(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); v_id uuid := (p ->> 'id')::uuid; i public.supplier_invoices; po public.purchase_orders;
  x record; n int := 0; v_no text; v_date date := (p ->> 'invoice_date')::date;
begin
  if v_seen is not null then return v_seen; end if;
  select * into po from public.purchase_orders where id = (p ->> 'po_id')::uuid;
  if not found then raise exception 'Purchase order not found'; end if;
  perform app.require_member(po.project_id);
  perform app.require_role_txt('procurement', 'finance', 'office_engineer', 'coordinator', 'admin');
  if not app.can_see_prices() then raise exception 'Supplier invoices need access to prices' using errcode = '42501'; end if;
  if po.status not in ('approved','sent','partially_received','received','closed') then
    raise exception 'PO % is % — invoices are recorded against approved purchase orders', po.number, po.status;
  end if;
  if nullif(trim(p ->> 'invoice_no'), '') is null then raise exception 'Enter the supplier''s invoice number'; end if;
  if v_date is null then raise exception 'Enter the invoice date'; end if;
  if v_date > app.eat_date(now()) then raise exception 'The invoice date cannot be in the future'; end if;
  if exists (select 1 from public.supplier_invoices s where s.supplier_id = po.supplier_id and lower(s.invoice_no) = lower(trim(p ->> 'invoice_no'))
             and s.id <> v_id and s.status <> 'rejected') then
    raise exception 'Invoice % from this supplier is already recorded (%)', trim(p ->> 'invoice_no'),
      (select s.number from public.supplier_invoices s where s.supplier_id = po.supplier_id and lower(s.invoice_no) = lower(trim(p ->> 'invoice_no'))
        and s.id <> v_id and s.status <> 'rejected' limit 1);
  end if;
  if jsonb_array_length(coalesce(p -> 'lines', '[]'::jsonb)) = 0 then raise exception 'Add at least one invoice line'; end if;

  select * into i from public.supplier_invoices where id = v_id for update;
  if found then
    if i.status not in ('draft','returned') then raise exception 'Invoice % is % and cannot be changed', i.number, i.status; end if;
    if i.po_id <> po.id then raise exception 'The purchase order of an invoice cannot be changed'; end if;
    update public.supplier_invoices set invoice_no = trim(p ->> 'invoice_no'), invoice_date = v_date,
      due_date = coalesce((p ->> 'due_date')::date, v_date + 30), remarks = nullif(trim(p ->> 'remarks'), '') where id = v_id;
    delete from public.supplier_invoice_lines where invoice_id = v_id;
  else
    v_no := app.pay_next_no(po.project_id, 'SINV', 'supplier_invoices');
    insert into public.supplier_invoices (id, project_id, number, supplier_id, po_id, invoice_no, invoice_date, due_date, remarks, prepared_by)
    values (v_id, po.project_id, v_no, po.supplier_id, po.id, trim(p ->> 'invoice_no'), v_date,
      coalesce((p ->> 'due_date')::date, v_date + 30), nullif(trim(p ->> 'remarks'), ''), auth.uid());
  end if;
  for x in select * from jsonb_to_recordset(p -> 'lines') as y(po_line_id uuid, qty numeric, unit_price numeric, description text) loop
    n := n + 1;
    if not exists (select 1 from public.po_lines where id = x.po_line_id and po_id = po.id and deleted_at is null) then
      raise exception 'Line %: not a line of PO %', n, po.number;
    end if;
    if x.qty is null or x.qty <= 0 then raise exception 'Line %: enter the invoiced quantity', n; end if;
    insert into public.supplier_invoice_lines (invoice_id, project_id, po_line_id, line_no, description, qty, unit_price)
    values (v_id, po.project_id, x.po_line_id, n, nullif(trim(x.description), ''), x.qty,
      coalesce(x.unit_price, (select unit_price from public.po_line_prices where po_line_id = x.po_line_id), 0));
  end loop;
  perform app.sinv_recalc(v_id, true);
  if coalesce((p ->> 'submit')::boolean, false) then
    perform public.finance_doc_action(jsonb_build_object('doc_type', 'supplier_invoice', 'id', v_id, 'action', 'submit'));
  end if;
  select * into i from public.supplier_invoices where id = v_id;
  return app.op_done(p, 'save_supplier_invoice', jsonb_build_object('ok', true, 'id', v_id, 'number', i.number, 'status', i.status,
    'match_status', i.match_status, 'match_notes', to_jsonb(i.match_notes), 'net_payable', i.net_payable));
end $$;

-- ---------------------------------------------------------------------------
-- B. Petty cash
-- ---------------------------------------------------------------------------
-- {id, project_id, name, custodian_id, float_amount, is_active?}
create or replace function public.save_petty_float(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_seen jsonb := app.op_seen(p); v_id uuid := (p ->> 'id')::uuid; v_project uuid := (p ->> 'project_id')::uuid; f public.petty_cash_floats;
begin
  if v_seen is not null then return v_seen; end if;
  perform app.require_member(v_project);
  perform app.require_role_txt('manager', 'finance', 'admin');
  if coalesce((p ->> 'float_amount')::numeric, 0) <= 0 then raise exception 'Enter the float amount'; end if;
  if not exists (select 1 from public.project_members where project_id = v_project and user_id = (p ->> 'custodian_id')::uuid)
     and not exists (select 1 from public.profiles where id = (p ->> 'custodian_id')::uuid and role = 'admin') then
    raise exception 'The custodian must be a member of the project';
  end if;
  select * into f from public.petty_cash_floats where id = v_id;
  if found then
    if f.project_id <> v_project then raise exception 'Float belongs to another project'; end if;
    if f.custodian_id <> (p ->> 'custodian_id')::uuid and exists (select 1 from public.petty_cash_entries where float_id = v_id and not voided
        and (claim_id is null or claim_id in (select id from public.petty_cash_claims where status not in ('paid','rejected')))) then
      raise exception 'Settle the open expenses before handing the float to another custodian';
    end if;
    update public.petty_cash_floats set name = coalesce(nullif(trim(p ->> 'name'), ''), name), custodian_id = (p ->> 'custodian_id')::uuid,
      float_amount = (p ->> 'float_amount')::numeric, is_active = coalesce((p ->> 'is_active')::boolean, is_active) where id = v_id;
  else
    insert into public.petty_cash_floats (id, project_id, name, custodian_id, float_amount)
    values (v_id, v_project, coalesce(nullif(trim(p ->> 'name'), ''), 'Site petty cash'), (p ->> 'custodian_id')::uuid, (p ->> 'float_amount')::numeric);
    perform app.notify_user((p ->> 'custodian_id')::uuid, v_project, 'You hold a petty cash float',
      to_char((p ->> 'float_amount')::numeric, 'FM999,999,990.00') || ' ETB', 'petty_cash', v_id);
  end if;
  return app.op_done(p, 'save_petty_float', jsonb_build_object('ok', true, 'id', v_id));
end $$;

-- Cash in hand = float − expenses not yet reimbursed (unclaimed or in an unpaid claim).
create or replace function app.petty_balance(p_float uuid) returns numeric
language sql stable security definer set search_path = public as $$
  select f.float_amount - coalesce((select sum(e.amount) from public.petty_cash_entries e
           left join public.petty_cash_claims c on c.id = e.claim_id
           where e.float_id = f.id and not e.voided and (c.id is null or c.status <> 'paid')), 0)
  from public.petty_cash_floats f where f.id = p_float
$$;
revoke execute on function app.petty_balance(uuid) from public;

-- {id, float_id, entry_date, category, description, payee?, receipt_no?, amount} — or {id, void: true}
create or replace function public.record_petty_expense(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_seen jsonb := app.op_seen(p); f public.petty_cash_floats; e public.petty_cash_entries; v_no text;
begin
  if v_seen is not null then return v_seen; end if;
  if coalesce((p ->> 'void')::boolean, false) then
    select * into e from public.petty_cash_entries where id = (p ->> 'id')::uuid for update;
    if not found then raise exception 'Expense not found'; end if;
    select * into f from public.petty_cash_floats where id = e.float_id;
    if f.custodian_id <> auth.uid() and not app.has_role_txt('admin') then raise exception 'Only the custodian can void an expense' using errcode = '42501'; end if;
    if e.claim_id is not null and exists (select 1 from public.petty_cash_claims where id = e.claim_id and status <> 'returned') then
      raise exception 'Expense % is in a replenishment claim', e.number;
    end if;
    update public.petty_cash_entries set voided = true, claim_id = null where id = e.id;
    return app.op_done(p, 'record_petty_expense', jsonb_build_object('ok', true, 'id', e.id, 'balance', app.petty_balance(f.id)));
  end if;
  select * into f from public.petty_cash_floats where id = (p ->> 'float_id')::uuid for update;
  if not found or not f.is_active then raise exception 'Petty cash float not found or closed'; end if;
  perform app.require_member(f.project_id);
  if f.custodian_id <> auth.uid() and not app.has_role_txt('admin') then raise exception 'Only the custodian records petty cash expenses' using errcode = '42501'; end if;
  if coalesce((p ->> 'amount')::numeric, 0) <= 0 then raise exception 'Enter the amount'; end if;
  if nullif(trim(p ->> 'description'), '') is null then raise exception 'Say what it was for'; end if;
  if (p ->> 'entry_date')::date > app.eat_date(now()) then raise exception 'The date cannot be in the future'; end if;
  if (p ->> 'amount')::numeric > app.petty_balance(f.id) then
    raise exception 'Not enough cash in the float: % ETB left — submit a replenishment claim', to_char(app.petty_balance(f.id), 'FM999,999,990.00');
  end if;
  v_no := app.pay_next_no(f.project_id, 'PCE', 'petty_cash_entries');
  insert into public.petty_cash_entries (id, project_id, float_id, number, entry_date, category, description, payee, receipt_no, amount)
  values ((p ->> 'id')::uuid, f.project_id, f.id, v_no, coalesce((p ->> 'entry_date')::date, app.eat_date(now())),
    coalesce(p ->> 'category', 'other'), trim(p ->> 'description'), nullif(trim(p ->> 'payee'), ''), nullif(trim(p ->> 'receipt_no'), ''),
    (p ->> 'amount')::numeric);
  return app.op_done(p, 'record_petty_expense', jsonb_build_object('ok', true, 'id', (p ->> 'id')::uuid, 'number', v_no, 'balance', app.petty_balance(f.id)));
end $$;

-- {id, float_id, remarks?} — claims every unclaimed expense (and re-submits a returned claim with its id).
create or replace function public.submit_petty_claim(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_seen jsonb := app.op_seen(p); f public.petty_cash_floats; c public.petty_cash_claims; v_id uuid := (p ->> 'id')::uuid; v_no text;
begin
  if v_seen is not null then return v_seen; end if;
  select * into f from public.petty_cash_floats where id = (p ->> 'float_id')::uuid;
  if not found then raise exception 'Petty cash float not found'; end if;
  perform app.require_member(f.project_id);
  if f.custodian_id <> auth.uid() and not app.has_role_txt('admin') then raise exception 'Only the custodian claims replenishment' using errcode = '42501'; end if;
  select * into c from public.petty_cash_claims where id = v_id for update;
  if found and c.status <> 'returned' then raise exception 'Claim % is %', c.number, c.status; end if;
  if not found then
    if exists (select 1 from public.petty_cash_claims where float_id = f.id and status in ('submitted','checked','returned')) then
      raise exception 'A replenishment claim of this float is already in approval';
    end if;
    v_no := app.pay_next_no(f.project_id, 'PCR', 'petty_cash_claims');
    insert into public.petty_cash_claims (id, project_id, float_id, number, prepared_by, remarks) values (v_id, f.project_id, f.id, v_no, auth.uid(), nullif(trim(p ->> 'remarks'), ''));
  end if;
  update public.petty_cash_entries set claim_id = v_id where float_id = f.id and not voided and claim_id is null;
  update public.petty_cash_claims set total = coalesce((select sum(amount) from public.petty_cash_entries where claim_id = v_id and not voided), 0),
    entries = (select count(*) from public.petty_cash_entries where claim_id = v_id and not voided),
    status = 'submitted', submitted_at = now(), return_comment = null, checked_by = null, checked_at = null where id = v_id;
  select * into c from public.petty_cash_claims where id = v_id;
  if c.entries = 0 then raise exception 'No expenses to claim'; end if;
  perform app.pay_event(f.project_id, 'petty_cash', v_id, 'submit', null, 'submitted', null);
  perform app.notify_roles_txt(f.project_id, '{coordinator}', 'Petty cash claim ' || c.number || ' to check',
    to_char(c.total, 'FM999,999,990.00') || ' ETB · ' || c.entries || ' receipts', 'petty_cash', v_id);
  return app.op_done(p, 'submit_petty_claim', jsonb_build_object('ok', true, 'id', v_id, 'number', c.number, 'total', c.total, 'entries', c.entries));
end $$;

-- ---------------------------------------------------------------------------
-- A + B chain: {doc_type: supplier_invoice | petty_cash, id, action: submit|check|approve|pay|return|reject, comment?,
--               payment_method?, payment_ref?, payment_date?}
-- ---------------------------------------------------------------------------
create or replace function public.finance_doc_action(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_seen jsonb := app.op_seen(p); v_type text := p ->> 'doc_type'; v_id uuid := (p ->> 'id')::uuid; v_action text := p ->> 'action';
  v_comment text := nullif(trim(p ->> 'comment'), ''); v_project uuid; v_status text; v_number text; v_prep uuid; v_checked uuid;
  v_amount numeric; v_to text; v_label text; v_match text; e record;
begin
  if v_seen is not null then return v_seen; end if;
  if v_type = 'supplier_invoice' then
    select s.project_id, s.status, s.number, s.prepared_by, s.checked_by, s.net_payable, s.match_status,
           'Supplier invoice ' || s.number || ' (' || sp.name || ' ' || s.invoice_no || ')'
      into v_project, v_status, v_number, v_prep, v_checked, v_amount, v_match, v_label
      from public.supplier_invoices s join public.suppliers sp on sp.id = s.supplier_id where s.id = v_id for update of s;
  elsif v_type = 'petty_cash' then
    select project_id, status, number, prepared_by, checked_by, total, 'matched', 'Petty cash claim ' || number
      into v_project, v_status, v_number, v_prep, v_checked, v_amount, v_match, v_label
      from public.petty_cash_claims where id = v_id for update;
  else
    raise exception 'Unknown finance document type %', v_type;
  end if;
  if v_project is null then raise exception 'Document not found'; end if;
  perform app.require_member(v_project);
  if v_type = 'supplier_invoice' then perform app.require_prices(); end if;

  if v_action = 'submit' then
    if v_type <> 'supplier_invoice' then raise exception 'Petty cash claims are submitted by the custodian'; end if;
    perform app.require_role_txt('procurement', 'finance', 'office_engineer', 'coordinator', 'admin');
    if v_status not in ('draft','returned') then raise exception '% is % — only drafts can be submitted', v_label, v_status; end if;
    perform app.sinv_recalc(v_id);
    select net_payable, match_status into v_amount, v_match from public.supplier_invoices where id = v_id;
    v_to := 'submitted';
    perform app.notify_roles_txt(v_project, '{coordinator}', v_label || ' to check',
      'Net ' || to_char(v_amount, 'FM999,999,999,990.00') || ' ETB' || case when v_match = 'variance' then ' · 3-way match variance' else '' end, v_type, v_id);
  elsif v_action = 'check' then
    perform app.require_role_txt('coordinator', 'admin');
    if v_status <> 'submitted' then raise exception '% is % — only submitted documents can be checked', v_label, v_status; end if;
    if v_prep = auth.uid() and not app.has_role_txt('admin') then raise exception 'You prepared % — another person must check it', v_number using errcode = '42501'; end if;
    v_to := 'checked';
    perform app.notify_roles_txt(v_project, '{manager}', v_label || ' to approve', 'Checked · ' || to_char(v_amount, 'FM999,999,999,990.00') || ' ETB', v_type, v_id);
  elsif v_action = 'approve' then
    perform app.require_role_txt('manager', 'admin');
    if v_status <> 'checked' then raise exception '% is % — it must be checked by the coordinator first', v_label, v_status; end if;
    if (v_prep = auth.uid() or v_checked = auth.uid()) and not app.has_role_txt('admin') then
      raise exception 'You prepared or checked % — the approver must be someone else', v_number using errcode = '42501';
    end if;
    if v_type = 'supplier_invoice' then
      perform app.sinv_recalc(v_id);
      select match_status into v_match from public.supplier_invoices where id = v_id;
      if v_match = 'variance' and v_comment is null then
        raise exception 'The invoice does not match the PO / goods received — write why it is approved anyway';
      end if;
      update public.supplier_invoices set override_comment = case when v_match = 'variance' then v_comment end where id = v_id;
    else
      for e in select * from public.petty_cash_entries where claim_id = v_id and not voided loop
        perform app.pay_cost(v_project, e.number, e.entry_date,
          case e.category when 'materials' then 'material_direct' when 'labour' then 'labour' else 'overhead' end,
          null, null, 'Petty cash: ' || e.description, e.payee, null, null, null, e.amount, 'manual', v_number);
      end loop;
    end if;
    v_to := 'approved';
    perform app.notify_roles_txt(v_project, '{finance}', v_label || ' approved — to pay', 'Net payable ' || to_char(v_amount, 'FM999,999,999,990.00') || ' ETB', v_type, v_id);
    perform app.notify_user(v_prep, v_project, v_label || ' approved', null, v_type, v_id);
  elsif v_action = 'pay' then
    perform app.require_role_txt('finance', 'admin');
    if v_status <> 'approved' then raise exception '% is % — only approved documents can be paid', v_label, v_status; end if;
    if coalesce(p ->> 'payment_method', '') not in ('bank_transfer','cheque','cash') then raise exception 'Choose how it was paid'; end if;
    if (p ->> 'payment_date') is null or (p ->> 'payment_date')::date > app.eat_date(now()) then raise exception 'Enter the payment date (not in the future)'; end if;
    if p ->> 'payment_method' = 'cash' and (app.tax_for((p ->> 'payment_date')::date)).bank_payment_threshold is null then
      raise exception 'No tax settings are effective on the payment date';
    end if;
    if p ->> 'payment_method' = 'cash' and v_amount > (app.tax_for((p ->> 'payment_date')::date)).bank_payment_threshold then
      raise exception 'Cash is limited to % ETB for this payment; use a bank transfer or cheque',
        to_char((app.tax_for((p ->> 'payment_date')::date)).bank_payment_threshold, 'FM999,999,990.00');
    end if;
    if p ->> 'payment_method' <> 'cash' and nullif(trim(p ->> 'payment_ref'), '') is null then raise exception 'Enter the transfer / cheque reference'; end if;
    v_to := 'paid';
    if v_type = 'supplier_invoice' then
      update public.supplier_invoices set paid_by = auth.uid(), paid_at = now(), payment_method = p ->> 'payment_method',
        payment_ref = nullif(trim(p ->> 'payment_ref'), ''), payment_date = (p ->> 'payment_date')::date where id = v_id;
    else
      update public.petty_cash_claims set paid_by = auth.uid(), paid_at = now(), payment_method = p ->> 'payment_method',
        payment_ref = nullif(trim(p ->> 'payment_ref'), ''), payment_date = (p ->> 'payment_date')::date where id = v_id;
    end if;
    perform app.notify_user(v_prep, v_project, v_label || ' paid', coalesce(p ->> 'payment_ref', 'cash'), v_type, v_id);
  elsif v_action in ('return', 'reject') then
    if v_comment is null then raise exception 'Say why it is %', case when v_action = 'return' then 'returned' else 'rejected' end; end if;
    if v_status = 'submitted' then perform app.require_role_txt('coordinator', 'manager', 'admin');
    elsif v_status = 'checked' then perform app.require_role_txt('manager', 'admin');
    else raise exception '% is % — it can no longer be %', v_label, v_status, case when v_action = 'return' then 'returned' else 'rejected' end;
    end if;
    v_to := case when v_action = 'return' then 'returned' else 'rejected' end;
    if v_type = 'petty_cash' and v_to = 'rejected' then
      update public.petty_cash_entries set claim_id = null where claim_id = v_id;   -- back to unclaimed; custodian voids or re-claims
    end if;
    perform app.notify_user(v_prep, v_project, v_label || ' ' || v_to, v_comment, v_type, v_id);
  else
    raise exception 'Unknown action %', v_action;
  end if;

  if v_type = 'supplier_invoice' then
    update public.supplier_invoices set status = v_to,
      submitted_at = case when v_to = 'submitted' then now() else submitted_at end,
      checked_by = case when v_to = 'checked' then auth.uid() when v_to = 'submitted' then null else checked_by end,
      checked_at = case when v_to = 'checked' then now() when v_to = 'submitted' then null else checked_at end,
      approved_by = case when v_to = 'approved' then auth.uid() else approved_by end,
      approved_at = case when v_to = 'approved' then now() else approved_at end,
      return_comment = case when v_to in ('returned','rejected') then v_comment when v_to = 'submitted' then null else return_comment end
    where id = v_id;
  else
    update public.petty_cash_claims set status = v_to,
      checked_by = case when v_to = 'checked' then auth.uid() else checked_by end,
      checked_at = case when v_to = 'checked' then now() else checked_at end,
      approved_by = case when v_to = 'approved' then auth.uid() else approved_by end,
      approved_at = case when v_to = 'approved' then now() else approved_at end,
      return_comment = case when v_to in ('returned','rejected') then v_comment else return_comment end
    where id = v_id;
  end if;
  perform app.pay_event(v_project, v_type, v_id, v_action, v_status, v_to,
    coalesce(v_comment, case when v_action = 'pay' then (p ->> 'payment_method') || coalesce(' ' || (p ->> 'payment_ref'), '') end));
  return app.op_done(p, 'finance_doc_action', jsonb_build_object('ok', true, 'id', v_id, 'number', v_number, 'status', v_to));
end $$;

-- Inbox items (approvals registry)
create or replace function app.finance_approvals_for(p_user uuid)
returns table (kind text, entity_type text, entity_id uuid, project_id uuid, number text, title text, status text,
               requested_by uuid, requested_at timestamptz, is_urgent boolean, actions text[], age_hours numeric)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare v_role text; v_prices boolean;
begin
  select pr.role::text into v_role from public.profiles pr where pr.id = p_user and pr.is_active;
  if v_role is null then return; end if;
  v_prices := v_role = 'admin' or v_role::public.app_role = any(coalesce((select price_roles from public.app_settings where id = 1), '{}'));
  return query
  with mem as (select pm.project_id as pid from public.project_members pm where pm.user_id = p_user
               union select pj.id from public.projects pj where v_role = 'admin'),
  docs as (
    select 'supplier_invoice'::text as t, s.id, s.project_id, s.number, s.status, s.prepared_by, s.submitted_at, s.checked_at, s.approved_at, s.updated_at,
           sp.name || ' inv. ' || s.invoice_no || case when s.match_status = 'variance' then ' · MATCH VARIANCE' else '' end as party, s.net_payable as net,
           s.due_date
    from public.supplier_invoices s join public.suppliers sp on sp.id = s.supplier_id where v_prices and s.project_id in (select pid from mem)
    union all
    select 'petty_cash', c.id, c.project_id, c.number, c.status, c.prepared_by, c.submitted_at, c.checked_at, c.approved_at, c.updated_at,
           'Petty cash replenishment · ' || c.entries || ' receipts', c.total, null::date
    from public.petty_cash_claims c where c.project_id in (select pid from mem))
  select 'payment'::text, d.t, d.id, d.project_id, d.number,
         d.party || ' · ' || to_char(d.net, 'FM999,999,999,990.00') || ' ETB', d.status, d.prepared_by,
         coalesce(case d.status when 'submitted' then d.submitted_at when 'checked' then d.checked_at when 'approved' then d.approved_at end, d.updated_at),
         (d.status = 'approved' and d.due_date is not null and d.due_date <= app.eat_date(now())),
         array[case d.status when 'submitted' then 'check' when 'checked' then 'approve' when 'approved' then 'pay' else 'fix' end],
         round((extract(epoch from now() - coalesce(d.approved_at, d.checked_at, d.submitted_at, d.updated_at)) / 3600)::numeric, 1)
  from docs d
  where (d.status = 'submitted' and v_role in ('coordinator','admin') and d.prepared_by is distinct from p_user)
     or (d.status = 'checked' and v_role in ('manager','admin'))
     or (d.status = 'approved' and v_role in ('finance','admin'))
     or (d.status = 'returned' and d.prepared_by = p_user);
end $$;
revoke execute on function app.finance_approvals_for(uuid) from public;
insert into app.approval_sources (fn) values ('app.finance_approvals_for') on conflict do nothing;

-- Views
create or replace view public.v_supplier_invoices with (security_invoker = true) as
select s.*, sp.name as supplier_name, sp.tin as supplier_tin, po.number as po_number
from public.supplier_invoices s join public.suppliers sp on sp.id = s.supplier_id join public.purchase_orders po on po.id = s.po_id;

create or replace view public.v_petty_cash_floats with (security_invoker = true) as
select f.*, pr.full_name as custodian_name,
       coalesce((select sum(e.amount) from public.petty_cash_entries e where e.float_id = f.id and not e.voided and e.claim_id is null), 0) as unclaimed,
       coalesce((select sum(e.amount) from public.petty_cash_entries e join public.petty_cash_claims c on c.id = e.claim_id
                 where e.float_id = f.id and not e.voided and c.status not in ('paid','rejected')), 0) as in_claim,
       f.float_amount - coalesce((select sum(e.amount) from public.petty_cash_entries e left join public.petty_cash_claims c on c.id = e.claim_id
                 where e.float_id = f.id and not e.voided and (c.id is null or c.status <> 'paid')), 0) as balance
from public.petty_cash_floats f join public.profiles pr on pr.id = f.custodian_id;

-- PO lines still to invoice (accepted on GRNs minus already invoiced), price data.
create or replace view public.v_po_invoiceable with (security_invoker = true) as
select pl.id as po_line_id, pl.po_id, pl.project_id, po.number as po_number, po.supplier_id, pl.line_no, pl.material_spec_id,
       ms.grade || coalesce(' ' || ms.description, '') as spec, m.name as material, pl.uom, pl.qty as qty_ordered, pl.qty_accepted,
       coalesce((select sum(l.qty) from public.supplier_invoice_lines l join public.supplier_invoices s on s.id = l.invoice_id
                 where l.po_line_id = pl.id and s.status <> 'rejected'), 0) as qty_invoiced,
       pp.unit_price, coalesce(pp.vat_applicable, true) as vat_applicable
from public.po_lines pl join public.purchase_orders po on po.id = pl.po_id
join public.material_specs ms on ms.id = pl.material_spec_id join public.materials m on m.id = ms.material_id
join public.po_line_prices pp on pp.po_line_id = pl.id
where pl.deleted_at is null;

grant select on public.v_supplier_invoices, public.v_petty_cash_floats, public.v_po_invoiceable to authenticated;

-- ---------------------------------------------------------------------------
-- C. Cash-flow forecast and finance overview
-- ---------------------------------------------------------------------------
create or replace function app.finance_guard(p_project uuid) returns void
language plpgsql stable security definer set search_path = public as $$
begin
  perform app.require_member(p_project);
  perform app.require_role_txt('finance', 'manager', 'coordinator', 'admin');
  if not app.can_see_prices() then raise exception 'This report needs access to prices' using errcode = '42501'; end if;
end $$;

-- Every expected cash movement: direction in/out, bucket, due date (overdue → today), amount.
create or replace function app.cash_items(p_project uuid)
returns table (direction text, bucket text, ref text, party text, due date, amount numeric)
language sql stable security definer set search_path = public as $$
  with t as (select app.eat_date(now()) as d),
  cc as (select coalesce((select payment_days from public.client_contracts where project_id = p_project), 30) as days)
  -- client receipts
  select 'in', 'client', 'IPC ' || i.ipc_no, coalesce(c.client_name, 'Client'),
         greatest(case when i.status = 'certified' then coalesce(i.certified_on, t.d) + cc.days
                       when i.status = 'submitted' then i.submitted_at::date + 14 + cc.days
                       else coalesce(i.prepared_at::date, t.d) + 21 + cc.days end, t.d),
         case when i.status = 'certified' then coalesce((i.certified ->> 'payable')::numeric, 0) - i.paid_amount
              else coalesce((i.claimed ->> 'payable')::numeric, 0) end
  from public.client_ipcs i left join public.client_contracts c on c.project_id = i.project_id, t, cc
  where i.project_id = p_project and i.status in ('prepared','checked','submitted','certified')
  union all
  select 'out', 'suppliers', s.number, sp.name, greatest(s.due_date, t.d), s.net_payable
  from public.supplier_invoices s join public.suppliers sp on sp.id = s.supplier_id, t
  where s.project_id = p_project and s.status in ('draft','submitted','checked','approved','returned')
  union all
  -- ordered but not yet invoiced: PO net minus invoices, due 30 days after expected delivery
  select 'out', 'committed', po.number, sp.name, greatest(coalesce(po.eta, po.expected_date, po.order_date) + 30, t.d),
         greatest(pt.net_payable - coalesce((select sum(s.net_payable) from public.supplier_invoices s where s.po_id = po.id and s.status <> 'rejected'), 0), 0)
  from public.purchase_orders po join public.po_totals pt on pt.po_id = po.id join public.suppliers sp on sp.id = po.supplier_id, t
  where po.project_id = p_project and po.status in ('approved','sent','partially_received','received')
  union all
  select 'out', 'subcontractors', c.number, sc.name, case when c.status = 'approved' then t.d else t.d + 7 end, c.net_payable
  from public.sc_certificates c join public.subcontracts k on k.id = c.subcontract_id join public.subcontractors sc on sc.id = k.subcontractor_id, t
  where c.project_id = p_project and c.status in ('submitted','checked','approved')
  union all
  select 'out', 'labour', l.number, 'Daily labour', case when l.status = 'approved' then t.d else t.d + 3 end, l.net
  from public.labour_payrolls l, t
  where l.project_id = p_project and l.status in ('submitted','checked','approved')
  union all
  select 'out', 'petty_cash', c.number, 'Petty cash', case when c.status = 'approved' then t.d else t.d + 3 end, c.total
  from public.petty_cash_claims c, t
  where c.project_id = p_project and c.status in ('submitted','checked','approved')
$$;
revoke execute on function app.cash_items(uuid) from public;

create or replace function public.cash_flow_forecast(p_project uuid, p_weeks int default 13)
returns table (week_start date, client_in numeric, suppliers_out numeric, subcontractors_out numeric, labour_out numeric,
               petty_cash_out numeric, committed_out numeric, net numeric, cumulative numeric)
language plpgsql stable security definer set search_path = public as $$
declare v_start date;
begin
  perform app.finance_guard(p_project);
  v_start := app.eat_date(now()) - (extract(isodow from app.eat_date(now()))::int - 1);
  return query
  with w as (select generate_series(0, greatest(least(coalesce(p_weeks, 13), 52), 1) - 1) as k),
  it as (select greatest(((x.due - v_start) / 7), 0) as k, x.*
         from app.cash_items(p_project) x
         where x.amount > 0 and x.due < v_start + greatest(least(coalesce(p_weeks, 13), 52), 1) * 7),
  agg as (
    select w.k,
      coalesce(sum(it.amount) filter (where it.bucket = 'client'), 0) as cin,
      coalesce(sum(it.amount) filter (where it.bucket = 'suppliers'), 0) as sup,
      coalesce(sum(it.amount) filter (where it.bucket = 'subcontractors'), 0) as sub,
      coalesce(sum(it.amount) filter (where it.bucket = 'labour'), 0) as lab,
      coalesce(sum(it.amount) filter (where it.bucket = 'petty_cash'), 0) as pet,
      coalesce(sum(it.amount) filter (where it.bucket = 'committed'), 0) as com
    from w left join it on it.k = w.k group by w.k)
  select v_start + a.k * 7, round(a.cin, 2), round(a.sup, 2), round(a.sub, 2), round(a.lab, 2), round(a.pet, 2), round(a.com, 2),
         round(a.cin - a.sup - a.sub - a.lab - a.pet - a.com, 2),
         round(sum(a.cin - a.sup - a.sub - a.lab - a.pet - a.com) over (order by a.k), 2)
  from agg a order by a.k;
end $$;

-- The movements behind the forecast (drill-down / export).
create or replace function public.cash_flow_items(p_project uuid)
returns table (direction text, bucket text, ref text, party text, due date, amount numeric)
language plpgsql stable security definer set search_path = public as $$
begin
  perform app.finance_guard(p_project);
  return query select * from app.cash_items(p_project) x where x.amount > 0 order by x.due, x.bucket;
end $$;

create or replace function public.finance_overview(p_project uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare v_today date := app.eat_date(now()); r jsonb;
begin
  perform app.finance_guard(p_project);
  with rec as (
    select coalesce(i.certified_on, i.period_to) as d, coalesce((i.certified ->> 'payable')::numeric, 0) - i.paid_amount as amt
    from public.client_ipcs i where i.project_id = p_project and i.status = 'certified'),
  lastcert as (select coalesce(i.certified, i.claimed) as t from public.client_ipcs i
               where i.project_id = p_project and i.status in ('certified','paid') order by i.ipc_no desc limit 1),
  pay as (
    select s.due_date as d, s.net_payable as amt from public.supplier_invoices s where s.project_id = p_project and s.status = 'approved'
    union all select app.eat_date(c.approved_at), c.net_payable from public.sc_certificates c where c.project_id = p_project and c.status = 'approved'
    union all select app.eat_date(l.approved_at), l.net from public.labour_payrolls l where l.project_id = p_project and l.status = 'approved'
    union all select app.eat_date(c.approved_at), c.total from public.petty_cash_claims c where c.project_id = p_project and c.status = 'approved')
  select jsonb_build_object(
    'receivable', coalesce((select sum(amt) from rec), 0),
    'receivable_ageing', jsonb_build_object(
      'd0_30', coalesce((select sum(amt) from rec where v_today - d <= 30), 0),
      'd31_60', coalesce((select sum(amt) from rec where v_today - d between 31 and 60), 0),
      'd61_90', coalesce((select sum(amt) from rec where v_today - d between 61 and 90), 0),
      'd90_plus', coalesce((select sum(amt) from rec where v_today - d > 90), 0)),
    'retention_receivable', greatest(coalesce((select rs.still_held from public.v_retention_status rs where rs.project_id = p_project),
      (select (t ->> 'retention_cum')::numeric from lastcert), 0), 0),
    'advance_to_recover_from_us', coalesce((select c.advance_amount from public.client_contracts c where c.project_id = p_project), 0)
        - coalesce((select (t ->> 'advance_recovery_cum')::numeric from lastcert), 0),
    'retention_payable', coalesce((select sum(c.retention_this - c.retention_release) from public.sc_certificates c
                                   where c.project_id = p_project and c.status in ('approved','paid')), 0),
    'payable_approved', coalesce((select sum(amt) from pay), 0),
    'payable_overdue', coalesce((select sum(amt) from pay where d < v_today), 0),
    'supplier_invoices_overdue', (select count(*) from public.supplier_invoices s where s.project_id = p_project
                                   and s.status in ('submitted','checked','approved') and s.due_date < v_today),
    'petty_cash_in_hand', coalesce((select sum(app.petty_balance(f.id)) from public.petty_cash_floats f where f.project_id = p_project and f.is_active), 0)
  ) into r;
  return r;
end $$;

-- ---------------------------------------------------------------------------
-- D. Monthly tax report (all of the caller's projects when p_project is null)
--   wht_payable     withholding we deducted from suppliers / subcontractors (remit to MoR)
--   payroll_tax     tax withheld from daily labour
--   vat_output      VAT on certificates to the client (certified in the month)
--   vat_input       VAT on supplier invoices (invoice date) and subcontractor certificates (approved in the month)
--   wht_credit      withholding the client deducted from us (tax credit)
-- ---------------------------------------------------------------------------
create or replace function public.tax_report(p_project uuid, p_month date)
returns table (section text, project_id uuid, doc_type text, doc_id uuid, number text, party text, tin text, doc_date date,
               base numeric, rate numeric, amount numeric)
language plpgsql stable security definer set search_path = public as $$
declare v_from date := date_trunc('month', p_month)::date; v_to date := (date_trunc('month', p_month) + interval '1 month')::date;
begin
  perform app.require_role_txt('finance', 'manager', 'coordinator', 'admin');
  if not app.can_see_prices() then raise exception 'The tax report needs access to prices' using errcode = '42501'; end if;
  if p_project is not null then perform app.require_member(p_project); end if;
  return query
  with prj as (select pj.id from public.projects pj where (p_project is null or pj.id = p_project) and app.is_member(pj.id))
  select 'wht_payable'::text, s.project_id, 'supplier_invoice'::text, s.id, s.number, sp.name, sp.tin, s.payment_date, s.subtotal, s.withholding_rate, s.withholding
  from public.supplier_invoices s join public.suppliers sp on sp.id = s.supplier_id
  where s.project_id in (select id from prj) and s.status = 'paid' and s.payment_date >= v_from and s.payment_date < v_to and s.withholding > 0
  union all
  select 'wht_payable', c.project_id, 'sc_certificate', c.id, c.number, sc.name, sc.tin, c.payment_date, c.gross_this, c.wht_pct, c.wht_this
  from public.sc_certificates c join public.subcontracts k on k.id = c.subcontract_id join public.subcontractors sc on sc.id = k.subcontractor_id
  where c.project_id in (select id from prj) and c.status = 'paid' and c.payment_date >= v_from and c.payment_date < v_to and c.wht_this > 0
  union all
  select 'payroll_tax', l.project_id, 'payroll', l.id, l.number, 'Daily labour (' || l.workers || ' workers)', null, l.payment_date, l.gross, l.tax_pct, l.tax
  from public.labour_payrolls l
  where l.project_id in (select id from prj) and l.status = 'paid' and l.payment_date >= v_from and l.payment_date < v_to and l.tax > 0
  union all
  select 'vat_output', i.project_id, 'client_ipc', i.id, 'IPC ' || i.ipc_no, coalesce(cc.client_name, 'Client'), null, i.certified_on,
         coalesce((i.certified ->> 'this_value')::numeric, (i.certified ->> 'this_net')::numeric, 0), (i.certified ->> 'vat_pct')::numeric,
         coalesce((i.certified ->> 'vat')::numeric, 0)
  from public.client_ipcs i left join public.client_contracts cc on cc.project_id = i.project_id
  where i.project_id in (select id from prj) and i.status in ('certified','paid') and i.certified_on >= v_from and i.certified_on < v_to
  union all
  select 'vat_input', s.project_id, 'supplier_invoice', s.id, s.number || ' / ' || s.invoice_no, sp.name, sp.tin, s.invoice_date, s.subtotal,
         case when s.subtotal > 0 then round(s.vat / s.subtotal * 100, 2) end, s.vat
  from public.supplier_invoices s join public.suppliers sp on sp.id = s.supplier_id
  where s.project_id in (select id from prj) and s.status in ('approved','paid') and s.invoice_date >= v_from and s.invoice_date < v_to and s.vat > 0
  union all
  select 'vat_input', c.project_id, 'sc_certificate', c.id, c.number, sc.name, sc.tin, app.eat_date(c.approved_at), c.gross_this, c.vat_pct, c.vat_this
  from public.sc_certificates c join public.subcontracts k on k.id = c.subcontract_id join public.subcontractors sc on sc.id = k.subcontractor_id
  where c.project_id in (select id from prj) and c.status in ('approved','paid') and c.approved_at >= v_from and c.approved_at < v_to and c.vat_this > 0
  union all
  select 'wht_credit', i.project_id, 'client_ipc', i.id, 'IPC ' || i.ipc_no, coalesce(cc.client_name, 'Client'), null, i.certified_on,
         coalesce((i.certified ->> 'this_value')::numeric, (i.certified ->> 'this_net')::numeric, 0), (i.certified ->> 'wht_pct')::numeric,
         coalesce((i.certified ->> 'wht')::numeric, 0)
  from public.client_ipcs i left join public.client_contracts cc on cc.project_id = i.project_id
  where i.project_id in (select id from prj) and i.status in ('certified','paid') and i.certified_on >= v_from and i.certified_on < v_to
    and coalesce((i.certified ->> 'wht')::numeric, 0) > 0
  order by 1, 8, 5;
end $$;

-- ---------------------------------------------------------------------------
-- E. Admin: what is waiting on a user (hand over before deactivating them)
-- ---------------------------------------------------------------------------
create or replace function public.user_pending_items(p_user uuid)
returns table (kind text, entity_type text, entity_id uuid, project_id uuid, number text, title text, status text,
               requested_by uuid, requested_at timestamptz, is_urgent boolean, actions text[], age_hours numeric)
language plpgsql volatile security definer set search_path = public as $$
declare v_me text := current_setting('request.jwt.claim.sub', true);
begin
  perform app.require_role_txt('admin');
  if not exists (select 1 from public.profiles where id = p_user) then raise exception 'User not found'; end if;
  -- the inbox functions only answer for the signed-in user: evaluate them as p_user, then switch back
  perform set_config('request.jwt.claim.sub', p_user::text, true);
  begin
    return query
      select * from app.approvals_for(p_user)
      union all select * from app.lookahead_approvals_for(p_user)
      union all select * from app.extra_approvals_for(p_user);
  exception when others then
    perform set_config('request.jwt.claim.sub', coalesce(v_me, ''), true);
    raise;
  end;
  perform set_config('request.jwt.claim.sub', coalesce(v_me, ''), true);
end $$;

revoke execute on function public.cash_flow_forecast(uuid, int), public.cash_flow_items(uuid), public.finance_overview(uuid),
  public.tax_report(uuid, date), public.user_pending_items(uuid) from public, anon;
grant execute on function public.cash_flow_forecast(uuid, int), public.cash_flow_items(uuid), public.finance_overview(uuid),
  public.tax_report(uuid, date), public.user_pending_items(uuid) to authenticated;


